// Dialoglar, oʻqish matnlari, mashqlar, daraja testlari va grammatika tushuntirishlari — oʻzimiz yozgan original kontent (2026-11).
var COURSE = {"levels":[{"id":"A1","title":"A1 — Boshlangʻich daraja","intro":"A1 da turk alifbosi, salomlashish, oʻzingizni tanishtirish, raqamlar va vaqt, kun tartibi, oila, restoranda buyurtma berish va oʻtgan dam olish kunlari haqida gapirishni oʻrganasiz. Har bir boʻlimga 4–5 kun ajrating.","units":["a1-1","a1-2","a1-3","a1-4","a1-5","a1-6","a1-7","a1-8"],"test":{"title":"A1 daraja testi","pass":60,"parts":[{"name":"Grammatika va lugʻat","qs":[{"q":"Merhaba! Benim adım Defne. ___ adın ne?","o":["Sen","Seni","Senin"],"a":2},{"q":"Biz öğrenci ___ .","o":["yiz","yim","siniz"],"a":0},{"q":"göz → koʻplik","o":["gözlar","gözleri","gözler"],"a":2},{"q":"O doktor ___ ?","o":["mu","mi","mü"],"a":0},{"q":"Kitaplar dolap ___ .","o":["ta","da","te"],"a":0},{"q":"Ben mühendis ___ , öğretmenim.","o":["değilim","değil","yok"],"a":0},{"q":"Saat 12:30","o":["Saat yarım.","Saat on iki.","Saat bir buçuk."],"a":0},{"q":"Annem şimdi yemek ___ .","o":["pişirdi","pişirin","pişiriyor"],"a":2},{"q":"Defne ___ kedisi çok tatlı.","o":["'nin","'in","'nın"],"a":0},{"q":"Dün Efes'e ___ . (gitmek, biz)","o":["gidiyoruz","gidin","gittik"],"a":2},{"q":"Odada buzdolabı ___ . Buzdolabı mutfakta.","o":["var","değil","yok"],"a":2},{"q":"«Tikuvchi» qaysi soʻz?","o":["şoför","hemşire","terzi"],"a":2},{"q":"Lütfen kapı ___ açın.","o":["ya","dan","yı"],"a":2},{"q":"Peynir köy ___ geliyor.","o":["de","e","den"],"a":2},{"q":"Dün hava çok soğuk ___ .","o":["tu","du","ydu"],"a":0}]},{"name":"Oʻqish","text":"Jasur Taşkentli. Şimdi İzmir'de yaşıyor ve bir şirkette mühendis. Her sabah saat yedide kalkıyor ve işe otobüsle gidiyor. Cumartesi günü Jasur pazara gitti. Domates, peynir ve bal aldı. Akşam arkadaşı Kerem geldi. Birlikte pilav pişirdiler ve film izlediler. Pazar günü Jasur evdeydi, ailesiyle telefonda konuştu.","qs":[{"q":"Jasur nereli?","o":["İzmirli","Buharalı","Taşkentli"],"a":2},{"q":"Jasur işe neyle gidiyor?","o":["otobüsle","arabayla","trenle"],"a":0},{"q":"Jasur pazarda ne almadı?","o":["bal","zeytin","peynir"],"a":1},{"q":"Akşam kim geldi?","o":["Defne","annesi","Kerem"],"a":2},{"q":"Pazar günü Jasur neredeydi?","o":["evde","pazarda","işte"],"a":0}]}]}},{"id":"A2","title":"A2 — Elementar daraja","intro":"Tabriklaymiz — siz A1 ni tugatdingiz! A2 da kelajak rejalari, odatlar, yoʻl soʻrash, maslahat va majburiyat, qiyoslash, xotiralar, ruxsat soʻrash va kuningizni aytib berishni oʻrganasiz. A2 oxirida doʻkonda, shifokorda, yoʻlda va telefonda turkcha muloqot qila olasiz.","units":["a2-1","a2-2","a2-3","a2-4","a2-5","a2-6","a2-7","a2-8"],"test":{"title":"A2 daraja testi","pass":60,"parts":[{"name":"Grammatika va lugʻat","qs":[{"q":"Yarın Buhara'ya ___ . (gitmek, ben)","o":["gideceğim","gittim","gidiyordum"],"a":0},{"q":"Hasan Usta her gece saat üçte ___ .","o":["kalkar","kalkın","kalkmış"],"a":0},{"q":"Ben televizyon ___ . (geniş zaman, inkor)","o":["izlemem","izlemezim","izlemeyim"],"a":0},{"q":"Müze parkın ___ .","o":["arkasında","arkasına","arkasından"],"a":0},{"q":"Müzeye ___ gittim. (piyoda)","o":["yürüyor","yürüyerek","yürümek"],"a":1},{"q":"Öksürüyorsun, doktora ___ .","o":["görünmelisin","görünüyorsun","göründün"],"a":0},{"q":"Erken yatmam ___ .","o":["zorunda","gerek","kadar"],"a":1},{"q":"Buhara İzmir' ___ daha sıcak.","o":["e","de","den"],"a":2},{"q":"Erzurum Türkiye'nin ___ soğuk şehri.","o":["daha","en","kadar"],"a":1},{"q":"Bu kavun bal ___ tatlı.","o":["gibi","daha","en"],"a":0},{"q":"Ben ders çalışıyordum, misafir ___ .","o":["geldi","geliyor","gelecek"],"a":0},{"q":"Eski mahalleye gittim. Çok ___ ! (koʻrib bildim)","o":["değişmiş","değişecek","değişmeli"],"a":0},{"q":"Hocam, ___ ?","o":["girebilir misin","girebilir miyim","girebilirim mi"],"a":1},{"q":"Maalesef yarın ___ . (kela olmayman)","o":["gelemem","gelmem","gelebilirim"],"a":0},{"q":"Evden ___ anahtarımı unuttum.","o":["çıktıktan","çıkarken","çıkmadan"],"a":1}]},{"name":"Oʻqish","text":"Zeynep geçen ay İzmir'e taşındı. Yeni evi denize yakın ama eski evinden daha küçük. Her sabah işe gitmeden önce sahilde yarım saat koşar. Geçen hafta koşarken ayağını burktu. Doktor ona \"Bir hafta dinlenmelisin\" dedi. Zeynep şimdi koşamıyor ama yüzebiliyor. Gelecek ay annesi gelecek; birlikte Efes'i gezecekler.","qs":[{"q":"Zeynep ne zaman taşındı?","o":["geçen hafta","gelecek ay","geçen ay"],"a":2},{"q":"Yeni evi nasıl?","o":["eskisinden daha büyük","eskisinden daha küçük","denizden uzak"],"a":1},{"q":"Zeynep ne zaman koşar?","o":["işe gitmeden önce","işten sonra","akşam yemeğinden sonra"],"a":0},{"q":"Zeynep şimdi ne yapamıyor?","o":["koşamıyor","yüzemiyor","yürüyemiyor"],"a":0},{"q":"Gelecek ay ne olacak?","o":["Zeynep taşınacak.","Annesi gelecek.","Zeynep doktora gidecek."],"a":1}]}]}},{"id":"B1","title":"B1 — Oʻrta daraja","intro":"B1 da murakkab gaplar tuzasiz: sifatdoshlar (okuduğum kitap), sabab va maqsad, shart gaplar, majhul va orttirma nisbat, koʻchirma gap va ravishdoshlar. Bu darajada fikringizni asoslab bera olasiz va oddiy rasmiy matnlarni tushunasiz.","units":["b1-1","b1-2","b1-3","b1-4","b1-5","b1-6","b1-7","b1-8"],"test":{"title":"B1 daraja testi","pass":60,"parts":[{"name":"Grammatika va lugʻat","qs":[{"q":"Köşede ___ adam benim hocam.","o":["duran","durduğu","durup"],"a":0},{"q":"Bu, ___ kitap. (men izlagan)","o":["aradığım","arayan","aramak"],"a":0},{"q":"Cihaz ___ için çalışamadık.","o":["bozulmak","bozulduğu","bozulan"],"a":1},{"q":"Yağmur ___ geç kaldık.","o":["yüzünden","sayesinde","kadar"],"a":0},{"q":"Hata ___ için iki kez kontrol ediyorum.","o":["yapmadığım","yapmayan","yapmamak"],"a":2},{"q":"Sis ___ olduğunuz yerde kalın.","o":["çöktü","çökmek","çökerse"],"a":2},{"q":"Keşke hava açık ___ !","o":["olsa","olursa","olur"],"a":0},{"q":"Türk kahvesi kısık ateşte ___ .","o":["pişirir","pişirilir","pişirtir"],"a":1},{"q":"Bu cami Mimar Sinan ___ yapıldı.","o":["yüzünden","tarafından","için"],"a":1},{"q":"Elbisemi terziye ___ .","o":["diktim","diktirdim","dikildim"],"a":1},{"q":"Ev sahibi kirayı ___ söyledi.","o":["artıracağını","artıracak","artırırsa"],"a":0},{"q":"Hoca kitapları ___ istedi. (bizdan)","o":["açtığımızı","açacağımızı","açmamızı"],"a":2},{"q":"Suya ___ üşüdüm.","o":["girdikçe","girince","gireli"],"a":1},{"q":"___ güçlenirsin.","o":["Çalışalı","Çalıştıkça","Çalışmadan"],"a":1},{"q":"Araba rahat, ___ çok pahalı.","o":["ayrıca","örneğin","ancak"],"a":2}]},{"name":"Oʻqish","text":"Kerem geçen yıl kafede çalışırken barista kursuna yazıldı. Kurs pahalı olduğu için parasını üç ayda biriktirdi. Hocası ona iyi kahvenin sabırla yapıldığını söyledi. Kerem çalıştıkça ustalaştı ve bir yarışmaya katıldı. Yarışmada heyecanlanınca sütü taşırdı, yine de üçüncü oldu. Şimdi kendi kafesini açmayı düşünüyor; ailesi de onu destekleyeceğini söyledi.","qs":[{"q":"Kerem kursa ne zaman yazıldı?","o":["Kafede çalışırken","Okuldayken","Yarışmadan sonra"],"a":0},{"q":"Parayı neden üç ayda biriktirdi?","o":["Kafe kapandığı için","Kurs pahalı olduğu için","Hocası istediği için"],"a":1},{"q":"Hocası ona ne söyledi?","o":["Yarışmaya katılmamasını","İyi kahvenin sabırla yapıldığını","Kafenin kapanacağını"],"a":1},{"q":"Yarışmada ne oldu?","o":["Birinci oldu.","Sütü taşırdı ama üçüncü oldu.","Yarışmaya geç kaldı."],"a":1},{"q":"Kerem şimdi ne düşünüyor?","o":["Kursu bırakmayı","Başka bir şehre taşınmayı","Kendi kafesini açmayı"],"a":2}]}]}},{"id":"B2","title":"B2 — Yuqori oʻrta daraja","intro":"B2 da nutqingiz tabiiy va boy boʻladi: harakat nomlari, murakkab oʻtgan zamonlar, xayoliy shart va taxmin, qarama-qarshilik ifodalari, rasmiy yozishma, iboralar va maqollar, yangiliklar tili, taqdimot va munozara.","units":["b2-1","b2-2","b2-3","b2-4","b2-5","b2-6","b2-7","b2-8"],"test":{"title":"B2 daraja testi","pass":60,"parts":[{"name":"Grammatika va lugʻat","qs":[{"q":"Kedileri ___ öğrendim.","o":["beslemeyi","beslemek","beslemeye"],"a":0},{"q":"Kar ___ başladı.","o":["yağmayı","yağmaktan","yağmaya"],"a":2},{"q":"Defne cumartesi ___ istedi. (men kelishimni)","o":["geldiğimi","gelmemi","geleceğimi"],"a":1},{"q":"İstasyona vardığımda tren ___ .","o":["kalkmıştı","kalkacak","kalkıyor"],"a":0},{"q":"Dün sana ___ ama unuttum.","o":["yazmıştım","yazarım","yazacaktım"],"a":2},{"q":"Çocukken her akşam masal ___ .","o":["dinleyeceğiz","dinlemeliyiz","dinlerdik"],"a":2},{"q":"___ kapıyı açardım.","o":["Duyarsam","Duysaydım","Duyunca"],"a":1},{"q":"Keşke dün prizi ___ .","o":["kontrol etseydim","kontrol edersem","kontrol ederim"],"a":0},{"q":"Işıklar yanmıyor. Elektrik ___ .","o":["kesilmiş olmalı","kesilecekti","kesilseydi"],"a":0},{"q":"Pahalı ___ rağmen kitabı aldım.","o":["olduğu","olsa","olmasına"],"a":2},{"q":"İnternet ___ bile ders devam eder.","o":["kesildiği","kesilmesine","kesilse"],"a":2},{"q":"Evde ___ sınıfa gitmeyi tercih ederim.","o":["otururken","oturmaktansa","oturduğu hâlde"],"a":1},{"q":"Rasmiy uslub: «Karar verildi.»","o":["Karar vermişler.","Karar verdik.","Karar verilmiştir."],"a":2},{"q":"«Jon-dildan ishlamoq» qaysi ibora?","o":["kafa yormak","pes etmek","canla başla çalışmak"],"a":2},{"q":"Başkan, etkinliğin önemli olduğunu ___ .","o":["vurguladı","yalanladı","sordu"],"a":0}]},{"name":"Oʻqish","text":"Dilnoza İzmir'e ilk geldiğinde tek kelime Türkçe bilmiyordu. Kursa başlamadan önce birkaç ay kendi kendine çalışmıştı, ama konuşmaya cesaret edemiyordu. Yorgun olmasına rağmen her akşam mahalledeki gönüllü kütüphanede çocuklara masal okumaya başladı. Çocuklar hatalarına gülseler de onu sabırla düzelttiler. Bir yıl sonra B2 sınavını geçti. Ona göre başarısının sırrı ders kitapları değil, o kütüphaneydi: \"Gitmeseydim hâlâ susuyor olurdum.\"","qs":[{"q":"Dilnoza İzmir'e geldiğinde Türkçesi nasıldı?","o":["Çok iyi konuşuyordu.","B2 düzeyindeydi.","Hiç bilmiyordu."],"a":2},{"q":"Kurstan önce ne yapmıştı?","o":["Kendi kendine çalışmıştı.","Sınava girmişti.","Kütüphane açmıştı."],"a":0},{"q":"Akşamları ne yapmaya başladı?","o":["Çocuklara masal okumaya","Çocuklara ders vermeye","Kitap satmaya"],"a":0},{"q":"Çocuklar onun hatalarına nasıl davrandı?","o":["Hiç fark etmediler.","Güldüler ama sabırla düzelttiler.","Öğretmene şikâyet ettiler."],"a":1},{"q":"Dilnoza'ya göre başarısının sırrı ne?","o":["Ders kitapları","Pahalı kurslar","Gönüllü kütüphane"],"a":2}]}]}},{"id":"C1","title":"C1 — Ilgʻor daraja","intro":"C1 da turk tilini erkin va aniq ishlatasiz: murakkab ergash gaplar, bilvosita va taxminiy ifoda, nisbatlar qatlami, akademik uslub, tasviriy feʼllar, badiiy til va imtihon koʻnikmalari — uzun dialoglar, kengaytirilgan matnlar va insholar bilan.","units":["c1-1","c1-2","c1-3","c1-4","c1-5","c1-6","c1-7","c1-8"],"test":{"title":"C1 daraja testi","pass":60,"parts":[{"name":"Grammatika va lugʻat","qs":[{"q":"Sözlüğe ___ bütün metni anladı.","o":["bakmaksızın","bakarak","baktığı için"],"a":0},{"q":"Her gün tekrar ___ unutmazsın.","o":["ettiğin gibi","edeceğin yerde","ettiğin sürece"],"a":2},{"q":"Ders bitmek ___ ; biraz daha bekle.","o":["yerine","suretiyle","üzere"],"a":2},{"q":"___ haber üç yıl öncesine aitmiş. (endi bildim)","o":["Güya","Meğer","Zira"],"a":1},{"q":"Hiçbir şey ___ gülümsedi.","o":["olmadığına göre","olmayacak kadar","olmamış gibi"],"a":2},{"q":"Fabrikanın ___ söyleniyor.","o":["kapanacağı","kapanacak","kapanmak"],"a":0},{"q":"Işıklar ___ evdeler.","o":["yandığı gibi","yandığına göre","yanacak kadar"],"a":1},{"q":"___ yorgunum. (yura olmaydigan darajada)","o":["Yürüyemediğim gibi","Yürüyemeyecek kadar","Yürümeksizin"],"a":1},{"q":"Rapor bir uzmana ___ . (orttirma + majhul)","o":["hazırlandı","hazırlattı","hazırlatıldı"],"a":2},{"q":"Bu hata ___ . (oldini olish mumkin edi)","o":["önlenebilirdi","önleyebilirdi","önletilmişti"],"a":0},{"q":"Veri yetersizdir; ___ kesin bir sonuca varılamaz.","o":["nitekim","dolayısıyla","oysa"],"a":1},{"q":"Sistem hızlıdır; ___ kurulumu pahalıdır.","o":["bu nedenle","bununla birlikte","zira"],"a":1},{"q":"Merdivenden ___ . (oz qoldi)","o":["düşüverdim","düşeyazdım","düşedurdum"],"a":1},{"q":"«kara» soʻzining kuchaytirma shakli","o":["kapkara","kaskara","karkara"],"a":0},{"q":"Odatiy tartib: «Gelmedi o akşam vapur.»","o":["Vapur o akşam gelmedi mi?","Gelmedi vapur akşam o.","O akşam vapur gelmedi."],"a":2}]},{"name":"Oʻqish","text":"Kütüphaneler uzun süredir yalnızca kitap ödünç alınan yerler olmaktan çıkmıştır. Dijital kaynakların yaygınlaşmasıyla birlikte ziyaretçi sayısının azalacağı öngörülmüştü; oysa birçok şehirde tam tersi yaşanmaktadır. Yeni kütüphaneler, sessiz okuma salonlarının yanı sıra atölyelere, dil kulüplerine ve ortak çalışma alanlarına da ev sahipliği yapmaktadır. Araştırmalara göre ziyaretçilerin önemli bir bölümü kitap almak için değil, başkalarıyla aynı ortamda çalışmak için gelmektedir. Uzmanlar bunu, evden çalışmanın yaygınlaşması nedeniyle artan yalnızlık duygusuyla açıklamaktadır. Bununla birlikte bütçe kesintileri küçük semt kütüphanelerini kapanma tehlikesiyle karşı karşıya bırakmıştır. Kütüphanelerin geleceği, onların bir depo olarak mı yoksa bir buluşma noktası olarak mı görüleceğine bağlıdır.","qs":[{"q":"Dijital kaynaklar yaygınlaşınca ne öngörülmüştü?","o":["Kütüphanelerin büyüyeceği","Kitapların ucuzlayacağı","Ziyaretçi sayısının azalacağı"],"a":2},{"q":"Birçok şehirde gerçekte ne yaşanmaktadır?","o":["Ziyaretçi sayısı artmaktadır.","Kütüphaneler boşalmaktadır.","Kitaplar kaldırılmaktadır."],"a":0},{"q":"Ziyaretçilerin önemli bir bölümü neden gelmektedir?","o":["Yalnızca kitap ödünç almak için","Başkalarıyla aynı ortamda çalışmak için","İnternet kullanmak için"],"a":1},{"q":"Uzmanlar bu durumu neyle açıklamaktadır?","o":["Kitap fiyatlarının artmasıyla","Okulların kapanmasıyla","Artan yalnızlık duygusuyla"],"a":2},{"q":"Küçük semt kütüphanelerini tehdit eden nedir?","o":["Ziyaretçi fazlalığı","Bütçe kesintileri","Dijital kitaplar"],"a":1}]}]}}],"units":[{"id":"a1-1","level":"A1","n":1,"title":"Merhaba!","sub":"Alifbo, talaffuz, salomlashish · Unli uygʻunligi · Koʻplik -lar/-ler","goals":["turk alifbosi va oʻqish qoidalari","kun vaqtiga qarab salomlashish va xayrlashish","kasblar nomi","unli uygʻunligi (ünlü uyumu)","koʻplik qoʻshimchasi -lar / -ler"],"vocab":[{"title":"Lugʻat","words":[["Merhaba / Selam","Salom"],["Teşekkür ederim / Teşekkürler","Rahmat"],["Günaydın","Xayrli tong"],["Rica ederim","Arzimaydi"],["İyi günler","Xayrli kun"],["Lütfen","Iltimos"],["İyi akşamlar","Xayrli kech"],["Özür dilerim","Kechirasiz (uzr)"],["İyi geceler","Xayrli tun"],["Affedersiniz","Kechirasiz (murojaat)"],["Hoş geldiniz","Xush kelibsiz"],["Evet / Hayır","Ha / Yoʻq"],["Hoş bulduk","Xush koʻrdik"],["Nasılsınız?","Qandaysiz?"],["Memnun oldum","Tanishganimdan xursandman"],["İyiyim","Yaxshiman"],["Görüşürüz","Koʻrishguncha"],["Hoşça kalın","Xayr (ketayotgan kishi)"],["Güle güle","Yaxshi boring (qolayotgan kishi)"],["Ben de","Men ham"]]},{"title":"Mavzuli lugʻat — kasblar (meslekler)","words":[["öğretmen","oʻqituvchi"],["doktor","shifokor"],["öğrenci","oʻquvchi, talaba"],["hemşire","hamshira"],["mühendis","muhandis"],["şoför","haydovchi"],["aşçı","oshpaz"],["satıcı","sotuvchi"],["avukat","advokat"],["tercüman","tarjimon"]]}],"sections":[{"kind":"other","title":"Alifbo va talaffuz","blocks":[{"p":"Turkcha lotin yozuvida yoziladi va 29 ta harfdan iborat: 8 tasi unli, 21 tasi undosh. Oʻzbek lotin yozuvidagi q, x va w turkchada uchramaydi. Eng yoqimli tomoni: soʻz qanday yozilgan boʻlsa, deyarli shunday oʻqiladi."},{"p":"Oʻzbek oʻquvchisi uchun yangi yoki boshqacha oʻqiladigan harflar:"},{"table":{"h":["Harf","Qanday oʻqiladi","Misol","Maʼnosi"],"r":[["C c","«j» (joʻja dagi kabi)","cam","oyna, shisha"],["Ç ç","«ch»","çanta","sumka"],["Ğ ğ","oʻzi oʻqilmaydi, oldingi unlini choʻzadi","yağmur [ya:mur]","yomgʻir"],["I ı (nuqtasiz)","qisqa, orqa «i» (qiz, tish dagi kabi)","kırmızı","qizil"],["İ i (nuqtali)","oddiy «i» (bir, til dagi kabi)","bilet","chipta"],["J j","yumshoq «j» (jurnal dagi kabi)","jöle","jele"],["O o","oʻzbekcha «oʻ» ga yaqin","portakal","apelsin"],["Ö ö","lab choʻchchaygan, til oldinda (koʻk dagi kabi)","köprü","koʻprik"],["Ş ş","«sh»","şeker","shakar"],["U u","«u»","uzun","uzun"],["Ü ü","lab «u» holatida, til «i» holatida","ütü","dazmol"],["H h","«h»; oʻzbekcha «x» oʻrnida ham keladi","hasta","xasta, kasal"],["K k","«k»; oʻzbekcha «q» oʻrnida ham keladi","kapı","eshik (qopqa)"]]}},{"note":"Nuqta muhim! Katta harfga oʻtganda ham nuqta saqlanadi: ı → I, i → İ (İzmir → İZMİR, ılık → ILIK). Bitta nuqta maʼnoni oʻzgartiradi: kıl (tuk, qil) — kil (loy). Shuning uchun ı va i ni doim aniq yozing."},{"p":"Undoshlar haqida ikki kuzatuv. Birinchisi: turkcha soʻz deyarli hech qachon b, c, d, g bilan tugamaydi — oxirida p, ç, t, k turadi: dolap (shkaf), sağlıklı (sogʻlom), dört (toʻrt), köpek (it). Ikkinchisi: oʻzbekcha q va x oʻrniga turkchada koʻpincha k va h keladi: qor → kar, qiz → kız, xabar → haber, xalq → halk."}]},{"kind":"grammar","title":"Grammatika: Unli uygʻunligi (Ünlü uyumu)","blocks":[{"p":"Turkchani oʻrganishning kaliti — unli uygʻunligi. Qoʻshimcha oʻzicha bir xil boʻlmaydi: u soʻzning eng oxirgi unlisiga «ohangdosh» boʻlib oladi. Buning uchun unlilarni ikki oilaga ajratamiz:"},{"table":{"h":["Qalin (orqa) unlilar","Ingichka (old) unlilar"],"r":[["a, ı, o, u","e, i, ö, ü"]]}},{"p":"Ikki shaklli qoʻshimchalarda (a / e) qoida oddiy: oxirgi unli qalin boʻlsa — a, ingichka boʻlsa — e. Toʻrt shaklli qoʻshimchalar (ı / i / u / ü) bilan keyingi boʻlimda tanishasiz."},{"sub":"Koʻplik qoʻshimchasi: -lar / -ler"},{"table":{"h":["Oxirgi unli","Qoʻshimcha","Misollar"],"r":[["a, ı, o, u","-lar","masa → masalar, kız → kızlar, top → toplar, kuş → kuşlar"],["e, i, ö, ü","-ler","defter → defterler, şehir → şehirler, köy → köyler, ütü → ütüler"]]}},{"p":"Soʻzning birinchi unlisiga emas, oxirgisiga qarang: telefon soʻzida avval e, keyin o keladi — demak telefonlar. Dilnoza soʻzida oxirgi unli a — demak Dilnozalar."},{"note":"Son kelsa, ot birlikda qoladi: üç kedi (uchta mushuk), beş öğrenci (beshta oʻquvchi). «Üç kediler» deyilmaydi — oʻzbekchada ham «uchta mushuklar» demaymiz."},{"p":"Baʼzi chetdan kirgan soʻzlar qoidaga boʻysunmaydi va ingichka qoʻshimcha oladi: saat → saatler, dikkat → dikkatler, rol → roller. Bunday soʻzlar kam, ularni uchragan sari eslab qoling."}]},{"kind":"dialog","title":"Dialog: Kütüphanede tanışma","blocks":[{"dlg":[["Defne","Merhaba!"],["Dilnoza","Merhaba!"],["Defne","Benim adım Defne. Senin adın ne?"],["Dilnoza","Benim adım Dilnoza."],["Defne","Memnun oldum, Dilnoza."],["Dilnoza","Ben de memnun oldum."],["Defne","Nasılsın?"],["Dilnoza","İyiyim, teşekkür ederim. Sen nasılsın?"],["Defne","Ben de iyiyim. Hoş geldin!"],["Dilnoza","Hoş bulduk."],["Defne","Görüşürüz!"],["Dilnoza","Görüşürüz, hoşça kal!"]]},{"gloss":[["memnun oldum","tanishganimdan xursandman"],["hoş bulduk","«Xush kelibsiz»ga javob"],["görüşürüz","koʻrishguncha"]]}]}],"reading":{"text":"Sabah saat yedi. Kerem evde. Annesi: \"Günaydın, Kerem!\" Kerem: \"Günaydın, anne!\" Öğlen Kerem okulda. Öğretmen: \"İyi günler, çocuklar!\" Öğrenciler: \"İyi günler, hocam!\" Akşam Kerem parkta. Arkadaşı Deniz: \"İyi akşamlar, Kerem! Nasılsın?\" Kerem: \"İyiyim, teşekkürler.\" Gece saat on. Kerem yatakta. Babası: \"İyi geceler, oğlum!\" Kerem: \"İyi geceler, baba!\"","gloss":[["öğlen","tushda"],["yatak","karavot"],["oğlum","oʻgʻlim"],["hocam","ustoz"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Sabah Kerem okulda.","Öğretmen \"İyi günler\" diyor. (diyor — deyapti)","Akşam Kerem parkta.","Babası \"Günaydın\" diyor."],"title":"Kerem'in günü","ans":{"1":"Y","2":"D","3":"D","4":"Y"}},"exercises":[{"n":1,"title":"Soʻzlarning oxirgi unlisi qalinmi (Q) yoki incemi (İ)?","items":[["a","masa"],["b","defter"],["c","kapı"],["d","gözlük"],["e","çocuk"],["f","şehir"]],"ans":{"a":"Q","b":"İ","c":"Q","d":"İ","e":"Q","f":"İ"}},{"n":2,"title":"Koʻplik qoʻshimchasini qoʻshing (-lar / -ler).","items":[["a","ev →"],["b","masa →"],["c","göz →"],["d","çocuk →"],["e","gün →"],["f","kapı →"],["g","şehir →"],["h","okul →"]],"ans":{"a":"evler","b":"masalar","c":"gözler","d":"çocuklar","e":"günler","f":"kapılar","g":"şehirler","h":"okullar"}},{"n":3,"title":"Mos javobni toping.","items":[],"ans":{"1":"c","2":"d","3":"a","4":"e","5":"b"},"match":{"left":["Günaydın!","Nasılsın?","Hoş geldin!","Görüşürüz!","Adın ne?"],"right":["Hoş bulduk.","Benim adım Kerem.","Günaydın!","İyiyim, sağ ol.","Hoşça kal!"],"keys":["a","b","c","d","e"]}},{"n":4,"title":"Qaysi salom mos? (Günaydın / İyi günler / İyi akşamlar / İyi geceler)","items":[["a","08:00, darsga kirganda —"],["b","14:00, doʻkonda —"],["c","20:00, mehmonga kelganda —"],["d","23:00, uxlashga yotayotganda —"]],"ans":{"a":"Günaydın","b":"İyi günler","c":"İyi akşamlar","d":"İyi geceler"}},{"n":5,"title":"Salomlarni kun davomidagi tartibda joylashtiring:","items":[["1","2) 3) 4)"]],"extra":"İyi geceler · İyi akşamlar · Günaydın · İyi günler","ans":{"_":"Günaydın → İyi günler → İyi akşamlar → İyi geceler"}},{"n":6,"title":"Turkchaga tarjima qiling.","items":[["a","Salom! Mening ismim Kerem."],["b","Tanishganimdan xursandman."],["c","Qalaysan? — Yaxshiman, rahmat."],["d","Xayrli kech, Elif xonim!"]],"ans":{"a":"Merhaba! Benim adım Kerem.","b":"Memnun oldum.","c":"Nasılsın? — İyiyim, teşekkür ederim.","d":"İyi akşamlar, Elif Hanım!"}}]},{"id":"a1-2","level":"A1","n":2,"title":"Ben Kimim?","sub":"Kishilik olmoshlari · «-man, -san» qoʻshimchalari · değil · soʻroq yuklamasi mi","goals":["oʻzingizni tanishtirish","millat, shahar va kasb haqida gapirish","kishilik olmoshlari","kesimlik qoʻshimchalari -(y)Im, -sIn…","inkor değil","soʻroq mi","-lI qoʻshimchasi (Semerkantlı)"],"vocab":[{"title":"Lugʻat","words":[["ad","ism"],["meslek","kasb"],["soyadı","familiya"],["öğretmen","oʻqituvchi"],["yaş","yosh"],["öğrenci","talaba, oʻquvchi"],["ülke","mamlakat"],["doktor","shifokor"],["şehir","shahar"],["mühendis","muhandis"],["nereli?","qayerlik?"],["şoför","haydovchi"],["evli","uylangan / turmushga chiqqan"],["tercüman","tarjimon"],["bekâr","boʻydoq"],["aşçı","oshpaz"],["Özbek","oʻzbek"],["Türk","turk"],["Kazak / Kırgız / Türkmen","qozoq / qirgʻiz / turkman"],["Rus","rus"]]},{"title":"Mavzuli lugʻat — mamlakatlar va tillar","words":[["Özbekistan","Oʻzbekiston"],["Türkiye","Turkiya"],["Kazakistan","Qozogʻiston"],["Kırgızistan","Qirgʻiziston"],["Rusya","Rossiya"],["Almanya","Germaniya"],["Japonya","Yaponiya"],["Amerika","Amerika"],["Türkçe","turkcha, turk tili"],["Özbekçe","oʻzbekcha, oʻzbek tili"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Kishilik olmoshlari"},{"table":{"h":["Turkcha","Oʻzbekcha","Turkcha","Oʻzbekcha"],"r":[["ben","men","biz","biz"],["sen","sen","siz","siz (koʻplik yoki hurmat)"],["o","u","onlar","ular"]]}},{"p":"Oʻzbekchadagi kabi siz ham koʻplikni, ham hurmatni bildiradi. Elif Hoca bilan, doʻkondagi sotuvchi bilan yoki birinchi marta koʻrgan odam bilan siz deb gaplashing."},{"sub":"Toʻrt shaklli unli uygʻunligi"},{"p":"Koʻp qoʻshimchalardagi unli toʻrt xil boʻlishi mumkin: ı, i, u, ü. Qaysi biri kelishini yana soʻzning oxirgi unlisi hal qiladi:"},{"table":{"h":["Oxirgi unli","Qoʻshimchadagi unli","Misol"],"r":[["a yoki ı","ı","yazar → yazarım"],["e yoki i","i","öğretmen → öğretmenim"],["o yoki u","u","doktor → doktorum"],["ö yoki ü","ü","şoför → şoförüm"]]}},{"p":"Qoidalarda bunday qoʻshimchalarni katta I harfi bilan yozamiz: -Im degani -ım, -im, -um yoki -üm demakdir. Katta A esa ikki shaklni bildiradi: -lAr = -lar / -ler."},{"sub":"«Talabaman, shifokorman» — kesimlik qoʻshimchalari"},{"p":"Oʻzbekchada «Men oshpazman» deganimizdek, turkchada ham kasb yoki millatga qoʻshimcha qoʻshiladi: Ben aşçıyım."},{"table":{"h":["Shaxs","Qoʻshimcha","aşçı","pilot","memur","şoför"],"r":[["ben","-(y)Im","aşçıyım","pilotum","memurum","şoförüm"],["sen","-sIn","aşçısın","pilotsun","memursun","şoförsün"],["o","— (-DIr)","aşçı","pilot","memur","şoför"],["biz","-(y)Iz","aşçıyız","pilotuz","memuruz","şoförüz"],["siz","-sInIz","aşçısınız","pilotsunuz","memursunuz","şoförsünüz"],["onlar","-lAr","aşçılar","pilotlar","memurlar","şoförler"]]}},{"p":"Unli bilan tugagan soʻzga -Im va -Iz qoʻshilganda oraga y kiradi: aşçı → aşçıyım, öğrenci → öğrenciyiz. Undosh bilan tugasa, y kerak emas: pilot → pilotum."},{"p":"O shaxsida odatda hech narsa qoʻshilmaydi: Kerem öğrenci. Yozma, rasmiy matnda -DIr uchraydi: Müze pazartesi kapalıdır. (Muzey dushanba kuni yopiq.)"},{"note":"Koʻp boʻgʻinli soʻz k bilan tugasa va unga unli bilan boshlanadigan qoʻshimcha qoʻshilsa, k odatda ğ ga aylanadi: Özbek → Özbeğim (oʻzbekman). Bir boʻgʻinli soʻzlarda esa odatda oʻzgarmaydi: Türk → Türküm."},{"sub":"Inkor: değil"},{"p":"Inkor uchun değil soʻzi ishlatiladi va kesimlik qoʻshimchasi unga ulanadi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Ben pilot değilim.","Men uchuvchi emasman."],["Sen memur değilsin.","Sen xizmatchi emassan."],["Defne Özbek değil.","Defne oʻzbek emas."],["Biz turist değiliz.","Biz sayyoh emasmiz."],["Siz aşçı değilsiniz.","Siz oshpaz emassiz."],["Onlar kardeş değiller.","Ular aka-uka emas."]]}},{"sub":"Soʻroq: mı / mi / mu / mü"},{"p":"Soʻroq yuklamasi alohida yoziladi, lekin unli uygʻunligiga boʻysunadi. Kesimlik qoʻshimchasi aynan shu yuklamaga ulanadi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Ben haklı mıyım?","Men haqmanmi?"],["Sen Jasur musun?","Sen Jasurmisan?"],["Kerem öğrenci mi?","Kerem talabami?"],["Siz Türk müsünüz?","Siz turkmisiz?"],["Onlar arkadaş mı?","Ular doʻstmi?"]]}},{"p":"Qisqa javoblar: Evet, öğrenciyim. (Ha, talabaman.) — Hayır, öğrenci değilim, memurum. (Yoʻq, talaba emasman, xizmatchiman.)"},{"sub":"Qayerliksiz? — -lI qoʻshimchasi"},{"p":"-lı / -li / -lu / -lü qoʻshimchasi oʻzbekchadagi -lik ga mos keladi: İzmir → İzmirli, Taşkent → Taşkentli, Bursa → Bursalı, Konya → Konyalı. — Nerelisin? (Qayerliksan?) — Ben Taşkentliyim, Defne İzmirli. (Men toshkentlikman, Defne izmirlik.)"}]},{"kind":"dialog","title":"Dialog: Yeni komşu","blocks":[{"dlg":[["Defne","Merhaba! Sen yeni öğrenci misin?"],["Dilnoza","Evet, yeni öğrenciyim. Adım Dilnoza."],["Defne","Ben Defne. Türk müsün?"],["Dilnoza","Hayır, Türk değilim. Özbeğim, Buharalıyım. Sen nerelisin?"],["Defne","Ben İzmirliyim. Bu kim?"],["Dilnoza","Bu Jasur. O da Özbek."],["Jasur","Merhaba! Ben Taşkentliyim."],["Defne","Siz de öğrenci misiniz?"],["Jasur","Hayır, ben öğrenci değilim. Mühendisim."],["Defne","Çok güzel! Hoş geldiniz."],["Dilnoza","Hoş bulduk!"]]},{"gloss":[["yeni","yangi"],["komşu","qoʻshni"],["nerelisin","qayerliksan"],["da / de","ham"],["mühendis","muhandis"]]}]}],"reading":{"text":"Merhaba! Benim adım Dilnoza. Ben Özbeğim, Buharalıyım. Yirmi yaşındayım ve öğrenciyim. Bu Jasur. O Taşkentli. Jasur öğrenci değil, mühendis. Bu da Defne. Defne Türk, İzmirli. O hemşire. Biz arkadaşız. Elif Hoca bizim öğretmenimiz. O çok iyi bir öğretmen.","gloss":[["yaşındayım","yoshdaman"],["hemşire","hamshira"],["arkadaş","doʻst"],["bizim öğretmenimiz","bizning oʻqituvchimiz"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Dilnoza nereli?","Dilnoza kaç yaşında?","Jasur öğrenci mi?","Defne doktor mu?","Öğretmen kim?"],"title":"Yeni arkadaşlar","ans":{"1":"Dilnoza Buharalı.","2":"Yirmi yaşında.","3":"Hayır, öğrenci değil, mühendis.","4":"Hayır, doktor değil, hemşire.","5":"Öğretmen Elif Hoca."}},"exercises":[{"n":1,"title":"Kesimlik qoʻshimchasini qoʻshing.","items":[["a","Ben mühendis___."],["b","Sen öğrenci___."],["c","Biz Özbek___."],["d","Siz doktor___."],["e","Ben Buharalı___."],["f","Onlar hemşire___."],["g","Sen Türk___."],["h","Biz arkadaş___."]],"ans":{"a":"mühendisim","b":"öğrencisin","c":"Özbeğiz","d":"doktorsunuz","e":"Buharalıyım","f":"hemşireler","g":"Türksün","h":"arkadaşız"}},{"n":2,"title":"Gaplarni inkorga aylantiring.","items":[["a","Ben öğretmenim. →"],["b","Sen hemşiresin. →"],["c","O mühendis. →"],["d","Biz Türk'üz. →"],["e","Siz yorgunsunuz. →"]],"ans":{"a":"Ben öğretmen değilim.","b":"Sen hemşire değilsin.","c":"O mühendis değil.","d":"Biz Türk değiliz.","e":"Siz yorgun değilsiniz."}},{"n":3,"title":"Soʻroq gap tuzing (mı / mi / mu / mü).","items":[["a","Sen doktor ___?"],["b","O öğrenci ___?"],["c","Siz Özbek ___?"],["d","Onlar Türk ___?"],["e","Sen yorgun ___?"]],"ans":{"a":"musun","b":"mi","c":"misiniz","d":"mü","e":"musun"}},{"n":4,"title":"-lı / -li / -lu / -lü qoʻshing.","items":[["a","Buhara →"],["b","İzmir →"],["c","Semerkant →"],["d","İstanbul →"],["e","Ürgenç →"],["f","Bursa →"],["g","Özbekistan →"]],"ans":{"a":"Buharalı","b":"İzmirli","c":"Semerkantlı","d":"İstanbullu","e":"Ürgençli","f":"Bursalı","g":"Özbekistanlı"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Men talabaman, buxorolikman."],["b","U muhandis emas, oʻqituvchi."],["c","Siz turkmisiz?"],["d","Biz doʻstmiz."],["e","Sen qayerliksan?"]],"ans":{"a":"Ben öğrenciyim, Buharalıyım.","b":"O mühendis değil, öğretmen.","c":"Siz Türk müsünüz?","d":"Biz arkadaşız.","e":"Sen nerelisin?"}},{"n":6,"title":"Yozish. Oʻzingiz haqingizda 5–6 gap yozing: ism, millat, shahar, yosh, kasb.","items":[],"ans":{"_":"Merhaba! Benim adım Madina. Ben Özbeğim, Namanganlıyım. Yirmi iki yaşındayım. Öğrenci değilim, hemşireyim. Memnun oldum!"},"sample":true}]},{"id":"a1-3","level":"A1","n":3,"title":"Burası Neresi?","sub":"bu / şu / o · var / yok · oʻrin-payt kelishigi -DA · Nerede?","goals":["narsa va joylarni koʻrsatish","biror narsa bor yoki yoʻqligini aytish","«qayerda?» savoliga javob berish","uy va shahar lugʻati","-da / -de / -ta / -te qoʻshimchasi"],"vocab":[{"title":"Lugʻat","words":[["kapı","eshik"],["masa","stol"],["pencere","deraza"],["sandalye","stul"],["yatak","karavot, oʻrin"],["dolap","shkaf"],["oda","xona"],["banyo / duş","hammom / dush"],["tuvalet","hojatxona"],["kütüphane","kutubxona"],["burada / şurada / orada","bu yerda / shu yerda / u yerda"],["sağda / solda","oʻngda / chapda"],["ileride","oldinda, narida"],["karşıda","qarshida"],["var","bor"],["yok","yoʻq"]]},{"title":"Mavzuli lugʻat — shaharda (şehirde)","words":[["okul","maktab"],["hastane","kasalxona"],["eczane","dorixona"],["banka","bank"],["market","doʻkon, supermarket"],["postane","pochta"],["park","bogʻ, park"],["otobüs durağı","avtobus bekati"],["lokanta","restoran, oshxona"],["çarşı","bozor"],["cadde / sokak","katta koʻcha / koʻcha"],["müze","muzey"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"bu / şu / o"},{"table":{"h":["Olmosh","Maʼnosi","Misol"],"r":[["bu","bu (qoʻl yetadigan joyda)","Bu ne? — Bu bir harita."],["şu","shu (sal nariroqda, koʻrsatib)","Şu kim? — Şu Murat Bey."],["o","u (uzoqda)","O ne? — O bir köprü."],["bunlar / şunlar / onlar","bular / shular / ular","Bunlar ne? — Bunlar anahtarlar."]]}},{"gloss":[["Ne?","nima? (narsa haqida)"],["Kim?","kim? (odam haqida)"],["Burası neresi?","bu yer qayer?"],["Burası kütüphane.","bu yer — kutubxona."]]},{"sub":"Oʻrin-payt kelishigi: -DA"},{"p":"Bu qoʻshimcha oʻzbekchadagi -da ning aynan oʻzi: bozorda → pazarda. Farqi shundaki, turkchada uning toʻrt shakli bor: unli uygʻunligi a / e ni, oxirgi undosh esa d / t ni tanlaydi."},{"table":{"h":["Oxirgi unli","Unli yoki jarangli undoshdan keyin","Jarangsiz undoshdan keyin (f, s, t, k, ç, ş, h, p)"],"r":[["qalin (a, ı, o, u)","-da: odada, mağazada, salonda","-ta: parkta, sokakta, kitapta"],["ingichka (e, i, ö, ü)","-de: evde, köyde, İzmir'de","-te: sepette, otobüste, Taşkent'te"]]}},{"note":"Jarangsiz undoshlarni bitta kulgili ibora bilan yodlang: FıSTıKÇı ŞaHaP (f, s, t, k, ç, ş, h, p). Soʻz shu harflardan biriga tugasa, d oʻrniga t keladi: kitap → kitapta. Shahar, davlat va ism kabi atoqli otlarda qoʻshimcha apostrof bilan ajratiladi: İzmir'de, Türkiye'de, Taşkent'te."},{"p":"-DA ga kesimlik qoʻshimchasi qoʻshilsa, «…daman, …dasan» maʼnosi chiqadi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Ben kütüphanedeyim.","Men kutubxonadaman."],["Sen neredesin?","Sen qayerdasan?"],["Pamuk balkonda.","Pamuk balkonda."],["Biz otobüsteyiz.","Biz avtobusdamiz."],["Siz mutfakta mısınız?","Siz oshxonadamisiz?"]]}},{"sub":"var / yok"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Mutfakta iki sandalye var.","Oshxonada ikkita stul bor."],["Bahçede havuz yok.","Bogʻda hovuz yoʻq."],["Buzdolabında süt var mı?","Muzlatgichda sut bormi?"],["— Evet, var. / — Hayır, yok.","— Ha, bor. / — Yoʻq."]]}},{"p":"Tartib oddiy: avval joy, keyin narsa, oxirida var yoki yok. Son ishlatilsa, ot birlikda qoladi: iki sandalye (ikki stullar ✘)."}]},{"kind":"dialog","title":"Dialog: Öğrenci yurdunda","blocks":[{"dlg":[["Dilnoza","Affedersiniz, burası neresi?"],["Görevli","Burası öğrenci yurdu. Hoş geldiniz!"],["Dilnoza","Teşekkürler. Benim odam nerede?"],["Görevli","Odanız ikinci katta, solda."],["Dilnoza","Odada masa var mı?"],["Görevli","Evet, bir masa, bir yatak ve bir dolap var."],["Dilnoza","Buzdolabı da var mı?"],["Görevli","Hayır, odada buzdolabı yok. Buzdolabı mutfakta."],["Dilnoza","Mutfak nerede?"],["Görevli","Mutfak birinci katta, sağda. Şu kapı."],["Dilnoza","Çok teşekkür ederim."],["Görevli","Rica ederim."]]},{"gloss":[["yurt","yotoqxona"],["görevli","xodim"],["kat","qavat"],["solda / sağda","chapda / oʻngda"],["buzdolabı","muzlatgich"],["mutfak","oshxona"]]}]}],"reading":{"text":"Burası bizim sınıf. Sınıf büyük ve temiz. Sınıfta on masa ve yirmi sandalye var. Duvarda bir harita ve bir saat var. Öğretmen masası solda. Masada bir bilgisayar var. Sınıfta televizyon yok. Kitaplar dolapta. Şu anda sınıfta beş öğrenci var. Öğretmen sınıfta değil, o kütüphanede. Kütüphane ikinci katta.","gloss":[["temiz","toza"],["sandalye","stul"],["duvar","devor"],["harita","xarita"],["şu anda","hozir"],["kütüphane","kutubxona"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Sınıf küçük.","Duvarda harita var.","Sınıfta televizyon var.","Kitaplar dolapta.","Öğretmen şu anda sınıfta."],"title":"Bizim sınıf","ans":{"1":"Y","2":"D","3":"Y","4":"D","5":"Y"}},"exercises":[{"n":1,"title":"-da / -de / -ta / -te qoʻshing.","items":[["a","ev →"],["b","sınıf →"],["c","park →"],["d","kütüphane →"],["e","mutfak →"],["f","İzmir →"],["g","sokak →"],["h","oda →"],["i","otobüs →"],["j","Buhara →"]],"ans":{"a":"evde","b":"sınıfta","c":"parkta","d":"kütüphanede","e":"mutfakta","f":"İzmir'de","g":"sokakta","h":"odada","i":"otobüste","j":"Buhara'da"}},{"n":2,"title":"var yoki yok bilan gap tuzing.","items":[["a","Sınıfta / harita →"],["b","Mutfakta / televizyon →"],["c","Parkta / çocuklar →"],["d","Çantada / kalem →"]],"ans":{"a":"Sınıfta harita var.","b":"Mutfakta televizyon yok.","c":"Parkta çocuklar var.","d":"Çantada kalem yok."},"sample":true},{"n":3,"title":"Savolga javob bering: Neredesin?","items":[["a","(ev) → Evdeyim."],["b","(kütüphane) →"],["c","(mutfak) →"],["d","(otobüs) →"],["e","(sınıf) →"]],"ans":{"b":"Kütüphanedeyim.","c":"Mutfaktayım.","d":"Otobüsteyim.","e":"Sınıftayım."}},{"n":4,"title":"bu / şu / o, ne / kim bilan boʻsh joyni toʻldiring.","items":[["a","___ ne? — Bu bir harita."],["b","Şu ___? — Şu, Defne."],["c","Bu ___? — Bu bir sandalye."],["d","Burası ___? — Burası kütüphane."]],"ans":{"a":"Bu","b":"kim","c":"ne","d":"neresi"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Oshxona qayerda? — Oshxona chapda."],["b","Xonada stol bor."],["c","Sinfda televizor yoʻq."],["d","Bu nima? — Bu xarita."],["e","Men kutubxonadaman."]],"ans":{"a":"Mutfak nerede? — Mutfak solda.","b":"Odada masa var.","c":"Sınıfta televizyon yok.","d":"Bu ne? — Bu bir harita.","e":"Ben kütüphanedeyim."}},{"n":6,"title":"Yozish. Xonangizni yoki uyingizni tasvirlang (5 gap): nima bor, nima yoʻq, qayerda.","items":[],"ans":{"_":"Bu bizim ev. Evde üç oda ve bir mutfak var. Benim odamda bir yatak ve bir masa var. Odada televizyon yok. Kitaplar masada."},"sample":true}]},{"id":"a1-4","level":"A1","n":4,"title":"Saat Kaç?","sub":"Sonlar · tartib sonlar · soat va vaqt · hafta kunlari va oylar","goals":["0 dan 1 000 000 gacha sonlar","tartib sonlar (birinci, ikinci…)","soatni aytish va soʻrash","«soat nechada?»","hafta kunlari, oylar","kun tartibi lugʻati"],"vocab":[{"title":"Lugʻat","words":[["saat","soat"],["gün","kun"],["dakika","daqiqa"],["hafta","hafta"],["saniye","soniya"],["ay","oy"],["buçuk","yarim (…-u yarim)"],["yıl","yil"],["çeyrek","chorak"],["bugün / yarın / dün","bugun / ertaga / kecha"],["sabah / öğle / akşam / gece","ertalab / tush / kechqurun / kechasi"],["Kaç? / Kaç tane?","Necha? / Nechta?"]]},{"title":"Mavzuli lugʻat — kun tartibi (günlük program)","words":[["kalkış","uygʻonish, turish"],["kahvaltı","nonushta"],["öğle yemeği","tushlik"],["akşam yemeği","kechki ovqat"],["ders","dars"],["ders çalışma","dars tayyorlash"],["toplantı","yigʻilish"],["randevu","uchrashuv, qabulga yozilish"],["alışveriş","xarid qilish"],["serbest zaman","boʻsh vaqt"],["spor","sport"],["uyku / yatış","uyqu / uxlash vaqti"]]}],"sections":[{"kind":"other","title":"Sonlar","blocks":[{"table":{"h":["0 sıfır","1 bir","2 iki","3 üç","4 dört","5 beş"],"r":[["6 altı","7 yedi","8 sekiz","9 dokuz","10 on","11 on bir"],["20 yirmi","30 otuz","40 kırk","50 elli","60 altmış","70 yetmiş"],["80 seksen","90 doksan","100 yüz","1 000 bin","1 000 000 bir milyon","1 000 000 000 bir milyar"]]}},{"p":"Katta sonlar oʻzbekchadagidek, chapdan oʻngga qoʻshib aytiladi: 47 kırk yedi · 812 sekiz yüz on iki · 2026 iki bin yirmi altı."},{"note":"Yüz (100) va bin (1000) oldidan bir aytilmaydi: yüz lira, bin kişi. Milyon va milyar oldidan esa aytiladi: bir milyon."},{"sub":"Tartib sonlar: -(I)ncI"},{"table":{"h":["Tartib son","Maʼnosi","Tartib son","Maʼnosi"],"r":[["birinci","birinchi","altıncı","oltinchi"],["ikinci","ikkinchi","yedinci","yettinchi"],["üçüncü","uchinchi","sekizinci","sakkizinchi"],["dördüncü","toʻrtinchi","dokuzuncu","toʻqqizinchi"],["beşinci","beshinchi","onuncu","oʻninchi"]]}},{"p":"Yozuvda raqamdan keyin nuqta qoʻyiladi: 3. kat (uchinchi qavat), 5. sınıf (beshinchi sinf), 1. gün (birinchi kun)."}]},{"kind":"grammar","title":"Grammatika: Soat","blocks":[{"sub":"Saat kaç? (Soat necha?)"},{"table":{"h":["Vaqt","Turkcha","Qanday tuziladi"],"r":[["8:00","Saat sekiz.","butun soat"],["8:30","Saat sekiz buçuk.","soat + buçuk (yarim)"],["12:30","Saat yarım.","faqat 12:30 va 00:30 uchun"],["8:15","Saat sekizi çeyrek geçiyor.","soat (-I) + daqiqa + geçiyor (oʻtyapti)"],["8:20","Saat sekizi yirmi geçiyor.","soat (-I) + daqiqa + geçiyor"],["8:45","Saat dokuza çeyrek var.","keyingi soat (-A) + daqiqa + var (qoldi)"],["8:55","Saat dokuza beş var.","keyingi soat (-A) + daqiqa + var"]]}},{"sub":"Saat kaçta? (Soat nechada?)"},{"p":"Biror ish qachon boʻlishini aytganda, soat -DA kelishigini oladi, geçiyor → geçe, var → kala boʻladi:"},{"table":{"h":["Vaqt","Saat kaç?","Saat kaçta?"],"r":[["9:00","Saat dokuz.","Saat dokuzda."],["9:30","Saat dokuz buçuk.","Saat dokuz buçukta."],["9:10","Saat dokuzu on geçiyor.","Saat dokuzu on geçe."],["9:50","Saat ona on var.","Saat ona on kala."]]}},{"sub":"Soatlarning kelishik shakllari"},{"table":{"h":["Soat","…-I (geçiyor)","…-A (var)","…-DA (kaçta)"],"r":[["1","biri","bire","birde"],["2","ikiyi","ikiye","ikide"],["3","üçü","üçe","üçte"],["4","dördü","dörde","dörtte"],["5","beşi","beşe","beşte"],["6","altıyı","altıya","altıda"],["7","yediyi","yediye","yedide"],["8","sekizi","sekize","sekizde"],["9","dokuzu","dokuza","dokuzda"],["10","onu","ona","onda"],["11","on biri","on bire","on birde"],["12","on ikiyi","on ikiye","on ikide"]]}},{"p":"Avtobus, poyezd va televizor jadvallarida 24 soatlik yozuv ishlatiladi: 07.15 — yedi on beş, 19.40 — on dokuz kırk. Qoʻshimcha apostrof bilan qoʻshiladi: Vapur 07.15'te kalkıyor. (Parom 7:15 da joʻnaydi.)"},{"sub":"Kunlar va sanalar"},{"p":"Hafta kunlari gap ichida kichik harf bilan yoziladi: Bu cuma Kemeraltı'na gidiyoruz. (Shu juma Kemeraltıga boramiz.) Sanani soʻrash: Bugün ayın kaçı? — Bugün on dört Mart. (Bugun 14-mart.) Hafta sonu — shanba va yakshanba."}]},{"kind":"dialog","title":"Dialog: Otobüs saat kaçta?","blocks":[{"dlg":[["Dilnoza","İyi günler! Bugün Bursa'ya otobüs var mı?"],["Görevli","Var. Bugün üç otobüs var."],["Dilnoza","İlk otobüs saat kaçta?"],["Görevli","İlk otobüs saat dokuzda."],["Dilnoza","Şimdi saat kaç?"],["Görevli","Saat dokuzu çeyrek geçiyor. İlk otobüs artık yok."],["Dilnoza","İkinci otobüs ne zaman?"],["Görevli","İkinci otobüs saat on bir buçukta."],["Dilnoza","Yolculuk kaç saat?"],["Görevli","İki buçuk saat. Saat ikide Bursa'dasınız."],["Dilnoza","Bir bilet lütfen. Kaç lira?"],["Görevli","Üç yüz elli lira."],["Dilnoza","Buyurun. Teşekkürler!"]]},{"gloss":[["ilk","birinchi"],["çeyrek","chorak"],["geçiyor","oʻtyapti"],["artık","endi"],["ne zaman","qachon"],["yolculuk","safar"],["bilet","chipta"]]}]}],"reading":{"text":"Dilnoza'nın Türkçe kursu pazartesi, çarşamba ve cuma günleri. Ders saat dokuzda başlıyor ve saat on ikide bitiyor. Öğle yemeği saat yarımda. Salı günü saat üçte kütüphanede konuşma kulübü var. Perşembe günü Dilnoza serbest. Cumartesi sabah saat onda pazar var, akşam saat yedi buçukta sinema var. Pazar günü ders yok. Dilnoza pazar günü saat on birde annesiyle telefonda konuşuyor. Kurs haziranda bitiyor.","gloss":[["başlıyor","boshlanadi"],["bitiyor","tugaydi"],["öğle yemeği","tushlik"],["konuşma kulübü","suhbat klubi"],["serbest","boʻsh"],["pazar","bozor; yakshanba"],["annesiyle","onasi bilan"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Kurs hangi günler?","Ders saat kaçta başlıyor?","Konuşma kulübü ne zaman?","Sinema saat kaçta?","Kurs hangi ayda bitiyor?"],"title":"Dilnoza'nın haftası","ans":{"1":"Pazartesi, çarşamba ve cuma günleri.","2":"Saat dokuzda başlıyor.","3":"Salı günü saat üçte.","4":"Saat yedi buçukta.","5":"Haziranda bitiyor."}},"exercises":[{"n":1,"title":"Sonlarni soʻz bilan yozing.","items":[["a","14"],["b","38"],["c","76"],["d","105"],["e","250"],["f","1991"],["g","2026"]],"ans":{"a":"on dört","b":"otuz sekiz","c":"yetmiş altı","d":"yüz beş","e":"iki yüz elli","f":"bin dokuz yüz doksan bir","g":"iki bin yirmi altı"}},{"n":2,"title":"Saat kaç? Turkcha yozing.","items":[["a","7:00"],["b","10:30"],["c","12:30"],["d","3:15"],["e","5:45"],["f","9:10"],["g","1:50"]],"ans":{"a":"Saat yedi.","b":"Saat on buçuk.","c":"Saat yarım.","d":"Saat üçü çeyrek geçiyor.","e":"Saat altıya çeyrek var.","f":"Saat dokuzu on geçiyor.","g":"Saat ikiye on var."}},{"n":3,"title":"Saat kaçta? Jumlani toʻldiring.","items":[["a","Ders saat (9:00) ___ başlıyor."],["b","Öğle yemeği saat (12:30) ___."],["c","Otobüs saat (11:30) ___ kalkıyor."],["d","Sinema saat (7:30) ___."]],"ans":{"a":"dokuzda","b":"yarımda","c":"on bir buçukta","d":"yedi buçukta"}},{"n":4,"title":"Tartib son bilan yozing.","items":[["a","2. kat → ___ kat"],["b","1. otobüs → ___ otobüs"],["c","6. ders → ___ ders"],["d","9. ay → ___ ay"]],"ans":{"a":"ikinci","b":"birinci","c":"altıncı","d":"dokuzuncu"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Bugun juma."],["b","Dars soat oʻnda boshlanadi."],["c","Soat necha? — Soat uch yarim."],["d","Kurs iyunda tugaydi."]],"ans":{"a":"Bugün cuma.","b":"Ders saat onda başlıyor.","c":"Saat kaç? — Saat üç buçuk.","d":"Kurs haziranda bitiyor."}}]},{"id":"a1-5","level":"A1","n":5,"title":"Ne Yapıyorsun?","sub":"Hozirgi zamon -(I)yor · inkor va soʻroq · kun tartibi","goals":["feʼlning noaniq shakli (-mak/-mek)","hozirgi zamon -(I)yor","inkor -mIyor","soʻroq mu","kundalik ishlar va kun tartibi haqida gapirish"],"vocab":[{"title":"Lugʻat","words":[["kalkmak","turmoq"],["çalışmak","ishlamoq; oʻqimoq (darsga tayyorlanmoq)"],["uyanmak","uygʻonmoq"],["okumak","oʻqimoq"],["yıkanmak","yuvinmoq"],["yazmak","yozmoq"],["giyinmek","kiyinmoq"],["dinlemek","tinglamoq"],["kahvaltı yapmak","nonushta qilmoq"],["konuşmak","gaplashmoq"],["yemek","yemoq"],["beklemek","kutmoq"],["içmek","ichmoq"],["gitmek / gelmek","bormoq / kelmoq"],["koşmak","yugurmoq"],["dinlenmek","dam olmoq"],["yürümek","yurmoq"],["uyumak","uxlamoq"],["temizlemek","tozalamoq"],["şimdi / şu anda","hozir / ayni paytda"]]},{"title":"Mavzuli lugʻat — uy ishlari va boʻsh vaqt","words":[["yemek pişirmek","ovqat pishirmoq"],["bulaşık yıkamak","idish yuvmoq"],["çamaşır yıkamak","kir yuvmoq"],["odayı toplamak","xonani yigʻishtirmoq"],["alışveriş yapmak","xarid qilmoq"],["televizyon izlemek","televizor koʻrmoq"],["müzik dinlemek","musiqa tinglamoq"],["telefon etmek","qoʻngʻiroq qilmoq"],["ders çalışmak","dars tayyorlamoq"],["spor yapmak","sport bilan shugʻullanmoq"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Feʼlning noaniq shakli"},{"p":"Lugʻatda feʼllar -mak / -mek bilan beriladi — bu oʻzbekchadagi -moq: içmek — ichmoq, uyumak — uxlamoq. Shu qoʻshimchani olib tashlasak, feʼl oʻzagi qoladi: iç-, uyu-, bak-."},{"sub":"Hozirgi zamon: -(I)yor"},{"p":"Oʻzak + (I)yor + shaxs qoʻshimchasi. Maʼnosi oʻzbekchadagi -yapman, -yapsan… ga yaqin."},{"table":{"h":["Shaxs","içmek","bakmak","okumak","gülmek","uyumak"],"r":[["ben","içiyorum","bakıyorum","okuyorum","gülüyorum","uyuyorum"],["sen","içiyorsun","bakıyorsun","okuyorsun","gülüyorsun","uyuyorsun"],["o","içiyor","bakıyor","okuyor","gülüyor","uyuyor"],["biz","içiyoruz","bakıyoruz","okuyoruz","gülüyoruz","uyuyoruz"],["siz","içiyorsunuz","bakıyorsunuz","okuyorsunuz","gülüyorsunuz","uyuyorsunuz"],["onlar","içiyorlar","bakıyorlar","okuyorlar","gülüyorlar","uyuyorlar"]]}},{"p":"Qoidalar. 1) Oʻzak undosh bilan tugasa, oraga toʻrt shaklli unli kiradi: iç-i-yor, bak-ı-yor, gül-ü-yor. 2) Oʻzak ı, i, u, ü bilan tugasa, faqat yor qoʻshiladi: oku-yor, uyu-yor. 3) Oʻzak a yoki e bilan tugasa, bu unli toʻrt shaklli unliga almashadi: ara → arıyor, dinle → dinliyor, oyna → oynuyor, izle → izliyor. 4) Baʼzi oʻzaklarda t → d: git → gidiyor, et → ediyor. 5) Ikki istisno: ye → yiyor, de → diyor."},{"note":"yor dagi o tufayli shaxs qoʻshimchalari doim u bilan keladi: -um, -sun, -uz, -sunuz. Pamuk uyuyor, Dilnoza kitap okuyor, biz televizyon izliyoruz."},{"sub":"Inkor: -mIyor"},{"p":"Oʻzakdan keyin m va toʻrt shaklli unli keladi: içmiyorum (ichmayapman), bakmıyorsun, okumuyor, gülmüyoruz."},{"p":"Kerem bugün kahve içmiyor, çay içiyor. — Kerem bugun qahva ichmayapti, choy ichyapti."},{"sub":"Soʻroq: mu"},{"p":"Bu zamonda soʻroq yuklamasi doim mu boʻladi va alohida yoziladi; shaxs qoʻshimchasi unga qoʻshiladi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Doğru söylüyor muyum?","Toʻgʻri aytyapmanmi?"],["Beni dinliyor musun?","Meni tinglayapsanmi?"],["Pamuk uyuyor mu?","Pamuk uxlayaptimi?"],["Yağmur yağıyor mu?","Yomgʻir yogʻyaptimi?"],["Bizi bekliyor musunuz?","Bizni kutyapsizmi?"],["Onlar geliyorlar mı?","Ular kelyaptilarmi?"]]}},{"p":"Savol soʻzi boʻlsa, mu kerak emas: Ne izliyorsun? (Nimani tomosha qilyapsan?) · Nereye gidiyorsunuz? · Kim arıyor?"},{"sub":"Qachon ishlatiladi?"},{"p":"-(I)yor uchta holatda keladi: (1) aynan hozir boʻlayotgan ish: Şu an yemek pişiriyorum. (2) yaqin kelajakdagi aniq reja: Yarın İzmir'e dönüyoruz. (3) soʻzlashuvda — odat boʻlib qolgan ish: Her sabah yedide uyanıyorum. Odatiy ishlar uchun alohida zamon ham bor, uni A2 da oʻrganasiz."}]},{"kind":"dialog","title":"Dialog: Görüntülü arama","blocks":[{"dlg":[["Kamila","Alo, ağabey! Nasılsın?"],["Jasur","İyiyim Kamila. Sen ne yapıyorsun?"],["Kamila","Ödev yapıyorum. Sen ne yapıyorsun?"],["Jasur","Yemek pişiriyorum."],["Kamila","Sen mi? Ne pişiriyorsun?"],["Jasur","Pilav pişiriyorum ama çok yavaş oluyor."],["Kamila","Annem gülüyor! O da seni dinliyor."],["Jasur","Babam ne yapıyor?"],["Kamila","Bahçede çalışıyor. Orada hava nasıl?"],["Jasur","Burada yağmur yağıyor. Sizde?"],["Kamila","Bizde hava çok sıcak."],["Jasur","Eyvah, pilav yanıyor! Kapatıyorum!"],["Kamila","Görüşürüz ağabey!"]]},{"gloss":[["görüntülü arama","videoqoʻngʻiroq"],["ödev","uy vazifasi"],["pişirmek","pishirmoq"],["yavaş","sekin"],["gülmek","kulmoq"],["bahçe","bogʻ"],["yanmak","kuymoq"],["kapatmak","(goʻshakni) qoʻymoq"]]}]}],"reading":{"text":"Bugün cumartesi. Saat on. Defne'nin ailesi evde. Annesi mutfakta kahvaltı hazırlıyor. Babası balkonda gazete okuyor ve çay içiyor. Kardeşi Can odasında bilgisayar oyunu oynuyor. Dedesi salonda televizyon izliyor ama uyuyor! Defne bahçede çiçekleri suluyor. Kedi Pamuk onu izliyor. Şimdi anne sesleniyor: \"Kahvaltı hazır!\" Herkes mutfağa geliyor ama Can gelmiyor. O hâlâ oynuyor.","gloss":[["hazırlamak","tayyorlamoq"],["gazete","gazeta"],["çiçek","gul"],["sulamak","sugʻormoq"],["seslenmek","chaqirmoq"],["herkes","hamma"],["hâlâ","hali ham"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Annesi ne yapıyor?","Babası ne içiyor?","Can ne yapıyor?","Defne nerede, ne yapıyor?","Kim kahvaltıya gelmiyor?"],"title":"Cumartesi sabahı","ans":{"1":"Mutfakta kahvaltı hazırlıyor.","2":"Çay içiyor.","3":"Bilgisayar oyunu oynuyor.","4":"Bahçede çiçekleri suluyor.","5":"Can gelmiyor."}},"exercises":[{"n":1,"title":"Feʼlni -(I)yor bilan tuslang.","items":[["a","Ben yemek (pişirmek) ___."],["b","Sen kitap (okumak) ___."],["c","Dedem (uyumak) ___."],["d","Biz müzik (dinlemek) ___."],["e","Siz mektup (yazmak) ___."],["f","Çocuklar (oynamak) ___."],["g","Ben pazara (gitmek) ___."],["h","Kedi süt (içmek) ___."]],"ans":{"a":"pişiriyorum","b":"okuyorsun","c":"uyuyor","d":"dinliyoruz","e":"yazıyorsunuz","f":"oynuyorlar","g":"gidiyorum","h":"içiyor"}},{"n":2,"title":"Inkor shaklga oʻtkazing.","items":[["a","Ben gazete okuyorum. →"],["b","Biz televizyon izliyoruz. →"],["c","O bahçede çalışıyor. →"],["d","Sen ödev yapıyorsun. →"]],"ans":{"a":"Ben gazete okumuyorum.","b":"Biz televizyon izlemiyoruz.","c":"O bahçede çalışmıyor.","d":"Sen ödev yapmıyorsun."}},{"n":3,"title":"Soʻroq gap tuzing.","items":[["a","Sen / yemek pişirmek → ___?"],["b","Siz / Türkçe konuşmak → ___?"],["c","O / uyumak → ___?"],["d","Onlar / oyun oynamak → ___?"]],"ans":{"a":"Sen yemek pişiriyor musun?","b":"Siz Türkçe konuşuyor musunuz?","c":"O uyuyor mu?","d":"Onlar oyun oynuyorlar mı?"}},{"n":4,"title":"Kim nima qilyapti? Toʻliq gap yozing.","items":[["a","Defne — çiçekleri (sulamak)"],["b","Dedem — televizyon (izlemek)"],["c","Çocuklar — parkta (koşmak)"],["d","Jasur — pilav (pişirmek)"]],"ans":{"a":"Defne çiçekleri suluyor.","b":"Dedem televizyon izliyor.","c":"Çocuklar parkta koşuyor.","d":"Jasur pilav pişiriyor."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Nima qilyapsan? — Uy vazifasi qilyapman."],["b","Otam bogʻda ishlayapti."],["c","Biz hozir televizor koʻrmayapmiz."],["d","Yomgʻir yogʻyaptimi?"]],"ans":{"a":"Ne yapıyorsun? — Ödev yapıyorum.","b":"Babam bahçede çalışıyor.","c":"Biz şimdi televizyon izlemiyoruz.","d":"Yağmur yağıyor mu?"}},{"n":6,"title":"Yozish. Oʻz kun tartibingizni yozing (6–8 gap, -(I)yor bilan).","items":[],"ans":{}}]},{"id":"a1-6","level":"A1","n":6,"title":"Benim Ailem","sub":"Egalik qoʻshimchalari · qaratqich kelishigi -(n)In · ot birikmalari · «menda … bor»","goals":["oila aʼzolari","egalik qoʻshimchalari (evim, evin, evi…)","qaratqich -(n)In (Aziz'in, öğretmenin)","ot birikmalari (Aziz'in babası, okul kapısı)","«Benim iki kardeşim var»"],"vocab":[{"title":"Lugʻat","words":[["aile","oila"],["ağabey (abi)","aka"],["anne","ona"],["abla","opa"],["baba","ota"],["kardeş","uka, singil; aka-uka"],["eş","turmush oʻrtoq"],["erkek kardeş / kız kardeş","uka / singil"],["oğul","oʻgʻil"],["amca / dayı","amaki / togʻa"],["kız","qiz"],["hala / teyze","amma / xola"],["çocuk","bola"],["dede / nine (büyükanne)","bobo / buvi"],["torun","nevara"],["akraba","qarindosh"],["genç / yaşlı","yosh / qari"],["uzun boylu / kısa boylu","baland boʻyli / past boʻyli"]]},{"title":"Mavzuli lugʻat — kengroq qarindosh va yaqinlar","words":[["gelin","kelin"],["damat","kuyov"],["kayınpeder","qaynota"],["kayınvalide","qaynona"],["yeğen","jiyan"],["kuzen","amakivachcha, xolavachcha"],["komşu","qoʻshni"],["arkadaş","doʻst, oʻrtoq"],["nişanlı","unashtirilgan"],["doğum günü","tugʻilgan kun"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Egalik qoʻshimchalari"},{"p":"Oʻzbekchadagi kitobim, kitobing, kitobi… kabi. Soʻz undosh yoki unli bilan tugashiga qarab qoʻshimcha biroz farq qiladi:"},{"table":{"h":["Kimning","Undoshdan keyin","anahtar (kalit)","Unlidan keyin","çanta (sumka)"],"r":[["benim","-Im","anahtarım","-m","çantam"],["senin","-In","anahtarın","-n","çantan"],["onun","-I","anahtarı","-sI","çantası"],["bizim","-ImIz","anahtarımız","-mIz","çantamız"],["sizin","-InIz","anahtarınız","-nIz","çantanız"],["onların","-lArI","anahtarları","-lArI","çantaları"]]}},{"p":"Unli bilan boshlanadigan qoʻshimcha oldidan oxirgi undosh oʻzgarishi mumkin: p → b (dolap → dolabım), ç → c (ağaç → ağacı), k → ğ (köpek → köpeğim, bardak → bardağım), nk → ng (renk → rengi). Baʼzi soʻzlarda ikkinchi boʻgʻindagi unli tushib qoladi: burun → burnum (burnim), ağız → ağzım, isim → ismim."},{"sub":"Qaratqich kelishigi: -(n)In («…ning»)"},{"table":{"h":["Soʻz oxiri","Qoʻshimcha","Misollar"],"r":[["undosh","-ın / -in / -un / -ün","Kerem'in, öğretmenin, okulun, gülün"],["unli","-nın / -nin / -nun / -nün","Dilnoza'nın, Defne'nin, kedinin, ütünün"]]}},{"p":"Olmoshlarning qaratqich shakli yodlab olinadi: benim (mening), senin, onun, bizim, sizin, onların. Ismlarda apostrof qoʻyiladi: Jasur'un telefonu, Zeynep'in çantası."},{"sub":"Ot birikmalari (isim tamlaması)"},{"table":{"h":["Turi","Tuzilishi","Misol","Maʼnosi"],"r":[["aniq (kimning ekani muhim)","X-(n)In + Y-(s)I","Defne'nin kedisi","Defnening mushugi"],["aniq","X-(n)In + Y-(s)I","Murat Bey'in arabası","Murat beyning mashinasi"],["umumiy (narsaning nomi)","X + Y-(s)I","kedi maması","mushuk ovqati"],["umumiy","X + Y-(s)I","Türkçe kitabı","turk tili kitobi"],["umumiy","X + Y-(s)I","otobüs durağı","avtobus bekati"]]}},{"p":"-(s)I dan keyin kelishik qoʻshilsa, oraga n kiradi: arabası + da → arabasında, otobüs durağı + a → otobüs durağına, Türkçe kitabı + nı → Türkçe kitabını."},{"sub":"«Menda … bor» = (benim) …-Im var"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["(Benim) bir kedim var.","Mening bitta mushugim bor."],["(Senin) bisikletin var mı?","Velosipeding bormi?"],["Jasur'un ablası yok.","Jasurning opasi yoʻq."],["Kaç kuzenin var?","Nechta amakivachchang bor?"]]}},{"p":"Olmosh (benim, senin…) koʻpincha tushib qoladi, chunki egalik qoʻshimchasining oʻzi kimni nazarda tutayotganimizni aytib turibdi: Bir kedim var — yetarli."}]},{"kind":"dialog","title":"Dialog: Düğün fotoğrafı","blocks":[{"dlg":[["Defne","Bu fotoğraf çok güzel! Bunlar kim?"],["Dilnoza","Bu benim ailem. Ağabeyimin düğünü."],["Defne","Bu senin ağabeyin mi?"],["Dilnoza","Evet, adı Rustam. Yanındaki de onun eşi, Nigora."],["Defne","Annen hangisi?"],["Dilnoza","Mavi elbiseli kadın benim annem. Babam da onun yanında."],["Defne","Kaç kardeşin var?"],["Dilnoza","Bir ağabeyim ve bir kız kardeşim var. Senin kardeşin var mı?"],["Defne","Bir erkek kardeşim var, adı Can. Ablam yok."],["Defne","Bu küçük çocuk kim?"],["Dilnoza","O amcamın oğlu."],["Defne","Aileniz çok kalabalık!"],["Dilnoza","Evet, bizim evimiz her zaman dolu."]]},{"gloss":[["düğün","toʻy"],["eş","turmush oʻrtogʻi"],["yanındaki","yonidagi"],["hangisi","qaysi biri"],["elbiseli","koʻylakli"],["amca","amaki"],["kalabalık","gavjum, katta"],["dolu","toʻla"]]}]}],"reading":{"text":"Benim adım Defne. Ailemiz İzmir'de yaşıyor. Babamın adı Hakan. O bir otobüs şoförü. Annemin adı Sevgi, o terzi. Annemin küçük bir dükkânı var. Bir kardeşim var, adı Can. Can on dört yaşında, ortaokul öğrencisi. Dedem ve babaannem de bizimle yaşıyor. Dedemin bahçesi çok güzel; bahçede elma ve incir ağaçları var. Bizim bir de kedimiz var. Kedimizin adı Pamuk. Pamuk'un en sevdiği yer dedemin koltuğu!","gloss":[["terzi","tikuvchi"],["dükkân","doʻkon"],["ortaokul","oʻrta maktab"],["babaanne","buvi (ota tomondan)"],["incir","anjir"],["ağaç","daraxt"],["koltuk","kreslo"],["en sevdiği yer","eng yaxshi koʻrgan joyi"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Defne'nin babası ne iş yapıyor?","Annesinin nesi var?","Can kaç yaşında?","Bahçede hangi ağaçlar var?","Kedinin adı ne?"],"title":"Defne'nin ailesi","ans":{"1":"Otobüs şoförü.","2":"Küçük bir dükkânı var.","3":"On dört yaşında.","4":"Elma ve incir ağaçları var.","5":"Kedinin adı Pamuk."}},"exercises":[{"n":1,"title":"Egalik qoʻshimchasini qoʻshing.","items":[["a","(benim) kedi →"],["b","(senin) kardeş →"],["c","(onun) bahçe →"],["d","(bizim) aile →"],["e","(sizin) dükkân →"],["f","(onların) ev →"],["g","(benim) dede →"],["h","(onun) kitap →"]],"ans":{"a":"kedim","b":"kardeşin","c":"bahçesi","d":"ailemiz","e":"dükkânınız","f":"evleri","g":"dedem","h":"kitabı"}},{"n":2,"title":"Ot birikmasini tuzing.","items":[["a","Defne / kedi → Defne'nin kedisi"],["b","dedem / bahçe →"],["c","Can / okul →"],["d","annem / dükkân →"],["e","ev / kapı →"],["f","Rustam / eş →"]],"ans":{"b":"dedemin bahçesi","c":"Can'ın okulu","d":"annemin dükkânı","e":"evin kapısı","f":"Rustam'ın eşi"}},{"n":3,"title":"var / yok bilan javob bering.","items":[["a","Kaç kardeşin var? →"],["b","Kedin var mı? →"],["c","Bahçeniz var mı? →"],["d","Ağabeyin var mı? →"]],"ans":{"a":"Bir kardeşim var.","b":"Evet, bir kedim var.","c":"Hayır, bahçemiz yok.","d":"Hayır, ağabeyim yok."},"sample":true},{"n":4,"title":"Xatoni toping va tuzating.","items":[["a","Benim kardeşin on yaşında."],["b","Defne'nin kedi çok tatlı."],["c","Bizim evimizi büyük."],["d","Senin kitapın nerede?"]],"ans":{"a":"Benim kardeşim on yaşında.","b":"Defne'nin kedisi çok tatlı.","c":"Bizim evimiz büyük.","d":"Senin kitabın nerede?"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Onam tikuvchi."],["b","Bobomning bogʻi juda chiroyli."],["c","Mening ikkita ukam bor."],["d","Ularning mushugi bormi?"]],"ans":{"a":"Annem terzi.","b":"Dedemin bahçesi çok güzel.","c":"Benim iki erkek kardeşim var.","d":"Onların kedisi var mı?"}},{"n":6,"title":"Yozish. Oilangizni tanishtiring (6–8 gap).","items":[],"ans":{}}]},{"id":"a1-7","level":"A1","n":7,"title":"Lokantada","sub":"Tushum -(y)I · joʻnalish -(y)A · chiqish -DAn · buyruq mayli · sinf buyruqlari","goals":["ovqat va xarid lugʻati","narx soʻrash","uchta yangi kelishik: -(y)I (…ni), -(y)A (…ga), - DAn (…dan)","buyruq mayli (Gel! Gelin!)","sinfda ishlatiladigan buyruqlar"],"vocab":[{"title":"Lugʻat","words":[["ekmek","non"],["et / tavuk / balık","goʻsht / tovuq / baliq"],["su","suv"],["pilav / makarna","palov (guruch) / makaron"],["çay / kahve","choy / qahva"],["çorba / salata","shoʻrva / salat"],["süt / şeker","sut / shakar"],["meyve / sebze","meva / sabzavot"],["peynir / zeytin","pishloq / zaytun"],["elma / portakal","olma / apelsin"],["yumurta","tuxum"],["domates / patates","pomidor / kartoshka"],["simit","simit (kunjutli bublik)"],["tuz","tuz"],["fiyat","narx"],["pahalı / ucuz","qimmat / arzon"],["Ne kadar? / Kaç lira?","Qancha? / Necha lira?"],["para / para üstü","pul / qaytim"],["Buyurun.","Marhamat."],["Başka bir şey?","Yana biror narsa?"],["Hepsi ne kadar?","Hammasi qancha?"],["Afiyet olsun!","Yoqimli ishtaha!"]]},{"title":"Mavzuli lugʻat — sinf buyruqlari (sınıfta)","words":[["Oturun!","Oʻtiring!"],["Dinleyin!","Tinglang!"],["Kitabı açın!","Kitobni oching!"],["Tekrar edin!","Takrorlang!"],["Yazın!","Yozing!"],["Okuyun!","Oʻqing!"],["Sessiz olun!","Jim boʻling!"],["Anlamadım.","Tushunmadim."],["Tekrar eder misiniz?","Takrorlaysizmi?"],["Yavaş konuşun.","Sekinroq gapiring."]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Kelishiklar jadvali"},{"table":{"h":["Kelishik","Qoʻshimcha","Oʻzbekcha","pazar","sepet","köy","İzmir"],"r":[["bosh","—","—","pazar","sepet","köy","İzmir"],["qaratqich","-(n)In","-ning","pazarın","sepetin","köyün","İzmir'in"],["tushum","-(y)I","-ni","pazarı","sepeti","köyü","İzmir'i"],["joʻnalish","-(y)A","-ga","pazara","sepete","köye","İzmir'e"],["oʻrin","-DA","-da","pazarda","sepette","köyde","İzmir'de"],["chiqish","-DAn","-dan","pazardan","sepetten","köyden","İzmir'den"]]}},{"sub":"Tushum kelishigi: -(y)I («…ni»)"},{"p":"Oʻzbekchadagidek, faqat aniq, maʼlum narsa toʻldiruvchi boʻlganda qoʻshiladi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Elma yiyorum.","Olma yeyapman. (qaysi olma — muhim emas)"],["Elmayı yiyorum.","Olmani yeyapman. (oʻsha, aytilgan olmani)"],["Zeynep'i arıyorum.","Zeynepni qidiryapman / Zeynepga qoʻngʻiroq qilyapman."]]}},{"p":"Ism va olmoshlar doim tushum kelishigida keladi: beni, seni, onu, bizi, sizi, onları. Unlidan keyin y kiradi: kapı → kapıyı, su → suyu. Oxirgi undosh yumshaydi: ekmek → ekmeği, dolap → dolabı."},{"sub":"Joʻnalish kelishigi: -(y)A («…ga»)"},{"p":"Misollar: pazara gidiyorum, köye dönüyoruz, İzmir'e geliyor, kapıya bakıyor. Olmoshlar oʻzgaradi — diqqat qiling: bana, sana, ona, bize, size, onlara. Bana bir menü getirir misiniz? — Menga menyu olib kelasizmi?"},{"sub":"Chiqish kelishigi: -DAn («…dan»)"},{"p":"Misollar: pazardan geliyorum, sepetten alıyor, Taşkent'ten arıyor, köprüden geçiyoruz. Olmoshlar: benden, senden, ondan, bizden, sizden, onlardan. Vaqt oraligʻi: Sabah sekizden akşam altıya kadar açık. — Ertalab sakkizdan kechki oltigacha ochiq."},{"p":"Har bir feʼl oʻz kelishigini «talab qiladi», shuning uchun ularni juft holda yodlang: bir şeyi sevmek (…ni sevmoq), otobüse binmek (avtobusga chiqmoq), bir şeyden hoşlanmak (…ni yoqtirmoq — turkchada …dan!), birine sormak (…dan soʻramoq — turkchada …ga!)."},{"sub":"Buyruq mayli"},{"table":{"h":["Kimga","Qoʻshimcha","almak","yazmak","dinlemek","Inkor"],"r":[["sen","— (oʻzakning oʻzi)","Al!","Yaz!","Dinle!","Yazma!"],["siz","-(y)In","Alın!","Yazın!","Dinleyin!","Yazmayın!"],["siz (rasmiy)","-(y)InIz","Alınız!","Yazınız!","Dinleyiniz!","Yazmayınız!"]]}},{"p":"Lütfen (iltimos) bilan buyruq muloyim eshitiladi: Lütfen menüyü verin. Rasmiy eʼlonlarda koʻproq -(y)InIz uchraydi: Lütfen sıraya giriniz. (Iltimos, navbatga turing.) Diqqat: et- unli oldidan ed- boʻladi: Yardım et! (sen), lekin Yardım edin! (siz)."}]},{"kind":"dialog","title":"Dialog: Pazarda","blocks":[{"dlg":[["Satıcı","Buyurun, hoş geldiniz!"],["Dilnoza","Merhaba. Domates ne kadar?"],["Satıcı","Kilosu kırk lira. Çok taze, bahçeden geliyor."],["Dilnoza","İki kilo verin lütfen. Peynir de var mı?"],["Satıcı","Var. Şu peyniri deneyin, köyden geliyor."],["Dilnoza","Çok lezzetli! Yarım kilo alıyorum."],["Satıcı","Başka bir şey? Zeytin, bal?"],["Dilnoza","Zeytini sevmiyorum. Bir kavanoz bal verin."],["Satıcı","Tabii. Hepsi üç yüz yirmi lira."],["Dilnoza","Biraz indirim yapın lütfen!"],["Satıcı","Peki, sizin için üç yüz lira olsun."],["Dilnoza","Teşekkürler. Poşete koyun lütfen."],["Satıcı","Buyurun. Yine bekleriz!"]]},{"gloss":[["satıcı","sotuvchi"],["taze","yangi, barra"],["denemek","tatib koʻrmoq"],["lezzetli","mazali"],["kavanoz","banka"],["bal","asal"],["indirim","chegirma"],["poşet","paket"],["yine bekleriz","yana kutamiz"]]}]}],"reading":{"text":"Menemen çok kolay ve lezzetli bir Türk yemeği. Önce iki domatesi ve bir biberi yıkayın, sonra küçük küçük doğrayın. Tavaya biraz yağ koyun. Biberi tavaya atın ve üç dakika pişirin. Sonra domatesi ekleyin. Tuz atın ve karıştırın. Beş dakika bekleyin. Şimdi iki yumurtayı tavaya kırın. Yumurtayı çok pişirmeyin! Tavayı ocaktan alın. Menemeni sıcak yiyin ve ekmeği unutmayın. Afiyet olsun!","gloss":[["tarif","retsept"],["biber","qalampir"],["doğramak","toʻgʻramoq"],["tava","tova"],["yağ","yogʻ"],["eklemek","qoʻshmoq"],["karıştırmak","aralashtirmoq"],["kırmak","chaqmoq"],["ocak","plita"],["afiyet olsun","yoqimli ishtaha"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Menemen zor bir yemek.","Önce biberi pişirin, sonra domatesi ekleyin.","Menemende yumurta yok.","Yumurtayı uzun süre pişirin. (uzun süre — uzoq vaqt)","Menemeni sıcak yiyin."],"title":"Menemen tarifi","ans":{"1":"Y","2":"D","3":"Y","4":"Y","5":"D"}},"exercises":[{"n":1,"title":"Tushum kelishigi (-(y)I) qoʻshing.","items":[["a","Şu peynir___ deneyin."],["b","Domates___ yıkıyorum."],["c","Kapı___ açın."],["d","Defne'___ bekliyoruz."],["e","Ekmek___ unutma!"],["f","Su___ için."]],"ans":{"a":"peyniri","b":"Domatesi","c":"Kapıyı","d":"Defne'yi","e":"Ekmeği","f":"Suyu"}},{"n":2,"title":"-(y)A yoki -DAn qoʻshing.","items":[["a","Ben pazar___ gidiyorum."],["b","Peynir köy___ geliyor."],["c","Yumurtayı tava___ kırın."],["d","Dilnoza okul___ dönüyor."],["e","Biz İzmir'___ gidiyoruz."],["f","Sen nere___ geliyorsun?"]],"ans":{"a":"pazara","b":"köyden","c":"tavaya","d":"okuldan","e":"İzmir'e","f":"nereden"}},{"n":3,"title":"Buyruq shaklini yozing (sen / siz).","items":[["a","beklemek → /"],["b","almak → /"],["c","okumak → /"],["d","gelmek → /"],["e","yıkamak → /"]],"ans":{"a":"Bekle / Bekleyin","b":"Al / Alın","c":"Oku / Okuyun","d":"Gel / Gelin","e":"Yıka / Yıkayın"}},{"n":4,"title":"Sinf buyruqlarini oʻzbekchaga tarjima qiling.","items":[["a","Tekrar edin!"],["b","Defteri kapatın!"],["c","Tahtaya bakın!"],["d","Yazmayın, dinleyin!"],["e","Onuncu sayfayı açın!"]],"ans":{"a":"Takrorlang!","b":"Daftarni yoping!","c":"Doskaga qarang!","d":"Yozmang, tinglang!","e":"Oʻninchi sahifani oching!"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Iltimos, ikki kilo pomidor bering."],["b","Hammasi qancha?"],["c","Men bozorga ketyapman."],["d","Eshikni yopmang!"],["e","Bu pishloq qishloqdan keladi."]],"ans":{"a":"Lütfen iki kilo domates verin.","b":"Hepsi ne kadar?","c":"Ben pazara gidiyorum.","d":"Kapıyı kapatmayın!","e":"Bu peynir köyden geliyor."}},{"n":6,"title":"Rolli oʻyin. Sherigingiz bilan kafe yoki doʻkonda xarid dialogini tuzing (8–10 qator).","items":[],"ans":{}}]},{"id":"a1-8","level":"A1","n":8,"title":"Hafta Sonu Ne Yaptın?","sub":"Aniq oʻtgan zamon -DI · «edim»: -(y)DI · vardı / yoktu","goals":["oʻtgan voqealar haqida gapirish","aniq oʻtgan zamon -DI","inkor va soʻroq","ot-kesimning oʻtgan zamoni (evdeydim, yorgundum)","vardı / yoktu","vaqt iboralari"],"vocab":[{"title":"Lugʻat","words":[["dün","kecha"],["gezmek","sayr qilmoq, aylanmoq"],["evvelsi gün","oʻtgan kuni"],["buluşmak","uchrashmoq"],["geçen hafta / ay / yıl","oʻtgan hafta / oy / yil"],["alışveriş yapmak","xarid qilmoq"],["iki gün önce","ikki kun oldin"],["fotoğraf çekmek","suratga olmoq"],["hafta sonu","dam olish kunlari"],["yorulmak / yorgun","charchamoq / charchagan"],["şehir merkezi","shahar markazi"],["eğlenmek","maza qilmoq, koʻngil ochmoq"],["müze / park / sinema","muzey / bogʻ / kino"],["otobüs / bilet","avtobus / chipta"],["güzel / kötü","yaxshi, chiroyli / yomon"],["sıcak / soğuk","issiq / sovuq"]]},{"title":"Mavzuli lugʻat — tabiat va kamp (doğa ve kamp)","words":[["dağ","togʻ"],["orman","oʻrmon"],["göl","koʻl"],["nehir","daryo"],["kamp","lager, kemping"],["çadır","chodir"],["harita","xarita"],["pusula","kompas"],["sırt çantası","ryukzak"],["ateş","olov"],["rehber","yoʻlboshchi, gid"],["yürüyüş","piyoda sayr"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Aniq oʻtgan zamon: -DI"},{"p":"Oʻzak + DI + shaxs qoʻshimchasi. Bu oʻzbekchadagi -dim, -ding, -di ning aynan oʻzi va uni eshitganingizda darrov taniysiz."},{"table":{"h":["Shaxs","almak","bilmek","uyumak","görmek","içmek"],"r":[["ben","aldım","bildim","uyudum","gördüm","içtim"],["sen","aldın","bildin","uyudun","gördün","içtin"],["o","aldı","bildi","uyudu","gördü","içti"],["biz","aldık","bildik","uyuduk","gördük","içtik"],["siz","aldınız","bildiniz","uyudunuz","gördünüz","içtiniz"],["onlar","aldılar","bildiler","uyudular","gördüler","içtiler"]]}},{"p":"Unli toʻrt shaklli (ı, i, u, ü). Jarangsiz undoshdan keyin (FıSTıKÇı ŞaHaP) d oʻrniga t keladi: iç-ti, bak-tı, koş-tu, git-ti. Biz shakli -k bilan tugaydi: aldık (oldik) — oʻzbekchadagi «-dik» ga oʻxshaydi."},{"sub":"Inkor va soʻroq"},{"table":{"h":["Inkor: oʻzak + mA + DI","Soʻroq: tayyor shakl + mI"],"r":[["almadım — olmadim","Aldın mı? — Oldingmi?"],["bilmedin — bilmading","Gördünüz mü? — Koʻrdingizmi?"],["uyumadı — uxlamadi","Pamuk uyudu mu? — Pamuk uxladimi?"],["içmedik — ichmadik","Gittiler mi? — Ketishdimi?"]]}},{"p":"-(I)yor zamonidan farqi: bu yerda shaxs qoʻshimchasi feʼlning oʻzida qoladi, soʻroq yuklamasi esa oxirida keladi: Aldın mı? (lekin: Alıyor musun?)."},{"sub":"«…edim»: ot-kesimning oʻtgan zamoni -(y)DI"},{"table":{"h":["Hozir","Oʻtgan zamon","Oʻzbekcha"],"r":[["Hastayım.","Hastaydım.","Kasal edim."],["Açsın.","Açtın.","Och eding."],["Hava güzel.","Hava güzeldi.","Havo yaxshi edi."],["Plajdayız.","Plajdaydık.","Plyajda edik."],["Evde değilim.","Evde değildim.","Uyda emas edim."],["Bilet var.","Bilet vardı.","Chipta bor edi."],["Vakit yok.","Vakit yoktu.","Vaqt yoʻq edi."]]}},{"p":"Unli bilan tugagan soʻzdan keyin y kiradi: hasta → hastaydım, kapıda → kapıdaydı. Jarangsiz undoshdan keyin d → t: aç → açtın, yok → yoktu."}]},{"kind":"dialog","title":"Dialog: Tatil dönüşü","blocks":[{"dlg":[["Defne","Hoş geldin Jasur! Tatil nasıldı?"],["Jasur","Çok güzeldi! Kapadokya'ya gittim."],["Defne","Öyle mi? Kiminle gittin?"],["Jasur","Kurstan iki arkadaşımla gittim."],["Defne","Balona bindiniz mi?"],["Jasur","Bindik! Sabah beşte kalktık. Hava çok soğuktu ama manzara harikaydı."],["Defne","Fotoğraf çektin mi?"],["Jasur","Yüzlerce fotoğraf çektim. Sen ne yaptın?"],["Defne","Ben hiçbir yere gitmedim. Evdeydim, sınava çalıştım."],["Jasur","Sınav nasıldı?"],["Defne","Zor değildi. Akşamları da kitap okudum."],["Jasur","Sana bir hediye getirdim. Buyur!"],["Defne","Çok teşekkür ederim!"]]},{"gloss":[["tatil dönüşü","taʼtildan qaytish"],["balona binmek","havo shariga chiqmoq"],["manzara","manzara"],["harika","ajoyib"],["yüzlerce","yuzlab"],["hiçbir yere","hech qayerga"],["sınav","imtihon"],["hediye","sovgʻa"]]}]}],"reading":{"text":"Pazar, 12 Mayıs. Bugün çok güzel bir gündü. Sabah erken kalktım ve Defne'yle Efes'e gittim. Otobüs yolculuğu bir saat sürdü. Efes çok eski bir şehir. Büyük tiyatroyu ve kütüphaneyi gördük. Hava çok sıcaktı, şapkam yoktu, bu yüzden çok su içtim. Öğlen küçük bir lokantada gözleme yedik ve ayran içtik. Rehber çok hızlı konuştu, her şeyi anlamadım ama Defne bana yardım etti. Akşam saat yedide eve döndük. Çok yoruldum ama mutluydum. Anneme fotoğrafları gönderdim.","gloss":[["günlük","kundalik"],["sürmek","davom etmoq"],["eski","qadimiy"],["şapka","shlyapa"],["bu yüzden","shuning uchun"],["gözleme","tovada pishirilgan yupqa somsa"],["rehber","gid"],["yorulmak","charchamoq"],["göndermek","yubormoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Dilnoza Efes'e kiminle gitti?","Yolculuk ne kadar sürdü?","Efes'te ne gördüler?","Öğlen ne yediler?","Dilnoza neden çok su içti?"],"title":"Dilnoza'nın günlüğü","ans":{"1":"Defne'yle gitti.","2":"Bir saat sürdü.","3":"Büyük tiyatroyu ve kütüphaneyi gördüler.","4":"Gözleme yediler.","5":"Çünkü hava çok sıcaktı ve şapkası yoktu."}},"exercises":[{"n":1,"title":"Feʼlni -DI bilan tuslang.","items":[["a","Ben dün Efes'e (gitmek) ___."],["b","Sen fotoğraf (çekmek) ___?"],["c","O ayran (içmek) ___."],["d","Biz erken (kalkmak) ___."],["e","Siz balona (binmek) ___?"],["f","Onlar eve (dönmek) ___."]],"ans":{"a":"gittim","b":"çektin mi","c":"içti","d":"kalktık","e":"bindiniz mi","f":"döndüler"}},{"n":2,"title":"Inkor shaklga oʻtkazing.","items":[["a","Dün kitap okudum. →"],["b","Biz balona bindik. →"],["c","O sınava çalıştı. →"],["d","Siz geç kaldınız. →"]],"ans":{"a":"Dün kitap okumadım.","b":"Biz balona binmedik.","c":"O sınava çalışmadı.","d":"Siz geç kalmadınız."}},{"n":3,"title":"-(y)DI qoʻshing.","items":[["a","Dün ben ev___."],["b","Manzara harika___."],["c","Biz çok mutlu___."],["d","Hava soğuk___."],["e","Sen dün nerede___?"],["f","Sınav zor değil___."]],"ans":{"a":"evdeydim","b":"harikaydı","c":"mutluyduk","d":"soğuktu","e":"neredeydin","f":"değildi"}},{"n":4,"title":"Savollarga oʻzingiz haqingizda javob bering.","items":[["a","Hafta sonu ne yaptın?"],["b","Dün akşam neredeydin?"],["c","Geçen yaz nereye gittin?"],["d","Bu sabah ne yedin?"]],"ans":{"a":"Hafta sonu pazara gittim ve yemek pişirdim.","b":"Dün akşam evdeydim.","c":"Geçen yaz Semerkant'a gittim.","d":"Bu sabah peynir ve ekmek yedim."},"sample":true},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Kecha men hech qayerga bormadim, uyda edim."],["b","Taʼtil qanday oʻtdi?"],["c","Biz ertalab beshda turdik."],["d","Havo juda issiq edi."],["e","Senga sovgʻa olib keldim."]],"ans":{"a":"Dün hiçbir yere gitmedim, evdeydim.","b":"Tatil nasıldı?","c":"Biz sabah beşte kalktık.","d":"Hava çok sıcaktı.","e":"Sana bir hediye getirdim."}},{"n":6,"title":"Yozish. «Geçen hafta sonu» mavzusida 8–10 gap yozing.","items":[],"ans":{}}]},{"id":"a2-1","level":"A2","n":1,"title":"Tatilde Ne Yapacaksın?","sub":"Kelasi zamon -(y)AcAK · inkor va soʻroq · reja va bashorat · sayohat lugʻati","goals":["kelajakdagi rejalar haqida gapirish","kelasi zamon -(y)AcAK","k → ğ oʻzgarishi (geleceğim)","inkor -mAyAcAK","taʼtil, yoʻl va chipta lugʻati","ishda taʼtilga ruxsat soʻrash"],"vocab":[{"title":"Lugʻat","words":[["tatil","taʼtil, dam olish"],["bilet almak","chipta olmoq"],["memleket","ona yurt, tugʻilgan joy"],["rezervasyon yapmak","joy band qilmoq"],["yolculuk","safar"],["havaalanı","aeroport"],["uçak / tren / otobüs","samolyot / poyezd / avtobus"],["otogar / gar","avtovokzal / vokzal"],["bavul / valiz","chamadon"],["uçmak","uchmoq"],["hazırlamak","tayyorlamoq"],["ziyaret etmek","ziyorat qilmoq, borib koʻrmoq"],["dönmek","qaytmoq"],["kalmak","qolmoq"],["yarın / öbür gün","ertaga / indinga"],["haftaya / gelecek hafta","kelasi hafta"],["seneye / gelecek yıl","kelasi yil"],["… sonra","… dan keyin (iki gün sonra)"],["yakında","yaqinda"],["belki","balki"]]},{"title":"Mavzuli lugʻat — sayohat va mehmonxona","words":[["otel","mehmonxona"],["oda ayırtmak","xona band qilmoq"],["pasaport","xorijiy pasport"],["vize","viza"],["gümrük","bojxona"],["gezi / tur","sayohat / tur"],["turist","sayyoh"],["tatil köyü","dam olish maskani"],["manzara","manzara"],["hediye","sovgʻa"],["izin","(ishdan) taʼtil, ruxsat"],["yıllık izin","yillik taʼtil"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Kelasi zamon: -(y)AcAK"},{"p":"Oʻzak + (y)AcAk + shaxs qoʻshimchasi. Oʻzbekchada bunga «boraman, qilaman» (kelajak maʼnosida) yoki «bormoqchiman» toʻgʻri keladi."},{"table":{"h":["Shaxs","almak","görmek","izlemek","uyumak"],"r":[["ben","alacağım","göreceğim","izleyeceğim","uyuyacağım"],["sen","alacaksın","göreceksin","izleyeceksin","uyuyacaksın"],["o","alacak","görecek","izleyecek","uyuyacak"],["biz","alacağız","göreceğiz","izleyeceğiz","uyuyacağız"],["siz","alacaksınız","göreceksiniz","izleyeceksiniz","uyuyacaksınız"],["onlar","alacaklar","görecekler","izleyecekler","uyuyacaklar"]]}},{"p":"Qoidalar. 1) Qoʻshimcha ikki shaklli: -acak / -ecek; oʻzak unli bilan tugasa, oraga y kiradi: izle-yecek, uyu-yacak. 2) Unli bilan boshlanadigan shaxs qoʻshimchasi oldidan k yumshab ğ boʻladi: alacak + ım → alacağım, görecek + iz → göreceğiz. -sın, -sınız, -lar oldida k oʻzgarmaydi. 3) Baʼzi oʻzaklarda t → d: git → gideceğim, et → edeceğim. 4) Istisnolar: ye → yiyeceğim, de → diyeceğim."},{"note":"Jonli nutqda bu shakl qisqarib eshitiladi: alacağım → [alıcam], göreceğim → [göricem], ne yapacaksın? → [ne yapıcan?]. Tinglaganda tanib oling, lekin yozganda doim toʻliq shaklni ishlating."},{"sub":"Inkor va soʻroq"},{"table":{"h":["Inkor: oʻzak + mA + (y)AcAK","Soʻroq: shakl + mI + shaxs"],"r":[["almayacağım — olmayman","Alacak mısın? — Olasanmi?"],["görmeyeceksin — koʻrmaysan","Görecek miyiz? — Koʻramizmi?"],["gitmeyecek — bormaydi","Gidecek mi? — Boradimi?"],["uyumayacağız — uxlamaymiz","Uyuyacaklar mı? — Uxlaydilarmi?"]]}},{"p":"Inkorda -mA dan keyin y albatta kiradi: alma-yacak, gitme-yecek."},{"sub":"-(I)yor yoki -(y)AcAK?"},{"table":{"h":["Gap","Qachon aytiladi"],"r":[["Cumartesi Bodrum'a gidiyoruz.","Reja aniq, hammasi kelishilgan (chipta olingan) — soʻzlashuvda koʻp uchraydi."],["Cumartesi Bodrum'a gideceğiz.","Kelajakdagi reja, qaror yoki vaʼda."],["Yarın hava güneşli olacak.","Bashorat, taxmin (ob-havo va hokazo)."]]}},{"p":"olmak (boʻlmoq) feʼli kelajakda juda koʻp keladi: Akşam evde olacağım. (Kechqurun uyda boʻlaman.) · Kerem gelecek yıl mimar olacak. (Kerem kelasi yil meʼmor boʻladi.)"},{"sub":"Vosita: -(y)lA («bilan», «…da»)"},{"p":"Transport va hamroh haqida gapirganda kerak. Ikki shaklli: -la / -le; unlidan keyin -yla / -yle. Misollar: vapurla (paromda), bisikletle (velosipedda), metroyla (metroda), taksiyle (taksida), annemle (onam bilan), Defne'yle (Defne bilan). Olmoshlar: benimle, seninle, onunla, bizimle, sizinle, onlarla."},{"p":"Rasmiy matnda alohida ile ham yoziladi: vapur ile, annem ile. Maʼnosi bir xil."}]},{"kind":"dialog","title":"Dialog: Bayram tatili planı","blocks":[{"dlg":[["Kerem","Dilnoza, bayram tatilinde ne yapacaksın?"],["Dilnoza","Buhara'ya gideceğim. Ailemi çok özledim."],["Kerem","Ne zaman yola çıkacaksın?"],["Dilnoza","Cuma akşamı uçakla gideceğim. Biletimi dün aldım."],["Kerem","Kaç gün kalacaksın?"],["Dilnoza","On gün kalacağım. Kız kardeşimin doğum günü olacak, ona sürpriz yapacağım."],["Kerem","Çok güzel! Bana Buhara'dan ne getireceksin?"],["Dilnoza","Kuru kayısı ve badem getireceğim. Sen ne yapacaksın?"],["Kerem","Ben hiçbir yere gitmeyeceğim. Kafede çalışacağım."],["Dilnoza","Hiç dinlenmeyecek misin?"],["Kerem","Son iki gün arkadaşlarla Çeşme'ye gideceğiz, denize gireceğiz."],["Dilnoza","İyi tatiller o zaman!"],["Kerem","Sana da iyi yolculuklar!"]]},{"gloss":[["özlemek","sogʻinmoq"],["yola çıkmak","yoʻlga chiqmoq"],["doğum günü","tugʻilgan kun"],["sürpriz","kutilmagan sovgʻa"],["kuru kayısı","turshak"],["badem","bodom"],["dinlenmek","dam olmoq"],["denize girmek","dengizda choʻmilmoq"],["iyi yolculuklar","oq yoʻl"]]}]}],"reading":{"text":"Jasur'un bu yaz çok planı var. Haziranda işi çok yoğun olacak, çünkü şirket yeni bir köprü projesine başlayacak. Bu yüzden haziranda izin almayacak. Temmuzun ilk haftasında annesi ve kız kardeşi Kamila Taşkent'ten gelecek. Onlar İzmir'de iki hafta kalacaklar. Jasur onları havaalanında karşılayacak. Birlikte Efes'i gezecekler, Çeşme'de denize girecekler ve Kemeraltı Çarşısı'nda alışveriş yapacaklar. Kamila Türkçe bilmiyor, bu yüzden Jasur onun tercümanı olacak. Ağustosta Jasur bir hafta izin alacak ve arkadaşı Kerem'le Karadeniz'e gidecek. Orada yaylalarda yürüyüş yapacaklar ve çadırda kalacaklar. Jasur fotoğraf makinesini de götürecek. Eylülde ise yeni bir şey deneyecek: akşamları gitar kursuna gidecek.","gloss":[["yoğun","tigʻiz"],["köprü","koʻprik"],["izin almak","taʼtil olmoq"],["karşılamak","kutib olmoq"],["gezmek","aylanib koʻrmoq"],["alışveriş","xarid"],["tercüman","tarjimon"],["yayla","yaylov"],["çadır","chodir"],["götürmek","olib bormoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Jasur haziranda neden izin almayacak?","Temmuzda kimler gelecek?","Jasur onları nerede karşılayacak?","Karadeniz'de nerede kalacaklar?","Eylülde Jasur ne yapacak?"],"title":"Jasur'un yaz planları","ans":{"1":"Çünkü işi çok yoğun olacak.","2":"Annesi ve kız kardeşi Kamila gelecek.","3":"Havaalanında karşılayacak.","4":"Çadırda kalacaklar.","5":"Gitar kursuna gidecek."}},"exercises":[{"n":1,"title":"Feʼlni -(y)AcAK bilan tuslang.","items":[["a","Ben yarın erken (uyanmak) ___."],["b","Sen Buhara'ya ne zaman (gitmek) ___?"],["c","Kerem kafede (çalışmak) ___."],["d","Biz denize (girmek) ___."],["e","Siz kaç gün (kalmak) ___?"],["f","Onlar çadırda (uyumak) ___."],["g","Ben sana badem (getirmek) ___."],["h","Yarın hava güzel (olmak) ___."]],"ans":{"a":"uyanacağım","b":"gideceksin","c":"çalışacak","d":"gireceğiz","e":"kalacaksınız","f":"uyuyacaklar","g":"getireceğim","h":"olacak"}},{"n":2,"title":"Inkorga oʻtkazing.","items":[["a","Yarın işe gideceğim. →"],["b","Biz otelde kalacağız. →"],["c","Kamila uçakla gelecek. →"],["d","Sen bilet alacaksın. →"]],"ans":{"a":"Yarın işe gitmeyeceğim.","b":"Biz otelde kalmayacağız.","c":"Kamila uçakla gelmeyecek.","d":"Sen bilet almayacaksın."}},{"n":3,"title":"Soʻroq gap tuzing va javob bering.","items":[["a","sen / bayramda / çalışmak → ? — Hayır, ___."],["b","siz / yarın / gelmek → ? — Evet, ___."],["c","o / gitar kursuna / gitmek → ? — Evet, ___."]],"ans":{"a":"Bayramda çalışacak mısın? — Hayır, çalışmayacağım.","b":"Yarın gelecek misiniz? — Evet, geleceğiz.","c":"Gitar kursuna gidecek mi? — Evet, gidecek."}},{"n":4,"title":"Mos soʻzni tanlang: yarın · seneye · iki gün sonra · bu akşam · haftaya","items":[["a","Bugün salı. Perşembe = ___."],["b","Şimdi 2026. 2027 = ___."],["c","Saat 15.00. Bugün saat 20.00 = ___."],["d","Bugün cuma. Cumartesi = ___."],["e","Bu hafta değil, gelecek hafta = ___."]],"ans":{"a":"iki gün sonra","b":"seneye","c":"bu akşam","d":"yarın","e":"haftaya"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Bayramda Buxoroga boraman."],["b","Biz chodirda qolamiz."],["c","Ertaga ishlamaysanmi?"],["d","Onam kelasi hafta keladi."],["e","Ular dengizda choʻmilishadi."]],"ans":{"a":"Bayramda Buhara'ya gideceğim.","b":"Biz çadırda kalacağız.","c":"Yarın çalışmayacak mısın?","d":"Annem haftaya gelecek.","e":"Onlar denize girecekler."}},{"n":6,"title":"Yozish. «Gelecek tatil planım» — keyingi taʼtilingiz rejasini 8–10 gapda yozing: qachon, qayerga, nima","items":[],"extra":"bilan, kim bilan, nima qilasiz, qachon qaytasiz.","ans":{}}]},{"id":"a2-2","level":"A2","n":2,"title":"Her Gün Ne Yaparsın?","sub":"Aniq zamon (geniş zaman) -(A/I)r · inkor -mAz · iltimos va taklif · odatlar va qoidalar","goals":["odatlar, umumiy haqiqatlar va qoidalar haqida gapirish","geniş zaman (yapar, gelir, okur)","inkor -mAz","muloyim iltimos (Yardım eder misiniz?) va taklif (Çay içer misiniz?)","takroriylik ravishlari","boʻsh vaqt mashgʻulotlari"],"vocab":[{"title":"Lugʻat","words":[["alışkanlık","odat"],["her zaman","doim"],["boş zaman","boʻsh vaqt"],["genellikle","odatda"],["futbol / satranç oynamak","futbol / shaxmat oʻynamoq"],["sık sık","tez-tez"],["yüzmek","suzmoq"],["bazen","baʼzan"],["balık tutmak","baliq tutmoq"],["nadiren","kamdan-kam"],["müzik dinlemek","musiqa tinglamoq"],["hiç","hech qachon (inkor bilan)"],["film izlemek","film koʻrmoq"],["haftada iki kez","haftasiga ikki marta"],["sevmek","sevmoq, yaxshi koʻrmoq"],["dakik","vaqtga qatʼiy rioya qiladigan"],["yardım etmek","yordam bermoq"],["açmak / kapatmak","ochmoq / yopmoq"]]},{"title":"Mavzuli lugʻat — odob va ish madaniyati","words":[["nezaket","muloyimlik, odob"],["saygı","hurmat"],["dakiklik","aniqlik, vaqtga rioya"],["sorumluluk","masʼuliyat"],["kural","qoida"],["uymak","rioya qilmoq"],["güler yüz","ochiq chehra"],["selam vermek","salom bermoq"],["haber vermek","xabar bermoq"],["zamanında","oʻz vaqtida"],["geç kalmak","kechikmoq"],["dikkat etmek","eʼtibor bermoq"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Geniş zaman — tuzilishi"},{"p":"Geniş zaman (keng zamon) oʻzbekchadagi «oʻqiyman, ishlaydi» kabi hozirgi-kelasi zamonga oʻxshaydi. Qoʻshimchaning uch xili bor:"},{"table":{"h":["Oʻzak","Qoʻshimcha","Misollar"],"r":[["unli bilan tugaydi","-r","ara → arar, söyle → söyler, yürü → yürür"],["bir boʻgʻinli, undosh bilan tugaydi","-ar / -er","bak → bakar, iç → içer, yüz → yüzer, sat → satar"],["koʻp boʻgʻinli, undosh bilan tugaydi","-ır / -ir / -ur / -ür","uyan → uyanır, getir → getirir, unut → unutur, düşün → düşünür"]]}},{"p":"13 ta bir boʻgʻinli feʼl istisno: ular -ar/-er emas, -Ir oladi: alır, bilir, bulur, durur, gelir, görür, kalır, olur, ölür, sanır, varır, verir, vurur."},{"note":"Istisnolarni toʻrt guruhda takrorlash oson: al · bil · bul — dur · gel · gör — kal · ol · öl — san · var · ver · vur."},{"sub":"Shaxs qoʻshimchalari"},{"table":{"h":["Shaxs","bakmak","bilmek","aramak","uyanmak"],"r":[["ben","bakarım","bilirim","ararım","uyanırım"],["sen","bakarsın","bilirsin","ararsın","uyanırsın"],["o","bakar","bilir","arar","uyanır"],["biz","bakarız","biliriz","ararız","uyanırız"],["siz","bakarsınız","bilirsiniz","ararsınız","uyanırsınız"],["onlar","bakarlar","bilirler","ararlar","uyanırlar"]]}},{"sub":"Inkor: -mAz (shakli boshqacha!)"},{"table":{"h":["Shaxs","bakmak","bilmek","Oʻzbekcha"],"r":[["ben","bakmam","bilmem","qaramayman"],["sen","bakmazsın","bilmezsin","qaramaysan"],["o","bakmaz","bilmez","qaramaydi"],["biz","bakmayız","bilmeyiz","qaramaymiz"],["siz","bakmazsınız","bilmezsiniz","qaramaysiz"],["onlar","bakmazlar","bilmezler","qaramaydilar"]]}},{"p":"Ben va biz shakllarida z tushib qoladi: bakmam, bilmeyiz. Qolgan shaxslarda z saqlanadi."},{"sub":"Soʻroq, taklif va muloyim iltimos"},{"table":{"h":["Turkcha","Maʼnosi"],"r":[["Satranç oynar mısın?","Shaxmat oʻynaysanmi?"],["Kahve alır mısınız?","Qahva ichasizmi? (taklif)"],["Pencereyi kapatır mısınız?","Derazani yopib qoʻyasizmi? (muloyim iltimos)"],["Bana bir bakar mısın?","Menga bir qarab yuborasanmi?"],["Biraz daha kalmaz mısınız?","Yana ozgina qolmaysizmi? (yanada iltifotli taklif)"]]}},{"sub":"Qachon ishlatiladi?"},{"table":{"h":["Vazifasi","Misol"],"r":[["odat","Hafta sonları geç kalkarım. — Dam olish kunlari kech turaman."],["umumiy haqiqat","Kediler balığı sever. — Mushuklar baliqni yaxshi koʻradi."],["qoida, yoʻriqnoma","Kütüphanede yüksek sesle konuşulmaz. — Kutubxonada baland ovozda gaplashilmaydi."],["iltimos, taklif","Tuzu uzatır mısın? — Tuzni uzatib yuborasanmi?"],["vaʼda, taxmin","Merak etme, akşam ararım. — Xavotir olma, kechqurun qoʻngʻiroq qilaman."]]}},{"p":"-(I)yor bilan farqi: Şu an kahve içiyorum — hozir qahva ichyapman (bir martalik ish). Sabahları kahve içerim — ertalablari qahva ichaman (odat). Odat va kun tartibi haqida yozganda geniş zaman tabiiy eshitiladi."}]},{"kind":"dialog","title":"Dialog: Yeni ev arkadaşı","blocks":[{"dlg":[["Zeynep","Merhaba, oda ilanı için aradım. Ben Zeynep."],["Defne","Hoş geldin Zeynep! Birkaç soru soracağım, olur mu?"],["Zeynep","Tabii."],["Defne","Sabahları erken kalkar mısın?"],["Zeynep","Evet, genellikle altıda kalkarım ve koşarım."],["Defne","Ben geç kalkarım. Sessiz olur musun?"],["Zeynep","Merak etme, hiç gürültü yapmam."],["Defne","Yemek yapar mısın?"],["Zeynep","Yaparım. Hafta sonları börek pişiririm."],["Defne","Harika! Ben de bulaşıkları yıkarım. Kedileri sever misin?"],["Zeynep","Çok severim."],["Defne","Kedim Pamuk bütün gün uyur, kimseyi rahatsız etmez."],["Zeynep","O zaman iyi anlaşırız!"],["Defne","Bir çay içer misin?"],["Zeynep","Memnuniyetle!"]]},{"gloss":[["ilan","eʼlon"],["birkaç","bir nechta"],["sessiz","jim"],["gürültü","shovqin"],["merak etme","xavotir olma"],["bulaşık","idish-tovoq"],["rahatsız etmek","bezovta qilmoq"],["anlaşmak","til topishmoq"],["memnuniyetle","jon deb"]]}]}],"reading":{"text":"Hasan Usta otuz yıldır fırıncı. Onun günü çok erken başlar. Her gece saat üçte kalkar ve fırına gider. Önce hamuru hazırlar, sonra fırını yakar. İlk ekmekler saat beşte çıkar. Mahalleli taze ekmeği çok sever, bu yüzden sabah altıda fırının önünde kuyruk olur. Hasan Usta müşterilerin adını bilir ve herkese selam verir. Çocuklara bazen küçük bir simit hediye eder. Öğleden sonra fırını oğlu Emre'ye bırakır ve eve gider. Evde biraz uyur, sonra bahçede çalışır. Akşamları erken yatar; televizyon izlemez. Pazar günleri fırın açılmaz. O gün Hasan Usta torunlarıyla balık tutar. \"Ekmek sabır ister\" der, \"balık da öyle.\"","gloss":[["fırıncı","novvoy"],["fırın","novvoyxona; tandir"],["hamur","xamir"],["yakmak","yoqmoq"],["mahalleli","mahalla ahli"],["kuyruk","navbat"],["müşteri","mijoz"],["simit","kunjutli halqa non"],["bırakmak","qoldirmoq"],["torun","nevara"],["balık tutmak","baliq ovlamoq"],["sabır","sabr"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Hasan Usta sabah altıda kalkar.","İlk ekmekler saat beşte çıkar.","Hasan Usta müşterilerini tanımaz.","Öğleden sonra fırında oğlu çalışır.","Pazar günleri fırın kapalıdır."],"title":"Bir fırıncının günü","ans":{"1":"Y","2":"D","3":"Y","4":"D","5":"D"}},"exercises":[{"n":1,"title":"Geniş zaman qoʻshimchasini qoʻshing (o shaxsi).","items":[["a","kalk →"],["b","sev →"],["c","uyu →"],["d","pişir →"],["e","bil →"],["f","koş →"],["g","ol →"],["h","hazırla →"],["i","gör →"],["j","konuş →"]],"ans":{"a":"kalkar","b":"sever","c":"uyur","d":"pişirir","e":"bilir","f":"koşar","g":"olur","h":"hazırlar","i":"görür","j":"konuşur"}},{"n":2,"title":"Feʼlni tuslang.","items":[["a","Ben her sabah (koşmak) ___."],["b","Hasan Usta ekmek (pişirmek) ___."],["c","Biz akşamları kitap (okumak) ___."],["d","Siz çay (sevmek) ___?"],["e","Çocuklar erken (yatmak) ___."],["f","Sen hafta sonu ne (yapmak) ___?"]],"ans":{"a":"koşarım","b":"pişirir","c":"okuruz","d":"sever misiniz","e":"yatarlar","f":"yaparsın"}},{"n":3,"title":"Inkorga oʻtkazing.","items":[["a","Ben televizyon izlerim. →"],["b","Biz geç kalkarız. →"],["c","Sen gürültü yaparsın. →"],["d","Fırın pazar günü açılır. →"]],"ans":{"a":"Ben televizyon izlemem.","b":"Biz geç kalkmayız.","c":"Sen gürültü yapmazsın.","d":"Fırın pazar günü açılmaz."}},{"n":4,"title":"Muloyim iltimos yoki taklif tuzing.","items":[["a","(kapıyı kapatmak — siz) → Kapıyı kapatır mısınız?"],["b","(bana tuzu vermek — sen) →"],["c","(bir kahve içmek — siz) →"],["d","(biraz beklemek — siz) →"],["e","(bizimle gelmek — sen) →"]],"ans":{"b":"Bana tuzu verir misin?","c":"Bir kahve içer misiniz?","d":"Biraz bekler misiniz?","e":"Bizimle gelir misin?"}},{"n":5,"title":"-(I)yor yoki geniş zaman? Qavsdagi feʼlni toʻgʻri shaklga qoʻying.","items":[["a","Bak! Pamuk şu anda balkonda (uyumak) ___."],["b","Ben her sabah yarım saat (koşmak) ___."],["c","Şimdi meşgulüm, börek (pişirmek) ___."],["d","Kediler balığı çok (sevmek) ___."],["e","Hasan Usta şu an bir müşteriyle (konuşmak) ___."]],"ans":{"a":"uyuyor","b":"koşarım","c":"pişiriyorum","d":"sever","e":"konuşuyor"}},{"n":6,"title":"Turkchaga tarjima qiling.","items":[["a","Men odatda erta turaman."],["b","U hech qachon shovqin qilmaydi."],["c","Bir choy ichasizmi?"],["d","Yakshanba kunlari bobom baliq ovlaydi."],["e","Biz kechqurunlari televizor koʻrmaymiz."]],"ans":{"a":"Ben genellikle erken kalkarım.","b":"O hiç gürültü yapmaz.","c":"Bir çay içer misiniz?","d":"Pazar günleri dedem balık tutar.","e":"Biz akşamları televizyon izlemeyiz."}},{"n":7,"title":"Yozish. «Benim günüm ve alışkanlıklarım» — odatlaringiz haqida 8–10 gap yozing. Takroriylik","items":[],"extra":"ravishlarini ishlating (her zaman, genellikle, bazen, hiç…).","ans":{}}]},{"id":"a2-3","level":"A2","n":3,"title":"Postane Nerede?","sub":"Koʻmakchilar (önünde, yanında…) · yoʻl koʻrsatish · -(y)ArAk · masofa va yoʻnalish","goals":["shaharda yoʻl soʻrash va koʻrsatish","joylashuvni aniq aytish (bankanın yanında, köprünün karşısında)","koʻmakchilar va ularning kelishik shakllari","-(y)ArAk ravishdoshi (yürüyerek)","masofa","dunyo tomonlari va xarita lugʻati"],"vocab":[{"title":"Lugʻat","words":[["cadde","katta koʻcha, prospekt"],["eczane","dorixona"],["sokak","koʻcha"],["hastane","kasalxona"],["meydan","maydon"],["postane","pochta"],["kavşak","chorraha"],["cami","masjid"],["trafik ışığı","svetofor"],["durak","bekat"],["köprü","koʻprik"],["yaya geçidi","piyodalar oʻtish joyi"],["köşe","burchak, muyulish"],["bina / apartman","bino / koʻp qavatli uy"],["yakın / uzak","yaqin / uzoq"],["düz","toʻgʻri"],["dönmek / sapmak","burilmoq"],["geçmek","oʻtmoq, kesib oʻtmoq"],["kaybolmak","adashmoq"],["sormak","soʻramoq"]]},{"title":"Mavzuli lugʻat — yoʻnalish va xarita","words":[["kuzey / güney","shimol / janub"],["harita okumak","xarita oʻqimoq"],["doğu / batı","sharq / gʻarb"],["ölçek","masshtab"],["yön","yoʻnalish"],["konum","joylashuv"],["güzergâh","marshrut"],["buluşma yeri","uchrashuv joyi"],["işaret","belgi"],["navigasyon","navigator"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Koʻmakchilar: joy va yoʻnalish"},{"p":"Bu birikmalar oʻzbekchadagi «uyning orqasida» kabi tuziladi: X-(n)In + koʻmakchi + egalik + kelishik."},{"table":{"h":["Koʻmakchi","Maʼnosi","Misol"],"r":[["önünde","oldida","Müzenin önünde uzun bir kuyruk var."],["arkasında","orqasida","Otopark marketin arkasında."],["yanında","yonida","Fırın eczanenin yanında."],["karşısında","qarshisida","Saat Kulesi vapur iskelesinin karşısında."],["içinde","ichida","Pamuk kutunun içinde uyuyor."],["üstünde / altında","ustida / ostida","Anahtar dolabın üstünde, ayakkabılar yatağın altında."],["arasında","orasida","Kafe, sinema ile kitapçının arasında."],["sağında / solunda","oʻng / chap tomonida","Banka postanenin solunda."],["çevresinde","atrofida","Gölün çevresinde bisiklet yolu var."]]}},{"p":"Koʻmakchining oʻzi ham kelishik oladi — qayerda, qayerga, qayerdan:"},{"table":{"h":["Asos","-DA (qayerda?)","-(y)A (qayerga?)","-DAn (qayerdan?)"],"r":[["ön","önünde","önüne","önünden"],["yan","yanında","yanına","yanından"],["alt","altında","altına","altından"]]}},{"p":"Misollar: Bisikleti kapının önüne bırak. (Velosipedni eshik oldiga qoʻy.) · Pamuk masanın altından çıktı. (Pamuk stol ostidan chiqdi.) Olmoshlar bilan: benim yanımda (yonimda), senin önünde, onun arkasında, bizim yanımızda."},{"sub":"Yoʻl koʻrsatish"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Dümdüz gidin.","Toʻppa-toʻgʻri boring."],["Sağa / sola dönün.","Oʻngga / chapga buriling."],["Üçüncü sokaktan sola dönün.","Uchinchi koʻchadan chapga buriling."],["Işıklara kadar devam edin.","Svetoforgacha davom eting."],["Yolun karşısına geçin.","Yoʻlning narigi tomoniga oʻting."],["Alt geçitten geçin.","Yer osti oʻtish joyidan oʻting."],["Köşeden sağa dönün.","Burchakdan oʻngga buriling."],["Solda göreceksiniz.","Chap tomonda koʻrasiz."]]}},{"p":"Soʻrash uchun: Affedersiniz, eczane nerede? · Saat Kulesi'ne nasıl gidebilirim? (Soat minorasiga qanday borsam boʻladi?) · Yakında bir ATM var mı? · Uzak mı?"},{"sub":"Masofa"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Ne kadar uzak?","Qanchalik uzoq?"],["Buraya çok yakın. / Buradan biraz uzak.","Bu yerga juda yaqin. / Bu yerdan biroz uzoq."],["Yürüyerek on dakika.","Piyoda oʻn daqiqa."],["Otobüsle iki durak.","Avtobusda ikki bekat."],["Evden sahile kadar bir kilometre.","Uydan sohilgacha bir kilometr."]]}},{"p":"Diqqat: yakın va uzak koʻpincha joʻnalish kelishigini oladi: denize yakın (dengizga yaqin), okula uzak (maktabdan uzoq). uzak chiqish kelishigi bilan ham aytiladi: merkezden uzak."},{"sub":"-(y)ArAk ravishdoshi («…ib», «…gan holda»)"},{"p":"Shakllari: -arak / -erek, unlidan keyin -yarak / -yerek. Misollar: yürüyerek (yurib, piyoda), gülerek (kulib), şarkı söyleyerek (qoʻshiq aytib), telefona bakarak (telefonga qarab)."},{"p":"Dilnoza haritaya bakarak müzeyi buldu. — Dilnoza xaritaga qarab muzeyni topdi."}]},{"kind":"dialog","title":"Dialog: Müze nerede?","blocks":[{"dlg":[["Jasur","Affedersiniz teyze, Arkeoloji Müzesi buraya yakın mı?"],["Teyze","Çok uzak değil evladım. Yürüyerek on dakika."],["Jasur","Nasıl gideceğim?"],["Teyze","Şu caddeden düz git. Eczanenin önünden geçeceksin."],["Jasur","Tamam. Eczaneden sonra?"],["Teyze","İkinci sokaktan sağa dön. Köşede bir fırın var."],["Jasur","Müze fırının yanında mı?"],["Teyze","Hayır. Fırının karşısında büyük bir park var. Müze parkın arkasında."],["Jasur","Parkın içinden mi geçeceğim?"],["Teyze","Evet, parkın içinden geçerek gidersen daha kısa."],["Jasur","Müzenin girişi nerede?"],["Teyze","Girişi çeşmenin tam karşısında."],["Jasur","Çok teşekkür ederim."],["Teyze","Bir şey değil evladım, kolay gelsin!"]]},{"gloss":[["teyze","xola (kattaroq ayolga murojaat)"],["evladım","bolam"],["cadde","katta koʻcha"],["düz","toʻgʻri"],["köşe","burchak"],["karşısında","qarshisida"],["arkasında","orqasida"],["giriş","kirish joyi"],["çeşme","favvora, buloq"],["kolay gelsin","ishingiz oʻngidan kelsin"]]}]}],"reading":{"text":"Bu cumartesi kurs öğrencileri için şehirde bir hazine avı düzenlenecek. Oyun saat onda Saat Kulesi'nin önünde başlayacak. Her takım bir harita ve bir zarf alacak. Zarfın içinde ilk ipucu olacak. Birinci durak, kulenin arkasındaki eski han. Hanın avlusunda, çeşmenin yanında ikinci ipucunu bulacaksınız. Oradan çarşının içinden geçerek sahile ineceksiniz. Üçüncü ipucu, iskelenin karşısındaki kitapçının vitrininde. Kitapçıdan çıkınca sola dönün ve sahil boyunca beş yüz metre yürüyün. Köprünün altından geçin; son durak köprü ile park arasındaki çay bahçesi. Hazine bir masanın altında saklı! Takımlar yürüyerek veya bisikletle gidebilir, ama taksiye binmek yasak. İlk gelen takım ödül kazanacak: herkese kahvaltı!","gloss":[["hazine avı","xazina izlash oʻyini"],["düzenlemek","tashkil qilmoq"],["takım","jamoa"],["zarf","konvert"],["ipucu","ishora"],["durak","bekat"],["han","karvonsaroy"],["avlu","hovli"],["iskele","pristan"],["boyunca","boʻylab"],["saklı","yashirilgan"],["yasak","taqiqlangan"],["ödül","mukofot"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Oyun nerede başlayacak?","İkinci ipucu nerede?","Üçüncü ipucu nerede?","Son durak neresi?","Oyunda ne yasak?"],"title":"Hazine avı","ans":{"1":"Saat Kulesi'nin önünde başlayacak.","2":"Hanın avlusunda, çeşmenin yanında.","3":"Kitapçının vitrininde.","4":"Köprü ile park arasındaki çay bahçesi.","5":"Taksiye binmek yasak."}},"exercises":[{"n":1,"title":"Koʻmakchi bilan toʻldiring.","items":[["a","Hazine masanın (ostida) ___."],["b","Müze parkın (orqasida) ___."],["c","Fırın eczane ile banka (orasida) ___."],["d","Kedi koltuğun (ustida) ___ uyuyor."],["e","Çocuklar okulun (oldida) ___ bekliyor."],["f","Park fırının (qarshisida) ___."]],"ans":{"a":"altında","b":"arkasında","c":"arasında","d":"üstünde","e":"önünde","f":"karşısında"}},{"n":2,"title":"Toʻgʻri kelishikni tanlang.","items":[["a","Kitabı rafın (üstünde / üstüne) koy."],["b","Kedi yatağın (altında / altından) çıktı."],["c","Defne benim (yanımda / yanıma) oturuyor."],["d","Arabayı evin (önünde / önüne) park et."],["e","Top masanın (altına / altında) duruyor."]],"ans":{"a":"üstüne","b":"altından","c":"yanımda","d":"önüne","e":"altında"}},{"n":3,"title":"-(y)ArAk qoʻshing.","items":[["a","Müzeye (yürümek) ___ gittim."],["b","Çocuk (gülmek) ___ eve girdi."],["c","Parkın içinden (geçmek) ___ sahile indik."],["d","Türkçeyi dizi (izlemek) ___ öğrendim."]],"ans":{"a":"yürüyerek","b":"gülerek","c":"geçerek","d":"izleyerek"}},{"n":4,"title":"Yoʻl koʻrsating. Maktab darvozasidan chiqib: toʻgʻri boring → ikkinchi chorrahada chapga buriling →","items":[],"extra":"koʻprikdan oʻting → dorixona oʻng tomonda, masjidning qarshisida. Shu yoʻriqni turkcha yozing.","ans":{"_":"Okulun kapısından çıkın ve düz gidin. İkinci kavşaktan sola dönün. Köprüyü geçin. Eczane sağda, caminin karşısında."},"sample":true},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Kechirasiz, muzey uzoqmi?"],["b","Ikkinchi koʻchadan oʻngga buriling."],["c","Novvoyxona dorixonaning yonida."],["d","Men ishga piyoda boraman."],["e","Koʻprikning ostidan oʻting."]],"ans":{"a":"Affedersiniz, müze uzak mı?","b":"İkinci sokaktan sağa dönün.","c":"Fırın eczanenin yanında.","d":"Ben işe yürüyerek giderim.","e":"Köprünün altından geçin."}},{"n":6,"title":"Yozish va gapirish. Oʻz uyingizdan eng yaqin bekat yoki doʻkongacha boʻlgan yoʻlni 6–8 gapda","items":[],"extra":"tasvirlang.","ans":{}}]},{"id":"a2-4","level":"A2","n":4,"title":"Doktora Gitmelisin!","sub":"Majburiyat: -mAlI · gerek / lazım · zorunda · sogʻliq va shifokor qabuli","goals":["tana aʼzolari va kasallik belgilari","shifokorga shikoyat aytish (Başım ağrıyor)","maslahat va majburiyat: -mAlI (gitmelisin), gerek / lazım, -mAk zorunda","birinchi yordam lugʻati"],"vocab":[{"title":"Lugʻat","words":[["baş / göz / kulak","bosh / koʻz / quloq"],["sağlık","sogʻliq"],["burun / ağız / diş","burun / ogʻiz / tish"],["hasta / hastalanmak","kasal / kasal boʻlmoq"],["boğaz / boyun","tomoq / boʻyin"],["ağrı / ağrımak","ogʻriq / ogʻrimoq"],["omuz / kol / el","yelka / qoʻl / kaft"],["ateş","isitma (yuqori harorat)"],["parmak","barmoq"],["öksürük / öksürmek","yoʻtal / yoʻtalmoq"],["sırt / bel","orqa / bel"],["grip / nezle","gripp / tumov"],["karın / mide","qorin / oshqozon"],["ilaç / reçete","dori / retsept"],["bacak / diz / ayak","oyoq / tizza / oyoq panjasi"],["muayene olmak","koʻrikdan oʻtmoq"],["kırılmak","sinmoq"],["iyileşmek","tuzalmoq"],["burkulmak","chiqmoq, lat yemoq (boʻgʻim)"],["Geçmiş olsun!","Tezroq tuzaling!"]]},{"title":"Mavzuli lugʻat — poliklinika va birinchi yordam","words":[["poliklinik","poliklinika"],["acil servis","shoshilinch yordam boʻlimi"],["ambulans","tez yordam"],["randevu almak","qabulga yozilmoq"],["ilk yardım","birinchi yordam"],["yara","jarohat"],["sargı / bandaj","bint / bogʻlam"],["sedye","zambil"],["rapor","tibbiy xulosa, kasallik varaqasi"],["istirahat","dam olish (kasallik boʻyicha)"],["eczacı","dorixonachi"],["sıcak çarpması","issiq urishi"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"«…im ogʻriyapti» — sogʻliq haqida"},{"p":"Turkchada ham oʻzbekchadagidek ogʻriyotgan aʼzo egalik qoʻshimchasini oladi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Kulağım ağrıyor.","Qulogʻim ogʻriyapti."],["Karnın mı ağrıyor?","Qorning ogʻriyaptimi?"],["Bileğim burkuldu.","Bilagim lat yedi."],["Ateşim yükseldi.","Isitmam koʻtarildi."],["Burnum akıyor ve hapşırıyorum.","Burnim oqyapti va aksiryapman."],["Başım dönüyor.","Boshim aylanyapti."]]}},{"sub":"Maslahat va burch: -mAlI"},{"p":"Oʻzak + mAlI + kesimlik qoʻshimchasi = «…ishim kerak», «…sang yaxshi boʻladi»:"},{"table":{"h":["Shaxs","yatmak","dinlenmek","Inkor"],"r":[["ben","yatmalıyım","dinlenmeliyim","yatmamalıyım"],["sen","yatmalısın","dinlenmelisin","yatmamalısın"],["o","yatmalı","dinlenmeli","yatmamalı"],["biz","yatmalıyız","dinlenmeliyiz","yatmamalıyız"],["siz","yatmalısınız","dinlenmelisiniz","yatmamalısınız"],["onlar","yatmalılar","dinlenmeliler","yatmamalılar"]]}},{"p":"Soʻroq: Hastaneye gitmeli miyim? — Kasalxonaga borishim kerakmi? Qoʻshimcha ikki shaklli: -malı / -meli."},{"p":"Ateşin var, bugün evde kalmalısın. — Isitmang bor, bugun uyda qolishing kerak. Bu şurubu aç karnına içmemelisiniz. — Bu siropni och qoringa ichmasligingiz kerak."},{"sub":"gerek / lazım"},{"p":"1) Ot + gerek / lazım — «…kerak»:"},{"gloss":[["Bana bir termometre lazım.","Menga termometr kerak."],["Sana ne gerek?","Senga nima kerak?"]]},{"p":"2) Harakat nomi -mA + egalik + gerek / lazım / gerekiyor — «…ishim kerak»:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Eczaneye gitmem gerek.","Dorixonaga borishim kerak."],["Biraz uyuman lazım.","Biroz uxlashing kerak."],["Kerem'in tahlil yaptırması gerekiyor.","Kerem tahlil topshirishi kerak."],["Bol su içmemiz lazım.","Koʻp suv ichishimiz kerak."]]}},{"p":"Inkor: Endişelenmene gerek yok. (Xavotir olishing shart emas.) · Reçete gerekmez. (Retsept kerak emas.)"},{"sub":"-mAk zorunda («majbur»)"},{"p":"Yarın erken kalkmak zorundayım. — Ertaga erta turishga majburman. Ziyaretçiler maske takmak zorundadır. — Tashrif buyuruvchilar niqob taqishga majbur. Bugün gelmek zorunda değilsin. — Bugun kelishga majbur emassan."},{"sub":"Qaysi birini tanlash kerak?"},{"p":"-mAlI — maslahat yoki ichki burch: dinlenmelisin (dam olishing kerak). zorunda — tashqi majburiyat, qoida: rapor almak zorundasın (maʼlumotnoma olishga majbursan). gerek / lazım — ehtiyoj; soʻzlashuvda eng koʻp eshitiladigani shu."}]},{"kind":"dialog","title":"Dialog: Eczanede","blocks":[{"dlg":[["Eczacı","Buyurun, nasıl yardımcı olayım?"],["Dilnoza","İki gündür boğazım ağrıyor ve öksürüyorum."],["Eczacı","Ateşiniz var mı?"],["Dilnoza","Dün akşam biraz vardı. Başım da ağrıyor."],["Eczacı","Geçmiş olsun. Size bir şurup vereyim. Günde üç kez içmelisiniz."],["Dilnoza","Yemekten önce mi, sonra mı?"],["Eczacı","Yemekten sonra. Ayrıca bol ılık su içmeniz lazım."],["Dilnoza","Antibiyotik almam gerek mi?"],["Eczacı","Reçetesiz antibiyotik vermiyoruz. Önce doktora görünmelisiniz."],["Dilnoza","Yarın sınavım var, okula gitmek zorundayım."],["Eczacı","O zaman bu akşam erken yatmalısınız. Soğuk içecek içmemelisiniz."],["Dilnoza","Peki. Doktora ne zaman gitmeliyim?"],["Eczacı","Üç gün sonra hâlâ öksürüyor musunuz? O zaman mutlaka gitmelisiniz."],["Dilnoza","Teşekkür ederim."],["Eczacı","Geçmiş olsun!"]]},{"gloss":[["eczacı","dorixonachi"],["boğaz","tomoq"],["öksürmek","yoʻtalmoq"],["ateş","isitma"],["geçmiş olsun","tezroq tuzaling"],["şurup","sirop"],["bol","koʻp"],["ılık","iliq"],["reçete","retsept"],["doktora görünmek","shifokorga koʻrinmoq"],["içecek","ichimlik"],["mutlaka","albatta"]]}]}],"reading":{"text":"Uzmanlara göre yetişkin bir insan günde yedi-sekiz saat uyumalıdır. Peki, iyi bir uyku için ne yapmalıyız? Önce düzenli olmalıyız: her gün aynı saatte yatmalı ve aynı saatte kalkmalıyız. Hafta sonu bile bu düzeni bozmamak gerek. Yatmadan en az bir saat önce telefonu ve bilgisayarı kapatmalısınız, çünkü ekran ışığı uykuyu kaçırır. Akşam yemeği hafif olmalı; yatmadan hemen önce yemek yememelisiniz. Öğleden sonra kahve ve koyu çay içmemek lazım. Yatak odası serin, sessiz ve karanlık olmalıdır. Gündüz spor yapmak uykuya yardım eder, ama gece geç saatte spor yapmamalısınız. Uyku gelmiyor mu? Yatakta saatlerce beklemek zorunda değilsiniz: kalkın, sakin bir kitap okuyun. Uykusuzluk iki haftadan uzun sürüyor mu? O zaman doktora başvurmak gerekir.","gloss":[["uzman","mutaxassis"],["yetişkin","katta yoshli"],["düzenli","tartibli"],["düzeni bozmak","tartibni buzmoq"],["ışık","yorugʻlik"],["uykuyu kaçırmak","uyquni qochirmoq"],["hafif","yengil"],["koyu çay","achchiq choy"],["serin","salqin"],["karanlık","qorongʻi"],["sakin","tinch"],["uykusuzluk","uyqusizlik"],["başvurmak","murojaat qilmoq"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Yetişkinler günde beş saat uyumalıdır.","Hafta sonu da aynı saatte kalkmak gerek.","Yatmadan önce telefona bakmak uykuya yardım eder.","Yatak odası serin ve karanlık olmalıdır.","İki haftadan uzun süren uykusuzlukta doktora gitmek gerekir."],"title":"Sağlıklı uyku için","ans":{"1":"Y","2":"D","3":"Y","4":"D","5":"D"}},"exercises":[{"n":1,"title":"-mAlI bilan toʻldiring.","items":[["a","Öksürüyorsun, şurup (içmek) ___."],["b","Biz erken (yatmak) ___."],["c","Hasta evde (dinlenmek) ___."],["d","Siz doktora (görünmek) ___."],["e","Ben bugün ilaç (almak) ___."],["f","Çocuklar soğuk su (içmemek) ___."]],"ans":{"a":"içmelisin","b":"yatmalıyız","c":"dinlenmeli","d":"görünmelisiniz","e":"almalıyım","f":"içmemeli"}},{"n":2,"title":"gerek / lazım bilan qayta yozing.","items":[["a","Erken yatmalıyım. → Erken yatmam gerek."],["b","Bol su içmelisin. →"],["c","Doktora görünmeli. →"],["d","İlacı almalıyız. →"],["e","Evde kalmalısınız. →"]],"ans":{"b":"Bol su içmen gerek.","c":"Doktora görünmesi gerek.","d":"İlacı almamız gerek.","e":"Evde kalmanız gerek."}},{"n":3,"title":"Shikoyatni turkcha ayting.","items":[["a","Tomogʻim ogʻriyapti."],["b","Yoʻtalyapman."],["c","Isitmam bor."],["d","Tishim ogʻriyapti."],["e","Boshim aylanyapti."]],"ans":{"a":"Boğazım ağrıyor.","b":"Öksürüyorum.","c":"Ateşim var.","d":"Dişim ağrıyor.","e":"Başım dönüyor."}},{"n":4,"title":"Maslahat bering (-mAlI / -mAmAlI).","items":[["a","Arkadaşın: «Çok yorgunum.» →"],["b","Arkadaşın: «Dişim ağrıyor.» →"],["c","Arkadaşın: «Öksürüyorum.» →"],["d","Arkadaşın: «Gece uyuyamıyorum.» →"]],"ans":{"a":"Erken yatmalısın, dinlenmelisin.","b":"Dişçiye gitmelisin.","c":"Ilık su içmelisin, soğuk içecek içmemelisin.","d":"Akşam kahve içmemelisin."},"sample":true},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Tomogʻim ogʻriyapti, dorixonaga borishim kerak."],["b","Kuniga uch marta ichishingiz kerak."],["c","Ertaga ishga borishga majburman."],["d","Sovuq suv ichmasliging kerak."],["e","Tezroq tuzaling!"],["f","Koʻp iliq suv ichish lozim."]],"ans":{"a":"Boğazım ağrıyor, eczaneye gitmem gerek.","b":"Günde üç kez içmelisiniz.","c":"Yarın işe gitmek zorundayım.","d":"Soğuk su içmemelisin.","e":"Geçmiş olsun!","f":"Bol ılık su içmek lazım."}},{"n":6,"title":"Rolli oʻyin. Sherigingiz bilan «Doktorda» dialogini tuzing: bemor shikoyat aytadi, shifokor savol beradi","items":[],"extra":"va 3 ta maslahat beradi.","ans":{}}]},{"id":"a2-5","level":"A2","n":5,"title":"Hava Nasıl Olacak?","sub":"Qiyoslash: daha · en · kadar · gibi · ob-havo va fasllar","goals":["ob-havo haqida gapirish va prognozni tushunish","fasllar","qiyosiy daraja (-DAn daha)","orttirma daraja (en)","tenglik (kadar)","oʻxshatish (gibi)","kiyim va ob-havo lugʻati"],"vocab":[{"title":"Lugʻat","words":[["hava / hava durumu","havo / ob-havo maʼlumoti"],["ilkbahar / yaz","bahor / yoz"],["güneşli / bulutlu","quyoshli / bulutli"],["sonbahar / kış","kuz / qish"],["yağmurlu / karlı","yomgʻirli / qorli"],["sıcak / soğuk","issiq / sovuq"],["rüzgârlı / sisli","shamolli / tumanli"],["ılık / serin","iliq / salqin"],["yağmur yağıyor","yomgʻir yogʻyapti"],["nem / nemli","namlik / nam"],["kar yağıyor","qor yogʻyapti"],["kuru","quruq"],["rüzgâr esiyor","shamol esyapti"],["derece","daraja"],["fırtına","boʻron"],["sıfırın altında","noldan past"],["dolu","doʻl"],["iklim","iqlim"],["kalabalık","gavjum"],["yüksek / alçak","baland / past"]]},{"title":"Mavzuli lugʻat — kiyim va ob-havo sharoiti","words":[["mont","kurtka"],["yağmurluk","yomgʻirpoʻsh"],["eldiven","qoʻlqop"],["bere / atkı","shapka / sharf"],["şemsiye","soyabon"],["çizme","etik"],["görüş mesafesi","koʻrinish masofasi"],["ertelemek","kechiktirmoq, keyinga qoldirmoq"],["iptal etmek","bekor qilmoq"],["donmak","muzlamoq"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Qiyosiy daraja: X, Y-DAn (daha) …"},{"p":"Oʻzbekchadagi «…dan …roq» kabi: chiqish kelishigi + daha + sifat."},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["İzmir Ankara'dan daha sıcak.","Izmir Anqaradan issiqroq."],["Bu ceket o ceketten daha hafif.","Bu kurtka u kurtkadan yengilroq."],["Jasur Kerem'den uzun.","Jasur Keremdan baland."],["Bugün dünden daha bulutlu.","Bugun kechagidan bulutliroq."],["daha iyi / daha kötü","yaxshiroq / yomonroq"]]}},{"p":"-DAn boʻlsa, daha ni tushirib qoldirish mumkin. Kim bilan solishtirilayotgani aytilmasa, daha shart: Bu yol daha güvenli. (Bu yoʻl xavfsizroq.) Daha az — kamroq, daha çok / daha fazla — koʻproq: Kışın daha az dışarı çıkıyoruz. (Qishda kamroq tashqariga chiqamiz.)"},{"sub":"Orttirma daraja: en …"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Türkiye'nin en uzun nehri Kızılırmak.","Turkiyaning eng uzun daryosi — Qizilirmoq."],["Sınıfın en sessiz öğrencisi Zeynep.","Sinfning eng kamgap oʻquvchisi — Zeynep."],["En sevdiğim mevsim ilkbahar.","Eng yaxshi koʻrgan faslim — bahor."],["Ağustos en sıcak ay.","Avgust — eng issiq oy."]]}},{"p":"Guruh ichida ikki usul bor: X-(n)In en …-(s)I (öğrencilerin en sessizi — oʻquvchilarning eng kamgapi) yoki X arasında en … (öğrenciler arasında en sessiz)."},{"sub":"Tenglik: kadar"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Defne, Zeynep kadar uzun.","Defne Zeynep bilan boʻyi barobar."],["Bursa, İstanbul kadar kalabalık değil.","Bursa Istanbulchalik gavjum emas."],["Bu valiz Pamuk kadar ağır!","Bu chamadon Pamukdek ogʻir!"]]}},{"p":"Olmoshlar qaratqich kelishigida keladi: benim kadar, senin kadar, onun kadar, bizim kadar, sizin kadar; faqat onlar kadar."},{"sub":"Oʻxshatish: gibi"},{"p":"Buz gibi soğuk (muzdek sovuq) · Sen de benim gibi öğretmen misin? (Sen ham men kabi oʻqituvchimisan?) · Bugün hava bahar gibi! (Bugun havo bahordek!)"},{"sub":"Ob-havo haqida"},{"table":{"h":["Savol","Javob"],"r":[["Hava nasıl?","Hava güneşli ama serin. / Hava kapalı."],["Kaç derece?","On sekiz derece. / Eksi üç derece."],["Yağmur yağıyor mu?","Evet, çiseliyor. / Hayır, ama bulutlu."],["Yarın hava nasıl olacak?","Yarın kar yağacak."]]}},{"p":"Yogʻmoq — yağmak: bu feʼl yomgʻir, qor va doʻl uchun: yağmur yağıyor, kar yağdı, dolu yağabilir. Shamol uchun esmek: rüzgâr esiyor. Sifat shakllari -lI bilan yasaladi: yağmur → yağmurlu, kar → karlı, güneş → güneşli, sis → sisli, bulut → bulutlu."}]},{"kind":"dialog","title":"Dialog: Buhara mı, İzmir mi?","blocks":[{"dlg":[["Kerem","Dilnoza, Buhara'da yazlar nasıl? İzmir kadar sıcak mı?"],["Dilnoza","İzmir'den çok daha sıcak! Temmuzda kırk beş derece olur."],["Kerem","Vay! Ama İzmir daha nemli, değil mi?"],["Dilnoza","Evet. Buhara'nın havası kuru, çöl gibi. Gölgede o kadar zor değil."],["Kerem","Kışlar nasıl?"],["Dilnoza","Kışlar İzmir'deki kadar ılık değil. Ocak en soğuk ay, bazen kar yağar."],["Kerem","Sence en güzel mevsim hangisi?"],["Dilnoza","Bence ilkbahar. Her yer çiçek açar, hava ne sıcak ne soğuk olur."],["Kerem","Ben İzmir'de en çok sonbaharı severim. Deniz hâlâ ılık, turistler daha az."],["Dilnoza","Buhara'da sonbahar kavun zamanı. Bizim kavunlar bal gibi tatlı!"],["Kerem","O zaman Buhara'ya sonbaharda geleceğim."],["Dilnoza","Bekleriz!"]]},{"gloss":[["nemli","nam"],["kuru","quruq"],["çöl","choʻl"],["gölge","soya"],["mevsim","fasl"],["ilkbahar","bahor"],["sonbahar","kuz"],["çiçek açmak","gullamoq"],["kavun","qovun"],["bal gibi","asaldek"],["bekleriz","kutamiz"]]}]}],"reading":{"text":"Türkiye büyük bir ülke, bu yüzden her bölgenin iklimi farklı. Antalya ülkenin en sıcak şehirlerinden biri. Yazlar uzun ve kurak, kışlar ılık ve yağmurlu geçer. Burada kasım ayında bile denize girenler olur. Rize ise Türkiye'nin en yağışlı şehri. Rize'ye Antalya'dan çok daha fazla yağmur yağar, bu yüzden her yer yemyeşil ve çay bahçeleriyle dolu. Erzurum en soğuk şehirlerden biri. Kışın sıcaklık eksi otuz dereceye kadar düşer ve kar aylarca kalkmaz. Ankara'nın iklimi Erzurum'unki kadar sert değil, ama İstanbul'a göre daha kuru. Yazın gündüzler sıcak, geceler serin olur. İstanbul'da ise hava bir çocuk gibi: sabah güneş açar, öğlen yağmur yağar, akşam rüzgâr eser.","gloss":[["bölge","hudud"],["iklim","iqlim"],["kurak","qurgʻoqchil"],["yağışlı","seryogʻin"],["yemyeşil","yam-yashil"],["sıcaklık","harorat"],["eksi","minus"],["düşmek","tushmoq"],["aylarca","oylab"],["sert","qattiq"],["-e göre","…ga nisbatan"],["rüzgâr esmek","shamol esmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["En yağışlı şehir hangisi?","Antalya'da kışlar nasıl geçer?","Erzurum'da kışın sıcaklık kaç dereceye düşer?","Hangisi daha kuru: Ankara mı, İstanbul mu?","İstanbul'un havası ne gibi?"],"title":"Dört şehir, dört iklim","ans":{"1":"Rize.","2":"Ilık ve yağmurlu geçer.","3":"Eksi otuz dereceye kadar düşer.","4":"Ankara daha kuru.","5":"Bir çocuk gibi."}},"exercises":[{"n":1,"title":"Qiyosiy gap tuzing.","items":[["a","Buhara / İzmir / sıcak → Buhara İzmir'den daha sıcak."],["b","Rize / Antalya / yağışlı →"],["c","tren / otobüs / hızlı →"],["d","kış / sonbahar / soğuk →"],["e","kavun / elma / tatlı →"]],"ans":{"b":"Rize Antalya'dan daha yağışlı.","c":"Tren otobüsten daha hızlı.","d":"Kış sonbahardan daha soğuk.","e":"Kavun elmadan daha tatlı."}},{"n":2,"title":"en bilan gap tuzing.","items":[["a","Erzurum / Türkiye / soğuk şehir →"],["b","Temmuz / yıl / sıcak ay →"],["c","Kamila / aile / küçük çocuk →"],["d","Pamuk / mahalle / tembel kedi →"]],"ans":{"a":"Erzurum Türkiye'nin en soğuk şehri.","b":"Temmuz yılın en sıcak ayı.","c":"Kamila ailenin en küçük çocuğu.","d":"Pamuk mahallenin en tembel kedisi."}},{"n":3,"title":"kadar yoki gibi?","items":[["a","Ankara, Erzurum ___ soğuk değil."],["b","Bugün hava buz ___."],["c","Kardeşim benim ___ uzun."],["d","Kedim aslan ___ cesur."],["e","Bu çanta seninki ___ pahalı değil."]],"ans":{"a":"kadar","b":"gibi","c":"kadar","d":"gibi","e":"kadar"}},{"n":4,"title":"Ob-havoni tasvirlang (2 gapdan).","items":[["a","yomgʻirli, +12°"],["b","qorli, −5°"],["c","quyoshli, +35°"],["d","shamolli, bulutli"]],"ans":{"a":"Hava yağmurlu ve serin. On iki derece.","b":"Kar yağıyor ve hava çok soğuk. Eksi beş derece.","c":"Hava güneşli ve çok sıcak. Otuz beş derece.","d":"Hava bulutlu. Kuvvetli rüzgâr esiyor."},"sample":true},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Bugun kechagidan sovuqroq."],["b","Bahor eng goʻzal fasl."],["c","Izmir Buxorodek quruq emas."],["d","Bu qovun asaldek shirin."],["e","Ertaga qor yogʻadi."]],"ans":{"a":"Bugün dünden daha soğuk.","b":"İlkbahar en güzel mevsim.","c":"İzmir Buhara kadar kuru değil.","d":"Bu kavun bal gibi tatlı.","e":"Yarın kar yağacak."}},{"n":6,"title":"Yozish. Oʻz shahringiz va Turkiyadagi bir shahar iqlimini solishtiring (8–10 gap). daha, en, kadar, gibi","items":[],"extra":"soʻzlarini ishlating.","ans":{}}]},{"id":"a2-6","level":"A2","n":6,"title":"Çocukluk Anıları","sub":"Oʻtgan zamon davomli -(I)yordu · eshitilgan oʻtgan zamon -mIş · xotiralar","goals":["oʻtmishdagi voqea va odatlarni hikoya qilish","-(I)yordu (yürüyordum — yurayotgan edim)","-mIş (gelmiş — kelgan ekan, kelibdi)","-DI va -mIş farqi","xotiralar va hayot bosqichlari lugʻati"],"vocab":[{"title":"Lugʻat","words":[["hatıra / anı","xotira"],["eskiden","ilgari"],["çocukluk","bolalik"],["o zamanlar","u paytlarda"],["mahalle","mahalla"],["çocukken","bolaligimda"],["köy","qishloq"],["… yıl önce","… yil oldin"],["okul arkadaşı","maktabdosh"],["ilk kez / ilk defa","birinchi marta"],["heyecan / heyecanlı","hayajon / hayajonli"],["duymak","eshitmoq"],["korkmak","qoʻrqmoq"],["anlatmak","gapirib bermoq, hikoya qilmoq"],["özlemek","sogʻinmoq"],["hatırlamak","eslamoq"],["ağlamak / gülmek","yigʻlamoq / kulmoq"],["unutmak","unutmoq"]]},{"title":"Mavzuli lugʻat — hayot bosqichlari","words":[["doğmak","tugʻilmoq"],["büyümek","oʻsmoq, ulgʻaymoq"],["bebek","chaqaloq"],["gençlik","yoshlik"],["okula başlamak","maktabga bormoq (boshlamoq)"],["mezun olmak","bitirmoq (oʻquv yurtini)"],["mezuniyet","bitiruv"],["evlenmek","turmush qurmoq"],["taşınmak","koʻchib oʻtmoq"],["emekli olmak","nafaqaga chiqmoq"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"-(I)yordu: «…yotgan edim», «…ardim»"},{"p":"-(I)yor + -DU + shaxs qoʻshimchasi. Oʻzbekchadagi «…yotgan edim» yoki «…ardim» ga toʻgʻri keladi."},{"table":{"h":["Shaxs","oynamak","izlemek","Inkor","Soʻroq"],"r":[["ben","oynuyordum","izliyordum","oynamıyordum","oynuyor muydum?"],["sen","oynuyordun","izliyordun","oynamıyordun","oynuyor muydun?"],["o","oynuyordu","izliyordu","oynamıyordu","oynuyor muydu?"],["biz","oynuyorduk","izliyorduk","oynamıyorduk","oynuyor muyduk?"],["siz","oynuyordunuz","izliyordunuz","oynamıyordunuz","oynuyor muydunuz?"],["onlar","oynuyorlardı","izliyorlardı","oynamıyorlardı","oynuyorlar mıydı?"]]}},{"p":"Qachon ishlatiladi. 1) Oʻtmishda davom etib turgan ish, uni boshqa voqea (-DI) boʻladi: Duş alıyordum, kapı çaldı. — Dush qabul qilayotgan edim, eshik taqilladi. 2) Oʻtmishdagi odat: Küçükken her akşam dedemle tavla oynuyordum. — Kichikligimda har kech bobom bilan nard oʻynardim. 3) Manzara tasviri: Rüzgâr esiyordu, çocuklar uçurtma uçuruyordu. — Shamol esayotgan edi, bolalar varrak uchirayotgan edi."},{"sub":"-mIş: «…ibdi», «…gan ekan»"},{"p":"Oʻzak + mIş + shaxs qoʻshimchasi (toʻrt shaklli: -mış / -miş / -muş / -müş):"},{"table":{"h":["Shaxs","kazanmak","bitirmek","unutmak","düşmek"],"r":[["ben","kazanmışım","bitirmişim","unutmuşum","düşmüşüm"],["sen","kazanmışsın","bitirmişsin","unutmuşsun","düşmüşsün"],["o","kazanmış","bitirmiş","unutmuş","düşmüş"],["biz","kazanmışız","bitirmişiz","unutmuşuz","düşmüşüz"],["siz","kazanmışsınız","bitirmişsiniz","unutmuşsunuz","düşmüşsünüz"],["onlar","kazanmışlar","bitirmişler","unutmuşlar","düşmüşler"]]}},{"p":"Inkor: kazanmamış, unutmamış. Soʻroq: Bitirmiş mi? · Unutmuş muyum?"},{"p":"Qachon ishlatiladi. 1) Birovdan eshitilgan xabar: Kerem sınavı kazanmış. — Kerem imtihondan oʻtibdi (eshitdim). 2) Natijani koʻrib keyin bilish: Aa, Pamuk sütü bitirmiş! — Voy, Pamuk sutni tugatib qoʻyibdi! 3) Ertak va rivoyat: Evvel zaman içinde bir köyde yaşlı bir balıkçı yaşarmış. — Qadim zamonda bir qishloqda keksa baliqchi yashagan ekan."},{"sub":"-DI yoki -mIş?"},{"table":{"h":["-DI (oʻzim koʻrdim, aniq bilaman)","-mIş (eshitdim yoki keyin bildim)"],"r":[["Otobüs geç kaldı.","Otobüs geç kalmış."],["Avtobus kechikdi. (oʻzim kutdim)","Avtobus kechikibdi. (aytishdi)"],["Gece fırtına çıktı.","Gece fırtına çıkmış."],["Kechasi boʻron boʻldi. (uygʻoq edim)","Kechasi boʻron boʻlibdi. (ertalab koʻrdim)"]]}},{"p":"Ot-kesimda ham ishlatiladi: -(y)mIş = «ekan»:"},{"gloss":[["Elif Hoca çok sabırlıymış.","Elif ustoz juda sabrli ekan."],["Müze bugün kapalıymış.","Muzey bugun yopiq ekan."],["Öyle miymiş?","Shunaqa ekanmi? (yangilik eshitganda)"]]}]},{"kind":"dialog","title":"Dialog: Eski mahalle","blocks":[{"dlg":[["Defne","Kerem, siz çocukken nerede oturuyordunuz?"],["Kerem","Karşıyaka'da, eski bir mahallede oturuyorduk. Sokakta her akşam top oynuyorduk."],["Defne","Biz de dedemin bahçesinde oynuyorduk. Ben hep ağaca tırmanıyordum."],["Kerem","Hiç düştün mü?"],["Defne","Bir kere düştüm! Annem mutfakta yemek yapıyordu, sesimi duydu ve koştu."],["Kerem","Ben de bir gün komşunun camını kırdım. Çok korkuyordum ama komşu kızmadı."],["Defne","Geçen hafta sizin eski mahalleye gittim. Çok değişmiş!"],["Kerem","Öyle mi? Bizim ev duruyor mu?"],["Defne","Maalesef yıkmışlar. Yerine büyük bir apartman yapmışlar."],["Kerem","Ya bakkal Ali Amca?"],["Defne","Dükkânı kapatmış, köyüne dönmüş."],["Kerem","Çok yazık. O bize hep şeker veriyordu."]]},{"gloss":[["oturmak","yashamoq (bu yerda)"],["top","toʻp"],["tırmanmak","tirmashmoq"],["düşmek","yiqilmoq"],["cam","oyna"],["kırmak","sindirmoq"],["kızmak","jahl qilmoq"],["değişmek","oʻzgarmoq"],["yıkmak","buzmoq"],["bakkal","mahalla doʻkonchisi"],["yazık","afsus"]]}]}],"reading":{"text":"Geçen yaz babaannemin köydeki evini temizliyorduk. Tavan arasında eski bir sandık bulduk. İçinde sararmış fotoğraflar ve mektuplar vardı. Akşam babaannem bize onların hikâyesini anlattı. Babaannem gençken köyde okul yokmuş. Çocuklar her sabah bir saat yürüyerek kasabadaki okula gidiyormuş. Kışın yollar karla kapanıyormuş, o zaman öğretmen köye kendisi geliyormuş. Babaannem okumayı çok seviyormuş ama ailesi onu ortaokula göndermemiş. On yedi yaşında dedemle tanışmış. Dedem o sırada İzmir'de bir fabrikada çalışıyormuş ve babaanneme her hafta mektup yazıyormuş. Babaannem bütün mektupları bu sandıkta saklamış. Biz mektupları okurken babaannem hem gülüyor hem ağlıyordu. Şimdi o sandık benim odamda duruyor.","gloss":[["sandık","sandiq"],["tavan arası","chordoq"],["sararmış","sargʻaygan"],["mektup","xat"],["kasaba","shaharcha"],["kapanmak","yopilmoq"],["kendisi","oʻzi"],["o sırada","oʻsha paytda"],["saklamak","saqlamoq"],["ağlamak","yigʻlamoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Sandığı nerede buldular?","Çocuklar okula nasıl gidiyormuş?","Kışın yollar kapanınca kim köye geliyormuş?","Dedesi o sırada nerede çalışıyormuş?","Babaannesi mektupları nerede saklamış?"],"title":"Babaannemin sandığı","ans":{"1":"Tavan arasında buldular.","2":"Bir saat yürüyerek gidiyormuş.","3":"Öğretmen kendisi geliyormuş.","4":"İzmir'de bir fabrikada çalışıyormuş.","5":"Sandıkta saklamış."}},"exercises":[{"n":1,"title":"-(I)yordu bilan tuslang.","items":[["a","Ben ders (çalışmak) ___, misafir geldi."],["b","Sen çocukken nerede (oturmak) ___?"],["c","Biz her akşam top (oynamak) ___."],["d","Annem mutfakta yemek (yapmak) ___."],["e","Çocuklar okula yürüyerek (gitmek) ___."],["f","Siz o sırada ne (yapmak) ___?"]],"ans":{"a":"çalışıyordum","b":"oturuyordun","c":"oynuyorduk","d":"yapıyordu","e":"gidiyorlardı","f":"yapıyordunuz"}},{"n":2,"title":"-(I)yordu yoki -DI? Qavsni oching.","items":[["a","Ben ağaca (tırmanmak) ___, annem beni (görmek) ___."],["b","Biz film (izlemek) ___, elektrik (kesilmek) ___."],["c","Kerem top (oynamak) ___, cam (kırılmak) ___."]],"ans":{"a":"tırmanıyordum, gördü","b":"izliyorduk, kesildi","c":"oynuyordu, kırıldı"}},{"n":3,"title":"Xabarni -mIş bilan qayta aytib bering («eshitdim…»).","items":[["a","Ali Amca dükkânı kapattı. → Ali Amca dükkânı kapatmış."],["b","Eski evi yıktılar. →"],["c","Mahalle çok değişti. →"],["d","Zeynep İzmir'e taşındı. →"],["e","Kerem sınavı kazandı. →"]],"ans":{"b":"Eski evi yıkmışlar.","c":"Mahalle çok değişmiş.","d":"Zeynep İzmir'e taşınmış.","e":"Kerem sınavı kazanmış."}},{"n":4,"title":"Vaziyatga mos -mIş gap ayting.","items":[["a","Uyga kirasiz — oshxonadan mazali hid kelyapti. →"],["b","Koʻchaga chiqasiz — yer hoʻl. →"],["c","Telefonni olasiz — beshta javobsiz qoʻngʻiroq. →"]],"ans":{"a":"Annem yemek yapmış!","b":"Yağmur yağmış!","c":"Biri beni aramış!"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Men kitob oʻqiyotgan edim, telefon jiringladi."],["b","Bolaligimizda bobomning bogʻida oʻynar edik."],["c","Eski uyni buzishibdi."],["d","Buvim yoshligida qishloqda maktab yoʻq ekan."],["e","Mahalla juda oʻzgaribdi."]],"ans":{"a":"Ben kitap okuyordum, telefon çaldı.","b":"Çocukken dedemin bahçesinde oynuyorduk.","c":"Eski evi yıkmışlar.","d":"Babaannem gençken köyde okul yokmuş.","e":"Mahalle çok değişmiş."}},{"n":6,"title":"Yozish. «Unutamadığım bir gün» — esdan chiqmaydigan bir kun haqida 10–12 gap yozing. -(I)yordu","items":[],"extra":"(vaziyat) va -DI (voqealar) ni birga ishlating.","ans":{}}]},{"id":"a2-7","level":"A2","n":7,"title":"Girebilir miyim, Hocam?","sub":"Imkoniyat -(y)Abil · qila olmaslik -(y)AmA · ruxsat soʻrash · muloyim murojaat","goals":["qila olish va qila olmaslik haqida gapirish","-(y)Abil (yapabilirim)","-(y)AmA (yapamam)","ruxsat soʻrash va muloyim iltimos","rad etish va uzr soʻrash","ustoz va rahbarga murojaat odobi"],"vocab":[{"title":"Lugʻat","words":[["izin","ruxsat"],["izin istemek","ruxsat soʻramoq"],["müsaade","ruxsat (rasmiy)"],["rica etmek","iltimos qilmoq"],["yardım etmek","yordam bermoq"],["müsait","boʻsh, vaqti bor"],["meşgul","band"],["maalesef","afsuski"],["elbette / tabii","albatta"],["kusura bakmayın","kechirasiz, xafa boʻlmang"],["acaba","...mikin, qiziq"],["toplantı","majlis, yigʻilish"],["müdür","direktor, mudir"],["sekreter","kotiba"],["randevu","uchrashuv vaqti"],["sunum","taqdimot"],["sınav","imtihon"],["ödev","uy vazifasi"],["kalem","ruchka, qalam"],["pencere","deraza"]]},{"title":"Mavzuli lugʻat — ofis va maktab","words":[["ofis","idora, ofis"],["bilgisayar","kompyuter"],["yazıcı","printer"],["fotokopi çekmek","nusxa koʻchirmoq"],["imzalamak","imzolamoq"],["dosya","papka, hujjat"],["sınıf","sinf"],["tahta","doska"],["kütüphane","kutubxona"],["öğle arası","tushlik tanaffusi"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"-(y)Abil: «…a olaman»"},{"p":"Oʻzak + (y)Abil + zamon qoʻshimchasi. Ikki shaklli: -abil / -ebil; unlidan keyin -yabil / -yebil."},{"table":{"h":["Zamon","çizmek","yüzmek","anlamak"],"r":[["geniş","çizebilirim","yüzebilirim","anlayabilirim"],["hozirgi","çizebiliyorum","yüzebiliyorum","anlayabiliyorum"],["oʻtgan","çizebildim","yüzebildim","anlayabildim"],["kelasi","çizebileceğim","yüzebileceğim","anlayabileceğim"]]}},{"p":"Biraz Türkçe anlayabiliyorum. — Biroz turkcha tushuna olaman. Bana yol tarif edebilir misiniz? — Menga yoʻl koʻrsatib bera olasizmi? Sonunda bileti alabildim. — Nihoyat chiptani ola oldim."},{"sub":"-(y)AmA: «…a olmayman» (inkor)"},{"p":"Inkorda -abil ishlatilmaydi — uning oʻrniga -(y)AmA keladi:"},{"table":{"h":["Zamon","çizmek","yüzmek","anlamak"],"r":[["geniş","çizemem / çizemezsin / çizemez","yüzemem / yüzemezsin / yüzemez","anlayamam / anlayamazsın / anlayamaz"],["geniş (koʻplik)","çizemeyiz / çizemezsiniz / çizemezler","yüzemeyiz / yüzemezsiniz / yüzemezler","anlayamayız / anlayamazsınız / anlayamazlar"],["hozirgi","çizemiyorum","yüzemiyorum","anlayamıyorum"],["oʻtgan","çizemedim","yüzemedim","anlayamadım"],["kelasi","çizemeyeceğim","yüzemeyeceğim","anlayamayacağım"]]}},{"p":"Kusura bakma, bu akşam gelemem. — Kechirasan, bugun kechqurun kela olmayman. Gürültüden dün gece uyuyamadım. — Shovqindan kecha kechasi uxlay olmadim."},{"sub":"-(y)Abil ning uch maʼnosi"},{"table":{"h":["Maʼnosi","Misol"],"r":[["qobiliyat","Gitar çalabilir misin? — Gitara chala olasanmi?"],["ruxsat","Pencereyi açabilir miyim? — Derazani ochsam boʻladimi? · Çıkabilirsiniz. — Chiqishingiz mumkin."],["ehtimol","Akşam yağmur yağabilir. — Kechqurun yomgʻir yogʻishi mumkin."]]}},{"sub":"Ruxsat soʻrash va iltimos — muloyimlik darajalari"},{"table":{"h":["Oddiy","Muloyim","Juda muloyim / rasmiy"],"r":[["Oturabilir miyim?","Acaba oturabilir miyim?","Müsaadenizle oturabilir miyim?"],["Bana yardım et.","Bana yardım edebilir misin?","Bana yardım edebilir misiniz acaba?"],["Defterini ver.","Defterini verir misin?","Rica etsem defterinizi verir misiniz?"]]}},{"p":"Javoblar: ✔ Tabii, buyurun. · Elbette. · Gel! — ✘ Maalesef olmaz. · Kusura bakmayın, şu an müsait değilim. (Kechirasiz, hozir bandman.)"},{"note":"Ustoz yoki rahbar xonasiga kirish odobi: eshikni taqillating → «Buyurun» yoki «Gel» javobini kuting → kirib salom bering → oʻzingizni tanishtiring → maqsadni qisqa ayting. Masalan: «İyi günler hocam, ben Jasur Rahimov. Ödevim hakkında birkaç dakika konuşabilir miyiz?»"}]},{"kind":"dialog","title":"Dialog: Hocanın odasında","blocks":[{"dlg":[["Dilnoza","Hocam, müsait misiniz? Girebilir miyim?"],["Elif Hoca","Tabii Dilnoza, gel. Oturabilirsin."],["Dilnoza","Teşekkür ederim. Bir şey rica edebilir miyim?"],["Elif Hoca","Buyur, seni dinliyorum."],["Dilnoza","Cuma günkü sınava giremeyeceğim. Konsolosluğa gitmem gerekiyor."],["Elif Hoca","Randevunu başka bir güne alamaz mısın?"],["Dilnoza","Maalesef alamıyorum, sadece cuma günü boş yer var."],["Elif Hoca","Anlıyorum. O zaman sınava pazartesi girebilirsin."],["Dilnoza","Çok sevinirim! Bir de, sunumumu size e-postayla gönderebilir miyim?"],["Elif Hoca","Gönderebilirsin, ama en geç perşembe akşamı elimde olmalı."],["Dilnoza","Tamam hocam. Çıkabilir miyim?"],["Elif Hoca","Çıkabilirsin. Kolay gelsin!"]]},{"gloss":[["müsait","boʻsh, qulay"],["rica etmek","iltimos qilmoq"],["konsolosluk","konsullik"],["randevu","qabul vaqti"],["boş yer","boʻsh joy"],["sevinmek","xursand boʻlmoq"],["sunum","taqdimot"],["en geç","eng kechi bilan"]]}]}],"reading":{"title":"Spor salonu kuralları","text":"Değerli üyelerimiz! Salonumuz her gün 07.00–23.00 arasında açıktır. Girişte üye kartınızı göstermelisiniz; kartsız giremezsiniz. Eşyalarınızı dolaplara koyabilirsiniz, ama dolapları gece boyunca kullanamazsınız. Salonda spor ayakkabısı giymek zorunludur. Aletleri kullandıktan sonra silmelisiniz. Su şişenizi yanınıza alabilirsiniz, fakat salonda yemek yiyemezsiniz. On altı yaşından küçükler yalnız gelemez; bir yetişkinle birlikte spor yapabilirler. Yeni üyeler ilk gün antrenörden ücretsiz program isteyebilir. Havuzu kullanmak için ayrıca sağlık raporu getirmeniz gerekir.","gloss":[["üye","aʼzo"],["eşya","buyum"],["gece boyunca","tun boʻyi"],["zorunlu","majburiy"],["alet","trenajyor, asbob"],["silmek","artmoq"],["şişe","shisha idish"],["yalnız","yolgʻiz"],["antrenör","murabbiy"],["ücretsiz","bepul"],["havuz","hovuz"],["paralı","pullik"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Üye kartı olmadan salona girebilirsiniz.","Eşyalarınızı dolaba koyabilirsiniz.","Salonda yemek yiyebilirsiniz.","On beş yaşındaki bir çocuk salona yalnız gelemez.","Yeni üyeler için ilk program paralıdır."],"ans":{"1":"Y","2":"D","3":"Y","4":"D","5":"Y"}},"exercises":[{"n":1,"title":"-(y)Abil bilan toʻldiring (geniş zaman).","items":[["a","Ben gitar ___ . (çalmak)"],["b","Sen bu soruyu ___ . (çözmek)"],["c","Defne çok hızlı ___ . (yüzmek)"],["d","Biz yarın ___ . (gelmek)"],["e","Siz dolapları ___ . (kullanmak)"],["f","Çocuklar burada ___ . (oynamak)"]],"ans":{"a":"çalabilirim","b":"çözebilirsin","c":"yüzebilir","d":"gelebiliriz","e":"kullanabilirsiniz","f":"oynayabilirler"}},{"n":2,"title":"Inkor shaklga aylantiring: -(y)AmA.","items":[["a","Gelebilirim. →"],["b","Yüzebilirsin. →"],["c","Dün uyuyabildim. →"],["d","Sınava girebiliriz. →"],["e","Kapıyı açabildi. →"]],"ans":{"a":"Gelemem.","b":"Yüzemezsin.","c":"Dün uyuyamadım.","d":"Sınava giremeyiz.","e":"Kapıyı açamadı."}},{"n":3,"title":"Muloyim iltimosga aylantiring (-(y)Abilir misiniz?).","items":[["a","Pencereyi aç."],["b","Biraz bekle."],["c","Bana kalemini ver."],["d","Tekrar et."],["e","Yavaş konuş."]],"ans":{"a":"Pencereyi açabilir misiniz?","b":"Biraz bekleyebilir misiniz?","c":"Bana kaleminizi verebilir misiniz?","d":"Tekrar edebilir misiniz?","e":"Yavaş konuşabilir misiniz?"}},{"n":4,"title":"Maʼnosini aniqlang: qobiliyat (Q), ruxsat (R) yoki ehtimol (E)?","items":[["a","Dedem üç dil konuşabilir."],["b","Yarın kar yağabilir."],["c","Hocam, dışarı çıkabilir miyim?"],["d","Pamuk çok yükseğe atlayabilir."],["e","Otobüs geç kalabilir."],["f","Burada fotoğraf çekebilirsiniz."]],"ans":{"a":"Q","b":"E","c":"R","d":"Q","e":"E","f":"R"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Kirsam maylimi?"],["b","Afsuski, juma kuni kela olmayman."],["c","Sekinroq gapira olasizmi?"],["d","Bu yerda ovqat yeyish mumkin emas."],["e","U gitara chala oladi."]],"ans":{"a":"Girebilir miyim?","b":"Maalesef cuma günü gelemem.","c":"Daha yavaş konuşabilir misiniz?","d":"Burada yemek yiyemezsiniz.","e":"O gitar çalabilir."}},{"n":6,"title":"Rolli oʻyin. Ustozingiz yoki rahbaringizdan biror narsa uchun ruxsat soʻrang: eshikni taqillating, salom bering, sababini ayting, rahmat aytib xayrlashing.","items":[],"ans":{}}]},{"id":"a2-8","level":"A2","n":8,"title":"Günüm Nasıldı?","sub":"-(y)ken · -DIktAn sonra · -mAdAn önce · ketma-ketlik · voqeani aytib berish","goals":["voqealarni tartib bilan aytib berish","-(y)ken (giderken — ketayotganda)","-DIktAn sonra (yedikten sonra — yegandan keyin)","-mAdAn önce (yatmadan önce — yotishdan oldin)","ketma-ketlik soʻzlari","qisqa xabar va hisobot yozish"],"vocab":[{"title":"Lugʻat","words":[["önce","oldin"],["sonra","keyin"],["ardından","uning ortidan, keyin"],["en sonunda","eng oxirida"],["ilk olarak","birinchi navbatda"],["sırasında","...vaqtida"],["olay","voqea"],["haber vermek","xabar bermoq"],["bildirmek","maʼlum qilmoq"],["gecikmek","kechikmoq"],["kaza","baxtsiz hodisa, avariya"],["arıza","buzilish, nosozlik"],["tamir etmek","taʼmirlamoq"],["dişlerini fırçalamak","tish yuvmoq"],["yola çıkmak","yoʻlga chiqmoq"],["dönmek","qaytmoq"],["bitmek","tugamoq"],["başlamak","boshlanmoq"],["müşteri","mijoz"],["vardiya","smena"]]},{"title":"Mavzuli lugʻat — ish kuni","words":[["mesai","ish vaqti"],["işe başlamak","ishni boshlamoq"],["mola vermek","tanaffus qilmoq"],["e-posta","elektron xat"],["rapor","hisobot"],["teslim etmek","topshirmoq"],["şef","boshliq, shef"],["iş arkadaşı","hamkasb"],["servis","xizmat avtobusi"],["fazla mesai","qoʻshimcha ish vaqti"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"-(y)ken: «…yotganda», «…ganda»"},{"p":"-ken unli uygʻunligiga boʻysunmaydi — doim -ken; unli bilan tugagan soʻzdan keyin -yken."},{"table":{"h":["Nimaga qoʻshiladi","Misol","Oʻzbekcha"],"r":[["ot yoki sifat","küçükken, gençken, yorgunken","kichikligimda, yoshligimda, charchaganimda"],["oʻrin shakli (-DA)","yoldayken, tatildeyken","yoʻldaligimda, taʼtilda boʻlganimda"],["feʼl + geniş zaman","okurken, yürürken, pişirirken","oʻqiyotganda, yurganda, pishirayotganda"],["inkor","bilmezken","bilmagan holda, bilmay turib"]]}},{"p":"Yemek pişirirken müzik dinlerim. — Ovqat pishirayotganda musiqa tinglayman. Otobüsteyken Defne aradı. — Avtobusda ketayotganimda Defne qoʻngʻiroq qildi."},{"sub":"-DIktAn sonra: «…gandan keyin»"},{"p":"Oʻzak + DIk + tAn sonra. Unli va undoshga qarab sakkiz xil shakl chiqadi:"},{"table":{"h":["Shakl","Oʻzbekcha","Misol"],"r":[["öğren-dikten sonra","bilib olgandan keyin","Sonucu öğrendikten sonra rahatladım."],["yap-tıktan sonra","qilgandan keyin","Kahvaltı yaptıktan sonra yürüyüşe çıktık."],["oku-duktan sonra","oʻqigandan keyin","Mesajı okuduktan sonra gülümsedi."],["gör-dükten sonra","koʻrgandan keyin","Pamuk'u gördükten sonra çocuklar sevindi."],["bit-tikten sonra","tugagandan keyin","Film bittikten sonra eve döndük."]]}},{"p":"Shaxs qoʻshimchasi olmaydi — kim ekanligi gapning qolgan qismidan bilinadi. Otdan keyin oddiygina -DAn sonra: maçtan sonra, öğleden sonra, bir haftadan sonra."},{"sub":"-mAdAn önce: «…ishdan oldin» va -mAdAn: «…may turib»"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Uyumadan önce kitap okurum.","Uxlashdan oldin kitob oʻqiyman."],["Evden çıkmadan önce ocağı kontrol et.","Uydan chiqishdan oldin plitani tekshir."],["Otdan keyin: Dersten önce kahve içeriz.","Darsdan oldin qahva ichamiz."],["-mAdAn = «…may turib»: Veda etmeden gitti.","Xayrlashmay ketib qoldi."]]}},{"sub":"Hikoya va hisobotda ketma-ketlik"},{"p":"Voqealarni tartib bilan aytish uchun: İlk olarak / Önce → Sonra / Ardından → Daha sonra → En sonunda."},{"note":"Qisqa hisobot yozish tartibi: 1) kim yozmoqda, 2) qachon va qayerda, 3) nima boʻldi, 4) qanday chora koʻrildi, 5) hozirgi holat. Gaplar qisqa va aniq boʻlsin. Masalan: «Merhaba Murat Bey, ben Dilnoza. Saat 09.40'ta asansör arızalandı. Teknik servisi aradım. Yaklaşık bir saat sürecek. Şu an merdiveni kullanıyoruz.»"}]},{"kind":"dialog","title":"Dialog: Akşam yemeğinde","blocks":[{"dlg":[["Zeynep","Hoş geldin Defne! Günün nasıldı?"],["Defne","Sorma! Sabah evden çıkarken anahtarımı unuttum."],["Zeynep","Eyvah! Sonra ne oldu?"],["Defne","Otobüs beklerken yağmur başladı. Şemsiyem de yoktu."],["Zeynep","İşe geç kaldın mı?"],["Defne","Beş dakika. Toplantıya girmeden önce bir kahve içtim, biraz kendime geldim."],["Zeynep","Öğleden sonra daha iyi miydi?"],["Defne","Evet. Hastaları gördükten sonra müdürle konuştum. Bana bir hafta izin verdi!"],["Zeynep","Harika! Ben de sen yokken yemek yaptım."],["Defne","Çok güzel kokuyor. Yemekten sonra bulaşıkları ben yıkarım."],["Zeynep","Anlaştık. Sofraya oturmadan önce ellerini yıka!"],["Defne","Tamam anne!"]]},{"gloss":[["sorma","soʻrama (yomon oʻtdi)"],["anahtar","kalit"],["şemsiye","soyabon"],["toplantı","yigʻilish"],["kendime geldim","oʻzimga keldim"],["hasta","bemor"],["izin","taʼtil, ruxsat"],["kokmak","hid taratmoq"],["anlaştık","kelishdik"],["sofra","dasturxon"]]}]}],"reading":{"title":"Kerem'in ilk iş günü","text":"Kerem dün yeni işine başladı. Sabah kahvaltı yapmadan önce gömleğini ütüledi. Evden çıkarken telefonuna baktı: saat yedi buçuktu. Metroda giderken notlarını tekrar etti. Kafeye vardıktan sonra müdürüyle tanıştı. Müdür ona önce kahve makinesini gösterdi. Kerem ilk kahveyi yaparken çok heyecanlıydı ve sütü döktü. Müşteriler gülmedi, hatta biri \"Kolay gelsin!\" dedi. Öğle arasından sonra işler hızlandı. Kerem sipariş alırken hiç hata yapmadı. Kafe kapandıktan sonra masaları sildi ve yerleri süpürdü. Eve dönmeden önce annesini aradı: \"Anne, ilk günüm çok güzel geçti!\"","gloss":[["gömlek","koʻylak"],["ütülemek","dazmollamoq"],["varmak","yetib bormoq"],["heyecanlı","hayajonli"],["dökmek","toʻkmoq"],["hatta","hatto"],["öğle arası","tushlik tanaffusi"],["sipariş","buyurtma"],["hata","xato"],["süpürmek","supurmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Kerem kahvaltıdan önce ne yaptı?","Metroda giderken ne yaptı?","İlk kahveyi yaparken ne oldu?","Kafe kapandıktan sonra ne yaptı?","Eve dönmeden önce kimi aradı?"],"ans":{"1":"Gömleğini ütüledi.","2":"Notlarını tekrar etti.","3":"Sütü döktü.","4":"Masaları sildi ve yerleri süpürdü.","5":"Annesini aradı."}},"exercises":[{"n":1,"title":"-(y)ken bilan birlashtiring.","items":[["a","Evden çıkıyordum. Anahtarı unuttum. → Evden ___ anahtarı unuttum."],["b","Otobüs bekliyordum. Yağmur başladı. → Otobüs ___ yağmur başladı."],["c","Öğrenciydim. Yurtta kalıyordum. → ___ yurtta kalıyordum."],["d","Kahve yapıyordu. Sütü döktü. → Kahve ___ sütü döktü."],["e","Sen yoktun. Yemek yaptım. → Sen ___ yemek yaptım."]],"ans":{"a":"çıkarken","b":"beklerken","c":"Öğrenciyken","d":"yaparken","e":"yokken"}},{"n":2,"title":"-DIktAn sonra qoʻshing.","items":[["a","Kafe kapan___ sonra masaları sildi."],["b","Yemek ye___ sonra çay içtik."],["c","Hastaları gör___ sonra müdürle konuştum."],["d","Kitabı oku___ sonra sana veririm."],["e","İşe başla___ sonra çok değişti."]],"ans":{"a":"kapandıktan","b":"yedikten","c":"gördükten","d":"okuduktan","e":"başladıktan"}},{"n":3,"title":"-mAdAn önce qoʻshing.","items":[["a","Sofraya otur___ önce ellerini yıka."],["b","Evden çık___ önce ışıkları kapat."],["c","Toplantıya gir___ önce kahve içtim."],["d","Yat___ önce kitap okurum."],["e","Karar ver___ önce iyi düşün."]],"ans":{"a":"oturmadan","b":"çıkmadan","c":"girmeden","d":"Yatmadan","e":"vermeden"}},{"n":4,"title":"Toʻgʻri tartibda yozing: önce, sonra, en sonunda.","items":[["a","bulaşıkları yıkadım · yemek yedim · yemek pişirdim"]],"ans":{"a":"Önce yemek pişirdim, sonra yemek yedim, en sonunda bulaşıkları yıkadım."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Uydan chiqayotganda kalitimni unutdim."],["b","Ovqatdan keyin idishlarni yuvaman."],["c","Uxlashdan oldin kitob oʻqiyman."],["d","Ishni tugatgandan keyin onamga qoʻngʻiroq qildim."],["e","Sen yoʻqligingda Kerem keldi."]],"ans":{"a":"Evden çıkarken anahtarımı unuttum.","b":"Yemekten sonra bulaşıkları yıkarım.","c":"Yatmadan önce kitap okurum.","d":"İşi bitirdikten sonra annemi aradım.","e":"Sen yokken Kerem geldi."}},{"n":6,"title":"Yozish. Kechagi kuningizni 6–8 gapda tartib bilan yozing: önce, sonra, -(y)ken, -DIktAn sonra, -mAdAn önce ishlating.","items":[],"ans":{}}]},{"id":"b1-1","level":"B1","n":1,"title":"Tarihe Yön Veren İnsanlar","sub":"Sifatdoshlar -(y)An · -DIK · -(y)AcAK · otlashgan sifatdosh · tarix va fan","goals":["murakkab aniqlovchilar tuzish: kütüphanede çalışan kadın (kutubxonada ishlaydigan ayol), okuduğum kitap (men oʻqigan kitob), gideceğimiz yer (boradigan joyimiz)","-(y)An va -DIK farqi","otlashgan shakllar (gelenler, bildiklerim)","tarix, fan va madaniyat lugʻati"],"vocab":[{"title":"Lugʻat","words":[["tarih","tarix"],["yüzyıl","asr"],["bilim insanı","olim"],["şair","shoir"],["yazar","yozuvchi"],["mimar","meʼmor"],["mucit","ixtirochi"],["keşif","kashfiyot"],["icat etmek","ixtiro qilmoq"],["eser","asar"],["yapı","imorat, inshoot"],["gözlemevi","rasadxona"],["medrese","madrasa"],["yönetmek","boshqarmoq"],["kurmak","qurmoq, asos solmoq"],["doğmak","tugʻilmoq"],["ölmek","vafot etmoq"],["ünlü","mashhur"],["önemli","muhim"],["etkilemek","taʼsir qilmoq"]]},{"title":"Mavzuli lugʻat — fan va madaniyat","words":[["matematik","matematika"],["astronomi","astronomiya"],["tıp","tibbiyot"],["felsefe","falsafa"],["şiir","sheʼr"],["roman","roman"],["müze","muzey"],["kitabe","bitik, yozuv"],["miras","meros"],["nesil","avlod"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"-(y)An: «…gan», «…yotgan», «…digan» (ish-harakat egasi)"},{"p":"Agar sifatdosh aniqlayotgan ot ishni oʻzi bajarsa, -(y)An ishlatiladi. Shakli ikki xil: -an / -en; unlidan keyin -yan / -yen."},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["köprüde balık tutan adam","koʻprikda baliq tutayotgan odam"],["geçen hafta gelen paket","oʻtgan hafta kelgan posilka"],["üç dil konuşan rehber","uch tilda gapiradigan gid"],["et yemeyen insanlar","goʻsht yemaydigan odamlar"],["yarışmayı kazanan öğrenci","tanlovda gʻolib chiqqan oʻquvchi"]]}},{"p":"-(y)An oʻzi zamonni koʻrsatmaydi, zamon gapdan bilinadi: dün arayan kişi (kecha qoʻngʻiroq qilgan odam) · şu an şarkı söyleyen kız (hozir qoʻshiq aytayotgan qiz)."},{"sub":"-DIK + egalik: «men …gan», «sen …gan»"},{"p":"Agar ot ishni bajarmasa — u toʻldiruvchi, joy yoki vaqt boʻlsa — -DIK + egalik qoʻshimchasi ishlatiladi:"},{"table":{"h":["Shaxs","-DIK + egalik","Misol","Oʻzbekcha"],"r":[["ben","izlediğim","izlediğim dizi","men koʻrgan serial"],["sen","izlediğin","izlediğin dizi","sen koʻrgan serial"],["o","izlediği","Defne'nin izlediği dizi","Defne koʻrgan serial"],["biz","izlediğimiz","izlediğimiz dizi","biz koʻrgan serial"],["siz","izlediğiniz","izlediğiniz dizi","siz koʻrgan serial"],["onlar","izledikleri","izledikleri dizi","ular koʻrgan serial"]]}},{"p":"Shakllari sakkizta: -dık / -dik / -duk / -dük / -tık / -tik / -tuk / -tük. Egalik qoʻshimchasi oldidan k → ğ: aldığım, sevdiğin, bulduğu."},{"p":"Misollar: Kaldığımız otel denize çok yakın. — Biz turgan mehmonxona dengizga juda yaqin. Murat Bey'in önerdiği restoran kapalıydı. — Murat bey tavsiya qilgan restoran yopiq edi. Tanıştığımız gün — biz tanishgan kun."},{"sub":"-(y)An yoki -DIK? — tekshiruv savoli"},{"p":"Oʻzingizdan soʻrang: ot bu ishni oʻzi qilyaptimi?"},{"table":{"h":["Ot ishni bajaradi → -(y)An","Ot ishni bajarmaydi → -DIK"],"r":[["resmi çizen çocuk (rasmni chizgan bola)","çocuğun çizdiği resim (bola chizgan rasm)"],["bizi götüren taksi (bizni olib ketayotgan taksi)","bindiğimiz taksi (biz oʻtirgan taksi)"],["bu sokakta oturan aileler","oturduğumuz sokak"]]}},{"sub":"Kelajak maʼnosi: -(y)AcAK"},{"p":"Haftaya açılacak kütüphane (kelasi hafta ochiladigan kutubxona) · kalacağımız ev (biz turadigan uy) · okuyacağım roman (men oʻqiydigan roman)."},{"sub":"Otlashgan sifatdoshlar"},{"p":"Aniqlanayotgan ot tushib qolsa, sifatdoshning oʻzi ot vazifasini bajaradi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Geç kalanlar içeri giremez.","Kechikkanlar ichkariga kira olmaydi."],["Bilet almayanlar sırada beklesin.","Chipta olmaganlar navbatda kutsin."],["Gördüklerimi sana anlatacağım.","Koʻrganlarimni senga aytib beraman."],["Dediğin doğru.","Aytganing toʻgʻri."],["Hatırladığım kadarıyla…","Esimda qolishicha…"]]}},{"note":"Tarjimada yordam: oʻzbekcha -gan, -yotgan, -digan ni koʻrsangiz, oʻylang — ot ishni bajaryaptimi? Ha → -(y)An. Ishni boshqa birov (men, sen, Kerem…) qilyaptimi? → -DIK + egalik. Men sotib olgan kitob → aldığım kitap · Kitobni sotib olgan odam → kitabı alan kişi."}]},{"kind":"dialog","title":"Dialog: Kitap fuarında","blocks":[{"dlg":[["Kerem","Dilnoza, aradığın kitabı buldun mu?"],["Dilnoza","Henüz bulamadım. Ali Kuşçu'yu anlatan bir biyografi arıyorum."],["Kerem","Şu köşede duran kitapçıya soralım."],["Kitapçı","Buyurun, aradığınız kitap bu olabilir. Geçen ay çıkan yeni bir çalışma."],["Dilnoza","Evet, bu! Yazarını tanıyorum; üniversitede dersine girdiğim hoca."],["Kitapçı","O zaman şanslısınız. Yarın burada imza günü yapacak."],["Kerem","Ben de okuyacak bir şey arıyorum. Tavsiye edeceğiniz bir roman var mı?"],["Kitapçı","Tarihi seven okurlar bunu çok beğeniyor: Semerkant'ta geçen bir hikâye."],["Kerem","Alıyorum. Dilnoza, okuduktan sonra sana veririm."],["Dilnoza","Anlaştık. Ben de bitirdiğim kitapları sana getiririm."]]},{"gloss":[["fuar","yarmarka"],["biyografi","tarjimai hol"],["çalışma","asar, ish"],["dersine girmek","darsiga qatnashmoq"],["imza günü","dastxat kuni"],["tavsiye etmek","tavsiya qilmoq"],["okur","kitobxon"],["beğenmek","yoqtirmoq"],["geçmek","boʻlib oʻtmoq (voqea)"]]}]}],"reading":{"title":"Ali Kuşçu","text":"Ali Kuşçu, on beşinci yüzyılda yaşayan ünlü bir gök bilimci ve matematikçidir. Semerkant'ta doğdu. Babası, Uluğ Bey'in kuşlarına bakan bir görevliydi; \"Kuşçu\" adı buradan gelir. Genç Ali, Uluğ Bey'in kurduğu medresede okudu ve hocasının en sevdiği öğrencilerden biri oldu. Daha sonra Semerkant Rasathanesi'ni yöneten bilginler arasına girdi. Uluğ Bey'in ölümünden sonra şehirden ayrıldı ve uzun bir yolculuğa çıktı. 1472'de Fatih Sultan Mehmet'in davet ettiği bilgin olarak İstanbul'a geldi. Ayasofya Medresesi'nde ders verdi; yazdığı matematik ve astronomi kitapları yüzyıllarca okutuldu. İki yıl sonra İstanbul'da öldü. Bugün onun adını taşıyan okullar hem Özbekistan'da hem Türkiye'de vardır.","gloss":[["yüzyıl","asr"],["gök bilimci","astronom"],["bakmak","parvarish qilmoq"],["kurmak","asos solmoq"],["rasathane","rasadxona"],["yönetmek","boshqarmoq"],["bilgin","olim"],["ayrılmak","ketmoq"],["davet etmek","taklif qilmoq"],["okutmak","oʻqitmoq"],["adını taşımak","nomi bilan atalmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Ali Kuşçu nerede doğdu?","\"Kuşçu\" adı nereden gelir?","Hangi medresede okudu?","İstanbul'a ne zaman geldi?","İstanbul'da nerede ders verdi?"],"ans":{"1":"Semerkant'ta doğdu.","2":"Babası Uluğ Bey'in kuşlarına bakan bir görevliydi.","3":"Uluğ Bey'in kurduğu medresede okudu.","4":"1472'de geldi.","5":"Ayasofya Medresesi'nde ders verdi."}},"exercises":[{"n":1,"title":"-(y)An bilan birlashtiring.","items":[["a","Çocuk bahçede oynuyor. → bahçede ___ çocuk"],["b","Kitap geçen ay çıktı. → geçen ay ___ kitap"],["c","Öğrenci tarihi seviyor. → tarihi ___ öğrenci"],["d","Adam köşede duruyor. → köşede ___ adam"],["e","Bilgin İstanbul'a geldi. → İstanbul'a ___ bilgin"]],"ans":{"a":"oynayan","b":"çıkan","c":"seven","d":"duran","e":"gelen"}},{"n":2,"title":"-DIK + egalik bilan birlashtiring.","items":[["a","Ben bir kitap arıyorum. → ___ kitap"],["b","Sen bir film izledin. → ___ film"],["c","O bir medrese kurdu. → ___ medrese"],["d","Biz bir şehirde yaşıyoruz. → ___ şehir"],["e","Siz bir roman tavsiye ettiniz. → ___ roman"]],"ans":{"a":"aradığım","b":"izlediğin","c":"kurduğu","d":"yaşadığımız","e":"tavsiye ettiğiniz"}},{"n":3,"title":"-(y)An yoki -DIK? Toʻgʻri shaklni yozing.","items":[["a","Beni ___ arkadaşım kapıda. (beklemek)"],["b","___ arkadaşım henüz gelmedi. (beklemek, ben)"],["c","Semerkant'ta ___ bir bilgin (doğmak)"],["d","Ali Kuşçu'nun ___ kitaplar (yazmak)"],["e","Yarın ___ kitabı bugün aldım. (okumak, ben)"]],"ans":{"a":"bekleyen","b":"Beklediğim","c":"doğan","d":"yazdığı","e":"okuyacağım"}},{"n":4,"title":"Otlashgan shakl bilan qayta yozing.","items":[["a","Geç kalan öğrenciler dışarıda beklesin. →"],["b","Öğrendiğim şeyleri unutmadım. →"],["c","Kitap seven insanlar fuara geldi. →"],["d","Söylediğin şeyleri anladım. →"]],"ans":{"a":"Geç kalanlar dışarıda beklesin.","b":"Öğrendiklerimi unutmadım.","c":"Kitap sevenler fuara geldi.","d":"Söylediklerini anladım."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Men izlagan kitob shu."],["b","Burchakda turgan odam mening ustozim."],["c","Ulugʻbek qurgan madrasa Samarqandda."],["d","Oʻqiydigan kitobim yoʻq."],["e","Kech qolganlar kirmasin."]],"ans":{"a":"Aradığım kitap bu.","b":"Köşede duran adam benim hocam.","c":"Uluğ Bey'in kurduğu medrese Semerkant'ta.","d":"Okuyacak kitabım yok.","e":"Geç kalanlar girmesin."}},{"n":6,"title":"Yozish. Siz hurmat qiladigan tarixiy shaxs, olim yoki yozuvchi haqida 8–10 gap yozing. -(y)An va -DIK shakllarini ishlating.","items":[],"ans":{}}]},{"id":"b1-2","level":"B1","n":2,"title":"İş ve Sorumluluk","sub":"Sabab: çünkü · -DIğI için · yüzünden / sayesinde · natija · maqsad -mAk için","goals":["sabab va natijani turli yoʻllar bilan ifodalash","-DIğI için (hasta olduğum için — kasal boʻlganim uchun)","yüzünden / sayesinde / nedeniyle","natija bogʻlovchilari (bu yüzden, bu nedenle)","maqsad: -mAk için va -mAsI için","masʼuliyat, mukofot va ish lugʻati"],"vocab":[{"title":"Lugʻat","words":[["sorumluluk","masʼuliyat"],["sorumlu","masʼul"],["görev","vazifa"],["ödül","mukofot"],["ceza","jazo, jarima"],["başarı","muvaffaqiyat"],["başarmak","uddalamoq"],["hata","xato"],["dikkatli","ehtiyotkor"],["dakik","aniq, oʻz vaqtida keladigan"],["güvenmek","ishonmoq"],["neden / sebep","sabab"],["sonuç","natija"],["ertelemek","kechiktirmoq, qoldirmoq"],["iptal etmek","bekor qilmoq"],["sis","tuman"],["fırtına","boʻron"],["terfi etmek","lavozimi oshmoq"],["maaş","maosh"],["izin","taʼtil, ruxsat"]]},{"title":"Mavzuli lugʻat — ish joyida","words":[["çalışan","xodim"],["yönetici","rahbar"],["ekip","jamoa"],["proje","loyiha"],["müşteri","mijoz"],["toplantı","yigʻilish"],["süre","muddat"],["teslim tarihi","topshirish sanasi"],["mesai","ish vaqti"],["performans","samaradorlik"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Sababni aytishning toʻrt yoʻli"},{"table":{"h":["Usul","Misol","Oʻzbekcha"],"r":[["çünkü + gap","Derse gelmedim, çünkü ateşim vardı.","Darsga kelmadim, chunki isitmam bor edi."],["-DIğI için","Ateşim olduğu için derse gelmedim.","Isitmam boʻlgani uchun darsga kelmadim."],["-DIğIndAn (dolayı) — rasmiy","Yollar buzlu olduğundan okullar tatil edildi.","Yoʻllar muz boʻlgani sababli maktablar yopildi."],["ot + yüzünden / nedeniyle","Fırtına yüzünden vapurlar kalkmadı.","Boʻron tufayli paromlar qatnamadi."]]}},{"sub":"-DIğI için: tuzilishi"},{"p":"Oʻzak + DIk + egalik + için. Bu 1-boʻlimdagi sifatdoshning aynan oʻzi, faqat oxiriga için qoʻshilgan:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Seni beklettiğim için özür dilerim.","Seni kuttirganim uchun uzr soʻrayman."],["Erken çıktığın için trafiğe takılmadın.","Erta chiqqaning uchun tirbandlikka tushmading."],["Zeynep çok çalıştığı için bursu kazandı.","Zeynep koʻp oʻqigani uchun grantni yutdi."],["Yarın taşınacağımız için bu akşam kutu topluyoruz.","Ertaga koʻchadiganimiz uchun bugun kechqurun quti yigʻyapmiz."],["Bugün işe gitmediğim için Pamuk'la oynayabilirim.","Bugun ishga bormaganim uchun Pamuk bilan oʻynay olaman."]]}},{"p":"Kelajak maʼnosida -(y)AcAğI için ishlatiladi (yuqoridagi taşınacağımız için kabi)."},{"sub":"yüzünden, sayesinde, nedeniyle"},{"table":{"h":["Soʻz","Maʼnosi","Misol"],"r":[["yüzünden","salbiy sabab («…dastidan, …tufayli»)","Gürültü yüzünden uyuyamadım. · Senin yüzünden otobüsü kaçırdık!"],["sayesinde","ijobiy sabab («…sharofati bilan»)","Komşumuz sayesinde anahtarı bulduk. · Senin sayende çok şey öğrendim."],["nedeniyle / -DAn dolayı","betaraf, rasmiy","Bakım çalışması nedeniyle su kesilecektir. · Yorgunluktan dolayı erken yattı."]]}},{"p":"Olmoshlar bilan: benim yüzümden, senin yüzünden · sayemde, sayende, sayesinde, sayemizde."},{"sub":"Natija: bu yüzden, bu nedenle"},{"p":"Otobüs çok kalabalıktı, bu yüzden yürümeye karar verdik. — Avtobus juda gavjum edi, shuning uchun piyoda yurishga qaror qildik. Rasmiy uslubda: Sistem güncelleniyor; bu nedenle site iki saat kapalı olacaktır. Boshqa variantlar: o yüzden (soʻzlashuvda), bu sebeple, dolayısıyla (rasmiy — «binobarin»)."},{"sub":"Maqsad: -mAk için va -mAsI için"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Para biriktirmek için ek iş yapıyorum.","Pul yigʻish uchun qoʻshimcha ish qilyapman. (ishni oʻzim qilaman)"],["Çocukların rahat uyuması için ışıkları kıstık.","Bolalar tinch uxlashi uchun chiroqlarni xiralashtirdik. (ishni boshqalar qiladi)"],["Sınavı geçmen için daha çok tekrar yapmalısın.","Imtihondan oʻtishing uchun koʻproq takrorlashing kerak."]]}},{"note":"Ikkalasini adashtirmang: -DIğI için — sabab (…gani uchun), -mAk için — maqsad (…ish uchun). Erken kalktığım için yorgunum. — Erta turganim uchun charchadim (sabab). Erken kalkmak için alarm kurdum. — Erta turish uchun budilnik qoʻydim (maqsad)."}]},{"kind":"dialog","title":"Dialog: Rapor neden gecikti?","blocks":[{"dlg":[["Murat Bey","Jasur, köprü raporu neden hâlâ bitmedi?"],["Jasur","Özür dilerim Murat Bey. Ölçüm cihazı bozulduğu için iki gün çalışamadık."],["Murat Bey","Bana neden haber vermedin?"],["Jasur","Sizi rahatsız etmek istemedim, çünkü toplantıdaydınız. Bu benim hatam."],["Murat Bey","Yağmur yüzünden de gecikme oldu, değil mi?"],["Jasur","Evet, ama Zeynep Hanım'ın yardımı sayesinde ölçümleri dün tamamladık."],["Murat Bey","Güzel. Peki rapor ne zaman hazır olur?"],["Jasur","Hata yapmamak için her sayfayı iki kez kontrol ediyorum. Bu yüzden cuma günü teslim edeceğim."],["Murat Bey","Tamam. Sorun olduğunda hemen söyle, böylece birlikte çözeriz."],["Jasur","Anlaşıldı, teşekkür ederim."]]},{"gloss":[["ölçüm cihazı","oʻlchov asbobi"],["bozulmak","buzilmoq"],["haber vermek","xabar bermoq"],["gecikme","kechikish"],["tamamlamak","tugatmoq"],["teslim etmek","topshirmoq"],["böylece","shunda"],["çözmek","hal qilmoq"],["anlaşıldı","tushunarli"]]}]}],"reading":{"title":"Küçük bir atölyenin sırrı","text":"Zehra Hanım on yıl önce küçük bir seramik atölyesi açtı. İlk yıllarda müşterisi azdı, çünkü atölye ara bir sokaktaydı. Kirayı ödemek için akşamları kurs vermeye başladı. Kurslar sayesinde atölyeyi tanıyanların sayısı arttı. Zehra Hanım siparişleri her zaman söz verdiği günde teslim eder; bu yüzden müşterileri ona güvenir. Bir kez fırın arızası yüzünden büyük bir sipariş gecikti. Müşteriyi hemen arayıp özür diledi ve indirim yaptı. Ona göre başarının sırrı basit: \"Hata yaptığın için değil, hatayı sakladığın için müşteri kaybedersin.\" Bugün atölyede beş kişi çalışıyor.","gloss":[["atölye","ustaxona"],["seramik","kulolchilik"],["ara sokak","tor koʻcha"],["kira","ijara haqi"],["ödemek","toʻlamoq"],["artmak","koʻpaymoq"],["söz vermek","vaʼda bermoq"],["güvenmek","ishonmoq"],["arıza","nosozlik"],["başarı","muvaffaqiyat"],["sır","sir"],["saklamak","yashirmoq"],["kaybetmek","yoʻqotmoq"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["İlk yıllarda atölyenin çok müşterisi vardı.","Zehra Hanım kirayı ödemek için kurs verdi.","Siparişler genellikle geç teslim edilir.","Bir sipariş fırın arızası yüzünden gecikti.","Zehra Hanım'a göre müşteri, hata saklandığı için kaybedilir."],"ans":{"1":"Y","2":"D","3":"Y","4":"D","5":"D"}},"exercises":[{"n":1,"title":"-DIğI için bilan birlashtiring.","items":[["a","Cihaz bozuldu. Çalışamadık. → Cihaz ___ için çalışamadık."],["b","Geç kaldım. Özür dilerim. → Geç ___ için özür dilerim."],["c","Çok yoruldun. Erken yat. → Çok ___ için erken yat."],["d","Yağmur yağıyor. Maç iptal oldu. → Yağmur ___ için maç iptal oldu."],["e","Toplantıdaydınız. Aramadım. → Toplantıda ___ için aramadım."]],"ans":{"a":"bozulduğu","b":"kaldığım","c":"yorulduğun","d":"yağdığı","e":"olduğunuz"}},{"n":2,"title":"yüzünden yoki sayesinde?","items":[["a","Arıza ___ sipariş gecikti."],["b","Kurslar ___ müşteriler arttı."],["c","Gürültü ___ uyuyamadım."],["d","Senin ___ sınavı geçtim, teşekkürler!"],["e","Kar ___ yollar kapandı."]],"ans":{"a":"yüzünden","b":"sayesinde","c":"yüzünden","d":"sayende","e":"yüzünden"}},{"n":3,"title":"Sabab yoki maqsad? -DIğI için yoki -mAk için qoʻying.","items":[["a","Kirayı ___ için kurs veriyor. (ödemek)"],["b","Hasta ___ için işe gelemedim. (olmak, ben)"],["c","Hata ___ için iki kez kontrol ediyorum. (yapmamak)"],["d","Çok ___ için başarılı oldu. (çalışmak, o)"]],"ans":{"a":"ödemek","b":"olduğum","c":"yapmamak","d":"çalıştığı"}},{"n":4,"title":"Ikki gapni bu yüzden bilan bogʻlang.","items":[["a","Cihaz bozuldu. Ölçüm yapamadık. →"],["b","Atölye ara sokaktaydı. Müşteri azdı. →"],["c","Sözünü tutar. Herkes ona güvenir. →"]],"ans":{"a":"Cihaz bozuldu, bu yüzden ölçüm yapamadık.","b":"Atölye ara sokaktaydı, bu yüzden müşteri azdı.","c":"Sözünü tutar, bu yüzden herkes ona güvenir."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Xabar bermaganim uchun uzr soʻrayman."],["b","Yomgʻir tufayli kechikdik."],["c","Sening yordaming tufayli tugatdim."],["d","Xato qilmaslik uchun ikki marta tekshiraman."],["e","U vaʼdasida turadi, shuning uchun unga ishonaman."]],"ans":{"a":"Haber vermediğim için özür dilerim.","b":"Yağmur yüzünden geç kaldık.","c":"Senin yardımın sayesinde bitirdim.","d":"Hata yapmamak için iki kez kontrol ediyorum.","e":"O sözünü tutar, bu yüzden ona güveniyorum."}},{"n":6,"title":"Yozish. «İşte sorumluluk neden önemlidir?» mavzusida 8–10 gap yozing. Sabab va natija ifodalarini ishlating.","items":[],"ans":{}}]},{"id":"b1-3","level":"B1","n":3,"title":"Alarm Çalarsa Ne Yapmalıyız?","sub":"Shart mayli -sA · -(A/I)rsA · varsa / yoksa · keşke · xavfsizlik qoidalari","goals":["shart gaplar tuzish (alarm çalarsa — signal chalinsa)","real shart -(A/I)rsA","taxminiy shart va istak -sA (gelsem, gelsen)","varsa / yoksa, -(y)sA ot bilan","keşke (qani endi)","yongʻin, zilzila va xavfsizlik qoidalari"],"vocab":[{"title":"Lugʻat","words":[["alarm","signal, xavf signali"],["yangın","yongʻin"],["deprem","zilzila"],["sel","sel, toshqin"],["acil durum","favqulodda holat"],["acil çıkış","favqulodda chiqish"],["merdiven","zinapoya"],["asansör","lift"],["itfaiye","oʻt oʻchiruvchilar"],["ambulans","tez yordam"],["yaralı","yarador"],["ilk yardım","birinchi yordam"],["sakin","xotirjam"],["panik","vahima"],["toplanma alanı","yigʻilish joyi"],["masa","stol"],["kapı","eshik"],["söndürmek","oʻchirmoq (olovni)"],["kurtarmak","qutqarmoq"],["güvenlik","xavfsizlik"]]},{"title":"Mavzuli lugʻat — favqulodda holat","words":[["yangın söndürücü","oʻt oʻchirgich"],["duman","tutun"],["el feneri","qoʻl chiroq"],["deprem çantası","zilzila sumkasi"],["düdük","hushtak"],["tahliye","evakuatsiya"],["112","favqulodda yordam raqami"],["sarsıntı","silkinish"],["enkaz","vayrona"],["prova","repetitsiya, oʻquv mashqi"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Real shart: -(A/I)rsA («…sa»)"},{"p":"Haqiqatan roʻy berishi mumkin boʻlgan shart. Tuzilishi: geniş zaman + sA + shaxs qoʻshimchasi:"},{"table":{"h":["Shaxs","bulmak","binmek","Inkor"],"r":[["ben","bulursam","binersem","bulmazsam"],["sen","bulursan","binersen","bulmazsan"],["o","bulursa","binerse","bulmazsa"],["biz","bulursak","binersek","bulmazsak"],["siz","bulursanız","binerseniz","bulmazsanız"],["onlar","bulurlarsa","binerlerse","bulmazlarsa"]]}},{"p":"Misollar: Yangın alarmı çalarsa asansörü kullanmayın. — Yongʻin signali chalinsa, liftdan foydalanmang. Anahtarı bulursan bana haber ver. — Kalitni topsang, menga xabar ber. Acele etmezsek treni kaçırırız. — Shoshilmasak, poyezddan qolib ketamiz."},{"p":"Eğer («agar») gap boshida kelishi mumkin, lekin majburiy emas: Eğer hafta sonu hava güzel olursa Efes'e gideceğiz."},{"sub":"Ot va var / yok bilan: -(y)sA"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Yorgunsan biraz uzan.","Charchagan boʻlsang, biroz yotib ol."],["Ofisteyseniz size uğrayacağım.","Ofisda boʻlsangiz, sizning oldingizga kirib oʻtaman."],["Bir sorun varsa bize yazın.","Biror muammo boʻlsa, bizga yozing."],["Paran yoksa ben öderim.","Puling boʻlmasa, men toʻlayman."],["Öğrenciyseniz indirim alabilirsiniz.","Talaba boʻlsangiz, chegirma olishingiz mumkin."]]}},{"p":"Boshqa zamonlar bilan ham ishlaydi: Geliyorsa… (kelayotgan boʻlsa) · Geldiyse… (kelgan boʻlsa) · Gelecekse… (keladigan boʻlsa)."},{"sub":"Istak va taklif: -sA + shaxs"},{"p":"Oʻzak + sA + shaxs qoʻshimchasi — kamroq real holat, maslahat soʻrash yoki istak:"},{"table":{"h":["Shaxs","sormak","dinlenmek"],"r":[["ben","sorsam","dinlensem"],["sen","sorsan","dinlensen"],["o","sorsa","dinlense"],["biz","sorsak","dinlensek"],["siz","sorsanız","dinlenseniz"],["onlar","sorsalar","dinlenseler"]]}},{"table":{"h":["Ishlatilishi","Misol","Oʻzbekcha"],"r":[["maslahat soʻrash","Ne giysem? · Hocaya sorsam mı?","Nima kiysam? · Ustozdan soʻrasam-mikan?"],["taklif","Bir mola versek mi?","Tanaffus qilsak-chi?"],["istak (keşke)","Keşke denize yakın otursak!","Qani endi dengiz yaqinida yashasak!"],["muloyim iltimos","Rica etsem pencereyi açar mısınız?","Iltimos qilsam, derazani ochib yuborasizmi?"]]}},{"note":"-ArsA va -sA farqi: Yağmur yağarsa maç ertelenir — yomgʻir yogʻsa (bu boʻlishi mumkin), oʻyin qoldiriladi. Yağmur yağsa… — yogʻib qolsa-yu (ehtimoli kamroq). Qoida va yoʻriqnomalarda doim -ArsA. Butunlay xayoliy shart («boʻlganida edi») — -sAydI, uni B2 da oʻrganasiz."},{"sub":"Foydali iboralar"},{"p":"Mümkünse (iloji boʻlsa) · İsterseniz (xohlasangiz) · Gerekirse (kerak boʻlsa) · Yoksa (aks holda) · Ne olursa olsun (nima boʻlsa ham) · Siz bilirsiniz (oʻzingiz bilasiz)."}]},{"kind":"dialog","title":"Dialog: Yaylada yürüyüş","blocks":[{"dlg":[["Rehber","Arkadaşlar, yola çıkmadan önce birkaç kural. Sis çökerse olduğunuz yerde kalın."],["Jasur","Peki yolu kaybedersek ne yapacağız?"],["Rehber","Kaybolursanız düdük çalın ve beni bekleyin. Telefon çekmezse panik yapmayın."],["Kerem","Ya yağmur yağarsa?"],["Rehber","Yağmurluğunuz varsa giyin; yoksa ben veririm. Şimşek çakarsa ağaçların altında durmayın."],["Jasur","Yorulursak mola verebilir miyiz?"],["Rehber","Tabii. Biri yorulursa hepimiz dururuz. Suyunuz biterse dereden içmeyin, bana söyleyin."],["Kerem","Keşke kalın bir montum olsa!"],["Rehber","Üşürsen bende fazla bir kazak var."],["Jasur","Keşke hava hep böyle açık kalsa!"],["Rehber","Dağda hava çabuk değişir. Hazırsanız yola çıkalım!"]]},{"gloss":[["sis çökmek","tuman tushmoq"],["kaybolmak","adashib qolmoq"],["düdük","hushtak"],["telefon çekmek","aloqa tutmoq"],["yağmurluk","yomgʻirpoʻsh"],["şimşek çakmak","chaqmoq chaqmoq"],["mola vermek","tanaffus qilmoq"],["dere","soy"],["üşümek","sovqotmoq"],["kazak","sviter"],["açık hava","ochiq havo"]]}]}],"reading":{"title":"Asansörde kalırsanız","text":"Asansör iki kat arasında durursa önce sakin olun. Paniğe kapılırsanız hem kendinizi hem yanınızdakileri korkutursunuz. Alarm düğmesine basın ve görevlinin cevabını bekleyin. Düğme çalışmazsa telefonunuzla bina yönetimini ya da 112'yi arayın. Telefon çekmiyorsa kapıya vurarak ses verin. Kapıyı zorla açmaya çalışmayın; asansör aniden hareket ederse yaralanabilirsiniz. Işık sönerse korkmayın: asansörde hava bitmez. Yanınızda yaşlı ya da çocuk varsa onlarla sakin bir sesle konuşun. Yardım gelince görevlinin söylediklerini dikkatle uygulayın. Sık sık arıza yapan bir asansör görürseniz mutlaka yönetime haber verin.","gloss":[["asansör","lift"],["paniğe kapılmak","vahimaga tushmoq"],["düğme","tugma"],["yönetim","maʼmuriyat"],["vurmak","urmoq"],["zorla","kuch bilan"],["aniden","toʻsatdan"],["yaralanmak","jarohatlanmoq"],["sönmek","oʻchmoq"],["uygulamak","bajarmoq"],["sık sık","tez-tez"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Asansör durursa önce ne yapmalıyız?","Düğme çalışmazsa kimi aramalıyız?","Kapıyı neden zorla açmamalıyız?","Işık sönerse neden korkmamalıyız?","Sık sık arıza yapan bir asansör görürsek ne yapmalıyız?"],"ans":{"1":"Sakin olmalı ve alarm düğmesine basmalıyız.","2":"Bina yönetimini ya da 112'yi aramalıyız.","3":"Çünkü asansör aniden hareket ederse yaralanabiliriz.","4":"Çünkü asansörde hava bitmez.","5":"Yönetime haber vermeliyiz."}},"exercises":[{"n":1,"title":"Real shart (-ArsA / -IrsA) shaklini yozing.","items":[["a","Sis ___ olduğunuz yerde kalın. (çökmek)"],["b","Erken ___ beni ara. (gelmek, sen)"],["c","Yağmur ___ pikniğe gitmeyiz. (yağmak)"],["d","Düğme ___ 112'yi arayın. (çalışmamak)"],["e","Yolu ___ düdük çalın. (kaybetmek, siz)"]],"ans":{"a":"çökerse","b":"gelirsen","c":"yağarsa","d":"çalışmazsa","e":"kaybederseniz"}},{"n":2,"title":"-(y)sA bilan toʻldiring.","items":[["a","Yağmurluğunuz ___ giyin. (var)"],["b","Suyunuz ___ bana söyleyin. (yok)"],["c","___ dinlen. (yorgun, sen)"],["d","___ yola çıkalım. (hazır, siz)"],["e","Hava ___ yürüyüş yaparız. (güzel)"]],"ans":{"a":"varsa","b":"yoksa","c":"Yorgunsan","d":"Hazırsanız","e":"güzelse"}},{"n":3,"title":"keşke bilan istak bildiring.","items":[["a","Yaylaya gitmek istiyorum. → Keşke ___ !"],["b","Kalın bir montum yok. → Keşke kalın bir montum ___ !"],["c","Yağmur durmuyor. → Keşke yağmur ___ !"],["d","Sen gelmiyorsun. → Keşke sen de ___ !"]],"ans":{"a":"yaylaya gitsem","b":"olsa","c":"dursa","d":"gelsen"}},{"n":4,"title":"Gapni tugating (namunaga qarang).","items":[["a","Asansörde kalırsanız…"],["b","Şimşek çakarsa…"],["c","Yolu kaybederseniz…"],["d","Işık sönerse…"]],"ans":{"a":"alarm düğmesine basın.","b":"ağaçların altında durmayın.","c":"olduğunuz yerde kalın ve düdük çalın.","d":"korkmayın, sakin olun."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Tuman tushsa, joyingizda qoling."],["b","Savolingiz boʻlsa, soʻrang."],["c","Charchasang, toʻxtaymiz."],["d","Qaniydi havo ochiq boʻlsa!"],["e","Tugma ishlamasa, qoʻngʻiroq qiling."]],"ans":{"a":"Sis çökerse olduğunuz yerde kalın.","b":"Sorunuz varsa sorun.","c":"Yorulursan dururuz.","d":"Keşke hava açık olsa!","e":"Düğme çalışmazsa arayın."}},{"n":6,"title":"Yozish. Uyingiz, maktabingiz yoki ish joyingiz uchun 8–10 bandlik xavfsizlik qoidalarini yozing (… -ArsA …).","items":[],"ans":{}}]},{"id":"b1-4","level":"B1","n":4,"title":"Kurallara Uyulmalıdır","sub":"Majhul nisbat (edilgen çatı) -Il / -In / -n · tarafından · shaxssiz gaplar · yoʻriqnomalar","goals":["majhul nisbat: yapıldı (qilindi), okunur (oʻqiladi), bilinir (maʼlum)","bajaruvchini koʻrsatish: tarafından","shaxssiz gaplar (Burada sigara içilmez)","yoʻriqnoma va rasmiy matnlarni tushunish va yozish","maishiy texnika va aloqa vositalari lugʻati"],"vocab":[{"title":"Lugʻat","words":[["kural","qoida"],["uymak","rioya qilmoq"],["yasak","taqiqlangan"],["izin verilmek","ruxsat berilmoq"],["kullanmak","foydalanmoq"],["kullanım kılavuzu","foydalanish yoʻriqnomasi"],["cihaz","qurilma"],["pil","batareya"],["şarj etmek","quvvatlamoq"],["tuş / düğme","tugma"],["basmak","bosmoq"],["açmak / kapatmak","yoqmoq, ochmoq / oʻchirmoq, yopmoq"],["takmak","oʻrnatmoq, taqmoq"],["doldurmak","toʻldirmoq"],["imzalamak","imzolamoq"],["form","blanka, shakl"],["kimlik","shaxsiy guvohnoma"],["iptal etmek","bekor qilmoq"],["tarafından","tomonidan"],["dikkat","diqqat"]]},{"title":"Mavzuli lugʻat — maishiy texnika","words":[["çamaşır makinesi","kir yuvish mashinasi"],["bulaşık makinesi","idish yuvish mashinasi"],["buzdolabı","muzlatgich"],["fırın","pech, duxovka"],["ütü","dazmol"],["elektrik süpürgesi","changyutgich"],["priz","rozetka"],["kablo","sim, kabel"],["garanti","kafolat"],["arıza","nosozlik"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Majhul nisbat qanday yasaladi?"},{"p":"Oʻzbekchadagi -il / -in ga juda oʻxshaydi (yozildi, oʻqildi):"},{"table":{"h":["Feʼl oʻzagi","Qoʻshimcha","Misollar"],"r":[["unli bilan tugaydi","-n","ara → aranmak (qidirilmoq), bekle → beklenmek (kutilmoq), iste → istenmek (soʻralmoq)"],["l bilan tugaydi","-In","sil → silinmek, del → delinmek, çal → çalınmak"],["boshqa undosh","-Il","sat → satılmak, kır → kırılmak, seç → seçilmek, kes → kesilmek, iç → içilmek"]]}},{"p":"Majhul feʼl istalgan zamonda ishlaydi: satıldı (sotildi) · satılıyor (sotilyapti) · satılacak (sotiladi) · satılır (sotiladi — umuman) · satılmalı (sotilishi kerak) · satılabilir (sotilishi mumkin)."},{"sub":"Qayerda ishlatiladi?"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Saat Kulesi 1901'de yapıldı.","Soat minorasi 1901-yilda qurilgan."],["Sonuçlar cuma günü açıklanacak.","Natijalar juma kuni eʼlon qilinadi."],["Bu peynir köyde üretilir.","Bu pishloq qishloqda ishlab chiqariladi."],["Uçuş iptal edildi.","Reys bekor qilindi."],["Bu şarkı kim tarafından söylendi?","Bu qoʻshiq kim tomonidan ijro etildi?"]]}},{"p":"tarafından — ishni bajaruvchi (asosan rasmiy uslubda): Proje belediye tarafından desteklendi. et- va ol- bilan qoʻshma feʼllar: iptal et- → iptal edil-, kontrol et- → kontrol edil-, teslim et- → teslim edil-."},{"sub":"Shaxssiz gaplar (egasi yoʻq)"},{"p":"Ogohlantirish yozuvlari, qoidalar va yoʻriqnomalarda juda koʻp uchraydi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Havuza duş almadan girilmez.","Hovuzga dush qabul qilmasdan kirilmaydi."],["Müzede fotoğraf çekilmez.","Muzeyda suratga olinmaydi."],["Çimlere basılmaz.","Maysaga bosilmaydi."],["Otogara nasıl gidilir?","Avtovokzalga qanday boriladi?"],["Önce numara alınır, sonra sıra beklenir.","Avval raqam olinadi, soʻng navbat kutiladi."]]}},{"sub":"Yoʻriqnoma uslubi"},{"p":"Turkcha yoʻriqnomalarda odatda majhul + geniş zaman yoki majhul + -mAlIdIr ishlatiladi:"},{"p":"Çay makinesine önce su konur. Kapak kapatılır. Düğmeye basılır. Makine çalışırken kapak açılmamalıdır. (Mashina ishlab turganda qopqoq ochilmasligi kerak.)"},{"note":"Majhul va oʻzlik nisbatni adashtirmang. Baʼzi feʼllarda -n oʻzlik maʼnosini beradi: taranmak (taralmoq — oʻz sochini), giyinmek (kiyinmoq), hazırlanmak (tayyorlanmoq). Maʼno gapdan aniqlanadi: Bulaşıklar yıkandı (idishlar yuvildi — majhul) · Kerem yıkandı (Kerem yuvindi — oʻzlik)."}]},{"kind":"dialog","title":"Dialog: Türk kahvesi nasıl yapılır?","blocks":[{"dlg":[["Dilnoza","Defne, Türk kahvesi nasıl yapılır? Bana öğretir misin?"],["Defne","Tabii, çok kolay. Önce cezveye bir fincan soğuk su konur."],["Dilnoza","Kahve ne zaman eklenir?"],["Defne","Hemen. Her fincan için iki çay kaşığı kahve atılır. Şeker isteniyorsa şimdi eklenir."],["Dilnoza","Sonra karıştırılır mı?"],["Defne","Evet, ocağa konmadan önce iyice karıştırılır. Sonra bir daha karıştırılmaz."],["Dilnoza","Ateş yüksek mi olmalı?"],["Defne","Hayır! Kahve kısık ateşte yavaş yavaş pişirilir. Köpük yükselince cezve ocaktan alınır."],["Dilnoza","Köpük fincana mı konur?"],["Defne","Aynen. Önce köpük paylaştırılır, sonra kahve bir kez daha ısıtılıp fincana dökülür."],["Dilnoza","Yanında ne verilir?"],["Defne","Bir bardak su ve lokum ikram edilir. Kahve içildikten sonra da fal bakılır!"]]},{"gloss":[["cezve","turka (qahva qaynatgich)"],["fincan","finjon"],["çay kaşığı","choy qoshiq"],["iyice","yaxshilab"],["kısık ateş","past olov"],["köpük","koʻpik"],["yükselmek","koʻtarilmoq"],["paylaştırmak","taqsimlamoq"],["ısıtmak","isitmoq"],["ikram etmek","mehmon qilmoq"],["fal bakmak","fol ochmoq"]]}]}],"reading":{"title":"Müze ziyaret kuralları","text":"Müzemiz pazartesi hariç her gün 09.00–18.00 saatleri arasında ziyarete açıktır. Biletler girişteki gişeden veya internet üzerinden satın alınır. Öğrencilere ve altmış beş yaş üstü ziyaretçilere indirim uygulanır. Büyük çantalar ve şemsiyeler içeri alınmaz; girişteki emanet bölümüne bırakılır. Salonlarda flaşsız fotoğraf çekilebilir, ancak eserlere dokunulmaz. Müze içinde yiyecek ve içecek tüketilmez; bunun için bahçedeki kafe kullanılır. Rehberli turlar her saat başı düzenlenir ve bilet ücretine dahildir. Kapanıştan yarım saat önce bilet satışı durdurulur.","gloss":[["hariç","tashqari"],["ziyaret","tashrif"],["gişe","kassa"],["satın almak","sotib olmoq"],["indirim uygulamak","chegirma qilmoq"],["emanet","saqlash xonasi"],["eser","asar, eksponat"],["dokunmak","tegmoq"],["tüketmek","isteʼmol qilmoq"],["saat başı","har soat boshida"],["dahil","ichida, kiritilgan"],["kapanış","yopilish"],["durdurmak","toʻxtatmoq"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Müze haftanın her günü açıktır.","Biletler sadece gişeden alınır.","Salonlarda flaşsız fotoğraf çekilebilir.","Rehberli tur için ayrıca ücret ödenir.","Saat 17.30'dan sonra bilet satılmaz."],"ans":{"1":"Y","2":"Y","3":"D","4":"Y","5":"D"}},"exercises":[{"n":1,"title":"Majhul shaklini yozing (noaniq shakl).","items":[["a","pişirmek →"],["b","eklemek →"],["c","satmak →"],["d","açmak →"],["e","yıkamak →"],["f","dökmek →"]],"ans":{"a":"pişirilmek","b":"eklenmek","c":"satılmak","d":"açılmak","e":"yıkanmak","f":"dökülmek"}},{"n":2,"title":"Gapni majhulga aylantiring.","items":[["a","Mimar Sinan bu camiyi 1557'de yaptı. → Bu cami 1557'de ___."],["b","Müdür toplantıyı erteledi. → Toplantı ___."],["c","Annem kahveyi kısık ateşte pişirdi. → Kahve kısık ateşte ___."],["d","Biletleri internetten satıyorlar. → Biletler internetten ___."],["e","Sonuçları yarın açıklayacaklar. → Sonuçlar yarın ___."]],"ans":{"a":"yapıldı","b":"ertelendi","c":"pişirildi","d":"satılıyor","e":"açıklanacak"}},{"n":3,"title":"Ogohlantirish yozuvini turkcha yozing (shaxssiz majhul).","items":[["a","Eksponatlarga tegilmaydi."],["b","Bu yerga mashina qoʻyilmaydi."],["c","Ichkarida ovqat yeyilmaydi."],["d","Eshik yopiq tutiladi."]],"ans":{"a":"Eserlere dokunulmaz.","b":"Buraya park edilmez.","c":"İçeride yemek yenmez.","d":"Kapı kapalı tutulur."}},{"n":4,"title":"Yoʻriqnomani majhul bilan qayta yozing.","items":[["a","Önce suyu cezveye koyun. →"],["b","Kahveyi ekleyin. →"],["c","İyice karıştırın. →"],["d","Fincana dökün. →"]],"ans":{"a":"Önce su cezveye konur.","b":"Kahve eklenir.","c":"İyice karıştırılır.","d":"Fincana dökülür."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Bu masjid kim tomonidan qurilgan?"],["b","Chiptalar internet orqali sotiladi."],["c","Yigʻilish keyinga qoldirildi."],["d","Turk qahvasi past olovda pishiriladi."],["e","Natijalar ertaga eʼlon qilinadi."]],"ans":{"a":"Bu cami kim tarafından yapıldı?","b":"Biletler internet üzerinden satılır.","c":"Toplantı ertelendi.","d":"Türk kahvesi kısık ateşte pişirilir.","e":"Sonuçlar yarın açıklanacak."}},{"n":6,"title":"Yozish. Uyingizdagi biror qurilmaning (choynak, telefon, kir yuvish mashinasi) yoʻriqnomasini majhul nisbat bilan 6–8 bandda yozing.","items":[],"ans":{}}]},{"id":"b1-5","level":"B1","n":5,"title":"Misafir Gelecek!","sub":"Orttirma nisbat (ettirgen çatı) -DIr / -t / -Ir / -Ar · birovga ish buyurish · xizmatlar","goals":["birovga ish qildirish: yaptırmak (qildirmoq), temizletmek (tozalatmoq), okutmak (oʻqitmoq)","orttirma nisbat qoʻshimchalari va istisnolar","X-A Y-I yaptırmak tuzilishi","xizmat iboralari (saç kestirmek)","uy ishlari va topshiriq taqsimlash lugʻati"],"vocab":[{"title":"Lugʻat","words":[["misafir","mehmon"],["hazırlık","tayyorgarlik"],["temizlemek","tozalamoq"],["temizletmek","tozalatmoq"],["boyamak","boʻyamoq"],["tamir etmek","taʼmirlamoq"],["dikmek","tikmoq"],["kesmek","kesmoq"],["yıkamak","yuvmoq"],["ütülemek","dazmollamoq"],["pişirmek","pishirmoq"],["getirmek","olib kelmoq"],["göstermek","koʻrsatmoq"],["kaldırmak","koʻtarmoq, olib qoʻymoq"],["bekletmek","kuttirmoq"],["usta","usta"],["terzi","tikuvchi"],["berber / kuaför","sartarosh"],["boyacı","boʻyoqchi"],["görev dağıtmak","vazifa taqsimlamoq"]]},{"title":"Mavzuli lugʻat — uy ishlari","words":[["halı","gilam"],["perde","parda"],["cam silmek","oyna artmoq"],["toz almak","chang artmoq"],["bulaşık yıkamak","idish yuvmoq"],["sofra kurmak","dasturxon yozmoq"],["çiçek","gul"],["pasta","tort"],["ikram etmek","mehmon qilmoq"],["davet","taklif"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Orttirma nisbat qoʻshimchalari"},{"p":"Oʻzbekchadagi -dir, -t, -ir, -ar ga (yozdirmoq, oʻqitmoq, ichirmoq, chiqarmoq) juda oʻxshaydi:"},{"table":{"h":["Qoʻshimcha","Qachon","Misollar"],"r":[["-DIr","undosh bilan tugagan koʻp oʻzaklar","sil → sildir, öl → öldür, dön → döndür, ye → yedir"],["-t","unli yoki l / r bilan tugagan koʻp boʻgʻinli oʻzaklar","ara → arat, uyu → uyut, ağla → ağlat, söyle → söylet, kısal → kısalt"],["-Ir","baʼzi bir boʻgʻinli feʼllar","doy → doyur, piş → pişir, düş → düşür, bat → batır, kaç → kaçır"],["-Ar","bir nechta feʼl","çık → çıkar, kop → kopar"]]}},{"note":"Yodlab olinadigan istisnolar: gel → getir (keltirmoq), gör → göster (koʻrsatmoq), kalk → kaldır (koʻtarmoq, turgʻizmoq)."},{"sub":"Maʼnosi va gap tuzilishi"},{"p":"1) Oʻtimsiz feʼl oʻtimliga aylanadi: Çorba ısındı. (Shoʻrva isidi.) → Çorbayı ısıttım. (Shoʻrvani isitdim.) 2) Ishni birovga qildirish: [kim] + [kimga -(y)A] + [nimani -(y)I] + feʼl-DIr:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Babam bize garajı boşalttı.","Dadam bizga garajni boʻshatdi."],["Mektubu Jasur'a imzalattım.","Xatni Jasurga imzolatdim."],["Hoca öğrencilere şiiri ezberletti.","Ustoz oʻquvchilarga sheʼrni yodlatdi."],["Hemşire hastaya şurubu içirdi.","Hamshira bemorga siropni ichirdi."]]}},{"p":"Oʻtimsiz feʼldan yasalganda, ishni bajaruvchi tushum kelishigida keladi: Taksi bizi yarım saat bekletti. (Taksi bizni yarim soat kuttirdi.) · Pamuk herkesi güldürdü. (Pamuk hammani kuldirdi.)"},{"sub":"Xizmatdan foydalanish"},{"p":"Ishni usta yoki xizmat qilsa ham, turkchada orttirma nisbat ishlatiladi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Dün gözlüğümü tamir ettirdim.","Kecha koʻzoynagimni taʼmirlatdim."],["Pamuk'u veterinere muayene ettirdik.","Pamukni veterinarga koʻrsatdik."],["Pantolonumu kısalttırdım.","Shimimni (tikuvchiga) qisqartirtirdim."],["Odayı boyattık.","Xonani boʻyatdik."]]}},{"p":"Taqqoslang: Gözlüğümü tamir ettim — koʻzoynagimni oʻzim tuzatdim; Gözlüğümü tamir ettirdim — ustaga tuzattirdim."},{"sub":"Orttirma va boshqa qoʻshimchalar birga"},{"p":"yaz-dır-ıl-dı (yozdirildi) · temizle-t-me-yeceğim (tozalatmayman) · bekle-t-tiğim için özür dilerim (kuttirganim uchun uzr) · güldür-ebil-ir misin? (kuldira olasanmi?)."},{"note":"Ikki marta orttirma ham uchraydi: yap → yaptır → yaptırt — soʻzlashuvda «birov orqali qildirtirish» maʼnosida. B1 uchun birinchi daraja yetarli."}]},{"kind":"dialog","title":"Dialog: Düğün hazırlığı","blocks":[{"dlg":[["Anne","Dilnoza, düğüne iki hafta kaldı. Davetiyeleri bastırdınız mı?"],["Dilnoza","Evet anne, dün matbaada bastırdık. Rustam bugün dağıtacak."],["Rustam","Yarısını postayla gönderttim bile."],["Anne","Elbisen ne oldu?"],["Dilnoza","Terziye diktiriyorum. Cuma günü prova yaptıracağım."],["Anne","Salonu kim süsleyecek?"],["Rustam","Bir firmaya süsleteceğiz. Çiçekleri de onlara getirteceğim."],["Anne","Pilavı mutlaka Hoşim Usta'ya pişirtin. Onun pilavı meşhurdur."],["Dilnoza","Merak etme, haber verdik. Pastayı da Defne'nin tavsiye ettiği pastaneye yaptırıyoruz."],["Anne","Fotoğrafları kim çekecek?"],["Rustam","Bir arkadaşıma çektireceğim. Sen hiçbir şeyi düşünme."],["Anne","Beni güldürdün! Bir anne düşünmeden durur mu?"]]},{"gloss":[["davetiye","taklifnoma"],["bastırmak","chop ettirmoq"],["matbaa","bosmaxona"],["dağıtmak","tarqatmoq"],["diktirmek","tiktirmoq"],["prova","kiyib koʻrish"],["süslemek","bezamoq"],["meşhur","mashhur"],["pastane","qandolatxona"],["güldürmek","kuldirmoq"]]}]}],"reading":{"title":"Eski ev yenileniyor","text":"Defne'nin ailesi geçen ay dedesinden kalan eski evi yeniletti. Önce çatıyı tamir ettirdiler, çünkü her yağmurda su damlıyordu. Sonra bir ustaya bütün duvarları boyattılar; Defne kendi odasını açık maviye boyattı. Mutfaktaki eski dolapları söktürüp yenilerini yaptırdılar. Elektrik tesisatını bir elektrikçiye kontrol ettirdiler, o da iki prizi değiştirdi. Babası bahçe kapısını kendisi onardı, kimseye yaptırmadı. Annesi perdeleri kendi dükkânında dikti. En son, halıları yıkatıp yerlerine serdiler. Dedesi evi görünce çok duygulandı: \"Beni yirmi yaş gençleştirdiniz!\" dedi.","gloss":[["yeniletmek","yangilatmoq"],["çatı","tom"],["tamir ettirmek","taʼmirlatmoq"],["damlamak","tommoq"],["boyatmak","boʻyatmoq"],["söktürmek","buzdirib oldirmoq"],["tesisat","simlar tarmogʻi"],["priz","rozetka"],["onarmak","tuzatmoq"],["perde","parda"],["halı","gilam"],["sermek","toʻshamoq"],["duygulanmak","taʼsirlanmoq"],["gençleştirmek","yoshartirmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Çatıyı neden tamir ettirdiler?","Defne odasını hangi renge boyattı?","Elektrikçi ne yaptı?","Bahçe kapısını kim onardı?","Dedesi evi görünce ne dedi?"],"ans":{"1":"Çünkü her yağmurda su damlıyordu.","2":"Açık maviye boyattı.","3":"İki prizi değiştirdi.","4":"Babası kendisi onardı.","5":"\"Beni yirmi yaş gençleştirdiniz!\" dedi."}},"exercises":[{"n":1,"title":"Orttirma shaklini yozing.","items":[["a","dikmek →"],["b","boyamak →"],["c","pişmek →"],["d","gülmek →"],["e","getirmek →"],["f","yıkamak →"]],"ans":{"a":"diktirmek","b":"boyatmak","c":"pişirmek","d":"güldürmek","e":"getirtmek","f":"yıkatmak"}},{"n":2,"title":"Orttirma nisbatga aylantiring.","items":[["a","Usta duvarları boyadı. (biz) → Duvarları ustaya ___ ."],["b","Terzi elbiseyi dikti. (ben) → Elbiseyi terziye ___ ."],["c","Çocuk süt içti. (anne) → Anne çocuğa süt ___ ."],["d","Arkadaşım fotoğraf çekecek. (ben) → Fotoğrafları arkadaşıma ___ ."]],"ans":{"a":"boyattık","b":"diktirdim","c":"içirdi","d":"çektireceğim"}},{"n":3,"title":"Xizmat iborasi bilan yozing.","items":[["a","Koʻylak tiktirdim. →"],["b","Mashinani yuvdirdim. →"],["c","Tomni taʼmirlatdik. →"],["d","Taklifnomalarni chop ettirdik. →"]],"ans":{"a":"Elbise diktirdim.","b":"Arabayı yıkattım.","c":"Çatıyı tamir ettirdik.","d":"Davetiyeleri bastırdık."}},{"n":4,"title":"Mos feʼlni yozing: gösterdi · getirdi · kaldırdı.","items":[["a","Kurye paketi kapıya ___ ."],["b","Müdür bana yeni odamı ___ ."],["c","Garson boş tabakları masadan ___ ."]],"ans":{"a":"getirdi","b":"gösterdi","c":"kaldırdı"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Devorlarni ustaga boʻyatdik."],["b","Palovni Hoshim ustaga pishirtiramiz."],["c","Sen meni kuldirding."],["d","Sochimni kestirishim kerak."],["e","Onam menga xonani tozalatdi."]],"ans":{"a":"Duvarları ustaya boyattık.","b":"Pilavı Hoşim Usta'ya pişirteceğiz.","c":"Sen beni güldürdün.","d":"Saçımı kestirmem gerek.","e":"Annem bana odayı temizletti."}},{"n":6,"title":"Yozish. Uyingizga ertaga mehmonlar keladi. Oila aʼzolariga vazifalarni taqsimlang: kim nimani qiladi va nimani boshqalarga qildiradi (8–10 gap).","items":[],"ans":{}}]},{"id":"b1-6","level":"B1","n":6,"title":"Müdür Ne Dedi?","sub":"Koʻchirma gap (dolaylı anlatım) · -DIğInI söyledi · -(y)Ip -mAdIğInI sordu · -mAsInI istedi · diye","goals":["boshqa odamning gapini yetkazish: Müdür yorgun olduğunu söyledi (Direktor charchaganini aytdi)","soʻroqlarni yetkazish: gelip gelmeyeceğimi sordu (kelish-kelmasligimni soʻradi)","buyruq va iltimoslarni yetkazish: beklememizi söyledi","diye","gap yetkazish feʼllari"],"vocab":[{"title":"Lugʻat","words":[["söylemek","aytmoq"],["demek","demoq"],["sormak","soʻramoq"],["istemek","xohlamoq, soʻramoq"],["anlatmak","aytib bermoq"],["bildirmek","maʼlum qilmoq"],["açıklamak","eʼlon qilmoq, tushuntirmoq"],["hatırlatmak","eslatmoq"],["uyarmak","ogohlantirmoq"],["önermek","taklif qilmoq"],["rica etmek","iltimos qilmoq"],["emretmek","buyurmoq"],["haber","xabar, yangilik"],["mesaj","xabar (SMS)"],["toplantı","yigʻilish"],["müdür","direktor"],["sekreter","kotib"],["ertelemek","kechiktirmoq"],["hazır","tayyor"],["müsait","boʻsh (vaqti bor)"]]},{"title":"Mavzuli lugʻat — ofisdagi muloqot","words":[["dahili hat","ichki telefon"],["not almak","yozib olmoq"],["gündem","kun tartibi"],["katılmak","qatnashmoq"],["bilgi vermek","maʼlumot bermoq"],["görüşme","uchrashuv, suhbat"],["onaylamak","tasdiqlamoq"],["reddetmek","rad etmoq"],["yanıtlamak","javob bermoq"],["iletmek","yetkazmoq"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Darak gapni yetkazish: -DIğInI / -(y)AcAğInI"},{"table":{"h":["Toʻgʻri gap","Koʻchirma gap","Oʻzbekcha"],"r":[["Kerem: «Açım.»","Kerem aç olduğunu söyledi.","Kerem och ekanini aytdi."],["Kerem: «Dün kütüphanedeydim.»","Kerem dün kütüphanede olduğunu söyledi.","Kerem kecha kutubxonada boʻlganini aytdi."],["Zeynep: «Biletleri aldım.»","Zeynep biletleri aldığını söyledi.","Zeynep chiptalarni olganini aytdi."],["Murat Bey: «Cuma günü toplantı yapacağız.»","Murat Bey cuma günü toplantı yapacağımızı söyledi.","Murat bey juma kuni yigʻilish oʻtkazishimizni aytdi."],["Defne: «Partiye gelmeyeceğim.»","Defne partiye gelmeyeceğini söyledi.","Defne ziyofatga kelmasligini aytdi."]]}},{"p":"Egalik qoʻshimchasi kimni nazarda tutayotganini toʻgʻri almashtiring: Bana yorgun olduğunu söyledi (u charchagan) · Ona yorgun olduğumu söyledim (men charchaganman)."},{"sub":"Soʻroqni yetkazish"},{"table":{"h":["Toʻgʻri soʻroq","Koʻchirma","Oʻzbekcha"],"r":[["«Ne zaman döneceksin?»","Ne zaman döneceğimi sordu.","Qachon qaytishimni soʻradi."],["«Kiminle gittin?»","Kiminle gittiğimi sordu.","Kim bilan borganimni soʻradi."],["«Pamuk nerede?»","Pamuk'un nerede olduğunu sordu.","Pamuk qayerdaligini soʻradi."],["«Aç mısın?» (ha / yoʻq)","Aç olup olmadığımı sordu.","Och yoki och emasligimni soʻradi."],["«Yarın gelecek misin?» (ha / yoʻq)","Ertesi gün gelip gelmeyeceğimi sordu.","Ertasi kuni kelish-kelmasligimni soʻradi."]]}},{"p":"Ha / yoʻq soʻroqlarida: -(y)Ip + -mAdIğI (oʻtgan yoki hozirgi) yoki -(y)Ip + -mAyAcAğI (kelasi)."},{"sub":"Buyruq va iltimosni yetkazish: -mAsInI"},{"table":{"h":["Toʻgʻri gap","Koʻchirma","Oʻzbekcha"],"r":[["Hoca: «Kitaplarınızı açın!»","Hoca kitaplarımızı açmamızı söyledi.","Ustoz kitoblarimizni ochishimizni aytdi."],["Doktor: «Çok su iç.»","Doktor çok su içmemi söyledi.","Shifokor koʻp suv ichishimni aytdi."],["Babam: «Gece geç dönme!»","Babam gece geç dönmememi istedi.","Dadam tunda kech qaytmasligimni soʻradi."],["Murat Bey: «Dilnoza sunumu hazırlasın.»","Murat Bey Dilnoza'nın sunumu hazırlamasını istedi.","Murat bey Dilnoza taqdimotni tayyorlashini soʻradi."]]}},{"p":"Tuzilishi: -mA + egalik + -(n)I: gel-me-m-i, gel-me-n-i, gel-me-si-ni, gel-me-miz-i, gel-me-niz-i, gel-me-leri-ni."},{"sub":"diye — toʻgʻri gapdan keyin"},{"p":"Soʻzlashuvda toʻgʻri gapni oʻzgartirmasdan ham aytish mumkin: «…» diye + feʼl. Kerem «Kim kazandı?» diye sordu. — Kerem «Kim yutdi?» deb soʻradi. «Hemen geliyorum» dedi. — «Hozir kelaman», dedi."},{"note":"Eshitilgan xabarni A2 dagi -mIş bilan ham yetkazish mumkin: Sınav ertelenmiş. (Imtihon qoldirilibdi.) Rasmiy uslubda esa: Müdür sınavın ertelendiğini bildirdi."}]},{"kind":"dialog","title":"Dialog: Ev sahibi ne dedi?","blocks":[{"dlg":[["Zeynep","Defne, sen yokken ev sahibi aradı."],["Defne","Öyle mi? Ne dedi?"],["Zeynep","Gelecek ay kirayı artıracağını söyledi."],["Defne","Ne kadar artıracağını sordun mu?"],["Zeynep","Sordum. Yüzde yirmi zam yapacağını söyledi. Bir de kombinin bakımını yaptırmamızı istedi."],["Defne","Ustayı kimin çağıracağını söyledi mi?"],["Zeynep","Kendisinin çağıracağını, bizim sadece evde olmamızı istediğini söyledi."],["Defne","Peki musluğu ne zaman tamir ettireceğini sordun mu?"],["Zeynep","Sordum ama cevap vermedi. Bu konuyu seninle konuşmak istediğini söyledi."],["Defne","Anladım, akşam ararım. Başka bir şey dedi mi?"],["Zeynep","Evet, Pamuk'un balkonda miyavlayıp miyavlamadığını sordu! Komşular şikâyet etmiş."],["Defne","Pamuk mu? Ona Pamuk'un bütün gün uyuduğunu söyle!"]]},{"gloss":[["ev sahibi","uy egasi"],["artırmak","oshirmoq"],["zam","narx oshishi"],["kombi","isitish qozoni"],["bakım","texnik xizmat"],["çağırmak","chaqirmoq"],["musluk","joʻmrak"],["konu","masala"],["miyavlamak","miyovlamoq"],["şikâyet etmek","shikoyat qilmoq"]]}]}],"reading":{"title":"Mahalle toplantısı","text":"Geçen cumartesi mahalle sakinleri parkta toplandı. Muhtar Ayten Hanım önce herkese geldiği için teşekkür etti. Belediyenin parka yeni bir oyun alanı yapacağını ve çalışmaların mayısta başlayacağını söyledi. Sakinlerden çalışma sırasında arabalarını park girişine bırakmamalarını rica etti. Yaşlı bir komşu, sokak lambalarının neden yanmadığını sordu. Muhtar, arızanın belediyeye bildirildiğini ve bir hafta içinde giderileceğini açıkladı. Genç bir anne mahalleye kütüphane açılıp açılmayacağını öğrenmek istedi. Muhtar bunun için bütçe olmadığını, ama gönüllüler kitap toplarsa eski çay ocağını verebileceklerini söyledi. Toplantının sonunda herkesten önerilerini yazılı olarak iletmesini istedi.","gloss":[["sakin","yashovchi"],["muhtar","mahalla oqsoqoli"],["belediye","shahar hokimligi"],["oyun alanı","oʻyin maydonchasi"],["sokak lambası","koʻcha chirogʻi"],["bildirmek","xabar qilmoq"],["gidermek","bartaraf etmoq"],["bütçe","byudjet"],["gönüllü","koʻngilli"],["çay ocağı","choyxona"],["öneri","taklif"],["iletmek","yetkazmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Belediye parka ne yapacak?","Muhtar sakinlerden ne rica etti?","Yaşlı komşu ne sordu?","Arıza ne zaman giderilecek?","Muhtar önerileri nasıl istedi?"],"ans":{"1":"Yeni bir oyun alanı yapacak.","2":"Arabalarını park girişine bırakmamalarını rica etti.","3":"Sokak lambalarının neden yanmadığını sordu.","4":"Bir hafta içinde giderilecek.","5":"Yazılı olarak istedi."}},"exercises":[{"n":1,"title":"Darak gapni koʻchirma gapga aylantiring.","items":[["a","Zeynep: «Yorgunum.» → Zeynep yorgun ___ söyledi."],["b","Ev sahibi: «Kirayı artıracağım.» → Ev sahibi kirayı ___ söyledi."],["c","Kerem: «Raporu bitirdim.» → Kerem raporu ___ söyledi."],["d","Muhtar: «Bütçe yok.» → Muhtar bütçe ___ söyledi."]],"ans":{"a":"olduğunu","b":"artıracağını","c":"bitirdiğini","d":"olmadığını"}},{"n":2,"title":"Soʻroqni koʻchirma gapga aylantiring.","items":[["a","«Ne zaman geleceksin?» → Ne zaman ___ sordu."],["b","«Usta geldi mi?» → Ustanın gelip ___ sordu."],["c","«Lambalar neden yanmıyor?» → Lambaların neden ___ sordu."],["d","«Evde misin?» → Evde olup ___ sordu."]],"ans":{"a":"geleceğimi","b":"gelmediğini","c":"yanmadığını","d":"olmadığımı"}},{"n":3,"title":"Buyruq/iltimosni koʻchirma gapga aylantiring.","items":[["a","Hoca: «Dinleyin!» → Hoca ___ söyledi."],["b","Doktor: «Çok su iç.» → Doktor çok su ___ söyledi."],["c","Muhtar: «Arabaları buraya bırakmayın.» → Muhtar arabaları buraya ___ rica etti."],["d","Annem: «Erken gel.» → Annem erken ___ istedi."]],"ans":{"a":"dinlememizi","b":"içmemi","c":"bırakmamamızı","d":"gelmemi"}},{"n":4,"title":"Koʻchirma gapni toʻgʻri gapga aylantiring.","items":[["a","Defne meşgul olduğunu söyledi. → Defne: «___»"],["b","Kerem nereye gittiğimi sordu. → Kerem: «___»"],["c","Hoca kitapları açmamızı söyledi. → Hoca: «___»"]],"ans":{"a":"Meşgulüm.","b":"Nereye gidiyorsun?","c":"Kitapları açın."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Zaynab charchaganini aytdi."],["b","U qachon kelishimni soʻradi."],["c","Uy egasi ijarani oshirishini aytdi."],["d","Onam erta kelishimni xohladi."],["e","Usta kelgan-kelmaganini soʻradim."]],"ans":{"a":"Zeynep yorgun olduğunu söyledi.","b":"Ne zaman geleceğimi sordu.","c":"Ev sahibi kirayı artıracağını söyledi.","d":"Annem erken gelmemi istedi.","e":"Ustanın gelip gelmediğini sordum."}},{"n":6,"title":"Yozish. Yaqinda boʻlgan bir suhbatni (doʻstingiz, ustozingiz yoki oilangiz bilan) koʻchirma gaplar bilan aytib bering (8–10 gap).","items":[],"ans":{}}]},{"id":"b1-7","level":"B1","n":7,"title":"Spor Salonunda","sub":"Ravishdoshlar: -(y)IncA · -(y)Ip · -DIğIndA · -DIkçA · -(y)A -(y)A · -(y)AlI · sport va sogʻlom turmush","goals":["harakatlarni bogʻlash va jarayonni tasvirlash: düdük çalınca (hushtak chalinganda), kalkıp koştu (turib yugurdi), koşa koşa (yugura-yugura), çalıştıkça (ishlagan sari), geleli (kelganidan beri)","sport, mashgʻulot va sogʻlom turmush lugʻati"],"vocab":[{"title":"Lugʻat","words":[["spor salonu","sport zali"],["antrenör","murabbiy"],["antrenman","mashgʻulot"],["ısınmak","isinmoq, qizishmoq"],["esnemek","choʻzilmoq (mashq)"],["koşmak","yugurmoq"],["atlamak","sakramoq"],["tırmanmak","tirmashmoq"],["sürünmek","emaklamoq"],["kaldırmak","koʻtarmoq"],["nefes almak","nafas olmoq"],["terlemek","terlamoq"],["yorulmak","charchamoq"],["dinlenmek","dam olmoq"],["kondisyon","jismoniy holat"],["kas","muskul"],["düdük","hushtak"],["parkur","yoʻlak, trassa"],["engel","toʻsiq"],["yarışma","musobaqa"]]},{"title":"Mavzuli lugʻat — sogʻlom turmush","words":[["sağlıklı beslenmek","sogʻlom ovqatlanmoq"],["yürüyüş","piyoda yurish"],["bisiklet sürmek","velosiped haydamoq"],["yüzmek","suzmoq"],["kilo vermek","vazn yoʻqotmoq"],["uyku","uyqu"],["alışkanlık","odat"],["su içmek","suv ichmoq"],["kalp","yurak"],["enerji","energiya, quvvat"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"p":"Ravishdosh (zarf-fiil) — bir feʼlni ikkinchisiga bogʻlaydigan shakl. Oʻzbekchadagi -ib, -ganda, -gach, -gan sari ga oʻxshaydi."},{"sub":"-(y)IncA: «…gach», «…shi bilan»"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Işık yanınca koşmaya başlayın.","Chiroq yonishi bilan yugurishni boshlang."],["Antrenman bitince soğuk su içtim.","Mashgʻulot tugagach, sovuq suv ichdim."],["Pamuk beni görünce kapıya koştu.","Pamuk meni koʻrgach, eshik tomon yugurdi."],["Güneş batınca sahil serinledi.","Quyosh botgach, sohil salqinlashdi."]]}},{"p":"Shakllari toʻrtta: -ınca / -ince / -unca / -ünce; unlidan keyin -yınca, -yince… (bekleyince, okuyunca)."},{"sub":"-(y)Ip: «…ib» (ketma-ket harakatlar)"},{"p":"Ikki feʼl bir xil zamon va shaxsda boʻlsa, birinchisi -(y)Ip oladi:"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Ayakkabılarımı giyip parka çıktım.","Poyabzalimni kiyib, bogʻga chiqdim."],["Formu doldurup antrenöre verdi.","Anketani toʻldirib, murabbiyga berdi."],["Havluyu alıp gel!","Sochiqni olib kel!"],["Topu kapıp kaleye doğru koştu.","Toʻpni ilib olib, darvoza tomon yugurdi."]]}},{"p":"-(y)Ip zamon va shaxsni koʻrsatmaydi — ularni oxirgi feʼldan oladi."},{"sub":"-DIğIndA: «…ganida»"},{"p":"-DIK + egalik + -DA: Salona girdiğimde herkes ısınıyordu. (Zalga kirganimda hamma qizinayotgan edi.) · Sen aradığında havuzdaydım. · Maraton koştuğunda çok gurur duyacağız. Farqi: -(y)IncA — «…gach, …shi bilan»; -DIğIndA — «…gan paytda» (vaqt nuqtasi)."},{"sub":"-DIkçA: «…gan sari», «har safar …ganda»"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Düzenli yüzdükçe kondisyonun artar.","Muntazam suzgan sari chidamliliging oshadi."],["Kelime öğrendikçe dizileri daha iyi anlıyorum.","Soʻz oʻrgangan sari seriallarni yaxshiroq tushunyapman."],["Vakit buldukça bisiklete binerim.","Vaqt topgan sari velosiped minaman."]]}},{"sub":"-(y)A -(y)A: takrorlanib turgan harakat"},{"p":"koşa koşa (yugura-yugura) · güle güle (kula-kula) · bile bile (bila turib) · düşe kalka (yiqilib-turib). Çocuklar bağıra bağıra şarkı söyledi. — Bolalar baqira-baqira qoʻshiq aytishdi. Güle güle! — Yaxshi boring! (aynan: «kula-kula»)."},{"sub":"-(y)AlI: «…gandan beri»"},{"p":"İzmir'e taşınalı iki yıl oldu. — Izmirga koʻchganimizga ikki yil boʻldi. Seninle konuşalı çok oldu! — Sen bilan gaplashmaganimga ancha boʻldi! Soʻzlashuvda -DIğIndAn beri ham ishlatiladi: taşındığımızdan beri."},{"note":"Asosiy ravishdoshlarni bir joyda eslab qoling: -(y)Ip (…ib), -(y)IncA (…gach), -DIğIndA (…ganda), -(y)ArAk (…ib, …gan holda), -mAdAn (…may), -DIkçA (…gan sari), -(y)AlI (…gandan beri)."}]},{"kind":"dialog","title":"Dialog: Yüzme kursunda","blocks":[{"dlg":[["Antrenör","Hoş geldin Dilnoza. Daha önce hiç yüzdün mü?"],["Dilnoza","Çocukken kanalda oynuyorduk ama gerçekten yüzmeyi bilmiyorum."],["Antrenör","Sorun değil. Suya girince önce nefes almayı öğreneceğiz."],["Dilnoza","Başımı suya sokunca çok korkuyorum."],["Antrenör","Normal. Derin nefes alıp yavaşça ver. Korktuğunda kenara tutun."],["Dilnoza","Tamam. Ayaklarımı nasıl kullanacağım?"],["Antrenör","Dizlerini bükmeden, ayaklarını çırpa çırpa ilerle. Ben düdük çalınca dur."],["Dilnoza","Kollarım çabuk yoruluyor."],["Antrenör","Çalıştıkça güçlenirsin. Kursa başlayalı bir saat bile olmadı!"],["Dilnoza","Haklısınız. Bir tur daha deneyeyim."],["Antrenör","Aferin! Turu bitirince mola veririz."],["Dilnoza","Yüzdükçe korkum azalıyor galiba."]]},{"gloss":[["nefes almak","nafas olmoq"],["sokmak","tiqmoq"],["derin","chuqur"],["kenar","chekka"],["tutunmak","ushlab olmoq"],["diz","tizza"],["bükmek","bukmoq"],["çırpmak","tipirchilatmoq"],["ilerlemek","oldinga siljimoq"],["güçlenmek","kuchaymoq"],["azalmak","kamaymoq"],["galiba","shekilli"]]}]}],"reading":{"title":"Bisikletle işe","text":"Jasur İzmir'e geleli iki yıl oldu, ama bisiklete bu bahar başladı. Önceleri işe otobüsle gidiyordu. Trafikte bekleye bekleye sabrı tükenince bir bisiklet aldı. İlk hafta yokuşları görünce pes etmek istedi. Yine de her sabah erken kalkıp sahil yolundan gitmeye başladı. Pedal çevirdikçe hem bacakları güçlendi hem keyfi yerine geldi. Şimdi ofise vardığında kendini yorgun değil, dinç hissediyor. Yağmur yağdığında bisikleti evde bırakıp vapura biniyor. Arkadaşları onu görünce önce güldü, sonra ikisi daha bisiklet aldı. Jasur'a göre en önemli kural şu: kask takmadan asla yola çıkma!","gloss":[["sabrı tükenmek","sabri tugamoq"],["yokuş","tepalik yoʻl"],["pes etmek","taslim boʻlmoq"],["pedal çevirmek","pedal aylantirmoq"],["bacak","oyoq"],["keyfi yerine gelmek","kayfiyati koʻtarilmoq"],["dinç","tetik"],["hissetmek","his qilmoq"],["vapur","parom"],["kask takmak","shlem kiymoq"],["asla","aslo"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Jasur İzmir'e gelir gelmez bisiklete başladı.","Bisikleti trafikten sıkıldığı için aldı.","Şimdi işe vardığında kendini dinç hissediyor.","Yağmurlu günlerde de bisikletle gidiyor.","Jasur kasksız yola çıkıyor."],"ans":{"1":"Y","2":"D","3":"D","4":"Y","5":"Y"}},"exercises":[{"n":1,"title":"-(y)IncA bilan birlashtiring.","items":[["a","Düdük çaldı. Durduk. → Düdük ___ durduk."],["b","Suya girdim. Üşüdüm. → Suya ___ üşüdüm."],["c","Yokuşu gördü. Pes etmek istedi. → Yokuşu ___ pes etmek istedi."],["d","Kurs bitti. Eve döndük. → Kurs ___ eve döndük."]],"ans":{"a":"çalınca","b":"girince","c":"görünce","d":"bitince"}},{"n":2,"title":"-(y)Ip bilan birlashtiring.","items":[["a","Derin nefes al. Yavaşça ver. → Derin nefes ___ yavaşça ver."],["b","Erken kalktı. Yola çıktı. → Erken ___ yola çıktı."],["c","Bisikleti bıraktı. Vapura bindi. → Bisikleti ___ vapura bindi."],["d","Oturduk. Çay içtik. → ___ çay içtik."]],"ans":{"a":"alıp","b":"kalkıp","c":"bırakıp","d":"Oturup"}},{"n":3,"title":"Toʻgʻri ravishdoshni yozing: -DIkçA · -(y)A -(y)A · -(y)AlI.","items":[["a","___ güçlenirsin. (çalışmak)"],["b","Çocuk ___ yanıma geldi. (gülmek)"],["c","Kursa ___ iki ay oldu. (başlamak)"],["d","Pedal ___ keyfim yerine geliyor. (çevirmek)"]],"ans":{"a":"Çalıştıkça","b":"güle güle","c":"başlayalı","d":"çevirdikçe"}},{"n":4,"title":"-DIğIndA bilan toʻldiring.","items":[["a","Ofise ___ herkes toplantıdaydı. (varmak, ben)"],["b","Yağmur ___ vapura biniyor. (yağmak)"],["c","Beni ___ telefonum kapalıydı. (aramak, sen)"]],"ans":{"a":"vardığımda","b":"yağdığında","c":"aradığında"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Suvga kirgach nafas olishni oʻrganamiz."],["b","Erta turib yoʻlga chiqdim."],["c","Mashq qilgan sari kuchayasan."],["d","Izmirga kelganimga ikki yil boʻldi."],["e","Qoʻrqqaningda chetidan ushlab ol."]],"ans":{"a":"Suya girince nefes almayı öğreneceğiz.","b":"Erken kalkıp yola çıktım.","c":"Çalıştıkça güçlenirsin.","d":"İzmir'e geleli iki yıl oldu.","e":"Korktuğunda kenara tutun."}},{"n":6,"title":"Yozish. Oʻzingizning bir kunlik sport yoki sogʻlom turmush tartibingizni ravishdoshlar bilan tasvirlab bering (8–10 gap).","items":[],"ans":{}}]},{"id":"b1-8","level":"B1","n":8,"title":"Bence…","sub":"Fikr bildirish · qoʻshilish va eʼtiroz · bogʻlovchilar · harakat nomi -mAk · fikr-mulohaza inshosi","goals":["oʻz fikrini bildirish va asoslash (bence, bana göre, -DIğInI düşünüyorum)","qoʻshilish va qoʻshilmaslik","juft bogʻlovchilar (hem … hem de, ne … ne de, ya … ya da)","matn bogʻlovchilari (ayrıca, örneğin, ancak, sonuç olarak)","fikr-mulohaza inshosi tuzilishi"],"vocab":[{"title":"Lugʻat","words":[["fikir","fikr"],["görüş","nuqtai nazar"],["katılmak","qoʻshilmoq (fikrga)"],["haklı","haq"],["haksız","nohaq"],["düşünmek","oʻylamoq"],["sanmak","deb oʻylamoq"],["tartışmak","munozara qilmoq"],["kanıt","dalil"],["örnek","misol"],["avantaj","afzallik"],["dezavantaj","kamchilik"],["fayda","foyda"],["zarar","zarar"],["gerekli","zarur"],["yararlı","foydali"],["sonuç olarak","xulosa qilib aytganda"],["ayrıca","bundan tashqari"],["ancak","lekin, biroq"],["öte yandan","boshqa tomondan"]]},{"title":"Mavzuli lugʻat — jamiyat va texnologiya","words":[["sosyal medya","ijtimoiy tarmoqlar"],["akıllı telefon","smartfon"],["uzaktan eğitim","masofaviy taʼlim"],["çevre","atrof-muhit"],["kirlilik","ifloslanish"],["geri dönüşüm","qayta ishlash"],["toplum","jamiyat"],["gençler","yoshlar"],["bağımlılık","qaramlik"],["yapay zekâ","sunʼiy intellekt"]]}],"sections":[{"kind":"grammar","title":"Grammatika va iboralar","blocks":[{"sub":"Fikr bildirish"},{"table":{"h":["Ibora","Misol"],"r":[["Bence / Bana göre …","Bence bu karar adil değil."],["Bence + -mAlI","Bence okullarda daha çok spor dersi olmalı."],["-DIğInI düşünüyorum / sanıyorum","Bu uygulamanın çok faydalı olduğunu düşünüyorum."],["Bana kalırsa …","Bana kalırsa asıl mesele zaman. (Mendan soʻrasangiz…)"],["Sanırım / Galiba …","Galiba Pamuk yine aç."],["…-A göre","Araştırmalara göre kitap okumak stresi azaltıyor. (Tadqiqotlarga koʻra…)"],["Bence de / Bence değil","Men ham shunday oʻylayman / Menimcha unday emas"]]}},{"sub":"Qoʻshilish va qoʻshilmaslik"},{"table":{"h":["✔ Qoʻshilaman","✘ Qoʻshilmayman","± Qisman"],"r":[["Kesinlikle katılıyorum.","Sana katılmıyorum.","Bir noktaya kadar haklısın, ama…"],["Çok haklısın.","Bence öyle değil.","Haklısın, yalnız şunu da düşünmek lazım: …"],["Aynen öyle!","Ben başka türlü düşünüyorum.","Olabilir, fakat…"],["Ben de aynı fikirdeyim.","Pek emin değilim.","Bir açıdan evet, başka bir açıdan…"]]}},{"p":"Muloyim eʼtiroz bildirish: Fikrine saygı duyuyorum ama katılmıyorum. — Fikringni hurmat qilaman, lekin qoʻshilmayman."},{"sub":"Juft bogʻlovchilar"},{"table":{"h":["Turkcha","Oʻzbekcha","Misol"],"r":[["hem … hem (de)","ham … ham","Hem resim yapıyor hem de gitar çalıyor."],["ne … ne (de) — feʼl tasdiqda!","na … na","Ne şemsiye ne de mont almış."],["ya … ya (da)","yo … yoki","Ya otobüsle ya da metroyla gideceğiz."],["bile","hatto","Pamuk bile bu sesten korktu."]]}},{"p":"Diqqat: ne … ne bilan feʼl tasdiq shaklida qoladi: Ne aradı ne yazdı. (Na qoʻngʻiroq qildi, na yozdi.)"},{"sub":"Matn bogʻlovchilari"},{"table":{"h":["Vazifasi","Bogʻlovchilar"],"r":[["qoʻshish","ayrıca (bundan tashqari), üstelik (ustiga-ustak), bunun yanı sıra"],["misol","örneğin, mesela, … gibi"],["qarama-qarshilik","ama, fakat, ancak (lekin), buna rağmen (shunga qaramay), öte yandan (boshqa tomondan)"],["natija","bu yüzden, bu nedenle, dolayısıyla"],["xulosa","sonuç olarak, kısacası, özetle"]]}},{"sub":"Harakat nomi -mAk ega vazifasida"},{"p":"Her gün yürüyüş yapmak kalbe iyi gelir. — Har kuni sayr qilish yurakka foydali. Sınavda sözlük kullanmak yasaktır. · Yeni bir dil öğrenmek sabır ister."},{"note":"Fikr-mulohaza inshosi uch qismdan iborat: Giriş (mavzu va sizning fikringiz) → Gelişme (2–3 dalil va misol; qarshi fikr va unga javob) → Sonuç (xulosa, asosiy fikrni boshqa soʻzlar bilan takrorlash). Har bir qismda bogʻlovchilardan foydalaning."}]},{"kind":"dialog","title":"Dialog: Evden çalışmak iyi mi?","blocks":[{"dlg":[["Kerem","Bence evden çalışmak harika bir şey. Yolda zaman kaybetmiyorsun."],["Zeynep","Bu konuda sana tam katılmıyorum. Bana göre insan ofiste daha verimli çalışır."],["Kerem","Neden öyle düşünüyorsun?"],["Zeynep","Çünkü evde dikkat çabuk dağılıyor. Ayrıca iş arkadaşlarınla yüz yüze konuşmak önemli."],["Kerem","Haklı olabilirsin, ancak herkes aynı değil. Örneğin ben sessiz ortamda daha iyi düşünüyorum."],["Zeynep","Doğru, fakat yalnız çalışmanın insanı yorduğunu düşünüyorum."],["Kerem","Belki en iyisi ikisini birleştirmek: hem evde hem ofiste."],["Zeynep","İşte buna katılıyorum! Sonuç olarak, önemli olan dengeyi bulmak."]]},{"gloss":[["zaman kaybetmek","vaqt yoʻqotmoq"],["katılmak","qoʻshilmoq"],["verimli","samarali"],["dikkat dağılmak","diqqat chalgʻimoq"],["yüz yüze","yuzma-yuz"],["ortam","muhit"],["birleştirmek","birlashtirmoq"],["denge","muvozanat"]]}]}],"reading":{"title":"Büyük şehirde araba şart mı?","text":"Büyük şehirlerde araba sahibi olmak gerekli mi? Bu konuda görüşler farklı. Bazılarına göre araba özgürlük demektir: istediğin saatte, istediğin yere gidersin. Özellikle küçük çocuklu aileler için büyük kolaylıktır. Ayrıca toplu taşımanın az olduğu mahallelerde başka seçenek yoktur. Öte yandan araba pahalı bir alışkanlıktır. Benzin, sigorta ve otopark masrafları her yıl artıyor. Üstelik trafikte geçen saatler hem zamanı hem sinirleri tüketiyor. Bence şehir merkezinde yaşayanlar için araba şart değil; metro, bisiklet ve yürüyüş çoğu zaman daha hızlıdır. Ancak şehir dışında oturanlar için durum farklıdır. Sonuç olarak tek bir doğru cevap yok: herkes kendi ihtiyacına göre karar vermelidir. Yine de şehirlerin arabalar için değil, insanlar için planlanması gerektiğini düşünüyorum.","gloss":[["sahip olmak","ega boʻlmoq"],["görüş","fikr"],["özgürlük","erkinlik"],["kolaylık","qulaylik"],["toplu taşıma","jamoat transporti"],["seçenek","tanlov"],["öte yandan","boshqa tomondan"],["alışkanlık","odat"],["sigorta","sugʻurta"],["masraf","xarajat"],["üstelik","buning ustiga"],["sinir","asab"],["şart","zarur"],["ihtiyaç","ehtiyoj"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Bazılarına göre araba ne demektir?","Araba kimler için büyük kolaylıktır?","Hangi masraflar her yıl artıyor?","Yazara göre kimler için araba şart değil?","Yazar şehirlerin kimler için planlanması gerektiğini düşünüyor?"],"ans":{"1":"Özgürlük demektir.","2":"Küçük çocuklu aileler için.","3":"Benzin, sigorta ve otopark masrafları artıyor.","4":"Şehir merkezinde yaşayanlar için.","5":"İnsanlar için planlanması gerektiğini düşünüyor."}},"exercises":[{"n":1,"title":"Fikringizni bildiring (Bence…, Bana göre…, -DIğInI düşünüyorum).","items":[["a","Herkes spor yapmalı mı?"],["b","Evden çalışmak iyi bir fikir mi?"],["c","Şehirde araba şart mı?"]],"ans":{"a":"Bence herkes spor yapmalı, çünkü sağlık için önemli.","b":"Bana göre iyi bir fikir, ama herkes için uygun değil.","c":"Şehir merkezinde araba şart olmadığını düşünüyorum."},"sample":true},{"n":2,"title":"Qoʻshiling yoki muloyim eʼtiroz bildiring.","items":[["a","Kitap okumak zaman kaybıdır."],["b","Çocuklar erken yaşta yabancı dil öğrenmeli."],["c","Evden çalışanlar daha az çalışır."]],"ans":{"a":"Buna katılmıyorum. Bence kitap okumak insanı geliştirir.","b":"Sana katılıyorum, çünkü çocuklar dili daha kolay öğrenir.","c":"Haklı olabilirsin, ancak bence bu kişiye göre değişir."},"sample":true},{"n":3,"title":"hem … hem de / ne … ne de / ya … ya da bilan toʻldiring.","items":[["a","___ evde ___ ofiste çalışıyor. (ham … ham)"],["b","___ arabam var ___ bisikletim. (na … na)"],["c","___ metroyla gideriz ___ yürürüz. (yo … yo)"]],"ans":{"a":"Hem … hem de","b":"Ne … ne de","c":"Ya … ya da"}},{"n":4,"title":"Mos bogʻlovchini yozing: ayrıca · örneğin · ancak · sonuç olarak.","items":[["a","Araba rahat. ___ çok pahalı."],["b","Benzin pahalı. ___ otopark bulmak zor."],["c","Toplu taşıma, ___ metro ve vapur, daha hızlı."],["d","___ herkes kendi ihtiyacına göre karar vermeli."]],"ans":{"a":"Ancak","b":"Ayrıca","c":"örneğin","d":"Sonuç olarak"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Menimcha uydan ishlash qulay."],["b","Bu fikrga qoʻshilmayman."],["c","Haqsan, lekin hamma bir xil emas."],["d","U ham ishlaydi, ham oʻqiydi."],["e","Xulosa qilib aytganda, muvozanatni topish kerak."]],"ans":{"a":"Bence evden çalışmak rahat.","b":"Bu görüşe katılmıyorum.","c":"Haklısın, ancak herkes aynı değil.","d":"O hem çalışıyor hem de okuyor.","e":"Sonuç olarak dengeyi bulmak gerek."}},{"n":6,"title":"Yozish. «Sosyal medya gençler için faydalı mı, zararlı mı?» mavzusida 150–200 soʻzlik fikr-mulohaza inshosi yozing (Giriş · Gelişme · Sonuç).","items":[],"ans":{}}]},{"id":"b2-1","level":"B2","n":1,"title":"Gönüllü Olmak","sub":"Harakat nomlari -mAk · -mA · -(y)Iş · feʼllarning boshqaruvi · -mA va -DIK farqi · jamiyatga xizmat","goals":["uchta harakat nomini toʻgʻri tanlash: -mAk (yüzmek — suzish), -mA + egalik (gelmeniz — kelishingiz), -(y)Iş (yürüyüş, giriş — yurish, kirish)","feʼllar qaysi kelishikni talab qilishi (-mAyA başlamak, -mAktAn korkmak)","-mAsInI istemek va -DIğInI bilmek farqi","rasmiy -mAktAdIr","koʻngillilik va tabiiy ofat lugʻati"],"vocab":[{"title":"Lugʻat","words":[["gönüllü","koʻngilli"],["yardım kampanyası","xayriya aksiyasi"],["bağış","xayriya, ehson"],["afet","ofat"],["deprem bölgesi","zilzila hududi"],["arama-kurtarma","qidiruv-qutqaruv"],["ihtiyaç","ehtiyoj"],["dağıtmak","tarqatmoq"],["ulaştırmak","yetkazmoq"],["barınak","boshpana"],["çadır","chodir"],["battaniye","adyol"],["gıda","oziq-ovqat"],["ilaç","dori"],["destek olmak","qoʻllab-quvvatlamoq"],["dayanışma","hamjihatlik"],["koordinasyon","muvofiqlashtirish"],["Kızılay","Qizil Yarim Oy"],["AFAD","Favqulodda vaziyatlar boshqarmasi"],["belediye","hokimiyat (shahar)"]]},{"title":"Mavzuli lugʻat — -(y)Iş bilan yasalgan otlar","words":[["giriş","kirish"],["çıkış","chiqish"],["yürüyüş","yurish"],["bakış","qarash"],["görüş","fikr, nuqtai nazar"],["anlayış","tushunish"],["dönüş","qaytish"],["buluşma","uchrashuv"],["satış","sotuv"],["yapılış","qurilish (jarayon)"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Uch xil harakat nomi"},{"table":{"h":["Shakl","Qachon ishlatiladi","Misol","Oʻzbekcha"],"r":[["-mAk","umumiy harakat (kim bajarishi muhim emas)","Gönüllü olmak insanı mutlu eder.","Koʻngilli boʻlish insonni baxtli qiladi."],["-mA + egalik","aniq bir shaxsning harakati","Senin de katılman lazım.","Sening ham qatnashishing kerak."],["-(y)Iş","harakatning tarzi yoki bir martalik harakat; koʻpi otga aylangan","Kerem'in gülüşü çok sıcak. · giriş, çıkış, satış","Keremning kulishi juda iliq. · kirish, chiqish, sotuv"]]}},{"sub":"-mAk va kelishiklar"},{"table":{"h":["Shakl","Misol"],"r":[["-mAk (bosh kelishik)","Yeni insanlarla tanışmak istiyorum."],["-mAyA (joʻnalish; k tushib qoladi)","Kar yağmaya başladı. · Taşınmaya karar verdik."],["-mAyI (tushum)","Çiçekleri sulamayı unuttum. · Erken kalkmayı severim."],["-mAktA (oʻrin)","Bu formu doldurmakta zorlanıyorum."],["-mAktAn (chiqish)","Topluluk önünde konuşmaktan çekinir. · Şeker yemekten vazgeçti."],["-mAk için","Yardım toplamak için buluştuk."]]}},{"p":"Feʼlni u talab qiladigan kelishik bilan birga yodlang:"},{"table":{"h":["-mAyA","-mAyI","-mAktAn","-mAk"],"r":[["başlamak · karar vermek · çalışmak (urinmoq) · alışmak · hazırlanmak","sevmek · unutmak · denemek · önermek · bırakmak","korkmak · vazgeçmek · hoşlanmak · yorulmak · kaçınmak","istemek · gerekmek · lazım · zorunda"]]}},{"sub":"-mA + egalik: ishni kim qiladi?"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Gönüllülerin su içmesi ve dinlenmesi şart.","Koʻngillilarning suv ichishi va dam olishi shart."],["Senin her hafta gelmen hepimizi sevindiriyor.","Sening har hafta kelishing barchamizni xursand qilyapti."],["Kolilerin akşamdan önce dağıtılması gerekiyor.","Qutilar kechgacha tarqatilishi kerak."],["Koordinatör eldiven takmamızı istedi.","Muvofiqlashtiruvchi qoʻlqop kiyishimizni soʻradi."]]}},{"sub":"-mAsInI yoki -DIğInI? (B2 ning eng muhim nuqtalaridan biri)"},{"table":{"h":["Feʼl turi","Shakl","Misol"],"r":[["istak, buyruq, kutish: istemek, beklemek, söylemek (buyruq maʼnosida), rica etmek, önermek","-mAsInI","Erken gelmeni istiyorum. · Sessiz olmanızı rica ederim."],["bilim, xabar: bilmek, duymak, görmek, anlamak, söylemek (xabar maʼnosida), öğrenmek","-DIğInI / -(y)AcAğInI","Taşındığını biliyorum. · Geleceğini duydum."]]}},{"p":"Taqqoslang: Hoca kalmamızı söyledi. (Qolishimizni aytdi — buyruq.) · Hoca kaldığımızı söyledi. (Qolganimizni aytdi — xabar.)"},{"sub":"Rasmiy uslub: -mAktAdIr / -mAktA"},{"p":"Yangiliklar va rasmiy matnlarda -(I)yor oʻrniga koʻp ishlatiladi: Bağış kampanyası tüm hızıyla sürmektedir. — Xayriya aksiyasi toʻla quvvat bilan davom etmoqda. Mahalleye sıcak yemek ulaştırılmakta. — Mahallaga issiq ovqat yetkazilmoqda."}]},{"kind":"dialog","title":"Dialog: Hayvan barınağında","blocks":[{"dlg":[["Kerem","Defne, hafta sonları barınakta gönüllü çalışmaya başladığını duydum."],["Defne","Evet, üç aydır gidiyorum. Hayvanlara bakmak beni çok mutlu ediyor."],["Kerem","Orada neler yapıyorsun?"],["Defne","Köpekleri gezdirmeyi, kedileri beslemeyi ve kafesleri temizlemeyi öğrendim."],["Kerem","Yorucu olmuyor mu?"],["Defne","Bazen oluyor, ama bir hayvanın sahiplenilmesini görmek her şeye değer."],["Kerem","Ben de katılmak istiyorum ama köpeklerden biraz korkuyorum."],["Defne","Korkmana gerek yok. Başlangıçta mama dağıtmaya yardım edersin."],["Kerem","Gönüllü olmak için ne yapmam gerekiyor?"],["Defne","Bir form doldurman ve kısa bir eğitime katılman yeterli."],["Kerem","Tamam, bu cumartesi gelmeye çalışacağım."],["Defne","Harika! Gelişin herkesi sevindirecek."]]},{"gloss":[["barınak","hayvonlar boshpanasi"],["gönüllü","koʻngilli"],["gezdirmek","sayr qildirmoq"],["beslemek","boqmoq"],["kafes","qafas"],["yorucu","charchatadigan"],["sahiplenmek","asrab olmoq"],["değmek","arzimoq"],["mama","hayvon yemi"],["doldurmak","toʻldirmoq"],["yeterli","yetarli"]]}]}],"reading":{"title":"Kitap Köprüsü","text":"İzmirli üniversite öğrencileri iki yıl önce \"Kitap Köprüsü\" adlı bir gönüllü projesi başlattı. Amaçları, köy okullarına kitap ulaştırmak ve çocuklara okumayı sevdirmekti. İlk aylarda kitap toplamak sanıldığı kadar kolay olmadı; öğrenciler kapı kapı dolaşmak zorunda kaldı. Sosyal medyada paylaşım yapmaya başlayınca bağışlar hızla arttı. Toplanan kitapların ayrılması, temizlenmesi ve paketlenmesi haftalar sürüyor. Gönüllüler her ay bir köye gidip kütüphane kurmanın yanında masal okuma saatleri de düzenliyor. Projenin koordinatörü Zeynep'e göre en zor şey kitap bulmak değil, projeyi sürdürmektir: \"Başlamak kolay, devam etmek emek ister.\" Bugüne kadar otuz iki okula on beş binden fazla kitap ulaştırıldı. Öğrenciler şimdi projeyi başka şehirlere yaymayı planlıyor. Projenin en dokunaklı anlarından biri geçen kış yaşandı. Yolların kardan kapanmasına rağmen gönüllüler bir dağ köyüne ulaşmayı başardı. Okulun tek öğretmeni, çocukların haftalardır onların gelişini beklediğini söyledi. Kitapları raflara dizmek birkaç saat sürdü; ancak çocukların kitaplara sarılışını görmek bütün yorgunluğu unutturdu. Gönüllülerden biri o günü şöyle anlatıyor: \"Bir çocuğun ilk kez kendi seçtiği kitabı eve götürmesine tanık olmak, verilen her emeğe değer.\" Proje ekibi, öğretmenlerin de sürece katılmasını sağlamak için bu yıl okuma atölyeleri düzenlemeyi hedefliyor.","gloss":[["amaç","maqsad"],["ulaştırmak","yetkazmoq"],["sevdirmek","sevdirmoq"],["sanmak","oʻylamoq"],["dolaşmak","aylanib chiqmoq"],["paylaşım","post, ulashish"],["bağış","xayriya"],["ayırmak","saralamoq"],["masal","ertak"],["sürdürmek","davom ettirmoq"],["emek","mehnat"],["yaymak","yoymoq"],["dokunaklı","taʼsirli, yurakka yaqin"],["dizmek","termoq"],["sarılmak","mahkam quchmoq"],["tanık olmak","guvoh boʻlmoq"],["hedeflemek","maqsad qilmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Projenin amacı neydi?","Bağışlar ne zaman arttı?","Gönüllüler köylerde ne yapıyor?","Zeynep'e göre en zor şey nedir?","Bugüne kadar kaç okula kitap ulaştırıldı?","Gönüllüler geçen kış neyi başardı?"],"ans":{"1":"Köy okullarına kitap ulaştırmak ve çocuklara okumayı sevdirmekti.","2":"Sosyal medyada paylaşım yapmaya başlayınca arttı.","3":"Kütüphane kuruyor ve masal okuma saatleri düzenliyor.","4":"Projeyi sürdürmektir.","5":"Otuz iki okula ulaştırıldı.","6":"Yolların kardan kapanmasına rağmen bir dağ köyüne ulaşmayı başardılar."}},"exercises":[{"n":1,"title":"Qavsdagi feʼlni toʻgʻri shaklga qoʻying (-mAk, -mAyA, -mAyI, -mAktAn).","items":[["a","Kar ___ başladı. (yağmak)"],["b","Kedileri ___ öğrendim. (beslemek)"],["c","Köpeklerden ___ vazgeçti. (korkmak)"],["d","Gönüllü ___ istiyorum. (olmak)"],["e","Erken ___ alıştım. (kalkmak)"]],"ans":{"a":"yağmaya","b":"beslemeyi","c":"korkmaktan","d":"olmak","e":"kalkmaya"}},{"n":2,"title":"-mAsInI yoki -DIğInI?","items":[["a","Defne cumartesi ___ istedi. (gelmek, ben)"],["b","Kerem köpeklerden ___ söyledi. (korkmak, o)"],["c","Koordinatör form ___ rica etti. (doldurmak, biz)"],["d","Bağışların ___ duydum. (artmak)"]],"ans":{"a":"gelmemi","b":"korktuğunu","c":"doldurmamızı","d":"arttığını"}},{"n":3,"title":"-(y)Iş bilan ot yasang.","items":[["a","gelmek →"],["b","bakmak →"],["c","satmak →"],["d","uçmak →"],["e","anlamak →"]],"ans":{"a":"geliş","b":"bakış","c":"satış","d":"uçuş","e":"anlayış"}},{"n":4,"title":"Rasmiy uslubga oʻtkazing (-mAktAdIr).","items":[["a","Proje devam ediyor. →"],["b","Kitaplar toplanıyor. →"],["c","Gönüllüler her ay bir köye gidiyor. →"]],"ans":{"a":"Proje devam etmektedir.","b":"Kitaplar toplanmaktadır.","c":"Gönüllüler her ay bir köye gitmektedir."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Kitob oʻqish foydali."],["b","Sening kelishing kerak."],["c","Mushuklarni boqishni oʻrgandim."],["d","U itlardan qoʻrqishini aytdi."],["e","Boshlash oson, davom ettirish qiyin."]],"ans":{"a":"Kitap okumak faydalıdır.","b":"Senin gelmen gerek.","c":"Kedileri beslemeyi öğrendim.","d":"Köpeklerden korktuğunu söyledi.","e":"Başlamak kolay, devam etmek zor."}},{"n":6,"title":"Yozish. Mahallangizda xayriya aksiyasi uchun eʼlon yozing: nima kerak, qachon, qayerda, koʻngillilardan nima kutilmoqda (120–150 soʻz).","items":[],"ans":{}},{"n":7,"title":"Feʼlning kelishik talabi: toʻgʻri qoʻshimchani yozing.","items":[["a","Çocuklar gönüllülerin geliş___ bekliyordu."],["b","Proje, çocuklara okumayı sevdirme___ amaçlıyor."],["c","Kitapları raflara dizme___ başladık."],["d","Kalabalık önünde konuşmak___ çekiniyorum."]],"ans":{"a":"gelişini","b":"sevdirmeyi","c":"dizmeye","d":"konuşmaktan"}},{"n":8,"title":"Ikki gapni -mA + egalik bilan birlashtiring.","items":[["a","Sen geldin. Buna çok sevindim. → Senin ___ çok sevindim."],["b","Kerem geç kaldı. Bu bizi şaşırttı. → Kerem'in geç ___ bizi şaşırttı."],["c","Çocuklar kitap okuyor. Bu önemli. → Çocukların kitap ___ önemli."],["d","Biz de katılalım. Bunu istiyorlar. → Bizim de ___ istiyorlar."]],"ans":{"a":"gelmene","b":"kalması","c":"okuması","d":"katılmamızı"}}]},{"id":"b2-2","level":"B2","n":2,"title":"Tarihin Sayfalarından","sub":"Murakkab zamonlar: -mIştI · -(y)AcAktI · -ArdI · -mAlIydI · -(I)yormuş · tarixiy hikoya","goals":["murakkab oʻtgan zamonlar bilan hikoya qilish: -mIştI (gelmiştim — kelgan edim), -(y)AcAktI (gelecektim — kelmoqchi edim), -ArdI (gelirdim — kelar edim), -mAlIydI (gelmeliydin — kelishing kerak edi), -(y)AbilirdI","eshitilgan murakkab shakllar (geliyormuş, gelmişmiş)","tarixiy matnlarni oʻqish"],"vocab":[{"title":"Lugʻat","words":[["İpek Yolu","Buyuk Ipak yoʻli"],["kervan","karvon"],["kervansaray","karvonsaroy"],["tüccar","savdogar"],["ticaret","savdo"],["ipek","ipak"],["baharat","ziravor"],["seyahat","sayohat"],["imparatorluk","imperiya"],["hükümdar","hukmdor"],["başkent","poytaxt"],["kurulmak","barpo etilmoq"],["yıkılmak","qulamoq"],["keşfetmek","kashf qilmoq"],["kalıntı","qoldiq, xaroba"],["efsane","afsona"],["yolculuk","yoʻl, safar"],["anlatılmak","hikoya qilinmoq"],["döneminde","...davrida"],["eskiden","ilgari"]]},{"title":"Mavzuli lugʻat — vaqt ifodalari","words":[["o sırada","oʻsha paytda"],["o zamanlar","oʻsha zamonlarda"],["daha önce","avvalroq"],["çoktan","allaqachon"],["henüz","hali (...emas)"],["yüzyıllar boyunca","asrlar davomida"],["günümüzde","bugungi kunda"],["milattan önce","miloddan avvalgi"],["sonunda","nihoyat"],["derken","shu payt, kutilmaganda"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"-mIştI: «…gan edi» (oʻtmishdan ham oldingi oʻtmish)"},{"table":{"h":["Shaxs","ben","sen","o","biz","siz","onlar"],"r":[["varmak","varmıştım","varmıştın","varmıştı","varmıştık","varmıştınız","varmışlardı"]]}},{"p":"Oʻtmishdagi ikki voqeadan qaysi biri oldinroq boʻlganini koʻrsatadi: Müzeye vardığımızda kapılar kapanmıştı. — Muzeyga yetib borganimizda eshiklar yopilgan edi. Bu şehri daha önce hiç görmemiştim. — Bu shaharni oldin hech koʻrmagan edim. Soʻroq: Daha önce gelmiş miydin? — Oldin kelganmiding?"},{"sub":"-(y)AcAktI: «…moqchi edim», «…ishi kerak edi»"},{"p":"Rejalashtirilgan, ammo amalga oshmay qolgan ish: Sana kartpostal gönderecektim ama adresini kaybettim. — Senga otkritka yubormoqchi edim, lekin manzilingni yoʻqotib qoʻydim. Kazı yazın bitecekti, fakat yeni buluntular çıktı. — Qazishma yozda tugashi kerak edi, ammo yangi topilmalar chiqdi."},{"sub":"-ArdI / -IrdI: «…ardi» (oʻtmishdagi odat)"},{"p":"Küçükken babaannem bize masal anlatırdı. — Kichikligimizda buvim bizga ertak aytib berardi. Eskiden köylüler suyu çeşmeden taşırdı; şimdi her evde musluk var. -(I)yordu ham odatni bildiradi, lekin -ArdI koʻproq xotira va hikoya ohangida eshitiladi."},{"sub":"-mAlIydI va -(y)AbilirdI"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Bileti önceden almalıydık.","Chiptani oldindan olishimiz kerak edi. (afsus)"],["Bunu bize daha önce söylemeliydin.","Buni bizga oldinroq aytishing kerak edi. (tanqid)"],["Haritaya baksaydık kaybolmazdık; yolu kolayca bulabilirdik.","Xaritaga qaraganimizda adashmasdik; yoʻlni oson topa olardik."],["Yangın erken fark edilseydi bina kurtarılabilirdi.","Yongʻin erta sezilganida binoni saqlab qolish mumkin edi."]]}},{"sub":"-mIş qoʻshilgan murakkab shakllar (eshitilgan xabar)"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["çalışıyormuş","ishlayotgan ekan"],["dönecekmiş","qaytar ekan"],["bitirmiş / bitirmişmiş","tugatgan ekan (soʻzlashuvda: aytishlaricha)"],["giderdi → gidermiş","borar ekan (eshitilgan odat)"]]}},{"p":"Zeynep'in kuzeni Efes'te rehberlik yapıyormuş; her gün yüzlerce turist gezdiriyormuş. — Zeynepning amakivachchasi Efesda gidlik qilayotgan ekan; har kuni yuzlab sayyohni aylantirayotgan ekan."},{"note":"Oʻtgan zamonlar xaritasi: -DI — aniq oʻtgan · -mIş — eshitilgan · -(I)yordu — davom etayotgan · -mIştI — undan ham oldingi · -ArdI — odat · -(y)AcAktI — amalga oshmagan reja · -mAlIydI — bajarilmagan burch. Hikoyada: fon va manzara (-(I)yordu), asosiy voqealar (-DI), undan oldin boʻlganlar (-mIştI)."}]},{"kind":"dialog","title":"Dialog: Eski fotoğraf albümü","blocks":[{"dlg":[["Dilnoza","Büyükanne, bu fotoğraftaki genç kız sen misin?"],["Büyükanne","Evet, o yıl liseyi yeni bitirmiştim. Öğretmen olacaktım ama olmadı."],["Dilnoza","Neden olmadı?"],["Büyükanne","Babam hastalanmıştı, tarlada çalışacak kimse yoktu. Ben de köyde kaldım."],["Dilnoza","O zamanlar hayat nasıldı?"],["Büyükanne","Elektrik yoktu; akşamları gaz lambasının ışığında dikiş dikerdik. Kışın herkes sandalın etrafında toplanırdı."],["Dilnoza","Sıkılmaz mıydınız?"],["Büyükanne","Hiç sıkılmazdık! Deden dutar çalar, biz şarkı söylerdik. Meğer en güzel günlerimizmiş."],["Dilnoza","O günleri görmek isterdim."],["Büyükanne","Aslında bir şey yapmalıydım: o şarkıları yazmalıydım. Şimdi çoğunu unuttum."],["Dilnoza","Hatırladıklarını söyle, ben kaydedeyim."],["Büyükanne","Olur kızım. Deden bunu görse çok sevinirdi."]]},{"gloss":[["tarla","dala"],["gaz lambası","kerosin chiroq"],["dikiş dikmek","tikish tikmoq"],["sandal","sandal (isinish joyi)"],["toplanmak","yigʻilmoq"],["sıkılmak","zerikmoq"],["meğer","bilsak"],["aslında","aslida"],["kaydetmek","yozib olmoq"]]}]}],"reading":{"title":"Kervansaraylar","text":"İpek Yolu üzerinde yolculuk eden kervanlar günde ortalama otuz-kırk kilometre yol alırdı. Bu yüzden her bir günlük mesafeye bir kervansaray yapılmıştı. Tüccarlar akşam olmadan kervansaraya ulaşmalıydı, çünkü kapılar gün batımında kapanırdı. İçeride yolcular için odalar, hayvanlar için ahırlar, ayrıca bir hamam ve bir mescit bulunurdu. Anadolu'daki Selçuklu kervansaraylarında ilk üç gün konaklama ücretsizdi; masrafları vakıflar karşılardı. Buhara'dan yola çıkan bir tüccar Akdeniz'e varana kadar aylar geçerdi. Demiryolları yapılınca kervanlar yavaş yavaş ortadan kalktı. Kervansarayların birçoğu terk edilmişti; bazıları sonradan onarılıp otele veya müzeye dönüştürüldü. Bugün Sultanhanı gibi yapılar, o dönemin nasıl bir dünya olduğunu bize anlatıyor. Kervansaraylar yalnızca birer konaklama yeri değildi; haberlerin, masalların ve yeni fikirlerin de el değiştirdiği yerlerdi. Bir tüccar Çin'den getirdiği ipeği satarken yolda öğrendiği bir hikâyeyi de anlatır, böylece hikâye ipekle birlikte batıya doğru yol alırdı. Kimi tarihçilere göre kâğıt yapımı gibi birçok buluş, Avrupa'ya bu yollardan ulaşmıştı. Kervan yola çıkmadan önce hayvanlar dinlendirilmiş, yükler yeniden bağlanmış olurdu; sabahın ilk ışıklarıyla birlikte kapılar açılır ve uzun yolculuk kaldığı yerden devam ederdi.","gloss":[["kervan","karvon"],["ortalama","oʻrtacha"],["mesafe","masofa"],["tüccar","savdogar"],["gün batımı","quyosh botishi"],["ahır","otxona"],["mescit","kichik masjid"],["konaklama","tunash"],["vakıf","vaqf"],["karşılamak","qoplamoq (xarajatni)"],["demiryolu","temir yoʻl"],["ortadan kalkmak","yoʻq boʻlib ketmoq"],["terk etmek","tashlab ketmoq"],["dönüştürmek","aylantirmoq"],["dönem","davr"],["el değiştirmek","qoʻldan-qoʻlga oʻtmoq"],["ipek","ipak"],["buluş","ixtiro"],["yük","yuk"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Kervanlar günde yüz kilometre yol alırdı.","Kervansarayların kapıları gün batımında kapanırdı.","Selçuklu kervansaraylarında ilk üç gün için para ödenmezdi.","Kervansaraylarda hayvanlar için yer yoktu.","Bazı kervansaraylar bugün otel veya müze olarak kullanılıyor.","Kervansaraylarda yalnızca mallar değil, haberler ve hikâyeler de el değiştirirdi."],"ans":{"1":"Y","2":"D","3":"D","4":"Y","5":"D","6":"D"}},"exercises":[{"n":1,"title":"-mIştI qoʻshing.","items":[["a","İstasyona vardığımda tren ___ . (kalkmak)"],["b","O filmi daha önce ___ . (izlemek, ben)"],["c","Biz geldiğimizde annem sofrayı ___ . (kurmak)"],["d","Sen aradığında çoktan ___ . (uyumak, biz)"]],"ans":{"a":"kalkmıştı","b":"izlemiştim","c":"kurmuştu","d":"uyumuştuk"}},{"n":2,"title":"-(y)AcAktI yoki -mAlIydI?","items":[["a","Dün sana ___ ama internet yoktu. (yazmak, ben)"],["b","Bu şarkıları daha önce ___ . (kaydetmek, biz — afsus)"],["c","Büyükannem öğretmen ___ ama köyde kaldı. (olmak)"],["d","Bana daha erken ___ . (söylemek, sen — taʼna)"]],"ans":{"a":"yazacaktım","b":"kaydetmeliydik","c":"olacaktı","d":"söylemeliydin"}},{"n":3,"title":"-ArdI bilan oʻtmishdagi odatlarni yozing.","items":[["a","Kışın herkes sandalın etrafında ___ . (toplanmak)"],["b","Çocukken her akşam masal ___ . (dinlemek, biz)"],["c","Dedem dutar ___ . (çalmak)"]],"ans":{"a":"toplanırdı","b":"dinlerdik","c":"çalardı"}},{"n":4,"title":"Eshitilgan shaklga oʻtkazing (-mIş).","items":[["a","Kerem'in yeni işi çok zor. →"],["b","Kervanlar günde otuz kilometre yol alırdı. →"],["c","Zeynep şu anda toplantıda. →"]],"ans":{"a":"Kerem'in yeni işi çok zormuş.","b":"Kervanlar günde otuz kilometre yol alırmış.","c":"Zeynep şu anda toplantıdaymış."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Men bu filmni oldin koʻrgan edim."],["b","Senga yozmoqchi edim, lekin unutdim."],["c","Bolaligimizda har kuni ertak tinglar edik."],["d","Menga oldinroq aytishing kerak edi."],["e","Biz kelganimizda poyezd ketib boʻlgan edi."]],"ans":{"a":"Bu filmi daha önce izlemiştim.","b":"Sana yazacaktım ama unuttum.","c":"Çocukken her gün masal dinlerdik.","d":"Bana daha önce söylemeliydin.","e":"Biz geldiğimizde tren kalkmıştı."}},{"n":6,"title":"Yozish. Oilangiz tarixidan yoki shahringiz tarixidan bir voqeani murakkab oʻtgan zamonlar bilan hikoya qiling (150 soʻz).","items":[],"ans":{}},{"n":7,"title":"-mIştI yoki -DI? Qavsni oching.","items":[["a","Eve geldiğimde herkes çoktan (uyumak) ___ ."],["b","Dün akşam erken (yatmak) ___ . (ben)"],["c","Onu aradım ama evden (çıkmak) ___ ."],["d","Filmi daha önce (izlemek) ___ , o yüzden gitmedim. (ben)"]],"ans":{"a":"uyumuştu","b":"yattım","c":"çıkmıştı","d":"izlemiştim"}},{"n":8,"title":"Oʻtmishdagi odatni -ArdI bilan yozing.","items":[["a","Eskiden her sabah koşuyordum. → Eskiden her sabah ___ ."],["b","Dedem bize hikâyeler anlatıyordu. → Dedem bize hikâyeler ___ ."],["c","Yazları köye gidiyorduk. → Yazları köye ___ ."],["d","Sen çocukken çok ağlıyordun. → Sen çocukken çok ___ ."]],"ans":{"a":"koşardım","b":"anlatırdı","c":"giderdik","d":"ağlardın"}}]},{"id":"b2-3","level":"B2","n":3,"title":"Ne Olmuş Olabilir?","sub":"Xayoliy shart -sAydI · keşke -sAydI · taxmin: -DIr · -mIş olmalı · -mIş olabilir · olsa gerek · herhalde","goals":["xayoliy shart: bilseydim söylerdim (bilganimda aytardim)","pushaymonlik: keşke gelseydin (qani endi kelgan boʻlsang)","ehtimol va taxmin darajalari: -DIr, -mIş olmalı, -mIş olabilir, olsa gerek, herhalde","natijadan sababga xulosa chiqarish"],"vocab":[{"title":"Lugʻat","words":[["tahmin etmek","taxmin qilmoq"],["ihtimal","ehtimol"],["muhtemelen","ehtimol, katta ehtimol bilan"],["herhalde","ehtimol, shekilli"],["belki","balki"],["kesin","aniq"],["şüphe","shubha"],["ipucu","ishora, iz"],["kaybolmak","yoʻqolmoq"],["bulmak","topmoq"],["unutmak","unutmoq"],["şarjı bitmek","zaryadi tugamoq"],["kaçırmak","boy bermoq (avtobus va h.k.)"],["trafik","tirbandlik"],["pişman olmak","pushaymon boʻlmoq"],["keşke","qani edi, koshki"],["zengin","boy"],["fırsat","imkoniyat"],["dikkat etmek","eʼtibor bermoq"],["merak etmek","xavotirlanmoq; qiziqmoq"]]},{"title":"Mavzuli lugʻat — xulosa iboralari","words":[["belli ki","koʻrinib turibdiki"],["anlaşılan","shekilli"],["öyle görünüyor ki","shunday koʻrinadiki"],["bu demek oluyor ki","bu degani"],["büyük ihtimalle","katta ehtimol bilan"],["galiba","chamasi"],["sanırım","menimcha"],["olabilir","boʻlishi mumkin"],["olamaz","boʻlishi mumkin emas"],["şüphesiz","shubhasiz"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Xayoliy shart: -sAydI → -ArdI / -(y)AcAktI"},{"p":"Haqiqatda boʻlmagan shart va uning natijasi — oʻzbekchadagi «…ganimda …ardim»:"},{"table":{"h":["Shart (-sAydI)","Natija (-ArdI / -(y)AcAktI)","Oʻzbekcha"],"r":[["Adresi bilseydim","seni ziyarete gelirdim.","Manzilni bilganimda, seni koʻrgani kelardim."],["Şemsiyeni alsaydın","ıslanmazdın.","Soyabonni olganingda, hoʻl boʻlmasding."],["Rüzgâr esmeseydi","tekneyle adaya geçecektik.","Shamol esmaganida, qayiqda orolga oʻtar edik."],["Vaktim olsaydı","bir müzik aleti öğrenirdim.","Vaqtim boʻlganida, biror cholgʻu chalishni oʻrganardim."]]}},{"table":{"h":["Shaxs","ben","sen","o","biz","siz","onlar"],"r":[["bilmek","bilseydim","bilseydin","bilseydi","bilseydik","bilseydiniz","bilselerdi"]]}},{"p":"Inkor: bilmeseydim. Ot bilan: mimar olsaydım (meʼmor boʻlganimda), orada olsaydın, param olsaydı."},{"sub":"Keşke + -sA / -sAydI"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Keşke denize yakın bir evde otursam.","Qani endi dengiz yaqinidagi uyda yashasam. (hozir yoki kelajak)"],["Keşke dün bizimle gelseydin.","Qani endi kecha biz bilan kelgan boʻlsang. (oʻtmish, afsus)"],["Keşke o mesajı göndermeseydim.","Koshki u xabarni yubormagan boʻlsam."]]}},{"sub":"Taxmin darajalari"},{"table":{"h":["Ishonch","Shakl","Misol","Oʻzbekcha"],"r":[["★★★★ juda kuchli","-mIş olmalı","Anahtarı evde unutmuş olmalı.","Kalitni uyda unutgan boʻlsa kerak (deyarli aniq)."],["★★★★","-DIr (taxmin)","Kerem şimdi uyuyordur. · Paket çoktan gelmiştir.","Kerem hozir uxlayotgan boʻlsa kerak. · Posilka allaqachon kelgandir."],["★★★","olsa gerek","Trafik yoğun olsa gerek.","Tirbandlik boʻlsa kerak."],["★★★","herhalde / muhtemelen","Herhalde toplantıda.","Ehtimol yigʻilishda."],["★★","-mIş olabilir","Şarjı bitmiş olabilir.","Quvvati tugagan boʻlishi mumkin."],["★★","-(y)Abilir","Akşama doğru fırtına çıkabilir.","Kechga yaqin boʻron boʻlishi mumkin."],["★ zaif","belki","Belki yarın uğrar.","Balki ertaga kirib oʻtar."]]}},{"note":"-DIr ikki xil vazifada keladi: 1) rasmiy tasdiq: Bu alanda kamp yapmak yasaktır. (Bu hududda chodir tikish taqiqlanadi.) 2) soʻzlashuvdagi taxmin: Defne şimdi iştedir. (Defne hozir ishda boʻlsa kerak.)"},{"sub":"Natijadan sababga: xulosa iboralari"},{"p":"Belli ki… (Koʻrinib turibdiki…) · Anlaşılan… (Shekilli…) · Öyle görünüyor ki… (Shunday koʻrinadiki…) · Bu demek oluyor ki… (Demak…) · Büyük ihtimalle… (Katta ehtimol bilan…). Masalan: Kapının önünde çamurlu ayak izleri var; belli ki Pamuk bahçeden yeni dönmüş."}]},{"kind":"dialog","title":"Dialog: Kargo neden gelmedi?","blocks":[{"dlg":[["Jasur","Sipariş ettiğim kitaplar hâlâ gelmedi. Bugün teslim edilecekti."],["Kerem","Kurye adresi bulamamış olabilir. Zil çalışıyor mu?"],["Jasur","Çalışıyor. Bütün gün evdeydim; gelseydi duyardım."],["Kerem","O zaman paket henüz yola çıkmamıştır. Takip numarasına baktın mı?"],["Jasur","Baktım, \"dağıtımda\" yazıyor. Yanlış binaya bırakmış olmalılar."],["Kerem","Olabilir. Komşuna sordun mu? Herhalde ona teslim etmişlerdir."],["Jasur","Sormadım. Keşke sabah kapıya bir not bıraksaydım."],["Kerem","Üzülme. Ben olsaydım önce kargo şirketini arardım."],["Jasur","Haklısın… Dur, mesaj geldi: \"Paketiniz bina görevlisine teslim edildi.\""],["Kerem","Gördün mü? Ona sorsaydın çoktan almış olurdun!"],["Jasur","Görevli izinde olsa gerek, sabahtan beri görmedim."],["Kerem","Akşama döner herhalde. Kitaplar kaçmıyor ya!"]]},{"gloss":[["sipariş etmek","buyurtma qilmoq"],["kurye","kuryer"],["zil","qoʻngʻiroq"],["takip numarası","kuzatuv raqami"],["dağıtım","yetkazib berish"],["herhalde","ehtimol"],["bina görevlisi","uy xodimi"],["çoktan","allaqachon"],["izinde","taʼtilda"],["kaçmak","qochmoq"]]}]}],"reading":{"title":"Çalmayan alarm","text":"Zeynep o sabah gözünü açtığında saat dokuza geliyordu. Oysa alarmı yediye kurmuştu. \"Çalmış olmalı, ben duymamışımdır\" diye düşündü. Telefonuna baktı: ekran kapkaraydı. Şarjı gece bitmiş olmalıydı. Fişe takmıştı ama priz çalışmıyor olabilirdi. Toplantı dokuz buçuktaydı; taksiye binse bile yetişemezdi. \"Keşke dün gece prizi kontrol etseydim\" dedi kendi kendine. Tam o sırada kapı çaldı. Gelen, ev arkadaşı Defne'ydi: \"Elektrikler bütün mahallede kesikmiş. Senin toplantı da ertelenmiş olsa gerek, şirketten kimse telefona cevap vermiyor.\" Zeynep derin bir nefes aldı. Elektrik kesilmeseydi toplantıyı kaçıracak, belki de müdürüyle tartışacaktı. Bazen bir aksilik, başka bir aksiliği önler. Kahvaltıda Defne gülerek bir şey daha anlattı: komşulardan biri aceleyle evden çıkmış olmalıydı, çünkü terliklerini kapının önünde unutmuştu. Zeynep o gün işe öğleden sonra gitti. Müdürü, elektrik kesintisinden haberdar olsaydı toplantıyı bir gün önceden erteleyeceğini söyledi. Akşam eve dönerken Zeynep bir saatçiye uğradı ve pille çalışan eski usul bir çalar saat aldı. \"Telefonum beni bir daha yarı yolda bırakırsa,\" diye düşündü, \"en azından bu çalmış olur.\"","gloss":[["alarm kurmak","budilnik qoʻymoq"],["kapkara","qop-qora"],["şarj","quvvat"],["fişe takmak","rozetkaga ulamoq"],["yetişmek","ulgurmoq"],["kendi kendine","oʻz-oʻziga"],["kesik","uzilgan"],["ertelemek","keyinga qoldirmoq"],["kaçırmak","oʻtkazib yubormoq"],["tartışmak","bahslashmoq"],["aksilik","omadsizlik"],["önlemek","oldini olmoq"],["terlik","shippak"],["kesinti","uzilish"],["haberdar olmak","xabardor boʻlmoq"],["uğramak","kirib oʻtmoq"],["çalar saat","budilnik"],["yarı yolda bırakmak","yarim yoʻlda qoldirmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Zeynep alarmı saat kaça kurmuştu?","Telefonun ekranı neden karaydı?","Zeynep neye pişman oldu?","Defne ne haber getirdi?","Elektrik kesilmeseydi ne olacaktı?","Zeynep akşam ne satın aldı?"],"ans":{"1":"Yediye kurmuştu.","2":"Şarjı gece bitmiş olmalıydı.","3":"Dün gece prizi kontrol etmediğine pişman oldu.","4":"Elektriklerin bütün mahallede kesik olduğunu söyledi.","5":"Zeynep toplantıyı kaçıracaktı.","6":"Pille çalışan eski usul bir çalar saat aldı."}},"exercises":[{"n":1,"title":"-sAydI … -ArdI bilan xayoliy shart tuzing.","items":[["a","Duymadım, kapıyı açmadım. → ___ kapıyı açardım."],["b","Erken çıkmadın, otobüsü kaçırdın. → Erken ___ otobüsü kaçırmazdın."],["c","Vaktim yoktu, gelemedim. → Vaktim ___ gelirdim."],["d","Not bırakmadık, kurye bizi bulamadı. → Not ___ kurye bizi bulurdu."]],"ans":{"a":"Duysaydım","b":"çıksaydın","c":"olsaydı","d":"bıraksaydık"}},{"n":2,"title":"keşke bilan afsus bildiring.","items":[["a","Prizi kontrol etmedim. → Keşke prizi ___ ."],["b","Ona her şeyi anlattım. → Keşke ___ ."],["c","Dün toplantıya gelmedin. → Keşke dün toplantıya ___ ."]],"ans":{"a":"kontrol etseydim","b":"anlatmasaydım","c":"gelseydin"}},{"n":3,"title":"Taxmin qiling. Qavsdagi shaklni ishlating.","items":[["a","Kurye hâlâ gelmedi. (-mIş olabilir: adresi bulamamak)"],["b","Zeynep'in gözleri kırmızı. (-mIştIr: az uyumak)"],["c","Işıklar yanmıyor. (-mIş olmalı: elektrik kesilmek)"]],"ans":{"a":"Adresi bulamamış olabilir.","b":"Az uyumuştur.","c":"Elektrik kesilmiş olmalı."}},{"n":4,"title":"Ishonch darajasi boʻyicha yozing: eng kuchlisi.","items":[["a","belki unutmuştur · unutmuş olmalı · unutmuş olabilir — eng kuchlisi qaysi?"]],"ans":{"a":"unutmuş olmalı"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Eshitganimda eshikni ochardim."],["b","Qaniydi kecha tekshirganimda!"],["c","U manzilni topa olmagan boʻlishi mumkin."],["d","Elektr uzilgan boʻlsa kerak."],["e","Sening oʻrningda boʻlganimda qoʻngʻiroq qilardim."]],"ans":{"a":"Duysaydım kapıyı açardım.","b":"Keşke dün kontrol etseydim!","c":"Adresi bulamamış olabilir.","d":"Elektrik kesilmiş olmalı.","e":"Senin yerinde olsaydım arardım."}},{"n":6,"title":"Yozish. «Agar siz boshqa davrda yashaganingizda…» mavzusida -sAydI va -ArdI bilan 8–10 gap yozing.","items":[],"ans":{}},{"n":7,"title":"Xayoliy shartni toʻldiring (-sAydI … -ArdI).","items":[["a","Zengin (olmak, ben) ___ dünyayı gezerdim."],["b","Daha çok çalışsaydın sınavı (geçmek) ___ ."],["c","Yağmur (yağmamak) ___ pikniğe giderdik."],["d","Bana sorsaydınız size (yardım etmek, ben) ___ ."]],"ans":{"a":"olsaydım","b":"geçerdin","c":"yağmasaydı","d":"yardım ederdim"}},{"n":8,"title":"Taxmin: -mIş olmalı (kuchli) yoki -mIş olabilir (kuchsiz)?","items":[["a","Yerler ıslak. Kesinlikle yağmur ___ . (yağmak)"],["b","Telefonu açmıyor. Belki ___ . (uyumak)"],["c","Bütün ışıklar kapalı. Herkes ___ . (gitmek — aniq)"],["d","Anahtarımı bulamıyorum. Belki ofiste ___ . (unutmak, ben)"]],"ans":{"a":"yağmış olmalı","b":"uyumuş olabilir","c":"gitmiş olmalı","d":"unutmuş olabilirim"}}]},{"id":"b2-4","level":"B2","n":4,"title":"Online mı, Yüz Yüze mi?","sub":"Toʻsiqsizlik va qarama-qarshilik: -mAsInA rağmen · -DIğI hâlde · -sA bile · oysa · -(y)ken · -mAktAnsA","goals":["qarama-qarshi fikrlarni nozik bogʻlash: -mAsInA rağmen (…ishiga qaramay), -DIğI hâlde (…gan boʻlsa-da), -sA bile / -sA da (…sa ham), oysa / hâlbuki (holbuki), -(y)ken (…sa, …esa), -mAktAnsA (…gandan koʻra)","sadece … değil, aynı zamanda …","B2 darajasidagi bahs (argumentativ) matn"],"vocab":[{"title":"Lugʻat","words":[["yüz yüze","yuzma-yuz"],["çevrim içi / online","onlayn"],["eğitim","taʼlim"],["ders","dars"],["etkileşim","oʻzaro taʼsir, muloqot"],["motivasyon","motivatsiya"],["disiplin","intizom"],["esneklik","moslashuvchanlik"],["maliyet","xarajat"],["ulaşım","transport, qatnov"],["bağlantı","ulanish, aloqa"],["kesilmek","uzilmoq"],["ekran","ekran"],["yalnızlık","yolgʻizlik"],["tercih etmek","afzal koʻrmoq"],["savunmak","himoya qilmoq (fikrni)"],["iddia etmek","daʼvo qilmoq"],["karşı çıkmak","qarshi chiqmoq"],["avantaj","afzallik"],["dezavantaj","kamchilik"]]},{"title":"Mavzuli lugʻat — bahs iboralari","words":[["buna rağmen","shunga qaramay"],["yine de","baribir"],["oysa","holbuki"],["hâlbuki","holbuki"],["aksine","aksincha"],["üstelik","ustiga-ustak"],["dahası","bundan ham koʻproq"],["bir yandan … diğer yandan","bir tomondan … ikkinchi tomondan"],["kısacası","qisqasi"],["özetle","xulosa qilib"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"«…ga qaramay»: -mAsInA rağmen / -DIğI hâlde"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["İnternet yavaş olmasına rağmen ders kesilmedi.","Internet sekin boʻlishiga qaramay, dars uzilmadi."],["Uykusu geldiği hâlde ödevini bitirdi.","Uyqusi kelgan boʻlsa-da, uy vazifasini tugatdi."],["Ot bilan: Fırtınaya rağmen uçak zamanında indi.","Boʻronga qaramay, samolyot oʻz vaqtida qoʻndi."],["Gap boshida: Buna rağmen / Yine de …","Shunga qaramay / Baribir …"]]}},{"sub":"«…sa ham»: -sA bile / -sA da"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Elektrik kesilse bile toplantı online devam edecek.","Elektr oʻchsa ham, yigʻilish onlayn davom etadi."],["Ne kadar tekrar etsem de bu kelimeyi unutuyorum.","Qancha takrorlasam ham, bu soʻzni unutaman."],["Kim olursa olsun sırasını beklemeli.","Kim boʻlishidan qatʼi nazar, navbatini kutishi kerak."]]}},{"sub":"Qarama-qarshilik: oysa, hâlbuki, -(y)ken, ama / ancak / fakat"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Herkes kameralarını açtı, oysa Jasur hâlâ bağlanamadı.","Hamma kamerasini yoqdi, holbuki Jasur hali ham ulana olmadi."],["Online ders sıkıcı olur sanıyordum; hâlbuki çok eğlenceliymiş.","Onlayn dars zerikarli boʻladi deb oʻylardim; holbuki juda qiziqarli ekan."],["Dilnoza sabahları çalışırken Kerem geceleri çalışıyor.","Dilnoza ertalablari oʻqisa, Kerem kechalari oʻqiydi."],["Kayıtlı derslere istediğin zaman bakabilirken canlı derste soru sorabilirsin.","Yozib olingan darslarni xohlagan vaqtda koʻra olasan, jonli darsda esa savol bera olasan."]]}},{"p":"ama / fakat / ancak — «lekin» (ancak rasmiyroq) · oysa / hâlbuki — kutilganga zid fakt · -(y)ken — ikki holatni yonma-yon qoʻyib taqqoslash."},{"sub":"-mAktAnsA: «…gandan koʻra»"},{"p":"Ekran başında oturmaktansa parkta ders çalışalım. — Ekran oldida oʻtirgandan koʻra, bogʻda dars qilaylik. Yanlış yapmaktan korkmaktansa soru sormayı tercih ederim. — Xato qilishdan qoʻrqqandan koʻra, savol berishni afzal koʻraman."},{"sub":"Qoʻshish va kuchaytirish"},{"table":{"h":["Ibora","Misol"],"r":[["sadece … değil, aynı zamanda …","Yüz yüze eğitim sadece bilgi değil, aynı zamanda arkadaşlık da sunar."],["-DIğI gibi … de","Zamandan tasarruf ettirdiği gibi yol masrafını da azaltır."],["üstelik / dahası","Üstelik dersleri tekrar izleyebilirsiniz. (Ustiga-ustak…)"],["aksine","Online eğitim tembellik getirmez, aksine disiplin ister. (Aksincha…)"]]}},{"note":"Bahs matnining tuzilishi: 1) Kirish — mavzu va tezis (Bu yazıda … savunacağım.) 2) Dalillar va misollar (İlk olarak…, Ayrıca…, Örneğin…) 3) Qarshi fikr (Bazıları … düşünüyor.) va unga javob (Ancak…) 4) Xulosa (Sonuç olarak…)."}]},{"kind":"dialog","title":"Dialog: Hangi kursa yazılsam?","blocks":[{"dlg":[["Jasur","Dilnoza, C1 kursuna yazılacak mısın? Online grup daha ucuz."],["Dilnoza","Ucuz olmasına rağmen online kursu pek istemiyorum. Geçen sefer derslere düzenli girdiğim hâlde konuşmam gelişmedi."],["Jasur","Oysa ben online derste daha rahat konuşuyorum. Sınıfta herkes bana bakarken heyecanlanıyorum."],["Dilnoza","Anlıyorum, ama ekran karşısında oturmaktansa sınıfta olmayı tercih ederim. İnternet kesilse bile ders devam ediyor!"],["Jasur","Doğru. Yine de yol bir saat sürüyor; yorgun olsan da gidecek misin?"],["Dilnoza","Gideceğim. Sınıf arkadaşlarıyla çay içmek sadece eğlence değil, aynı zamanda pratik."],["Jasur","Beni ikna ettin sayılır. Pahalı olsa bile bir dönem deneyeceğim."],["Dilnoza","Pişman olmayacaksın!"]]},{"gloss":[["yazılmak","yozilmoq"],["pek","uncha"],["geçen sefer","oʻtgan safar"],["gelişmek","rivojlanmoq"],["tercih etmek","afzal koʻrmoq"],["eğlence","koʻngilochar ish"],["ikna etmek","koʻndirmoq"],["sayılır","desa boʻladi"],["dönem","semestr"],["pişman olmak","pushaymon boʻlmoq"]]}]}],"reading":{"title":"Dijital kitap mı, basılı kitap mı?","text":"E-kitap okuyucular yaygınlaştığında birçok kişi basılı kitabın sonunun geldiğini düşünmüştü. Oysa aradan yıllar geçmesine rağmen kitapçılar hâlâ dolu. Dijital kitabın üstünlükleri açık: yüzlerce kitabı tek bir cihazda taşırsınız, yazı boyutunu ayarlarsınız, gece ışık yakmadan okursunuz. Üstelik çoğu zaman daha ucuzdur. Buna rağmen araştırmalar, insanların kâğıttan okuduklarını daha iyi hatırladığını gösteriyor. Ekranda okurken dikkat kolayca dağılırken, basılı kitap okuru metnin içinde tutuyor. Birçok okur, pahalı olsa bile sevdiği kitabı rafında görmek istiyor. Bir kitabı ödünç vermek ya da hediye etmek de dijitalde aynı tadı vermiyor. Sonuç olarak iki biçim birbirinin rakibi olmaktansa birbirini tamamlıyor: yolculukta ekran, evde kâğıt. Önemli olan sadece nasıl okuduğumuz değil, aynı zamanda okumaya devam etmemizdir. Sesli kitaplar ise tartışmaya üçüncü bir boyut ekledi. Yolda, spor yaparken ya da ev işleriyle uğraşırken kitap dinlemek mümkün olsa da, bazı okurlar bunu gerçek okuma saymıyor. Oysa araştırmalar, dinleyerek anlamanın okuyarak anlamaktan pek de farklı olmadığını gösteriyor. Yayıncılar da bu değişime ayak uyduruyor: birçok kitap artık basılı, dijital ve sesli olmak üzere üç biçimde birden yayımlanıyor. Okur hangisini seçerse seçsin, önemli olan metinle kurduğu bağdır.","gloss":[["yaygınlaşmak","keng tarqalmoq"],["basılı","bosma"],["üstünlük","afzallik"],["cihaz","qurilma"],["boyut","oʻlcham"],["ayarlamak","sozlamoq"],["araştırma","tadqiqot"],["metin","matn"],["raf","tokcha"],["ödünç vermek","vaqtincha berib turmoq"],["biçim","shakl"],["rakip","raqib"],["tamamlamak","toʻldirmoq"],["sesli kitap","audiokitob"],["uğraşmak","shugʻullanmoq"],["ayak uydurmak","moslashmoq"],["yayımlamak","nashr etmoq"],["bağ","bogʻliqlik"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["E-kitaplar yaygınlaşınca insanlar ne düşünmüştü?","Dijital kitabın üstünlüklerinden biri nedir?","Araştırmalar neyi gösteriyor?","Okurlar sevdikleri kitabı nerede görmek istiyor?","Yazara göre iki biçim arasındaki ilişki nasıl?","Yayıncılar değişime nasıl ayak uyduruyor?"],"ans":{"1":"Basılı kitabın sonunun geldiğini düşünmüştü.","2":"Yüzlerce kitabı tek bir cihazda taşırsınız.","3":"İnsanların kâğıttan okuduklarını daha iyi hatırladığını gösteriyor.","4":"Rafında görmek istiyor.","5":"Birbirini tamamlıyor.","6":"Birçok kitabı basılı, dijital ve sesli olmak üzere üç biçimde yayımlıyorlar."}},"exercises":[{"n":1,"title":"-mAsInA rağmen yoki -DIğI hâlde bilan birlashtiring.","items":[["a","Yol uzundu. Kursa gittik. → Yol uzun ___ rağmen kursa gittik."],["b","Çok çalıştı. Sınavı geçemedi. → Çok ___ hâlde sınavı geçemedi."],["c","Pahalıydı. Kitabı aldım. → Pahalı ___ rağmen kitabı aldım."]],"ans":{"a":"olmasına","b":"çalıştığı","c":"olmasına"}},{"n":2,"title":"-sA bile / -sA da bilan toʻldiring.","items":[["a","İnternet ___ bile ders devam eder. (kesilmek)"],["b","Ne kadar ___ da bitiremiyorum. (okumak, ben)"],["c","Pahalı ___ bile deneyeceğim. (olmak)"]],"ans":{"a":"kesilse","b":"okusam","c":"olsa"}},{"n":3,"title":"Mos bogʻlovchini yozing: oysa · -ken · -mAktAnsA.","items":[["a","Kitapçılar kapanacak denmişti, ___ hâlâ dolu."],["b","Ekranda ___ dikkatim dağılıyor. (okumak)"],["c","Evde ___ sınıfa gitmeyi tercih ederim. (oturmak)"]],"ans":{"a":"oysa","b":"okurken","c":"oturmaktansa"}},{"n":4,"title":"sadece … değil, aynı zamanda … bilan qayta yozing.","items":[["a","Dijital kitap ucuz. Pratik de. →"],["b","Sınıfta dil öğreniyoruz. Arkadaş da ediniyoruz. →"]],"ans":{"a":"Dijital kitap sadece ucuz değil, aynı zamanda pratiktir.","b":"Sınıfta sadece dil öğrenmiyoruz, aynı zamanda arkadaş da ediniyoruz."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Qimmat boʻlishiga qaramay kitobni oldim."],["b","Internet uzilsa ham dars davom etadi."],["c","Koʻp oʻqigan boʻlsam-da, eslay olmayapman."],["d","Uyda oʻtirgandan koʻra sayr qilishni afzal koʻraman."]],"ans":{"a":"Pahalı olmasına rağmen kitabı aldım.","b":"İnternet kesilse bile ders devam eder.","c":"Çok okuduğum hâlde hatırlayamıyorum.","d":"Evde oturmaktansa yürüyüş yapmayı tercih ederim."}},{"n":6,"title":"Yozish. «Online eğitim yüz yüze eğitimin yerini alabilir mi?» mavzusida 200 soʻzlik bahs matni yozing.","items":[],"ans":{}},{"n":7,"title":"Qavsdagi feʼlni toʻgʻri shaklga qoʻying (-mAsInA rağmen · -DIğI hâlde · -sA bile).","items":[["a","Çok (çalışmak) ___ rağmen yorulmadı."],["b","Yağmur (yağmak) ___ hâlde dışarı çıktık."],["c","Ne kadar pahalı (olmak) ___ bile alacağım."],["d","Hasta (olmak) ___ rağmen işe geldi."]],"ans":{"a":"çalışmasına","b":"yağdığı","c":"olsa","d":"olmasına"}},{"n":8,"title":"Turkchaga tarjima qiling (2).","items":[["a","U charchagan boʻlsa-da, ishini tugatdi."],["b","Qor yogʻsa ham boraman."],["c","Oson deb oʻylardim, holbuki qiyin ekan."],["d","U nafaqat oʻqiydi, balki yozadi ham."]],"ans":{"a":"Yorgun olduğu hâlde işini bitirdi.","b":"Kar yağsa bile gideceğim.","c":"Kolay sanıyordum, oysa zormuş.","d":"O sadece okumuyor, aynı zamanda yazıyor."}}]},{"id":"b2-5","level":"B2","n":5,"title":"Gereğini Arz Ederim","sub":"Rasmiy yozishma: dilekçe · rapor · rasmiy e-pochta · rasmiy uslub qoliplari","goals":["turkcha dilekçe (ariza), rapor (hisobot) va rasmiy e-pochta tuzilishi","rasmiy uslubning grammatik belgilari (-mAktAdIr, -mIştIr, majhul nisbat)","tayyor qoliplar: Gereğini arz ederim, Bilgilerinize sunarım, söz konusu, adı geçen","rahbarga va hamkasbga yozish farqi"],"vocab":[{"title":"Lugʻat","words":[["dilekçe","ariza"],["rapor","hisobot"],["talep etmek","talab qilmoq, soʻramoq"],["arz etmek","taqdim etmoq (yuqoriga)"],["sunmak","taqdim etmoq"],["söz konusu","mazkur, gap ketayotgan"],["adı geçen","yuqorida nomi zikr etilgan"],["tespit etmek","aniqlamoq, qayd etmoq"],["belirlemek","belgilamoq"],["ek","ilova"],["konu","mavzu"],["tarih","sana"],["imza","imzo"],["yetkili","masʼul shaxs"],["müdürlük","boshqarma"],["rektörlük","rektorat"],["insan kaynakları","kadrlar boʻlimi"],["izin","taʼtil, ruxsat"],["onaylamak","tasdiqlamoq"],["gereği","kerakli chorasi"]]},{"title":"Mavzuli lugʻat — rasmiy qoliplar","words":[["Gereğini arz ederim.","Kerakli chorani koʻrishingizni soʻrayman. (yuqoriga)"],["Gereğini rica ederim.","Kerakli chorani soʻrayman. (teng/quyiga)"],["Bilgilerinize sunarım.","Maʼlumotingiz uchun taqdim etaman."],["Saygılarımla,","Hurmat bilan,"],["Sayın …,","Hurmatli …,"],["… hakkında","… haqida"],["… -DAn itibaren","… dan boshlab"],["meydana gelmek","yuz bermoq"],["… amacıyla","… maqsadida"],["tutanak","dalolatnoma"]]}],"sections":[{"kind":"grammar","title":"Rasmiy uslub qoidalari","blocks":[{"sub":"Rasmiy uslubning grammatik belgilari"},{"table":{"h":["Belgi","Soʻzlashuvda","Rasmiy matnda"],"r":[["-mAktAdIr","Başvurular devam ediyor.","Başvurular devam etmektedir."],["-mIştIr","Sınav yapıldı.","Sınav yapılmıştır."],["-(y)AcAktIr","Sonuçlar cuma açıklanacak.","Sonuçlar cuma günü açıklanacaktır."],["majhul nisbat","Müdür başvuruyu onayladı.","Başvuru onaylanmıştır."],["-mAsI rica olunur","Lütfen yerinize oturun.","Yerlerinize oturmanız rica olunur."],["-DIğI tespit edilmiştir","Kapı bozukmuş.","Kapının arızalı olduğu tespit edilmiştir."]]}},{"sub":"Murojaat va yakunlash qoliplari"},{"table":{"h":["Kimga","Murojaat","Yakun"],"r":[["rahbariyatga, yuqori idoraga","… MÜDÜRLÜĞÜNE / … REKTÖRLÜĞÜNE","Gereğini arz ederim. · Bilgilerinize arz ederim."],["teng yoki quyi idoraga","… MÜDÜRLÜĞÜNE","Gereğini rica ederim. · Bilgilerinizi rica ederim."],["rasmiy elektron xat","Sayın Murat Bey, / Sayın Yetkili,","Saygılarımla, · Bilgilerinize sunarım."]]}},{"p":"Arizada (dilekçe) adresat katta harflar bilan va joʻnalish kelishigida yoziladi: ÖĞRENCİ İŞLERİ MÜDÜRLÜĞÜNE · EGE DİL MERKEZİ MÜDÜRLÜĞÜNE."},{"sub":"Ariza (dilekçe) tuzilishi"},{"p":"1) Adresat — yuqorida, oʻrtada, katta harflar bilan. 2) Matn: kim yozyapti → sabab → aniq soʻrov (… verilmesini arz ederim). 3) Yakun: Gereğini arz ederim. 4) Sana va imzo (oʻngda), ism-familiya, lavozim. 5) Manzil va aloqa (chapda), ilovalar (Ek: …)."},{"sub":"Hisobot (rapor) tuzilishi"},{"p":"Konu (mavzu) → Olay / Durum (qachon, qayerda, nima boʻldi) → Tespitler (aniqlangan faktlar) → Yapılan işlemler (koʻrilgan choralar) → Sonuç ve öneriler (xulosa va takliflar) → imzo."},{"note":"Rasmiy matnda ishlatmang: soʻzlashuv soʻzlari (falan, şey, hani), qisqartirilgan shakllar (gelicem), his-hayajon, «ben» ni koʻp takrorlash. Gaplar toʻliq, aniq va betaraf boʻlsin. Sana va soatni aniq yozing: 12.04.2027, saat 10.30."}]},{"kind":"other","title":"Namunaviy hujjatlar","blocks":[{"sub":"1. Dilekçe"},{"p":"EGE DİL MERKEZİ MÜDÜRLÜĞÜNE"},{"p":"Merkezinizin B2 Türkçe kursuna 2026 yılı Eylül döneminden itibaren kayıtlı kursiyerim. Burs başvurumda kullanılmak üzere kursa devam ettiğimi ve bugüne kadar aldığım notları gösteren bir belgeye ihtiyaç duymaktayım."},{"p":"Söz konusu belgenin Türkçe ve İngilizce olarak düzenlenmesini ve tarafıma teslim edilmesini arz ederim."},{"p":"05.11.2026 (İmza) Dilnoza RAHİMOVA, Kursiyer No: 2417 · Ek: Kimlik fotokopisi (1 sayfa)"},{"sub":"2. Rapor"},{"p":"Konu: Okuma salonundaki su sızıntısı hakkında."},{"p":"Olay: 03.11.2026 tarihinde saat 08.15'te kütüphanenin okuma salonunda tavandan su damladığı tespit edilmiştir."},{"p":"Tespitler: Yapılan incelemede üst kattaki ısıtma borusunun çatladığı, iki raftaki kırk kadar kitabın ıslandığı belirlenmiştir."},{"p":"Yapılan işlemler: Vana aynı gün saat 08.40'ta kapatılmış, ıslanan kitaplar kurutulmak üzere ayrı bir odaya alınmıştır. Salon 04.11.2026 tarihinden itibaren yeniden hizmet vermektedir."},{"p":"Sonuç ve öneriler: Olayda yaralanan olmamıştır. Benzer sızıntıların önlenmesi amacıyla ısıtma tesisatının kış öncesinde kontrol ettirilmesi önerilmektedir. Bilgilerinize arz ederim."},{"p":"04.11.2026 (İmza) Defne YILMAZ, Kütüphane Sorumlusu"},{"gloss":[["kursiyer","kurs tinglovchisi"],["kayıtlı","roʻyxatda turgan"],["burs başvurusu","stipendiya uchun ariza"],["ihtiyaç duymak","ehtiyoj sezmoq"],["düzenlemek","rasmiylashtirmoq"],["tarafıma","menga (rasmiy)"],["sızıntı","sizib chiqish"],["inceleme","tekshiruv"],["çatlamak","yorilmoq"],["hizmet vermek","xizmat koʻrsatmoq"]]}]}],"reading":{"title":"Resmî e-posta","text":"Konu: Grup ziyareti hakkında bilgi talebi. Sayın Yetkili, Ege Dil Merkezi'nde Türkçe öğrenen yirmi kişilik bir öğrenci grubunun temsilcisiyim. 21 Kasım Cumartesi günü müzenizi ziyaret etmeyi planlamaktayız. Grup indiriminden yararlanıp yararlanamayacağımızı ve Türkçe rehberli tur için önceden randevu alınmasının gerekip gerekmediğini öğrenmek istiyorum. Ayrıca müzede fotoğraf çekimine izin verilip verilmediği konusunda bilgi verirseniz sevinirim. Ziyaret saatimizi vereceğiniz cevaba göre belirleyeceğiz. İlginiz için şimdiden teşekkür eder, iyi çalışmalar dilerim. Saygılarımla, Jasur Tursunov Cevap: Sayın Jasur Tursunov, Müzemize gösterdiğiniz ilgi için teşekkür ederiz. Yirmi kişi ve üzeri gruplara yüzde otuz indirim uygulanmaktadır. Türkçe rehberli turlar için en az üç gün önceden randevu alınması gerekmektedir; randevu talebinizi bu e-postayı yanıtlayarak iletebilirsiniz. Sergi salonlarında flaş kullanılmaksızın fotoğraf çekilmesine izin verilmektedir. Ziyaret gününde grup listesinin gişeye teslim edilmesini rica ederiz. Bilgilerinize sunar, iyi günler dileriz. Müze Müdürlüğü","gloss":[["talep","soʻrov"],["yetkili","masʼul shaxs"],["temsilci","vakil"],["yararlanmak","foydalanmoq"],["önceden","oldindan"],["çekim","suratga olish"],["belirlemek","belgilamoq"],["ilginiz için","eʼtiboringiz uchun"],["şimdiden","hozirdanoq"],["ilgi göstermek","qiziqish bildirmoq"],["yanıtlamak","javob bermoq"],["iletmek","yetkazmoq"],["sergi salonu","koʻrgazma zali"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["E-posta kime yazılmış?","Grup kaç kişilik?","Ziyaret hangi gün planlanıyor?","Jasur rehberli tur hakkında ne öğrenmek istiyor?","E-posta hangi sözle bitiyor?","Gruplara ne kadar indirim uygulanmaktadır?"],"ans":{"1":"Müze yetkilisine yazılmış.","2":"Yirmi kişilik.","3":"21 Kasım Cumartesi günü.","4":"Önceden randevu alınmasının gerekip gerekmediğini öğrenmek istiyor.","5":"\"Saygılarımla\" sözüyle bitiyor.","6":"Yirmi kişi ve üzeri gruplara yüzde otuz indirim uygulanmaktadır."}},"exercises":[{"n":1,"title":"Ogʻzaki gapni rasmiy uslubga oʻtkazing.","items":[["a","Karar verildi. →"],["b","İnceleme sürüyor. →"],["c","Lütfen bekleyin. →"],["d","Müdür belgeyi imzaladı. →"]],"ans":{"a":"Karar verilmiştir.","b":"İnceleme sürmektedir.","c":"Beklemeniz rica olunur.","d":"Belge imzalanmıştır."}},{"n":2,"title":"Mos yakunni yozing: Gereğini arz ederim / Gereğini rica ederim / Saygılarımla.","items":[["a","Markaz direktoriga yozilgan ariza →"],["b","Teng darajadagi boshqa idoraga rasmiy xat →"],["c","Muzeyga yozilgan rasmiy e-pochta →"]],"ans":{"a":"Gereğini arz ederim.","b":"Gereğini rica ederim.","c":"Saygılarımla,"}},{"n":3,"title":"Boʻsh joylarni toʻldiring: söz konusu · tespit edilmiştir · itibaren · amacıyla.","items":[["a","Borunun çatladığı ___ ."],["b","Salon 04.11.2026 tarihinden ___ hizmet vermektedir."],["c","___ belgenin düzenlenmesini arz ederim."],["d","Sızıntıların önlenmesi ___ tesisat kontrol ettirilecektir."]],"ans":{"a":"tespit edilmiştir","b":"itibaren","c":"Söz konusu","d":"amacıyla"}},{"n":4,"title":"Dilekçe adresatini toʻgʻri yozing.","items":[["a","til markazi direktorligiga →"],["b","kutubxona mudirligiga →"]],"ans":{"a":"DİL MERKEZİ MÜDÜRLÜĞÜNE","b":"KÜTÜPHANE MÜDÜRLÜĞÜNE"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Qaror qabul qilindi. (rasmiy)"],["b","Hujjat ertaga topshiriladi. (rasmiy)"],["c","Hujjat rasmiylashtirilishini soʻrayman."],["d","Eʼtiboringiz uchun rahmat."]],"ans":{"a":"Karar verilmiştir.","b":"Belge yarın teslim edilecektir.","c":"Belgenin düzenlenmesini arz ederim.","d":"İlginiz için teşekkür ederim."}},{"n":6,"title":"Yozish. Ish joyingiz yoki oʻqish joyingiz rahbariyatiga bir haftalik taʼtil soʻrab dilekçe yozing (barcha qismlari bilan).","items":[],"ans":{}},{"n":7,"title":"Kundalik iborani rasmiy e-pochta uslubiga oʻtkazing.","items":[["a","Merhaba! (xat boshi)"],["b","Bana bilgi verin."],["c","Çok sağ olun."],["d","Görüşürüz. (xat oxiri)"]],"ans":{"a":"Sayın Yetkili,","b":"Bilgi verirseniz sevinirim.","c":"İlginiz için teşekkür ederim.","d":"Saygılarımla,"},"sample":true},{"n":8,"title":"-mAktAdIr / -mIştIr bilan rasmiylashtiring.","items":[["a","Randevu gerekiyor. →"],["b","İndirim uygulanıyor. →"],["c","Başvurunuz kabul edildi. →"],["d","Belgeler gönderildi. →"]],"ans":{"a":"Randevu gerekmektedir.","b":"İndirim uygulanmaktadır.","c":"Başvurunuz kabul edilmiştir.","d":"Belgeler gönderilmiştir."}}]},{"id":"b2-6","level":"B2","n":6,"title":"Damlaya Damlaya Göl Olur","sub":"Iboralar (deyimler) · maqollar (atasözleri) · oʻzbekcha muqobillari · nutqni boyitish","goals":["eng koʻp ishlatiladigan 30 ta turkcha ibora va 15 ta maqol","ularning oʻzbekcha muqobillari","iboralarni gapda toʻgʻri tuslash (egalik, zamon)","matnlarda koʻchma maʼnoni tushunish","yozma va ogʻzaki nutqni tabiiyroq qilish"],"vocab":[{"title":"Lugʻat","words":[["deyim","ibora"],["atasözü","maqol"],["mecaz","koʻchma maʼno"],["kulak vermek","quloq solmoq"],["göz atmak","koʻz yugurtirmoq"],["başı göğe ermek","boshi osmonga yetmoq"],["dili tutulmak","tili tutilib qolmoq"],["yüz çevirmek","yuz oʻgirmoq"],["el ele vermek","qoʻl-qoʻlga berib ishlamoq"],["pes etmek","taslim boʻlmoq"],["kafa yormak","bosh qotirmoq"],["söz vermek","vaʼda bermoq"],["göz yummak","koʻz yummoq (kechirmoq)"],["kulak asmamak","quloq solmaslik"],["canı sıkılmak","zerikmoq, xafa boʻlmoq"],["dört gözle beklemek","intizorlik bilan kutmoq"],["ağzı sıkı","sir saqlay oladigan"],["burnu havada","kibrli"],["işi başından aşkın","ishi boshidan oshgan"],["eli kulağında","yaqinlashib qoldi"]]}],"sections":[{"kind":"grammar","title":"Iboralar qanday ishlaydi?","blocks":[{"p":"Ibora (deyim) soʻzma-soʻz emas, koʻchma maʼnoda tushuniladi. Turkcha iboralarning koʻpi oʻzbekchadagiga juda yaqin — bu sizning katta ustunligingiz."},{"table":{"h":["Turkcha","Soʻzma-soʻz","Oʻzbekcha muqobili"],"r":[["kulak vermek","quloq bermoq","quloq solmoq"],["göz atmak","koʻz tashlamoq","koʻz yugurtirmoq"],["başı göğe ermek","boshi osmonga yetmoq","boshi osmonga yetmoq"],["dili tutulmak","tili tutilmoq","tili tutilib qolmoq"],["yüz çevirmek","yuz burmoq","yuz oʻgirmoq"]]}},{"p":"Grammatikasi: iboradagi tana aʼzosi egalik qoʻshimchasini oladi, feʼl esa odatdagidek tuslanadi: Sahneye çıkınca dilim tutuldu. — Sahnaga chiqqanimda tilim tutilib qoldi. Bursu kazandığımızı duyunca başımız göğe erdi. — Grantni yutganimizni eshitib, boshimiz osmonga yetdi."}]},{"kind":"grammar","title":"Mavzular boʻyicha 30 ta ibora","blocks":[{"sub":"His-tuygʻu"},{"table":{"h":["Ibora","Maʼnosi","Misol"],"r":[["ağzı kulaklarına varmak","juda xursand boʻlmoq (ogʻzi qulogʻida)","Mektubu okuyunca ağzı kulaklarına vardı."],["etekleri zil çalmak","quvonchdan oʻzini qoʻyarga joy topolmaslik","Konser biletlerini alınca etekleri zil çalıyordu."],["içi rahat etmek","koʻngli tinchimoq","Pamuk eve dönünce içim rahat etti."],["canı sıkılmak","zerikmoq, koʻngli gʻash boʻlmoq","Pazar akşamları canım sıkılır."],["yüreği ağzına gelmek","yuragi ogʻziga kelmoq (qattiq qoʻrqmoq)","Bardak yere düşünce yüreğim ağzıma geldi."],["dört gözle beklemek","intizorlik bilan kutmoq","Bayram tatilini dört gözle bekliyoruz."]]}},{"sub":"Ish va harakat"},{"table":{"h":["Ibora","Maʼnosi","Misol"],"r":[["el ele vermek","qoʻl-qoʻlga berib ishlamoq","Komşular el ele verip parkı temizledi."],["elini çabuk tutmak","tezroq harakat qilmoq","Elini çabuk tut, vapur kalkmak üzere!"],["canla başla çalışmak","jon-dildan ishlamoq","Ekip proje için canla başla çalıştı."],["kafa yormak","bosh qotirmoq","Bu bulmacaya bütün akşam kafa yorduk."],["pes etmek","taslim boʻlmoq, qoʻl siltamoq","Üç kez düştü ama pes etmedi."],["ipe un sermek","bahona qidirmoq","Spora gitmemek için hep ipe un seriyor."],["kılı kırk yarmak","qilni qirq yormoq (oʻta sinchkov boʻlmoq)","Editörümüz her cümlede kılı kırk yarar."],["gözünü budaktan sakınmamak","xavfdan choʻchimaslik","Gözünü budaktan sakınmayan bir dağcıydı."]]}},{"sub":"Muloqot va xulq"},{"table":{"h":["Ibora","Maʼnosi","Misol"],"r":[["söz vermek / sözünde durmak","vaʼda bermoq / soʻzida turmoq","Pazar günü geleceğine söz verdin, sözünde dur!"],["ağzı sıkı","ogʻzi mahkam (sir saqlay oladigan)","Sırrını Zeynep'e söyleyebilirsin, ağzı sıkıdır."],["burnu havada","burni koʻtarilgan, kibrli","Ödül aldı ama hiç burnu havada değil."],["göz yummak","koʻz yummoq (kechirib yubormoq)","Hoca bu küçük yanlışa göz yumdu."],["kulak asmamak","quloq solmaslik","Uyarılara kulak asmadı ve yağmurda yola çıktı."],["ağız birliği etmek","kelishib olgandek bir xil gapirmoq","Çocuklar ağız birliği etmiş gibi aynı bahaneyi söyledi."],["gözden düşmek","obroʻsini yoʻqotmoq","Sözünü tutmayınca gözden düştü."]]}},{"sub":"Soʻzlashuvda tez-tez uchraydi"},{"table":{"h":["Ibora","Maʼnosi"],"r":[["gözü tutmak","koʻzi tushmoq, yoqib qolmoq"],["aklına gelmek / aklından çıkmak","esiga tushmoq / esidan chiqmoq"],["hapı yutmak","ishi chatoq boʻlmoq (soʻzlashuvda)"],["taş çatlasa","nari borsa"],["işi başından aşkın","ishi boshidan oshgan"],["ayağına çabuk","chaqqon, oyogʻi yengil"],["eli kulağında","yaqinlashib qoldi, ostonada"],["baş başa vermek","bosh qoʻshib maslahatlashmoq"],["göz göre göre","koʻz koʻrib turib"]]}}]},{"kind":"grammar","title":"15 ta maqol (atasözleri)","blocks":[{"table":{"h":["Turkcha","Oʻzbekcha muqobili yoki maʼnosi"],"r":[["Damlaya damlaya göl olur.","Tomchi-tomchi koʻl boʻlur."],["Birlikten kuvvet doğar.","Birlikdan kuch tugʻiladi."],["Bir elin nesi var, iki elin sesi var.","Bir qoʻldan sado chiqmas."],["Acele işe şeytan karışır.","Shoshgan qiz erga yolchimas."],["Ayağını yorganına göre uzat.","Koʻrpangga qarab oyoq uzat."],["Dost kara günde belli olur.","Doʻst boshga ish tushganda bilinadi."],["Ak akçe kara gün içindir.","Oq tanga qora kun uchun."],["Sabreden derviş muradına ermiş.","Sabr tagi — sariq oltin."],["Ağaç yaşken eğilir.","Nihol yoshligida egiladi (tarbiya yoshlikdan)."],["Bugünün işini yarına bırakma.","Bugungi ishni ertaga qoldirma."],["Söz gümüşse sükût altındır.","Soʻz kumush boʻlsa, sukut — oltin."],["Az olsun, öz olsun.","Oz boʻlsin, soz boʻlsin."],["Görünen köy kılavuz istemez.","Koʻrinib turgan qishloqqa yoʻlboshchi kerak emas."],["Bin bilsen de bir bilene danış.","Ming bilsang ham, bir bilganga maslahat sol."],["Her işte bir hayır vardır.","Har ishda bir hikmat bor."]]}},{"note":"Qanday ishlatish kerak: inshoda bir-ikkita maqol yetarli — odatda kirish yoki xulosada: Atalarımızın dediği gibi, «Damlaya damlaya göl olur»; her gün on kelime öğrenmek bile büyük fark yaratır. Suhbatda oʻrniga tushgan bitta ibora nutqingizni darhol tabiiyroq qiladi."}]},{"kind":"dialog","title":"Dialog: Deyimlerle konuşmak","blocks":[{"dlg":[["Kerem","Dilnoza, yüzün gülüyor, ağzın kulaklarına varmış! Hayırdır?"],["Dilnoza","Burs başvurum kabul edildi! Sonucu dört gözle bekliyordum."],["Kerem","Harika! Aylardır canla başla çalışıyordun, hakkındır."],["Dilnoza","Açıkçası mülakat günü yüreğim ağzıma geldi. Bir soruda takıldım, az kalsın pes ediyordum."],["Kerem","Ama etmedin. Ben olsam ipe un sererdim, \"hazır değilim\" derdim."],["Dilnoza","Yok canım, sen kılı kırk yaran birisin; benden iyi hazırlanırdın."],["Kerem","Peki kimseye söylemedin mi? Bugüne kadar hiç duymadım."],["Dilnoza","Sadece Defne biliyordu. Onun ağzı sıkıdır, kimseye söylemez."],["Kerem","Şimdi işin başından aşkın olacak: belgeler, vize, ev…"],["Dilnoza","Öyle. Bu akşam ailemle baş başa verip bir plan yapacağız."],["Kerem","Yardıma ihtiyacın olursa söyle; el ele verirsek her şey çabuk biter."],["Dilnoza","Sağ ol. Dost kara günde belli olur derler ama sen iyi günde de yanımdasın!"],["Kerem","O zaman bunu kutlayalım, kahveler benden."]]},{"gloss":[["hayırdır","tinchlikmi, nima gap"],["burs","stipendiya"],["mülakat","suhbat, intervyu"],["takılmak","tutilib qolmoq"],["hakkındır","bunga loyiqsan"],["kutlamak","nishonlamoq"]]}]}],"reading":{"title":"Küçük fırının büyük günü","text":"Emre, babası Hasan Usta'nın fırınını devraldığında işler hiç iyi gitmiyordu. Mahalleye büyük bir market açılmış, müşterilerin çoğu oraya gitmeye başlamıştı. Emre günlerce kafa yordu ama pes etmedi. Ailesiyle baş başa verip bir plan yaptı: fırında sadece ekmek değil, eski usul börekler de satacaklardı. Bütün aile el ele verdi; annesi tarifleri hazırladı, kız kardeşi dükkânı boyadı. Herkes canla başla çalıştı. Açılış günü Emre'nin yüreği ağzına geliyordu: ya kimse gelmezse? Oysa sabah yedide kapının önünde uzun bir kuyruk vardı. Akşam kasayı sayarken ağzı kulaklarına varıyordu. Babası omzuna dokundu: \"Damlaya damlaya göl olur oğlum. Sabreden derviş muradına ermiş.\" Bugün fırının işi başından aşkın; Emre ikinci dükkânı açmayı dört gözle bekliyor.","gloss":[["devralmak","qabul qilib olmoq"],["günlerce","kunlab"],["eski usul","eskicha"],["tarif","retsept"],["açılış","ochilish"],["kuyruk","navbat"],["kasa","kassa"],["saymak","sanamoq"],["omuz","yelka"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Fırının işleri neden iyi gitmiyordu?","Emre ailesiyle ne yaptı?","Açılış günü Emre neden korkuyordu?","Babası hangi atasözlerini söyledi?","Emre şimdi neyi dört gözle bekliyor?"],"ans":{"1":"Çünkü mahalleye büyük bir market açılmıştı.","2":"Baş başa verip bir plan yaptı.","3":"Kimsenin gelmeyeceğinden korkuyordu.","4":"\"Damlaya damlaya göl olur\" ve \"Sabreden derviş muradına ermiş.\"","5":"İkinci dükkânı açmayı bekliyor."}},"exercises":[{"n":1,"title":"Iboraning maʼnosini oʻzbekcha yozing.","items":[["a","kafa yormak"],["b","canla başla çalışmak"],["c","kulak asmamak"],["d","burnu havada"],["e","işi başından aşkın"]],"ans":{"a":"bosh qotirmoq","b":"jon-dildan ishlamoq","c":"quloq solmaslik","d":"kibrli","e":"ishi boshidan oshgan"}},{"n":2,"title":"Mos iborani toʻgʻri shaklda qoʻying: dört gözle beklemek · pes etmek · canı sıkılmak.","items":[["a","Bayram tatilini ___ . (biz)"],["b","Zor olsa da ___ ! (siz, buyruq inkor)"],["c","Evde tek başıma kalınca ___ . (ben)"]],"ans":{"a":"dört gözle bekliyoruz","b":"pes etmeyin","c":"canım sıkılıyor"}},{"n":3,"title":"Vaziyatga mos maqolni yozing.","items":[["a","Kichkina doʻkon yillar davomida asta-sekin katta boʻldi."],["b","Butun mahalla birgalashib maktabni taʼmirladi."],["c","Ishsiz qolganimda faqat bitta doʻstim yordam berdi."]],"ans":{"a":"Damlaya damlaya göl olur.","b":"Birlikten kuvvet doğar.","c":"Dost kara günde belli olur."}},{"n":4,"title":"Oʻzbekcha maqolni turkchaga oʻgiring.","items":[["a","Oz boʻlsin, soz boʻlsin."],["b","Oq tanga qora kun uchun."],["c","Ming bilsang ham, bir bilganga maslahat sol."]],"ans":{"a":"Az olsun, öz olsun.","b":"Ak akçe kara gün içindir.","c":"Bin bilsen de bir bilene danış."}},{"n":5,"title":"Yozish. Bitta maqolni tanlang va 150–180 soʻzli insho yozing: maqolning maʼnosi, hayotingizdan misol, xulosa.","items":[],"ans":{}}]},{"id":"b2-7","level":"B2","n":7,"title":"Haberlerde Bugün","sub":"Media tili · sarlavhalar · «aytdi» feʼllari · kapsamında / çerçevesinde · xalqaro hamkorlik","goals":["gazeta va televideniye yangiliklarini tushunish","sarlavha grammatikasi","xabar yetkazish feʼllari (açıkladı, vurguladı, kaydetti, belirtti, öne sürdü)","rasmiy birikmalar (kapsamında, çerçevesinde, doğrultusunda, -mAsI bekleniyor)","foiz va statistika","taʼlim, madaniyat va xalqaro hamkorlik"],"vocab":[{"title":"Lugʻat","words":[["haber","yangilik"],["manşet","bosh sarlavha"],["muhabir","muxbir"],["açıklama","bayonot"],["basın toplantısı","matbuot anjumani"],["bakan","vazir"],["heyet","delegatsiya"],["ziyaret","tashrif"],["anlaşma","shartnoma, kelishuv"],["imzalamak","imzolamoq"],["işbirliği","hamkorlik"],["değişim programı","almashinuv dasturi"],["artış","oʻsish"],["azalış","kamayish"],["oran","nisbat, ulush"],["yüzde","foiz"],["kaynak","manba"],["iddia","daʼvo"],["yalanlamak","rad etmoq"],["gündem","kun tartibi"]]}],"sections":[{"kind":"grammar","title":"Grammatika va media uslubi","blocks":[{"sub":"Yangilik sarlavhasi grammatikasi"},{"table":{"h":["Xususiyati","Misol","Maʼnosi"],"r":[["hozirgi yoki geniş zamon oʻtgan zamon oʻrniga","Kitap fuarı kapılarını açıyor / Bakan İzmir'e geliyor","Kitob yarmarkasi eshiklarini ochdi / Vazir Izmirga kelmoqda"],["feʼlsiz sarlavha","Bakan İzmir'de","Vazir Izmirda"],["-(y)AcAk — reja","Yeni metro hattı açılacak","Yangi metro liniyasi ochiladi"],["majhul nisbat","Burs sonuçları açıklandı","Grant natijalari eʼlon qilindi"],["iqtibos va ikki nuqta","Belediye Başkanı: \"Sahiller temiz kalacak\"","Shahar hokimi: «Sohillar toza boʻladi»"]]}},{"sub":"«Aytdi» feʼllarining maʼno farqlari"},{"table":{"h":["Feʼl","Nozik maʼnosi"],"r":[["söyledi / dedi","aytdi (betaraf)"],["açıkladı","rasman eʼlon qildi"],["belirtti / ifade etti","qayd etdi, bildirdi"],["vurguladı","taʼkidladi (muhimligini)"],["kaydetti","qayd etdi (rasmiy)"],["ekledi","qoʻshimcha qildi"],["hatırlattı","eslatib oʻtdi"],["öne sürdü / iddia etti","daʼvo qildi (hali tasdiqlanmagan)"],["yalanladı","rad etdi (xabarni)"],["bildirildi / açıklandı (majhul)","maʼlum qilindi"]]}},{"p":"Hammasi bir xil tuzilishda keladi: -DIğInI / -(y)AcAğInI + feʼl: Başkan, bisiklet yollarının iki katına çıkacağını vurguladı."},{"sub":"Rasmiy birikmalar"},{"table":{"h":["Birikma","Maʼnosi","Misol"],"r":[["… kapsamında","… doirasida","Proje kapsamında 60 okula kütüphane kuruldu."],["… çerçevesinde","… doirasida (kelishuv, tashrif)","Ziyaret çerçevesinde üç protokol imzalandı."],["… doğrultusunda","… ga muvofiq","Alınan karar doğrultusunda sahil yolu trafiğe kapatılacak."],["… ile ilgili / hakkında","… ga oid / haqida","Fuarla ilgili açıklama"],["… -mAsI bekleniyor","… kutilmoqda","Yeni köprünün yaz sonunda tamamlanması bekleniyor."],["… -DIğI öğrenildi","… maʼlum boʻldi","Takımın cumartesi günü döneceği öğrenildi."],["Konuya ilişkin","Masalaga oid","Konuya ilişkin açıklama yapan yetkili …"]]}},{"sub":"Raqamlar va statistika"},{"p":"yüzde 40 (40%) · yüzde 40'lık artış (40% oʻsish) · iki katına çıkmak (ikki barobar oshmoq) · yarı yarıya azalmak (yarmiga kamaymoq) · ortalama (oʻrtacha) · yaklaşık / civarında (taxminan) · …-DAn fazla / az (…dan koʻp / kam). Misol: Fuarı ziyaret edenlerin sayısı geçen yıla göre yüzde 20 artarak 85 bine ulaştı."},{"note":"Yangilik tinglash boʻyicha maslahat: birinchi gap odatda eng muhim maʼlumotni beradi — kim, nima, qayerda, qachon; qolgan gaplar tafsilot. Raqam, sana va ismlarni yozib boring. «öne sürdü / iddia etti» ni eshitsangiz — bu hali tasdiqlanmagan maʼlumot."}]},{"kind":"dialog","title":"Dialog: Haberi kim yazacak?","blocks":[{"dlg":[["Zeynep","Jasur, kitap fuarı haberini sen yazar mısın? Yarın sabaha yetişmesi gerekiyor."],["Jasur","Yazarım. Elimizde hangi bilgiler var?"],["Zeynep","Düzenleme kurulu fuara 320 yayınevinin katıldığını açıkladı. Başkan da etkinliğin önemini vurguladı."],["Jasur","Ziyaretçi sayısı belli mi?"],["Zeynep","Henüz değil; hafta sonuna kadar 200 bin kişinin gelmesi bekleniyor."],["Jasur","Bir yayıncı stant ücretlerinin çok yüksek olduğunu öne sürmüş. Bunu da yazalım mı?"],["Zeynep","Yazalım ama kurulun cevabını da ekleyelim: ücretlerin üç yıldır değişmediğini hatırlattılar."],["Jasur","Anlaşıldı, iki tarafın görüşüne de yer vereceğim. Başlık ne olsun?"],["Zeynep","Kısa ve tarafsız olsun: \"Kitap Günleri kapılarını açtı.\""],["Jasur","Onur konuğu ülke programı kapsamında gelen Özbek yazarlarla kısa bir röportaj da yapabilirim."],["Zeynep","Çok iyi olur. Yalnız doğrulamadığın hiçbir bilgiyi yazma."],["Jasur","Merak etme, her bilgiyi kaynağıyla birlikte vereceğim."]]},{"gloss":[["yetişmek","ulgurmoq"],["belli","maʼlum"],["yer vermek","oʻrin bermoq"],["tarafsız","xolis"],["röportaj","intervyu"],["doğrulamak","tekshirib tasdiqlamoq"]]}]}],"reading":{"title":"İzmir'de Uluslararası Kitap Günleri başladı","text":"İZMİR — Bu yıl on ikincisi düzenlenen Uluslararası Kitap Günleri dün Kültürpark'ta kapılarını açtı. Açılışta konuşan Belediye Başkanı, etkinliğin şehrin kültür hayatı için büyük önem taşıdığını vurguladı. Düzenleme kurulundan yapılan açıklamaya göre, fuara bu yıl 18 ülkeden 320 yayınevi katılıyor. Onur konuğu ülke programı kapsamında Özbekistan'dan gelen yazarlar okurlarıyla buluşacak. Kurul başkanı, geçen yıla göre katılımcı sayısında yüzde 25'lik bir artış olduğunu belirtti. Etkinlik çerçevesinde çocuklar için ücretsiz atölyeler de düzenlenecek. Bazı yayıncılar stant ücretlerinin yüksek olduğunu öne sürdü; kurul ise ücretlerin üç yıldır değişmediğini hatırlattı. Fuarın hafta sonuna kadar 200 bin kişi tarafından ziyaret edilmesi bekleniyor. Etkinlik pazar akşamı sona erecek.","gloss":[["uluslararası","xalqaro"],["etkinlik","tadbir"],["önem taşımak","ahamiyatga ega boʻlmoq"],["düzenleme kurulu","tashkiliy qoʻmita"],["açıklama","bayonot"],["yayınevi","nashriyot"],["onur konuğu","faxriy mehmon"],["katılımcı","ishtirokchi"],["artış","oʻsish"],["atölye","mahorat darsi"],["stant","stend"],["hatırlatmak","eslatmoq"],["sona ermek","yakunlanmoq"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Kitap Günleri bu yıl ilk kez düzenleniyor.","Fuara 18 ülkeden yayınevi katılıyor.","Onur konuğu ülke Özbekistan'dır.","Katılımcı sayısı geçen yıla göre azaldı.","Fuarı 200 bin kişinin ziyaret etmesi bekleniyor."],"ans":{"1":"Y","2":"D","3":"D","4":"Y","5":"D"}},"exercises":[{"n":1,"title":"Sarlavhani oddiy gapga aylantiring (-DI yoki koʻchirma gap).","items":[["a","Kitap Günleri başlıyor →"],["b","Başkan İzmir'de →"],["c","Yazar: \"Çok mutluyum\" →"]],"ans":{"a":"Kitap Günleri başladı.","b":"Başkan İzmir'e geldi.","c":"Yazar çok mutlu olduğunu söyledi."},"sample":true},{"n":2,"title":"Mos feʼlni yozing: vurguladı · öne sürdü · yalanladı.","items":[["a","Başkan, etkinliğin şehir için çok önemli olduğunu ___ ."],["b","Bir haber sitesi, fuarın erken kapanacağını ___ ; ancak bu bilgi doğrulanmadı."],["c","Düzenleme kurulu bu iddiayı ___ ."]],"ans":{"a":"vurguladı","b":"öne sürdü","c":"yalanladı"}},{"n":3,"title":"Mos birikmani yozing: kapsamında · çerçevesinde · doğrultusunda · bekleniyor.","items":[["a","Onur konuğu ülke programı ___ Özbek yazarlar İzmir'e geldi."],["b","Etkinlik ___ ücretsiz atölyeler düzenlendi."],["c","Kurulun kararı ___ fuar bir gün uzatıldı."],["d","Fuarı 200 bin kişinin ziyaret etmesi ___ ."]],"ans":{"a":"kapsamında","b":"çerçevesinde","c":"doğrultusunda","d":"bekleniyor"}},{"n":4,"title":"Statistik maʼlumotni turkcha yozing.","items":[["a","25% oʻsish"],["b","uch barobar oshmoq"],["c","10% pasayish"]],"ans":{"a":"yüzde 25'lik artış","b":"üç katına çıkmak","c":"yüzde 10'luk düşüş"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Rais tadbirning muhimligini taʼkidladi."],["b","Yarmarka yakshanba kuni yakunlanishi kutilmoqda."],["c","Nashriyotlar soni oshgani maʼlum qilindi."]],"ans":{"a":"Başkan, etkinliğin önemli olduğunu vurguladı.","b":"Fuarın pazar günü sona ermesi bekleniyor.","c":"Yayınevi sayısının arttığı bildirildi."}},{"n":6,"title":"Yozish. Shahringizdagi biror voqea (festival, yangi kutubxona, sport musobaqasi) haqida 120–150 soʻzli yangilik yozing: sarlavha + asosiy gap + tafsilotlar.","items":[],"ans":{}}]},{"id":"b2-8","level":"B2","n":8,"title":"Sunum ve Tartışma","sub":"Taqdimot iboralari · munozara strategiyalari · gapirish imtihoniga tayyorgarlik · soxta doʻstlar","goals":["taqdimotni boshlash, tuzish va yakunlash","savol-javobni boshqarish","munozarada soʻz olish, muloyim gapni boʻlish, aniqlashtirish, vaqt yutish","gapirish imtihoni strategiyasi va oʻz-oʻzini baholash","oʻzbek va turk tillaridagi soxta doʻst soʻzlar"],"vocab":[{"title":"Lugʻat","words":[["sunum","taqdimot"],["sunmak","taqdim etmoq"],["konu","mavzu"],["bölüm","qism"],["grafik","grafik"],["rakam","raqam"],["özetlemek","xulosa qilmoq"],["vurgulamak","taʼkidlamoq"],["tartışma","munozara"],["söz almak","soʻz olmoq"],["sözünü kesmek","gapini boʻlmoq"],["açmak (fikri)","batafsil tushuntirmoq"],["hemfikir olmak","fikrdosh boʻlmoq"],["bakış açısı","nuqtai nazar"],["ortak nokta","umumiy nuqta"],["memnuniyetle","mamnuniyat bilan"],["kesin","aniq"],["araştırmak","tadqiq qilmoq"],["dikkatini çekmek","eʼtiborini qaratmoq"],["dinleyici","tinglovchi"]]}],"sections":[{"kind":"grammar","title":"Taqdimot (sunum) iboralari","blocks":[{"table":{"h":["Bosqich","Turkcha iboralar"],"r":[["boshlash","Değerli hocalarım, sevgili arkadaşlar, hoş geldiniz. · Bugün sizlere … konusundan bahsedeceğim. · Sunumum on dakika kadar sürecek."],["reja","Konuşmamı üç başlık altında topladım. · İlk olarak …, daha sonra …, en son … konusuna değineceğim."],["oʻtish","Gelelim ikinci konuya. · Bu konuyu burada noktalayıp … · Bununla bağlantılı olarak …"],["koʻrgazma","Ekrandaki tabloda gördüğünüz gibi … · Bu grafik bize … gösteriyor. · Şu rakama özellikle dikkat etmenizi istiyorum."],["taʼkid","Altını çizmek istediğim nokta şu: … · Gözden kaçırmamamız gereken şey …"],["xulosa","Kısaca özetlersem … · Vardığım sonuç şu: … · Beni dinlediğiniz için teşekkür ederim."],["savollar","Sorularınız varsa memnuniyetle cevaplarım. · Güzel bir soru, teşekkür ederim. · Bu konuda kesin bir bilgim yok; araştırıp size dönerim."]]}}]},{"kind":"grammar","title":"Munozara strategiyalari","blocks":[{"table":{"h":["Vazifa","Iboralar"],"r":[["soʻz olish","Bir ekleme yapmak istiyorum. · Bu konuda benim de söyleyeceklerim var. · İzin verirseniz …"],["muloyim boʻlish","Affedersiniz, sözünüzü kesiyorum ama … · Kısa bir şey söyleyebilir miyim?"],["aniqlashtirish","Yani şunu mu demek istiyorsunuz: …? · Biraz daha açar mısınız? · Tam anlayamadım, bir daha söyler misiniz?"],["vaqt yutish","Nasıl desem … · Şöyle anlatayım … · Güzel bir soru, bir saniye düşüneyim. · Aslında …"],["qarshi fikrni yumshatish","Anlıyorum, ancak … · Bu bakış açısına saygı duyuyorum; yine de … · Bir yere kadar katılıyorum, ama …"],["mavzuga qaytish","Asıl konumuza dönersek … · Az önce de söylediğim gibi …"],["kelishuvga kelish","Ortak bir noktada buluşabiliriz. · Sanırım … konusunda ikimiz de aynı fikirdeyiz."]]}},{"note":"«Nasıl desem…» qoidasi: gapirish imtihonida yoki suhbatda jim qolib ketish — eng yomon variant. Soʻz topa olmasangiz, vaqt yutuvchi ibora ayting yoki narsani boshqacha tushuntiring: «… için kullanılan bir şey, nasıl desem, küçük bir alet…»."}]},{"kind":"grammar","title":"Gapirish imtihoni: strategiya","blocks":[{"table":{"h":["Qism","Odatda nima soʻraladi","Strategiya"],"r":[["1. Tanishuv","oʻzingiz, ishingiz, odatlaringiz, rejalaringiz","Qisqa, lekin toʻliq javob: javob + sabab + misol. Bitta «Evet» bilan toʻxtab qolmang."],["2. Tasvirlash yoki hikoya","rasm, vaziyat yoki shaxsiy tajriba","Vaqt va joy → voqealar (-DI) → fon (-(I)yordu) → his-tuygʻu → xulosa."],["3. Munozara","mavzu boʻyicha fikr bildirish va uni himoya qilish","Tezis → 2 ta dalil va misol → qarshi fikr → unga javob → xulosa. Bogʻlovchilardan foydalaning."]]}},{"p":"Oʻz-oʻzini baholash varagʻi (har mashqdan keyin ✔ qoʻying):"},{"table":{"h":["Mezon","Savol"],"r":[["topshiriq","Savolga toʻliq javob berdimmi?"],["ravonlik","Uzoq pauzalar boʻldimi? Vaqt yutuvchi iboralarni ishlatdimmi?"],["grammatika","Turli zamonlar, sifatdoshlar va shart gaplarni ishlatdimmi?"],["lugʻat","B2 soʻzlari va bir-ikkita ibora bormi? Bir soʻzni koʻp takrorlamadimmi?"],["talaffuz","ı / i, ö / ü va choʻziq ğ toʻgʻri chiqdimi?"],["tuzilish","Kirish — asosiy qism — xulosa bormi?"]]}}]},{"kind":"grammar","title":"Soxta doʻstlar: oʻzbekchaga oʻxshash, maʼnosi boshqa","blocks":[{"table":{"h":["Turkcha","Turkchadagi maʼnosi","Oʻzbekcha oʻxshash soʻz","Toʻgʻri turkchasi"],"r":[["ona","unga (olmosh)","ona","anne"],["ata","ajdod, ota-bobo","ota","baba"],["tez","dissertatsiya, tezis","tez","hızlı, çabuk"],["uymak","rioya qilmoq, mos kelmoq","uy","ev"],["işlemek","ishlov bermoq; (jinoyat) sodir etmoq","ishlamoq","çalışmak"],["kaldırmak","koʻtarmoq; bekor qilmoq","qoldirmoq","bırakmak"],["hala","amma (otaning opa-singlisi)","xola (onaning opa-singlisi)","teyze"],["sağ","oʻng; tirik","sogʻ","sağlıklı"],["tamam","xoʻp, mayli; tugadi","tamom","bitti"]]}},{"p":"Annem yarın geliyor — onam ertaga keladi. Ona telefon ettim — unga qoʻngʻiroq qildim (onamga emas!). Şemsiyemi otobüste bıraktım — soyabonimni avtobusda qoldirdim; «kaldırdım» desangiz — «koʻtardim» yoki «yigʻishtirib qoʻydim» degan maʼno chiqadi."}]},{"kind":"dialog","title":"Dialog: Sunum provası","blocks":[{"dlg":[["Dilnoza","Hocam, sunumumu dinler misiniz? Konum \"Buhara'nın tarihî mahalleleri\"."],["Elif Hoca","Tabii, başla."],["Dilnoza","Bugün size Buhara'nın eski mahallelerinden söz etmek istiyorum. Sunumum üç bölümden oluşuyor."],["Elif Hoca","Güzel bir giriş. Yalnız dinleyicinin ilgisini çekmek için bir soruyla başlayabilirsin."],["Dilnoza","Şöyle sorabilirim: \"Bin yıllık bir sokakta hiç yürüdünüz mü?\""],["Elif Hoca","Çok daha iyi. Devam et."],["Dilnoza","İlk olarak mahallelerin tarihine değineceğim. Ardından mimari özelliklere geçeceğim."],["Elif Hoca","Geçişlerin açık. Slaytlardaki yazıları okuma; onlar sana değil, dinleyiciye yardım etsin."],["Dilnoza","Anladım. Peki bir soruya cevap veremezsem ne yapmalıyım?"],["Elif Hoca","\"Güzel bir soru, bunu araştırıp size döneyim\" demek, yanlış cevap vermekten iyidir."],["Dilnoza","Sonuç bölümünü şöyle bitiriyorum: \"Özetlemek gerekirse, bu mahalleler yaşayan birer müzedir. Dinlediğiniz için teşekkür ederim.\""],["Elif Hoca","Harika. Süreni de kontrol et, on dakikayı geçme."]]},{"gloss":[["söz etmek","soʻz yuritmoq"],["oluşmak","iborat boʻlmoq"],["ilgi çekmek","qiziqish uygʻotmoq"],["değinmek","toʻxtalib oʻtmoq"],["mimari","meʼmoriy"],["geçiş","oʻtish"],["süre","vaqt, muddat"]]}]}],"reading":{"title":"İyi bir sunumun sırrı","qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","text":"İyi bir sunum, slaytlar hazırlanmadan çok önce başlar. Konuşmacı önce kendine şu soruyu sormalıdır: dinleyiciler salondan çıkarken akıllarında hangi tek cümle kalsın? Bu cümle belli olduktan sonra geri kalan her şey ona hizmet eder. Uzmanlar bir sunumda en fazla üç ana fikir verilmesini önerir; daha fazlası hatırlanmaz. Slaytlar konuşmacının notları değildir: az yazı, büyük harfler ve tek bir görsel çoğu zaman yeterlidir. Heyecan ise bir engel değil, enerjidir; deneyimli konuşmacılar bile sahneye çıkmadan önce heyecanlanır. Farkı yaratan provadır: sunumu en az üç kez yüksek sesle ve saat tutarak denemek, hem süreyi hem geçişleri sağlamlaştırır. Göz teması kurmak, dinleyiciyi konuşmanın bir parçası hâline getirir. Son olarak, güçlü bir kapanış güçlü bir açılış kadar önemlidir: sunumu \"Bu kadar\" diyerek değil, ana cümlenizi bir kez daha söyleyerek bitirin.","gloss":[["hizmet etmek","xizmat qilmoq"],["görsel","tasvir"],["engel","toʻsiq"],["sahne","sahna"],["prova","sinov mashqi"],["saat tutmak","vaqtni oʻlchamoq"],["sağlamlaştırmak","mustahkamlamoq"],["göz teması","koʻz bilan aloqa"],["kapanış","yakun"]],"qs":["İyi bir sunum slaytları hazırlamakla başlar.","Bir sunumda en fazla üç ana fikir verilmesi önerilir.","Slaytlarda mümkün olduğunca çok yazı olmalıdır.","Deneyimli konuşmacılar da heyecanlanır.","Sunum, ana cümle bir kez daha söylenerek bitirilmelidir."],"ans":{"1":"Y","2":"D","3":"Y","4":"D","5":"D"}},"exercises":[{"n":1,"title":"Taqdimot bosqichini yozing (Boshlash / Oʻtish / Xulosa).","items":[["a","Sunumuma kısa bir soruyla başlamak istiyorum."],["b","Bu noktadan sonra ikinci bölüme geçelim."],["c","Toparlamak gerekirse, üç önemli nokta var."]],"ans":{"a":"Boshlash","b":"Oʻtish","c":"Xulosa"}},{"n":2,"title":"Munozarada nima deysiz? (turkcha)","items":[["a","Suhbatdoshning gapini muloyim boʻlmoqchisiz."],["b","Savolni tushunmadingiz."],["c","Fikrga qisman qoʻshilasiz."]],"ans":{"a":"Özür dilerim, bir şey ekleyebilir miyim?","b":"Sorunuzu tekrar edebilir misiniz?","c":"Bir ölçüde haklısınız, ancak…"},"sample":true},{"n":3,"title":"Soxta doʻstlarni toʻgʻrilang: toʻgʻri turkcha soʻzni yozing.","items":[["a","Ona her gün telefon ediyorum. (onamga)"],["b","Anahtarı evde kaldırdım. (qoldirdim)"],["c","Tren çok tez gidiyor. (tez)"]],"ans":{"a":"Anneme her gün telefon ediyorum.","b":"Anahtarı evde bıraktım.","c":"Tren çok hızlı gidiyor."}},{"n":4,"title":"Taqdimot. Quyidagi mavzulardan birida 3–4 daqiqali taqdimot tayyorlang va ovoz chiqarib ayting: «Benim şehrim», «Sağlıklı yaşam», «Türkçe öğrenmenin faydaları».","items":[],"ans":{}},{"n":5,"title":"Munozara. Doʻstingiz bilan bir fikrni tanlab bahslashing: «Şehirde yaşamak köyde yaşamaktan daha iyidir.» Munozara iboralarini ishlating.","items":[],"ans":{}}]},{"id":"c1-1","level":"C1","n":1,"title":"Dil Öğrenmenin Bilimi","sub":"Ilgʻor ravishdoshlar: -mAksIzIn · -DIğI sürece · -DIğI takdirde · -mAk üzere · -mAklA birlikte · -mAk yerine","goals":["«…masdan» ning kitobiy shakli: -mAksIzIn","shart va muddat: -DIğI sürece, -DIğI takdirde, -mAsI hâlinde","-mAk üzere ning ikki maʼnosi (maqsad va arafa)","yon berish va muqobil: -mAklA birlikte, -mAk yerine, -AcAğI yerde"],"vocab":[{"title":"Lugʻat","words":[["edinim","oʻzlashtirish"],["ana dili","ona tili"],["akıcı","ravon"],["telaffuz","talaffuz"],["söz dağarcığı","soʻz boyligi"],["maruz kalmak","taʼsiriga tushmoq, duch kelmoq"],["pekiştirmek","mustahkamlamoq"],["bağlam","kontekst"],["kalıp","qolip"],["ezberlemek","yodlamoq"],["ilerleme","olgʻa siljish"],["yöntem","usul"],["verimli","samarali"],["aksan","aksent"],["yetkinlik","malaka"],["çaba","saʼy-harakat"],["süreç","jarayon"],["geri bildirim","fikr-mulohaza, qayta aloqa"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"«…masdan»: -mAksIzIn / -mAdAn"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Sözlüğe bakmaksızın bütün metni anladı.","Lugʻatga qaramasdan butun matnni tushundi."],["Hata yapmaktan korkmadan konuşun.","Xato qilishdan qoʻrqmasdan gapiring."]]}},{"p":"-mAksIzIn kitobiy va rasmiy uslubga xos; ogʻzaki nutqda -mAdAn ishlatiladi."},{"sub":"Shart va muddat: -DIğI sürece · -DIğI takdirde · -mAsI hâlinde"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Her gün tekrar ettiğin sürece unutmazsın.","Har kuni takrorlar ekansan, unutmaysan."],["Sınavı geçemediğiniz takdirde kursu tekrar edersiniz.","Imtihondan oʻta olmagan taqdiringizda kursni qayta oʻqiysiz."],["Kaydın iptal edilmesi hâlinde ücret iade edilir.","Roʻyxat bekor qilingan holda toʻlov qaytariladi."]]}},{"sub":"Maqsad va arafa: -mAk üzere"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Türkçe öğretmek üzere Taşkent'e gitti.","Turk tilini oʻrgatish uchun Toshkentga ketdi. (maqsad)"],["Ders bitmek üzere.","Dars tugay deb qoldi. (arafa)"],["Yarın görüşmek üzere!","Ertaga koʻrishguncha!"]]}},{"sub":"Yon berish va muqobil: -mAklA birlikte · -mAk yerine · -AcAğI yerde"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Dil bilgisi önemli olmakla birlikte tek başına yetmez.","Grammatika muhim boʻlsa-da, oʻzi yetarli emas."],["Ezberlemek yerine cümle içinde kullanın.","Yodlash oʻrniga gap ichida ishlating."],["Çalışacağı yerde bütün gün dizi izledi.","Oʻqish oʻrniga kun boʻyi serial koʻrdi. (taʼna)"]]}},{"note":"Farqlang: -mAklA birlikte = «…sa-da, shu bilan birga» (yon berish); -mAk yerine = betaraf muqobil; -AcAğI yerde = kutilgan ish qilinmagani uchun taʼna."}]},{"kind":"dialog","title":"Dialog: Konuşma kulübünde","blocks":[{"dlg":[["Elif Hoca","Bugünkü konumuz şu: yetişkinler yeni bir dili gerçekten ana dili gibi öğrenebilir mi? Dilnoza, sen ne dersin?"],["Dilnoza","Bence aksan dışında mümkün, hocam. Yeter ki insan dile her gün maruz kalsın. Ben İzmir'e taşınmaksızın bu seviyeye gelemezdim."],["Jasur","Ben o kadar emin değilim. Türkiye'de yaşamakla birlikte iş yerinde hep aynı kalıpları kullanıyorum; söz dağarcığım bir noktada durdu."],["Elif Hoca","Çok önemli bir noktaya değindin. Rahat ettiğimiz alandan çıkmadığımız sürece ilerleme yavaşlar. Peki bunu aşmak üzere ne yapıyorsun?"],["Jasur","Açıkçası pek bir şey yapmıyordum. Geçen aydan beri haber dinlemek yerine dinlediğim haberi kendi cümlelerimle özetlemeye çalışıyorum."],["Dilnoza","Ben de hatalarımı bir deftere yazıyorum. Aynı hatayı üçüncü kez yaptığım takdirde o yapıyla beş yeni cümle kuruyorum."],["Elif Hoca","Güzel bir yöntem. Yalnız şunu unutmayın: hata yapmaktan korkmaksızın konuşmak, kusursuz ama sessiz kalmaktan çok daha verimlidir."],["Jasur","Hocam, toplantıda yanlış bir ek kullanınca herkes anlıyor ama ben günlerce onu düşünüyorum."],["Elif Hoca","Düşüneceğin yerde not al ve geç. Dinleyenler anlamına bakar, ekine değil."],["Dilnoza","Bir de şu var: öğrendiğim deyimleri kullanmaya çekiniyorum, yersiz kaçar diye."],["Elif Hoca","Bağlamını görmeksizin ezberlenen deyim gerçekten yersiz kaçabilir. O yüzden deyimi duyduğun cümleyle birlikte not et."],["Jasur","Anlaşıldı. Gelecek hafta herkes bir haber özeti getirsin mi?"],["Elif Hoca","Harika fikir. O hâlde haftaya görüşmek üzere!"]]},{"gloss":[["yeter ki","faqat … boʻlsa bas"],["değinmek","toʻxtalib oʻtmoq"],["aşmak","yengib oʻtmoq"],["açıkçası","ochigʻi"],["özetlemek","qisqacha bayon qilmoq"],["kusursuz","benuqson"],["çekinmek","tortinmoq"],["yersiz kaçmak","oʻrinsiz chiqmoq"]]}]}],"reading":{"text":"Uzun yıllar boyunca dil öğrenmenin bir \"kritik dönemi\" olduğu, bu dönem kapandıktan sonra yeni bir dilin tam olarak edinilemeyeceği düşünüldü. Bugün araştırmacılar bu görüşü bütünüyle reddetmemekle birlikte çok daha temkinli konuşuyor. Çocukların telaffuzda üstün olduğu doğrudur; ancak yetişkinler dil bilgisi kurallarını kavramada ve bilinçli çalışmada çocuklardan daha hızlıdır. Başka bir deyişle, yaş ilerledikçe öğrenme yetisi kaybolmaz, yalnızca biçim değiştirir. Asıl belirleyici olan, dile ne ölçüde ve nasıl maruz kalındığıdır. Öğrenci, anladığı düzeyin biraz üzerindeki metinleri okuduğu ve dinlediği sürece ilerlemeyi sürdürür. Yalnızca kural ezberlemek yerine o kuralı anlamlı bir bağlamda kullanmak kalıcılığı artırır. Araştırmalar, aralıklı tekrarın, yani bilgiyi unutmak üzereyken yeniden hatırlamanın, art arda yapılan uzun çalışmalardan daha verimli olduğunu gösteriyor. Duygusal etkenler de en az yöntem kadar önemlidir. Hata yapmaktan çekinen öğrenci konuşma fırsatlarını kaçırır; oysa geri bildirim almaksızın hatayı düzeltmek neredeyse imkânsızdır. Bu nedenle uzmanlar, öğrencinin kendini güvende hissettiği ortamların oluşturulmasını öneriyor. Sonuç olarak, düzenli çaba gösterildiği takdirde yetişkinlerin de ileri düzeye ulaşması bir istisna değil, beklenen bir sonuçtur.","gloss":[["reddetmek","rad etmoq"],["temkinli","ehtiyotkor"],["kavramak","anglab olmoq"],["yeti","qobiliyat"],["belirleyici","hal qiluvchi"],["kalıcılık","barqarorlik"],["aralıklı tekrar","oraliqli takrorlash"],["etken","omil"],["istisna","istisno"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Eskiden \"kritik dönem\" hakkında ne düşünülüyordu?","Yetişkinler hangi konularda çocuklardan daha hızlıdır?","Yazara göre asıl belirleyici olan nedir?","Aralıklı tekrar ne demektir?","Hata yapmaktan çekinen öğrenci neyi kaçırır?","Metnin vardığı sonuç nedir?"],"title":"Yetişkin beyni ve ikinci dil","ans":{"1":"Bu dönem kapandıktan sonra yeni bir dilin tam olarak edinilemeyeceği düşünülüyordu.","2":"Dil bilgisi kurallarını kavramada ve bilinçli çalışmada daha hızlıdır.","3":"Dile ne ölçüde ve nasıl maruz kalındığıdır.","4":"Bilgiyi unutmak üzereyken yeniden hatırlamaktır.","5":"Konuşma fırsatlarını kaçırır.","6":"Düzenli çaba gösterildiği takdirde yetişkinler de ileri düzeye ulaşabilir."}},"exercises":[{"n":1,"title":"-mAksIzIn bilan birlashtiring.","items":[["a","Sözlüğe bakmadı. Metni çevirdi. → Sözlüğe ___ metni çevirdi."],["b","Ara vermedi. Üç saat çalıştı. → Ara ___ üç saat çalıştı."],["c","İzin almadı. Odaya girdi. → İzin ___ odaya girdi."],["d","Düşünmedi. Cevap verdi. → ___ cevap verdi."]],"ans":{"a":"bakmaksızın","b":"vermeksizin","c":"almaksızın","d":"Düşünmeksizin"}},{"n":2,"title":"-DIğI sürece yoki -DIğI takdirde?","items":[["a","Her gün tekrar ___ unutmazsın. (etmek, sen — davomiylik)"],["b","Ödemeyi zamanında ___ kaydınız silinir. (yapmamak, siz — rasmiy shart)"],["c","Sen yanımda ___ hiçbir şeyden korkmam. (olmak — davomiylik)"],["d","Belgeler eksik ___ başvuru kabul edilmez. (olmak — rasmiy shart)"]],"ans":{"a":"ettiğin sürece","b":"yapmadığınız takdirde","c":"olduğun sürece","d":"olduğu takdirde"}},{"n":3,"title":"-mAk üzere: maqsadmi (M) yoki arafami (A)?","items":[["a","Film başlamak üzere, acele et!"],["b","Staj yapmak üzere Ankara'ya gitti."],["c","Pilim bitmek üzere."],["d","Konuyu görüşmek üzere toplandık."]],"ans":{"a":"A","b":"M","c":"A","d":"M"}},{"n":4,"title":"Mos shaklni qoʻying: -mAklA birlikte · -mAk yerine · -AcAğI yerde.","items":[["a","Pahalı ___ kaliteli değil. (olmak)"],["b","Şikâyet ___ çözüm öner. (etmek)"],["c","Özür ___ bir de bana kızdı. (dilemek, o)"],["d","Asansöre ___ merdivenleri kullanıyorum. (binmek)"]],"ans":{"a":"olmakla birlikte","b":"etmek yerine","c":"dileyeceği yerde","d":"binmek yerine"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Xato qilishdan qoʻrqmasdan gapiring."],["b","Mashq qilar ekansan, olgʻa siljiysan."],["c","Dars tugay deb qoldi."],["d","Yodlash oʻrniga gapda ishlating."]],"ans":{"a":"Hata yapmaktan korkmaksızın konuşun.","b":"Çalıştığın sürece ilerlersin.","c":"Ders bitmek üzere.","d":"Ezberlemek yerine cümlede kullanın."}},{"n":6,"title":"Yozish. «Yabancı dil öğrenmenin en verimli yolu nedir?» mavzusida 250 soʻzlik insho yozing: oʻz tajribangiz, kamida uchta dalil va xulosa. -DIğI sürece, -mAk yerine, -mAklA birlikte shakllarini ishlating.","items":[],"ans":{}}]},{"id":"c1-2","level":"C1","n":2,"title":"Haber mi, Söylenti mi?","sub":"Bilvosita va taxminiy ifoda: -mIş · -(y)mIş · meğer · sözde / güya · -mIş gibi · -cAsInA · … söyleniyor","goals":["eshitilgan va endi bilingan maʼlumot: -mIş, -(y)mIş, meğer","shubha va kinoya: sözde, güya","oʻxshatish: -mIş gibi, -cAsInA, sanki","betaraf xabar uslubi: -DIğI / -AcAğI söyleniyor, bildirildi"],"vocab":[{"title":"Lugʻat","words":[["söylenti","mish-mish"],["kaynak","manba"],["doğrulamak","tasdiqlamoq"],["yalanlamak","rad etmoq"],["iddia","daʼvo"],["asılsız","asossiz"],["yanıltıcı","chalgʻituvchi"],["manşet","bosh sarlavha"],["tarafsız","xolis"],["abartmak","boʻrttirmoq"],["yaymak","tarqatmoq"],["paylaşmak","ulashmoq"],["kanıt","dalil"],["güvenilir","ishonchli"],["şüphe","shubha"],["çarpıtmak","buzib koʻrsatmoq"],["gündem","kun tartibi"],["algı","idrok, taassurot"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Eshitilgan va endi bilingan: -mIş, -(y)mIş, meğer"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Kütüphane kapanacakmış.","Kutubxona yopilar emish. (eshitdim)"],["Meğer haber eskiymiş.","Bilsam, xabar eski ekan. (endi bildim)"],["Sen de oradaymışsın!","Sen ham oʻsha yerda ekansan-ku!"]]}},{"sub":"Shubha va kinoya: sözde, güya"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Güya bu ilaç her derdi iyileştiriyormuş.","Goʻyo bu dori har dardga davo emish."],["Sözde uzman, konuyu hiç bilmiyor.","Nomiga mutaxassis, mavzuni umuman bilmaydi."]]}},{"sub":"Oʻxshatish: -mIş gibi, -cAsInA, sanki"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Hiçbir şey olmamış gibi davrandı.","Hech narsa boʻlmagandek tutdi oʻzini."],["Her şeyi bilircesine konuşuyor.","Hamma narsani biladigandek gapiryapti."],["Sanki dünya yıkılmış!","Xuddi dunyo ostin-ustun boʻlgandek!"]]}},{"sub":"Betaraf xabar uslubi"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Fabrikanın kapanacağı söyleniyor.","Fabrika yopilishi aytilmoqda."],["Kazada iki kişinin yaralandığı bildirildi.","Hodisada ikki kishi jarohatlangani maʼlum qilindi."],["İddiaya göre toplantı ertelenmiş.","Daʼvo qilinishicha, yigʻilish kechiktirilgan."]]}},{"note":"Manbasi aniq boʻlmagan xabarni -DI bilan aytsangiz, uni oʻzingiz koʻrgandek tasdiqlagan boʻlasiz. Ishonchingiz komil boʻlmasa -mIş yoki «… söyleniyor» ishlating."}]},{"kind":"dialog","title":"Dialog: Bu haber doğru mu?","blocks":[{"dlg":[["Kerem","Zeynep, duydun mu? Kemeraltı'ndaki tarihî han yıkılacakmış, yerine alışveriş merkezi yapılacakmış!"],["Zeynep","Nereden duydun bunu?"],["Kerem","Bir grupta paylaşılmış. Altında binlerce yorum var, herkes çok öfkeli."],["Zeynep","Kaynağına baktın mı? Güya belediye karar almış da kimsenin haberi yokmuş… Bana pek inandırıcı gelmedi."],["Kerem","Haklısın, bakmadım. Fotoğraf yeni çekilmiş gibi görünüyordu ama şimdi dikkat edince eski olduğunu fark ettim."],["Zeynep","Meğer üç yıl önceki restorasyon haberinden alınmış. Bak, tarih burada yazıyor."],["Kerem","İnanılır gibi değil. Ben de hiç düşünmeksizin iki arkadaşıma gönderdim."],["Zeynep","Olur böyle şeyler. Önemli olan düzeltmek. Belediyenin sitesinde bir açıklama var mı?"],["Kerem","Varmış: hanın yıkılmayacağı, tam tersine onarılıp kültür merkezine dönüştürüleceği bildirilmiş."],["Zeynep","Demek söylenti bile değil, düpedüz çarpıtma. Başlığı öfke uyandıracak biçimde yazmışlar."],["Kerem","Sanki bilerek yapmışlar. Tıklanma sayısı arttıkça kazanıyorlar herhâlde."],["Zeynep","Büyük olasılıkla. O yüzden ben bir haberi paylaşmadan önce üç şeye bakarım: kim yazmış, ne zaman yazmış, başka bir kaynak doğruluyor mu."],["Kerem","Bundan sonra ben de öyle yapacağım. Şimdi arkadaşlarıma doğrusunu yazayım."]]},{"gloss":[["öfkeli","gʻazablangan"],["inandırıcı","ishonarli"],["fark etmek","payqamoq"],["restorasyon","taʼmirlash"],["düpedüz","ochiqdan-ochiq"],["uyandırmak","uygʻotmoq"],["tıklanma","bosishlar (klik)"],["büyük olasılıkla","katta ehtimol bilan"]]}]}],"reading":{"text":"Sosyal medyada yapılan araştırmalar, yanlış haberlerin doğru haberlerden çok daha hızlı ve geniş bir kitleye yayıldığını ortaya koyuyor. Bunun başlıca nedeni teknoloji değil, insan psikolojisidir. Şaşırtıcı, korkutucu ya da öfkelendirici içerikler dikkatimizi daha kolay çeker; duygularımız harekete geçtiğinde ise düşünmeden paylaşma eğilimimiz artar. Üstelik bir bilgiyi ne kadar sık duyarsak onu o kadar doğru sanırız. Uzmanlar buna \"tekrar etkisi\" diyor: asılsız bir iddia, yalanlandığı hâlde yeterince tekrarlanırsa zihnimizde tanıdık, dolayısıyla güvenilir bir bilgiymiş gibi yer eder. İkinci etken, kendi görüşümüzü destekleyen haberlere daha kolay inanmamızdır. Hoşumuza giden bir haberi sorgulamaksızın kabul eder, hoşumuza gitmeyeni ise en küçük hatasından dolayı reddederiz. Peki ne yapmalı? Öncelikle başlıkla yetinmeyip haberin tamamını okumak gerekir, çünkü çarpıcı başlıklar çoğu zaman metnin söylemediği şeyi söylüyormuş gibi yazılır. Ardından kaynağa, tarihe ve görsellerin gerçekten o olaya ait olup olmadığına bakılmalıdır. Son olarak, bir haber bizi çok öfkelendiriyor ya da çok sevindiriyorsa tam da o anda durup düşünmek en sağlıklı tepkidir. Unutmayalım: paylaştığımız her içerikle biz de bir yayıncı oluruz.","gloss":[["kitle","omma"],["ortaya koymak","koʻrsatib bermoq"],["başlıca","asosiy"],["içerik","kontent"],["eğilim","moyillik"],["yer etmek","oʻrnashib qolmoq"],["sorgulamak","shubha ostiga olmoq"],["yetinmek","kifoyalanmoq"],["çarpıcı","shov-shuvli, taʼsirli"],["görsel","tasvir"],["tepki","munosabat"],["yayıncı","noshir"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Yanlış haberler doğru haberlerden daha yavaş yayılır.","Yalan haberin hızlı yayılmasının asıl nedeni insan psikolojisidir.","Bir iddia yalanlandıktan sonra tekrarlansa bile kimse ona inanmaz.","İnsanlar kendi görüşlerini destekleyen haberlere daha kolay inanır.","Çarpıcı başlıklar her zaman metnin içeriğini doğru yansıtır.","Yazara göre bir haber bizi çok öfkelendirdiğinde durup düşünmeliyiz."],"title":"Yalan haber neden hızlı yayılır?","ans":{"1":"Y","2":"D","3":"Y","4":"D","5":"Y","6":"D"}},"exercises":[{"n":1,"title":"Xabarni eshitilgan shaklga oʻtkazing (-mIş / -(y)mIş).","items":[["a","Han yıkılacak. →"],["b","Toplantı ertelendi. →"],["c","Yeni müdür çok titiz. →"],["d","Bilet fiyatları artıyor. →"]],"ans":{"a":"Han yıkılacakmış.","b":"Toplantı ertelenmiş.","c":"Yeni müdür çok titizmiş.","d":"Bilet fiyatları artıyormuş."}},{"n":2,"title":"meğer bilan qayta yozing (endi bilib qoldingiz).","items":[["a","Fotoğraf eski. → Meğer ___ ."],["b","Sen haklısın. → Meğer ___ ."],["c","Kapı açık kaldı. → Meğer ___ ."]],"ans":{"a":"fotoğraf eskiymiş","b":"sen haklıymışsın","c":"kapı açık kalmış"}},{"n":3,"title":"-mIş gibi yoki -cAsInA bilan toʻldiring.","items":[["a","Beni hiç ___ yanımdan geçti. (görmemek, -mIş gibi)"],["b","Yıllardır burada ___ rahat davranıyor. (yaşıyor, -mIş gibi)"],["c","Her şeyi ___ konuşuyor. (bilmek, -cAsInA)"],["d","Çocuk ___ ağlıyordu. (boğulmak, -cAsInA)"]],"ans":{"a":"görmemiş gibi","b":"yaşıyormuş gibi","c":"bilircesine","d":"boğulurcasına"}},{"n":4,"title":"Betaraf xabar uslubiga oʻtkazing.","items":[["a","Fabrika kapanacak. (söyleniyor) →"],["b","Kazada üç kişi yaralandı. (bildirildi) →"],["c","Han onarılacak. (açıklandı) →"]],"ans":{"a":"Fabrikanın kapanacağı söyleniyor.","b":"Kazada üç kişinin yaralandığı bildirildi.","c":"Hanın onarılacağı açıklandı."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Bilsam, xabar yolgʻon ekan."],["b","Goʻyo u hamma narsani biladi."],["c","U hech narsa boʻlmagandek jilmaydi."],["d","Yigʻilish kechiktirilgani aytilmoqda."]],"ans":{"a":"Meğer haber yalanmış.","b":"Güya o her şeyi biliyormuş.","c":"Hiçbir şey olmamış gibi gülümsedi.","d":"Toplantının ertelendiği söyleniyor."}},{"n":6,"title":"Yozish. Ijtimoiy tarmoqda koʻrgan shubhali bir xabarni tahlil qiling (200–250 soʻz): xabar nima deydi, nega shubhali, uni qanday tekshirdingiz. -mIş, güya, meğer, … söyleniyor shakllarini ishlating.","items":[],"ans":{}}]},{"id":"c1-3","level":"C1","n":3,"title":"Şehir, Göç ve Aidiyet","sub":"Murakkab ergash gaplar: -DIğInA göre · -DIğI kadarıyla · -DIğI gibi · -AcAk kadar · -DIğIndAn beri · -sIn diye","goals":["xulosa va manba: -DIğInA göre, -DIğI kadarıyla","-DIğI gibi ning ikki maʼnosi (oʻxshashlik va «bilanoq»)","daraja: -AcAk kadar / -mAyAcAk kadar","boshlanish va maqsad: -DIğIndAn beri, -sIn diye, -mAsI için"],"vocab":[{"title":"Lugʻat","words":[["göç","koʻchish, migratsiya"],["aidiyet","mansublik"],["kırsal","qishloq hududi"],["kentleşme","urbanizatsiya"],["nüfus","aholi"],["konut","uy-joy"],["istihdam","bandlik"],["altyapı","infratuzilma"],["yabancılaşmak","begonalashmoq"],["uyum sağlamak","moslashmoq"],["köklü","ildizi chuqur"],["komşuluk","qoʻshnichilik"],["özlem","sogʻinch"],["fırsat","imkoniyat"],["yoğunluk","zichlik"],["yaşam kalitesi","turmush sifati"],["semt","mavze"],["barınma","turar joy, boshpana"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Xulosa va manba: -DIğInA göre, -DIğI kadarıyla"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Işıklar yandığına göre evdeler.","Chiroqlar yonib turibdi, demak ular uyda."],["Bildiğim kadarıyla kiralar yine artmış.","Bilishimcha, ijara haqi yana oshibdi."],["Anladığım kadarıyla taşınmayı düşünüyorsun.","Tushunishimcha, koʻchishni oʻylayapsan."]]}},{"sub":"Oʻxshashlik va tezkorlik: -DIğI gibi"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Söylediğin gibi yaptım.","Sen aytgandek qildim. (oʻxshashlik)"],["Şehre geldiği gibi iş aramaya başladı.","Shaharga kelishi bilanoq ish qidira boshladi. (darhol)"]]}},{"sub":"Daraja: -AcAk kadar / -mAyAcAk kadar"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Ev, beş kişinin sığacağı kadar büyük.","Uy besh kishi sigʻadigan darajada katta."],["Yürüyemeyecek kadar yorgunum.","Yura olmaydigan darajada charchaganman."]]}},{"sub":"Boshlanish nuqtasi va maqsad: -DIğIndAn beri · -sIn diye · -mAsI için"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Buraya taşındığımızdan beri komşularımızı tanımıyoruz.","Bu yerga koʻchganimizdan beri qoʻshnilarimizni tanimaymiz."],["Çocuklar iyi okusun diye şehre göç ettiler.","Bolalar yaxshi oʻqisin deb shaharga koʻchishdi."],["Trafiğin azalması için yeni hat açıldı.","Tirbandlik kamayishi uchun yangi yoʻnalish ochildi."]]}},{"note":"-DIğInA göre ikki maʼnoli: 1) sabab-xulosa («…gan ekan, demak»); 2) manba: Uzmanların söylediğine göre — mutaxassislarning aytishicha."}]},{"kind":"dialog","title":"Dialog: Dönsem mi, kalsam mı?","blocks":[{"dlg":[["Murat Bey","Jasur, duyduğuma göre Taşkent'e dönmeyi düşünüyormuşsun. Doğru mu?"],["Jasur","Henüz karar vermiş değilim Murat Bey. İzmir'e geldiğimden beri hem çok şey öğrendim hem de ailemden uzak kalmanın ağırlığını hissettim."],["Murat Bey","Seni anlıyorum. Ben de yirmi yıl önce Erzurum'dan geldiğim gibi kendimi yapayalnız bulmuştum. İnsan alışıyor ama özlem bitmiyor."],["Jasur","Siz nasıl uyum sağladınız?"],["Murat Bey","Açıkçası ilk yıllar zordu. Mahallede kimse kimseyi tanımayacak kadar hızlı yaşıyordu. Sonra bir dernekte gönüllü oldum; çevrem genişledikçe şehir de bana ait olmaya başladı."],["Jasur","Bildiğim kadarıyla Taşkent'te de inşaat sektörü hızla büyüyor. Burada edindiğim deneyim orada işime yarayabilir."],["Murat Bey","Yarar elbette. Yalnız şunu sor kendine: dönmek istediğin yer gerçekten bıraktığın yer mi? Şehirler de insanlar gibi değişir."],["Jasur","Haklısınız. Annem, döndüğüm takdirde her şeyin eskisi gibi olacağını söylüyor ama arkadaşlarımın çoğu başka şehirlere dağılmış."],["Murat Bey","O hâlde acele etme. Projenin bitmesine altı ay var; bu süreyi düşünmen için bir fırsat say."],["Jasur","Ailem merak etmesin diye onlara şimdilik bir şey söylemeyeceğim."],["Murat Bey","Bence açık konuş. Sen söylemediğin sürece onlar da plan yapamaz."],["Jasur","Doğru. Bu akşam arayıp olduğu gibi anlatacağım."]]},{"gloss":[["ağırlık","ogʻirlik, yuk"],["yapayalnız","yakka-yolgʻiz"],["dernek","jamiyat, uyushma"],["çevre","tanishlar doirasi"],["edinmek","orttirmoq"],["işe yaramak","asqotmoq"],["dağılmak","tarqalib ketmoq"],["saymak","hisoblamoq"]]}]}],"reading":{"text":"Son elli yılda dünya nüfusunun yarısından fazlası şehirlerde yaşamaya başladı. İnsanları kırsaldan kente çeken nedenler bellidir: daha fazla iş imkânı, daha iyi eğitim ve sağlık hizmetleri, daha canlı bir kültür hayatı. Ne var ki bu fırsatların bir bedeli de vardır. Nüfus arttığı gibi konut fiyatları ve kiralar da yükselir; birçok aile gelirinin yarısını yalnızca barınmaya ayırmak zorunda kalır. Şehir merkezinde ev bulamayanlar uzak semtlere taşınır ve günün iki üç saatini yolda geçirir. Sosyologların dikkat çektiği bir başka sorun ise yalnızlıktır. Köyde herkes birbirini tanırken büyük şehirde aynı apartmanda oturanlar bile çoğu zaman selamlaşmaz. Araştırmalara göre kalabalık içinde yaşayan insanlar, küçük yerleşimlerde yaşayanlardan daha sık yalnızlık hisseder. Yine de tablo tümüyle karamsar değildir. Uzmanların belirttiğine göre mahalle ölçeğinde kurulan ilişkiler, yani ortak bahçeler, semt pazarları ve komşu dernekleri, aidiyet duygusunu güçlendiriyor. Bazı belediyeler her ihtiyacın on beş dakikalık yürüme mesafesinde karşılanacağı biçimde mahalleler planlıyor. Anlaşıldığı kadarıyla geleceğin şehri daha büyük değil, daha yakın olacak: insanın hem fırsatlara hem de komşusuna ulaşabildiği bir şehir.","gloss":[["bedel","badal, toʻlov"],["ne var ki","biroq"],["ayırmak","ajratmoq"],["dikkat çekmek","eʼtibor qaratmoq"],["yerleşim","aholi punkti"],["karamsar","umidsiz"],["ölçek","miqyos"],["karşılamak","qondirmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["İnsanları şehre çeken nedenler nelerdir?","Nüfus artınca konut piyasasında ne olur?","Merkezde ev bulamayanlar ne yapar?","Sosyologlar hangi soruna dikkat çekiyor?","Aidiyet duygusunu neler güçlendiriyor?","Yazara göre geleceğin şehri nasıl olacak?"],"title":"Büyük şehrin bedeli","ans":{"1":"Daha fazla iş imkânı, daha iyi eğitim ve sağlık hizmetleri ile canlı bir kültür hayatıdır.","2":"Konut fiyatları ve kiralar yükselir.","3":"Uzak semtlere taşınır ve günün iki üç saatini yolda geçirir.","4":"Yalnızlık sorununa dikkat çekiyor.","5":"Ortak bahçeler, semt pazarları ve komşu dernekleri güçlendiriyor.","6":"Daha büyük değil, daha yakın olacak."}},"exercises":[{"n":1,"title":"-DIğInA göre bilan xulosa chiqaring.","items":[["a","Işıklar yanıyor. Evdeler. → Işıklar ___ evdeler."],["b","Telefonu açmıyor. Meşgul. → Telefonu ___ meşgul."],["c","Bavulunu hazırladın. Gidiyorsun. → Bavulunu ___ gidiyorsun."]],"ans":{"a":"yandığına göre","b":"açmadığına göre","c":"hazırladığına göre"}},{"n":2,"title":"-DIğI kadarıyla bilan toʻldiring.","items":[["a","___ kiralar yine artmış. (bilmek, ben)"],["b","___ toplantı ertelenecek. (duymak, biz)"],["c","___ bu mahalleyi çok seviyorsun. (anlamak, ben)"]],"ans":{"a":"Bildiğim kadarıyla","b":"Duyduğumuz kadarıyla","c":"Anladığım kadarıyla"}},{"n":3,"title":"-DIğI gibi: oʻxshashlikmi (O) yoki «bilanoq» (B)?","items":[["a","Eve girdiği gibi telefona sarıldı."],["b","Her şey planladığımız gibi gitti."],["c","Haberi aldığım gibi yola çıktım."],["d","Annemin yaptığı gibi yapmaya çalıştım."]],"ans":{"a":"B","b":"O","c":"B","d":"O"}},{"n":4,"title":"-AcAk kadar / -mAyAcAk kadar bilan birlashtiring.","items":[["a","Çok yorgunum. Yürüyemiyorum. → ___ yorgunum."],["b","Salon büyük. Yüz kişi sığar. → Salon yüz kişinin ___ büyük."],["c","Çok gürültü var. Konuşamıyoruz. → ___ gürültü var."]],"ans":{"a":"Yürüyemeyecek kadar","b":"sığacağı kadar","c":"Konuşamayacak kadar"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Bilishimcha, u Toshkentga qaytmoqchi."],["b","Bu yerga koʻchganimdan beri uni koʻrmadim."],["c","Bolalar yaxshi oʻqisin deb shaharga koʻchdik."],["d","Xabarni olishim bilanoq yoʻlga chiqdim."]],"ans":{"a":"Bildiğim kadarıyla Taşkent'e dönmek istiyor.","b":"Buraya taşındığımdan beri onu görmedim.","c":"Çocuklar iyi okusun diye şehre taşındık.","d":"Haberi aldığım gibi yola çıktım."}},{"n":6,"title":"Yozish. «Büyük şehirde mi, küçük şehirde mi yaşamak daha iyidir?» mavzusida 250 soʻzlik qiyosiy insho yozing. Ikki tomonning afzallik va kamchiliklarini solishtirib, oʻz xulosangizni asoslang.","items":[],"ans":{}}]},{"id":"c1-4","level":"C1","n":4,"title":"İş Dünyası","sub":"Nisbatlar qatlami: orttirma + majhul (hazırlatıldı) · birgalik -(I)ş · oʻzlik -(I)n · -(y)Abil + majhul","goals":["orttirma + majhul: «…tirildi»","birgalik nisbati: anlaşmak, yazışmak, görüşmek","oʻzlik nisbati: hazırlanmak, sevinmek","imkoniyat + majhul: iptal edilebilir, önlenebilirdi"],"vocab":[{"title":"Lugʻat","words":[["girişimci","tadbirkor"],["yatırım","sarmoya"],["ortak","sherik"],["sözleşme","shartnoma"],["müzakere","muzokara"],["teklif","taklif"],["rekabet","raqobat"],["kâr","foyda"],["zarar","zarar"],["maliyet","tannarx"],["tedarikçi","yetkazib beruvchi"],["teslim","topshirish"],["yükümlülük","majburiyat"],["onaylamak","tasdiqlamoq"],["denetlemek","nazorat qilmoq"],["verimlilik","unumdorlik"],["hedef","maqsad"],["nakit","naqd pul"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Orttirma + majhul: «…tirildi»"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Rapor bir uzmana hazırlatıldı.","Hisobot bir mutaxassisga tayyorlattirildi."],["Bütün belgeler noterde onaylatılacak.","Barcha hujjatlar notariusda tasdiqlatiladi."],["Çalışanlara yeni program öğretildi.","Xodimlarga yangi dastur oʻrgatildi."]]}},{"p":"Tartib doim: oʻzak + orttirma + majhul + zamon: hazırla-t-ıl-dı. Ishni kim buyurgani aytilmaydi — rasmiy hisobotlarga xos."},{"sub":"Birgalik nisbati: -(I)ş"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["İki şirket fiyatta anlaştı.","Ikki shirkat narxda kelishdi."],["Ortaklar uzun süre tartıştı.","Sheriklar uzoq bahslashdi."],["Toplantıdan sonra yazışmaya devam ettik.","Yigʻilishdan keyin yozishmani davom ettirdik."]]}},{"sub":"Oʻzlik nisbati: -(I)n"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Toplantıya iyi hazırlandım.","Yigʻilishga yaxshi tayyorlandim."],["Müdür bu sözlere çok sevindi.","Direktor bu gaplardan juda quvondi."],["Kararı duyunca söylendi durdu.","Qarorni eshitib toʻngʻillab yurdi."]]}},{"sub":"Imkoniyat + majhul: -(y)Abil bilan"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Sözleşme otuz gün içinde iptal edilebilir.","Shartnoma oʻttiz kun ichida bekor qilinishi mumkin."],["Bu hata önlenebilirdi.","Bu xatoning oldini olish mumkin edi."],["Teklif bu koşullarda kabul edilemez.","Taklif bu shartlarda qabul qilinishi mumkin emas."]]}},{"note":"Qoʻshimchalar tartibi: oʻzak → birgalik/oʻzlik → orttirma → majhul → imkoniyat → inkor → zamon → shaxs: anlaş-tır-ıl-a-ma-dı (kelishtirib boʻlmadi)."}]},{"kind":"dialog","title":"Dialog: Sözleşme görüşmesi","blocks":[{"dlg":[["Kerem","Zehra Hanım, kafem için iki yüz fincan ve yüz tabak yaptırmak istiyorum. Teklifinizi inceledim; fiyat konusunda anlaşabileceğimizi umuyorum."],["Zehra Hanım","Elbette konuşalım Kerem Bey. Hepsi elde boyanacağı için maliyet düşürülemiyor, ama teslim süresinde esnek olabilirim."],["Kerem","Açılış on beş Mart'ta. Ürünlerin en geç ayın onunda teslim edilmesi gerekiyor."],["Zehra Hanım","Fırınım o hafta bakıma alınacak; yine de siparişinizin yarısı ayın beşinde, kalanı onunda gönderilebilir."],["Kerem","Bu bana uyar. Logo fincanlara nasıl işlenecek?"],["Zehra Hanım","Kalıbı dışarıda hazırlatıyorum. Önce bir numune yaptırılır, siz onayladıktan sonra üretime geçilir."],["Kerem","Peki teslimat sırasında kırılan olursa?"],["Zehra Hanım","Kırılan ürünler ücretsiz yenilenir; bu madde sözleşmeye yazdırılabilir."],["Kerem","Çok iyi. Ödemeyi iki taksitte yapabilir miyim? Yarısı şimdi, yarısı teslimde."],["Zehra Hanım","Olur. Yalnız gecikme hâlinde üretim durdurulur; bunu da açıkça belirtelim ki sonra tartışmayalım."],["Kerem","Haklısınız, her şey yazılı olsun. Sözleşmeyi avukatıma inceletip yarın imzalarım."],["Zehra Hanım","Anlaştık o hâlde. Yeni işinizde bol kazançlar dilerim!"],["Kerem","Teşekkür ederim. Umarım uzun yıllar birlikte çalışırız."]]},{"gloss":[["incelemek","koʻrib chiqmoq"],["esnek","moslashuvchan"],["bakıma almak","texnik koʻrikka qoʻymoq"],["işlemek","tushirmoq (naqshni)"],["numune","namuna"],["üretim","ishlab chiqarish"],["madde","band"],["taksit","boʻlib toʻlash"],["belirtmek","koʻrsatib oʻtmoq"],["kazanç","daromad"]]}]}],"reading":{"text":"Her yıl binlerce girişim kuruluyor, ancak bunların büyük bölümü ilk üç yıl içinde kapanıyor. Araştırmacılar başarısızlığın nedenini çoğu zaman fikrin kötü olmasında değil, pazarın yeterince tanınmamasında buluyor. Girişimci ürününe o kadar inanır ki müşterinin gerçekten neye ihtiyaç duyduğunu sormayı unutur. Bu yüzden deneyimli yatırımcılar, büyük harcamalar yapılmadan önce küçük bir deneme sürümünün hazırlatılıp gerçek kullanıcılara sunulmasını öneriyor. Alınan geri bildirimlere göre ürün geliştirilir, gerekirse baştan tasarlanır. İkinci büyük sorun nakit akışıdır. Kâr eden bir şirket bile ödemeleri zamanında tahsil edemediği takdirde batabilir; dolayısıyla sözleşmelerde ödeme koşullarının açıkça belirtilmesi hayati önem taşır. Üçüncü etken ise ekiptir. Tek başına her işi yapmaya çalışan kurucu kısa sürede tükenir; görevlerin paylaşılması ve ortaklar arasındaki yükümlülüklerin baştan yazıya dökülmesi gerekir. Unutulmamalıdır ki ortaklıkların çoğu para yüzünden değil, konuşulmamış beklentiler yüzünden bozulur. Bütün bu risklere rağmen girişimcilik öğrenilebilen bir beceridir. Başarılı kurucuların çoğu ilk denemesinde değil, ikinci ya da üçüncü denemesinde hedefine ulaşmıştır; onları ötekilerden ayıran şey hiç yanılmamaları değil, her yanılgıdan bir ders çıkarmalarıdır.","gloss":[["girişim","tashabbus, startap"],["harcama","sarf-xarajat"],["deneme sürümü","sinov versiyasi"],["tasarlamak","loyihalamoq"],["nakit akışı","pul oqimi"],["tahsil etmek","undirib olmoq"],["batmak","kasodga uchramoq"],["hayati","hayotiy"],["kurucu","asoschi"],["tükenmek","holdan toymoq"],["yazıya dökmek","yozma rasmiylashtirmoq"],["beklenti","kutilma"],["yanılgı","yanglishish"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Girişimlerin çoğu ilk üç yıl içinde kapanır.","Başarısızlığın başlıca nedeni fikirlerin kötü olmasıdır.","Yatırımcılar önce küçük bir deneme sürümünün hazırlanmasını önerir.","Kâr eden bir şirket hiçbir zaman batmaz.","Ortaklıklar çoğunlukla konuşulmamış beklentiler yüzünden bozulur.","Başarılı kurucular genellikle ilk denemelerinde hedefe ulaşır."],"title":"Bir fikirden bir şirkete","ans":{"1":"D","2":"Y","3":"D","4":"Y","5":"D","6":"Y"}},"exercises":[{"n":1,"title":"Orttirma + majhul shaklini yozing.","items":[["a","Fincanları bir ustaya boyattık. → Fincanlar bir ustaya ___ ."],["b","Sözleşmeyi avukata inceletti. → Sözleşme avukata ___ ."],["c","Belgeleri noterde onaylatacaklar. → Belgeler noterde ___ ."],["d","Raporu bir uzmana hazırlattılar. → Rapor bir uzmana ___ ."]],"ans":{"a":"boyatıldı","b":"inceletildi","c":"onaylatılacak","d":"hazırlatıldı"}},{"n":2,"title":"Birgalik nisbatiga oʻtkazing.","items":[["a","yazmak →"],["b","görmek →"],["c","anlamak →"],["d","bakmak →"]],"ans":{"a":"yazışmak","b":"görüşmek","c":"anlaşmak","d":"bakışmak"}},{"n":3,"title":"-(y)Abil + majhul bilan qayta yozing.","items":[["a","Sözleşmeyi iptal edebilirsiniz. → Sözleşme ___ ."],["b","Bu hatayı önleyebilirdik. → Bu hata ___ ."],["c","Teklifi kabul edemeyiz. → Teklif ___ ."]],"ans":{"a":"iptal edilebilir","b":"önlenebilirdi","c":"kabul edilemez"}},{"n":4,"title":"Nisbatni aniqlang: majhul (M), oʻzlik (Z), birgalik (B) yoki orttirma (O).","items":[["a","Toplantıya hazırlandım."],["b","İki taraf anlaştı."],["c","Ürünler dün teslim edildi."],["d","Sözleşmeyi avukata okuttum."],["e","Haberi duyunca çok sevindi."]],"ans":{"a":"Z","b":"B","c":"M","d":"O","e":"Z"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Shartnoma oʻttiz kun ichida bekor qilinishi mumkin."],["b","Namuna tayyorlattirildi."],["c","Biz narxda kelishdik."],["d","Bu xatoning oldini olish mumkin edi."]],"ans":{"a":"Sözleşme otuz gün içinde iptal edilebilir.","b":"Numune hazırlatıldı.","c":"Fiyatta anlaştık.","d":"Bu hata önlenebilirdi."}},{"n":6,"title":"Yozish. Rasmiy xat: yetkazib beruvchi shirkatga buyurtmangiz kechikkani haqida 180–220 soʻzlik shikoyat xati yozing — buyurtma tafsiloti, muammo, talabingiz va muddat. Majhul va orttirma-majhul shakllarini ishlating.","items":[],"ans":{}}]},{"id":"c1-5","level":"C1","n":5,"title":"Yapay Zekâ Çağı","sub":"Akademik uslub: nominalizatsiya · -mAktA olup · -mAk suretiyle · dolayısıyla · nitekim · zira · bununla birlikte · buna karşın","goals":["feʼlni otga aylantirib yozish (nominalizatsiya)","rasmiy bogʻlash: -mAktA olup, -mAk suretiyle, -mAsI nedeniyle","mantiqiy bogʻlovchilar: dolayısıyla, zira, nitekim, bununla birlikte, buna karşın, öte yandan","«ben» siz betaraf akademik gap"],"vocab":[{"title":"Lugʻat","words":[["yapay zekâ","sunʼiy intellekt"],["veri","maʼlumot (data)"],["öngörmek","oldindan koʻrmoq"],["otomasyon","avtomatlashtirish"],["iş gücü","ishchi kuchi"],["etik","axloqiy"],["ön yargı","tarafkashlik"],["gizlilik","maxfiylik"],["denetim","nazorat"],["şeffaflık","shaffoflik"],["sorumluluk","masʼuliyat"],["yenilik","innovatsiya"],["dönüşüm","transformatsiya"],["beceri","koʻnikma"],["ölçüt","mezon"],["varsayım","faraz"],["bulgu","topilma, natija"],["eleştirel düşünme","tanqidiy fikrlash"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Nominalizatsiya: feʼlni otga aylantirib yozish"},{"table":{"h":["Ogʻzaki","Akademik"],"r":[["Veriler arttı, bu yüzden hatalar azaldı.","Verilerin artması hataların azalmasına yol açtı."],["Sistemi denetlemek gerekiyor.","Sistemin denetlenmesi gerekmektedir."],["İnsanlar işini kaybedecek diye korkuyor.","İş kaybı korkusu yaygındır."]]}},{"sub":"Rasmiy bogʻlash: -mAktA olup · -mAk suretiyle · -mAsI nedeniyle"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Sistem hastanelerde kullanılmakta olup sonuçları izlenmektedir.","Tizim shifoxonalarda qoʻllanilmoqda, natijalari esa kuzatilmoqda."],["Veriler anonimleştirilmek suretiyle paylaşılır.","Maʼlumotlar anonimlashtirish yoʻli bilan ulashiladi."],["Verilerin eksik olması nedeniyle çalışma ertelendi.","Maʼlumotlar toʻliq boʻlmagani sababli tadqiqot kechiktirildi."]]}},{"sub":"Mantiqiy bogʻlovchilar"},{"table":{"h":["Bogʻlovchi","Vazifasi","Misol"],"r":[["dolayısıyla / bu nedenle","natija","Veri azdır; dolayısıyla sonuç kesin değildir."],["zira","sabab (kitobiy)","Dikkatli olunmalıdır, zira hata payı yüksektir."],["nitekim","tasdiqlovchi dalil","Risk büyüktür; nitekim geçen yıl üç hata yaşandı."],["bununla birlikte","yon berish","Sistem hızlıdır; bununla birlikte pahalıdır."],["buna karşın","zidlash","Kentte erişim kolaydır; buna karşın kırsalda sınırlıdır."],["öte yandan","boshqa jihat","Maliyet düşer; öte yandan denetim zorlaşır."]]}},{"note":"Akademik matnda «ben» ishlatilmaydi: «Bence…» oʻrniga «…olduğu söylenebilir», «…düşünülmektedir», «Bu çalışmada … ele alınmaktadır»."}]},{"kind":"dialog","title":"Dialog: Seminer sonrası","blocks":[{"dlg":[["Dilnoza","Seminer nasıldı sence? Konuşmacı, yapay zekânın on yıl içinde mesleklerin yarısını dönüştüreceğini öne sürdü."],["Jasur","Etkileyiciydi, bununla birlikte biraz abartılı buldum. Nitekim benzer tahminler yirmi yıl önce de yapılmıştı."],["Dilnoza","Doğru, ama bu kez durum farklı olabilir; zira sistemler artık yalnızca hesap yapmıyor, metin yazıyor, tasarım üretiyor."],["Jasur","İnşaat sektöründe de etkisini görüyoruz. Projelerdeki hatalar yazılım tarafından önceden saptanıyor; dolayısıyla maliyet düşüyor."],["Dilnoza","Peki bu, mühendislere duyulan ihtiyacın azalması anlamına gelmiyor mu?"],["Jasur","Bence hayır. Yazılım hatayı buluyor, buna karşın kararı yine insan veriyor. Sorumluluğun bir makineye devredilmesi düşünülemez."],["Dilnoza","Beni asıl kaygılandıran ön yargı meselesi. Sistem hangi verilerle eğitilirse o verilerdeki hataları da öğreniyor."],["Jasur","Haklısın. Konuşmacının da belirttiği gibi, şeffaflık sağlanmadığı sürece güven oluşmaz."],["Dilnoza","Öte yandan dil öğrenenler için büyük kolaylık. Yazdığım metni anında düzeltiyor, hatamın nedenini açıklıyor."],["Jasur","Yeter ki düşünme işini tümüyle ona bırakmayalım. Aracı kullanmakla araca bağımlı olmak aynı şey değil."],["Dilnoza","Güzel söyledin. Bunu yarınki sunumumun son cümlesi yapabilir miyim?"],["Jasur","Kaynak göstermek suretiyle, evet!"]]},{"gloss":[["öne sürmek","ilgari surmoq"],["etkileyici","taʼsirli"],["abartılı","boʻrttirilgan"],["saptamak","aniqlamoq"],["devretmek","topshirmoq"],["kaygılandırmak","tashvishga solmoq"],["mesele","masala"],["anında","shu zahoti"],["bağımlı","qaram"],["kaynak göstermek","manba koʻrsatmoq"]]}]}],"reading":{"text":"Yapay zekâ teknolojilerinin hızla yaygınlaşması, çalışma hayatının geleceğine ilişkin tartışmaları yeniden gündeme getirmiştir. Bu tartışmalarda iki temel görüş öne çıkmaktadır. Birinci görüşe göre otomasyon, tekrara dayalı işlerin büyük bölümünü ortadan kaldıracak; dolayısıyla geniş çaplı bir işsizlik dalgası yaşanacaktır. İkinci görüş ise tarihsel deneyime dayanmaktadır: buhar makinesinden bilgisayara kadar her büyük yenilik bazı meslekleri sona erdirmekle birlikte, önceden öngörülemeyen yeni meslekler de yaratmıştır. Mevcut bulgular ikinci görüşü kısmen desteklemektedir. Nitekim son yıllarda veri analizi, siber güvenlik ve yapay zekâ denetimi gibi alanlarda istihdam belirgin biçimde artmıştır. Bununla birlikte dönüşümün maliyeti toplumun bütün kesimlerine eşit dağılmamaktadır. Yeni mesleklerin yüksek beceri gerektirmesi nedeniyle, işini kaybeden bir çalışanın bu alanlara geçmesi çoğu zaman kolay olmamaktadır. Bu durum, yaşam boyu öğrenme politikalarının önemini artırmaktadır. Uzmanlar, eğitim sistemlerinin ezbere dayalı bilgiden çok eleştirel düşünme, iş birliği ve yaratıcılık gibi makinelerin kolayca taklit edemediği becerilere yönelmesi gerektiğini vurgulamaktadır. Öte yandan teknolojinin nasıl kullanılacağı teknik değil, toplumsal bir tercihtir. Kuralların şeffaf biçimde belirlenmesi ve sistemlerin bağımsız kurumlarca denetlenmesi sağlandığı takdirde, yapay zekânın insan emeğinin yerini alan değil, onu güçlendiren bir araç olması mümkündür.","gloss":[["ilişkin","doir"],["öne çıkmak","ajralib turmoq"],["dayalı","asoslangan"],["geniş çaplı","keng koʻlamli"],["dalga","toʻlqin"],["buhar makinesi","bugʻ mashinasi"],["mevcut","mavjud"],["kısmen","qisman"],["belirgin","sezilarli"],["kesim","qatlam"],["taklit etmek","taqlid qilmoq"],["yönelmek","yuz burmoq"],["emek","mehnat"],["bağımsız","mustaqil"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Birinci görüşe göre otomasyonun sonucu ne olacaktır?","İkinci görüş neye dayanmaktadır?","Son yıllarda hangi alanlarda istihdam artmıştır?","İşini kaybedenlerin yeni alanlara geçmesi neden zordur?","Eğitim sistemleri hangi becerilere yönelmelidir?","Yapay zekâ hangi koşulda insan emeğini güçlendiren bir araç olabilir?"],"title":"Yapay zekâ ve çalışma hayatının geleceği","ans":{"1":"Geniş çaplı bir işsizlik dalgası yaşanacaktır.","2":"Tarihsel deneyime dayanmaktadır.","3":"Veri analizi, siber güvenlik ve yapay zekâ denetimi alanlarında artmıştır.","4":"Çünkü yeni meslekler yüksek beceri gerektirmektedir.","5":"Eleştirel düşünme, iş birliği ve yaratıcılık gibi becerilere yönelmelidir.","6":"Kurallar şeffaf biçimde belirlendiği ve sistemler bağımsız kurumlarca denetlendiği takdirde."}},"exercises":[{"n":1,"title":"Akademik uslubga oʻtkazing (nominalizatsiya).","items":[["a","Veriler arttı, bu yüzden hatalar azaldı. → Verilerin ___ hataların ___ yol açtı."],["b","Sistemi denetlemek gerekiyor. → Sistemin ___ gerekmektedir."],["c","Fiyatlar yükseldi, bu yüzden satışlar düştü. → Fiyatların ___ satışların ___ neden oldu."]],"ans":{"a":"artması, azalmasına","b":"denetlenmesi","c":"yükselmesi, düşmesine"}},{"n":2,"title":"Mos bogʻlovchini yozing: dolayısıyla · zira · nitekim · bununla birlikte · buna karşın.","items":[["a","Veri yetersizdir; ___ kesin bir sonuca varılamaz."],["b","Dikkatli olunmalıdır, ___ hata payı yüksektir."],["c","Risk büyüktür; ___ geçen yıl üç ciddi hata yaşanmıştır."],["d","Sistem çok hızlıdır; ___ kurulumu pahalıdır."],["e","Kentlerde internet yaygındır; ___ kırsalda erişim sınırlıdır."]],"ans":{"a":"dolayısıyla","b":"zira","c":"nitekim","d":"bununla birlikte","e":"buna karşın"}},{"n":3,"title":"-mAk suretiyle yoki -mAsI nedeniyle?","items":[["a","Veriler ___ paylaşılır. (anonimleştirilmek)"],["b","Bütçenin yetersiz ___ proje durduruldu. (olmak)"],["c","Sonuçlar ___ doğrulanmıştır. (karşılaştırılmak)"]],"ans":{"a":"anonimleştirilmek suretiyle","b":"olması nedeniyle","c":"karşılaştırılmak suretiyle"}},{"n":4,"title":"Shaxsiy gapni betaraf akademik gapga aylantiring.","items":[["a","Bence bu yöntem daha verimli."],["b","Ben bu yazıda otomasyonu anlatacağım."],["c","Bana göre denetim şart."]],"ans":{"a":"Bu yöntemin daha verimli olduğu söylenebilir.","b":"Bu yazıda otomasyon ele alınmaktadır.","c":"Denetimin zorunlu olduğu düşünülmektedir."}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Narxlarning oshishi sotuvlarning pasayishiga olib keldi."],["b","Tizim tez ishlaydi; shu bilan birga qimmat."],["c","Maʼlumotlar yetarli emas; binobarin, natija aniq emas."],["d","Tizimning nazorat qilinishi lozim."]],"ans":{"a":"Fiyatların artması satışların düşmesine yol açtı.","b":"Sistem hızlıdır; bununla birlikte pahalıdır.","c":"Veriler yetersizdir; dolayısıyla sonuç kesin değildir.","d":"Sistemin denetlenmesi gerekmektedir."}},{"n":6,"title":"Yozish. «Yapay zekâ çalışma hayatını nasıl değiştirecek?» mavzusida 250–300 soʻzlik akademik uslubdagi insho yozing: kirish (muammo), ikki qarama-qarshi qarash, dalillar, xulosa. «Bence» ishlatmang; kamida toʻrtta mantiqiy bogʻlovchi qoʻllang.","items":[],"ans":{}}]},{"id":"c1-6","level":"C1","n":6,"title":"Yaşam Dengesi","sub":"Tasviriy feʼllar: -(y)Iver · -(y)Adur · -(y)Agel · -(y)AyAz · -(y)Akal · qoliplar: -mAyA kalk- · -mAk durumunda kal- · şöyle dursun","goals":["tezlik va osonlik: -(y)Iver","davomiylik: -(y)Adur, -(y)Agel, -(y)Akal","«oz qoldi»: -(y)AyAz","munosabat qoliplari: -mAyA kalkmak, -mAk durumunda kalmak, -AcAğI tutmak, şöyle dursun"],"vocab":[{"title":"Lugʻat","words":[["tükenmişlik","holdan toyish"],["denge","muvozanat"],["öncelik","ustuvorlik"],["ertelemek","keyinga surmoq"],["mola","tanaffus"],["odaklanmak","diqqatni jamlamoq"],["kaygı","xavotir"],["yenilenmek","kuch toʻplamoq"],["mesai","ish vaqti"],["fazla mesai","ish vaqtidan tashqari ish"],["yük","yuk"],["sınır koymak","chegara qoʻymoq"],["farkındalık","anglash, ogohlik"],["uyku düzeni","uyqu tartibi"],["beslenme","ovqatlanish"],["hareketsizlik","kamharakatlik"],["ihmal","eʼtiborsizlik"],["vazgeçmek","voz kechmoq"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Tezlik va osonlik: -(y)Iver"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Şu raporu bir okuyuver.","Shu hisobotni bir oʻqib yubor. (iltimos, yengillik)"],["Kapı birden açılıverdi.","Eshik birdan ochilib ketdi. (kutilmagan tezlik)"]]}},{"sub":"Davomiylik: -(y)Adur · -(y)Agel · -(y)Akal"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Sen yazadur, ben çay koyayım.","Sen yozib tur, men choy quyay."],["Bu gelenek yüzyıllardır süregelmiştir.","Bu anʼana asrlar davomida davom etib kelgan."],["Haberi duyunca donakaldı.","Xabarni eshitib qotib qoldi."],["Ekrana bakakaldım.","Ekranga tikilib qoldim."]]}},{"sub":"Yaqinlashish: -(y)AyAz"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Merdivenden düşeyazdım.","Zinadan yiqilib tushishimga oz qoldi."],["Otobüsü kaçırayazdık.","Avtobusdan qolib ketishimizga sal qoldi."]]}},{"sub":"Munosabat bildiruvchi qoliplar"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Her işi tek başına yapmaya kalktı.","Har ishni yolgʻiz oʻzi qilishga urindi. (oʻrinsiz urinish)"],["İstifa etmek durumunda kaldı.","Isteʼfo berishga majbur boʻlib qoldi."],["Tam çıkacakken telefon çalacağı tuttu.","Endi chiqaman deganda telefon jiringlab qolsa boʻladimi."],["Dinlenmek şöyle dursun, yemek bile yiyemedim.","Dam olish u yoqda tursin, ovqat ham yeya olmadim."]]}},{"note":"-(y)Iver unli uygʻunligiga boʻysunadi (alıver, görüver), -(y)Adur va -(y)AyAz esa faqat a/e bilan: bakadur, düşeyazdı. -(y)AyAz bugun asosan yozma va adabiy tilda uchraydi; ogʻzaki nutqda «az kalsın düşüyordum» deyiladi."}]},{"kind":"dialog","title":"Dialog: Tükenmenin eşiğinde","blocks":[{"dlg":[["Zeynep","Defne, iyi misin? Dün gece ikide ışığın yanıyordu."],["Defne","Raporları bitirmeye kalktım ama ekrana bakakalmışım. Bir ara masada uyuyayazdım."],["Zeynep","Bu üçüncü hafta oluyor. Hastanede fazla mesai, evde rapor… Böyle süregelirse hasta olacaksın."],["Defne","Biliyorum. Geçen gün iki hastanın dosyasını karıştırayazdım; neyse ki arkadaşım fark etti."],["Zeynep","Bak, bu ciddi. Sorumlu hemşireyle konuştun mu?"],["Defne","Konuşmak şöyle dursun, yüzünü bile göremiyorum. İki kişi istifa etti, onların vardiyalarını biz üstlenmek durumunda kaldık."],["Zeynep","Anlıyorum ama sen hayır demedikçe yük hep sana kalır. Bir sınır koyman şart."],["Defne","Haklısın. Tam izin isteyecekken bayram yoğunluğu başlayacağı tuttu."],["Zeynep","Yoğunluk hiç bitmez ki. Sen dilekçeni yazadur, ben de sana güzel bir çorba yapıvereyim."],["Defne","Sen olmasan ne yapardım bilmiyorum."],["Zeynep","Bir şey daha: bu hafta sonu telefonu kapatıp Çeşme'ye gidiyoruz. İtiraz kabul etmiyorum."],["Defne","Peki, peki! Dilekçeyi yarın sabah ilk iş veriyorum."]]},{"gloss":[["eşik","ostona"],["karıştırmak","adashtirmoq"],["neyse ki","yaxshiyamki"],["istifa etmek","isteʼfo bermoq"],["vardiya","smena"],["üstlenmek","zimmasiga olmoq"],["şart","zarur"],["dilekçe","ariza"],["itiraz","eʼtiroz"]]}]}],"reading":{"text":"Günümüzde \"Nasılsın?\" sorusuna verilen en yaygın cevap artık \"İyiyim\" değil, \"Çok yoğunum\" oldu. Meşgul olmak neredeyse bir başarı göstergesi sayılıyor; dinlenmek ise tembellikle karıştırılıyor. Oysa araştırmalar, haftada elli saatin üzerinde çalışanların veriminin belirgin biçimde düştüğünü, altmış saati aşanların ise fazladan çalıştıkları sürede neredeyse hiçbir şey üretemediğini gösteriyor. Uzun mesai yalnızca verimi değil, sağlığı da etkiliyor: uykusuzluk, kalp hastalıkları ve tükenmişlik riski artıyor. Tükenmişlik bir anda ortaya çıkıvermez; yıllarca süregelen küçük ihmallerin sonucudur. Kişi önce hobilerinden, sonra arkadaşlarından, en sonunda uykusundan vazgeçer. Bir sabah uyandığında ise sevdiği işe karşı hiçbir şey hissetmediğini fark edip şaşırakalır. Uzmanlara göre çözüm daha iyi zaman yönetimi uygulamalarında değil, önceliklerin yeniden belirlenmesindedir. Her isteğe evet demeye kalkan biri, aslında kendi önceliklerine hayır demektedir. Molaların bir ödül değil, işin bir parçası olduğunu kabul etmek gerekir; nitekim beyin, yeni bilgileri en çok dinlenirken işler. Bazı ülkelerde çalışanların mesai dışında iş e-postalarına cevap vermeme hakkı yasayla güvence altına alınmıştır. Belki de asıl soru şudur: yoğun olmak mı istiyoruz, yoksa anlamlı bir iş çıkarmak mı?","gloss":[["meşguliyet","bandlik"],["erdem","fazilat"],["gösterge","koʻrsatkich"],["tembellik","dangasalik"],["aşmak","oshmoq"],["şaşırakalmak","hayratdan qotib qolmoq"],["uygulama","ilova"],["ödül","mukofot"],["işlemek","qayta ishlamoq"],["güvence altına almak","kafolatlamoq"]],"qtitle":"Savollar. Toʻgʻri (D) yoki notoʻgʻri (Y)?","qs":["Günümüzde meşgul olmak bir başarı göstergesi sayılıyor.","Haftada altmış saatten fazla çalışanlar çok daha fazla üretir.","Tükenmişlik birdenbire ortaya çıkar.","Uzmanlara göre çözüm önceliklerin yeniden belirlenmesidir.","Beyin yeni bilgileri en çok dinlenirken işler.","Hiçbir ülkede mesai dışında e-postaya cevap vermeme hakkı yoktur."],"title":"Meşguliyet bir erdem mi?","ans":{"1":"D","2":"Y","3":"Y","4":"D","5":"D","6":"Y"}},"exercises":[{"n":1,"title":"-(y)Iver bilan toʻldiring.","items":[["a","Şu kapıyı ___ . (açmak, sen — iltimos)"],["b","Çocuk bir anda ___ . (uyumak)"],["c","Bana bir kahve ___ misin? (yapmak)"],["d","Yağmur birden ___ . (başlamak)"]],"ans":{"a":"açıver","b":"uyuyuverdi","c":"yapıverir","d":"başlayıverdi"}},{"n":2,"title":"-(y)AyAz bilan qayta yozing («oz qoldi»).","items":[["a","Az kalsın düşüyordum. →"],["b","Az kalsın treni kaçırıyorduk. →"],["c","Az kalsın bayılıyordu. →"]],"ans":{"a":"Düşeyazdım.","b":"Treni kaçırayazdık.","c":"Bayılayazdı."}},{"n":3,"title":"Mos tasviriy feʼlni qoʻying: -(y)Adur · -(y)Akal · -(y)Agel.","items":[["a","Sen çalış___ , ben hemen dönerim."],["b","Haberi duyunca don___ . (o, oʻtgan zamon)"],["c","Bu âdet yüzyıllardır sür___ . (-mIştIr)"]],"ans":{"a":"çalışadur","b":"donakaldı","c":"süregelmiştir"}},{"n":4,"title":"Mos qolipni yozing: -mAyA kalkmak · -mAk durumunda kalmak · şöyle dursun.","items":[["a","Ustaya sormadan makineyi tamir ___ ve bozdu. (etmek)"],["b","Şirket kapanınca başka şehre ___ . (taşınmak, biz)"],["c","Tatile çıkmak ___ , hafta sonu bile çalışıyorum."]],"ans":{"a":"etmeye kalktı","b":"taşınmak durumunda kaldık","c":"şöyle dursun"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Zinadan yiqilib tushishimga oz qoldi."],["b","Sen yozib tur, men choy damlay."],["c","U isteʼfo berishga majbur boʻlib qoldi."],["d","Eshik birdan ochilib ketdi."]],"ans":{"a":"Merdivenden düşeyazdım.","b":"Sen yazadur, ben çay demleyeyim.","c":"İstifa etmek durumunda kaldı.","d":"Kapı birden açılıverdi."}},{"n":6,"title":"Yozish. «Çok çalışmak mı, verimli çalışmak mı?» mavzusida 250 soʻzlik insho yozing: oʻz tajribangizdan bir voqea, mutaxassislar fikri va xulosa. Kamida uchta tasviriy feʼl (-(y)Iver, -(y)AyAz, -(y)Akal…) ishlating.","items":[],"ans":{}}]},{"id":"c1-7","level":"C1","n":7,"title":"Edebiyatın Dili","sub":"Badiiy uslub: devrik cümle · kuchaytirma (masmavi) · ikilemeler · oʻxshatish va majoz · hikoya zamonlari","goals":["devrik cümle va uning hissiy taʼsiri","kuchaytirma sifatlar: masmavi, kapkara, bembeyaz","ikilemeler: yavaş yavaş, ağır aksak, sessiz sedasız","oʻxshatish, jonlantirish, majoz; hikoyada zamonlar"],"vocab":[{"title":"Lugʻat","words":[["öykü","hikoya"],["anlatıcı","hikoyachi"],["kahraman","qahramon"],["betimleme","tasvir"],["benzetme","oʻxshatish"],["mecaz","majoz"],["ima","ishora"],["üslup","uslub"],["tema","mavzu"],["çatışma","ziddiyat"],["ayrıntı","tafsilot"],["sezmek","sezmoq"],["iç geçirmek","xoʻrsinmoq"],["fısıldamak","shivirlamoq"],["hüzün","mahzunlik"],["dize","misra"],["izlenim","taassurot"],["yansıtmak","aks ettirmoq"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"Devrik cümle: kesim gap oxirida kelmaydi"},{"table":{"h":["Odatiy tartib","Devrik (badiiy, hissiy)"],"r":[["Bir gün mutlaka geleceğim.","Geleceğim bir gün mutlaka."],["O eski ev hâlâ duruyor.","Duruyor hâlâ o eski ev."],["Annemin sesini unutamadım.","Unutamadım annemin sesini."]]}},{"p":"Devrik gap urgʻuni oʻzgartiradi: kesimdan keyin kelgan boʻlak xuddi keyinroq esga tushgandek, hissiy ohang beradi. Rasmiy matnda ishlatilmaydi."},{"sub":"Kuchaytirma sifatlar (pekiştirme)"},{"table":{"h":["Sifat","Kuchaytirma","Oʻzbekcha"],"r":[["mavi","masmavi","koʻm-koʻk"],["kara","kapkara","qop-qora"],["beyaz","bembeyaz","oppoq"],["temiz","tertemiz","top-toza"],["yeşil","yemyeşil","yam-yashil"],["yalnız","yapayalnız","yakka-yolgʻiz"]]}},{"p":"Birinchi boʻgʻin + m, p, r yoki s: ka-p-kara, ye-m-yeşil, te-r-temiz, ma-s-mavi. Qaysi tovush kelishi yodlanadi."},{"sub":"Ikilemeler (juft soʻzlar)"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["yavaş yavaş","asta-sekin"],["ağır aksak","imillab"],["eğri büğrü","qiyshiq-qingʻir"],["ufak tefek","mayda-chuyda"],["sessiz sedasız","jimgina"],["konu komşu","qoʻni-qoʻshni"]]}},{"sub":"Oʻxshatish, jonlantirish, majoz"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Zaman su gibi akıp gitti.","Vaqt suvdek oqib ketdi. (oʻxshatish)"],["Şehir uyuyordu.","Shahar uxlar edi. (jonlantirish)"],["İçimde bir kuş çırpınıyordu.","Ichimda bir qush tipirchilardi. (majoz)"]]}},{"note":"Hikoyada voqealar -DI bilan, fon va tasvir -(I)yordu bilan, voqeadan oldingi holat -mIştI bilan beriladi. Ertak va rivoyatlarda esa -mIş hukmron: Bir varmış, bir yokmuş…"}]},{"kind":"dialog","title":"Dialog: Bir öykü üzerine","blocks":[{"dlg":[["Elif Hoca","\"Son Vapur\" öyküsünü okudunuz. İlk izleniminiz ne oldu?"],["Kerem","Açıkçası başta hiçbir şey olmuyor gibi geldi hocam. Yaşlı bir adam iskelede oturuyor, o kadar."],["Dilnoza","Bence her şey o \"hiçbir şey\"in içinde saklı. Adamın elindeki ikinci bilet bütün öyküyü anlatıyor."],["Elif Hoca","Güzel bir gözlem. Yazar, adamın eşini kaybettiğini herhangi bir yerde açıkça söylüyor mu?"],["Kerem","Söylemiyor. Ama \"yanındaki boş yere ceketini serdi\" cümlesinden seziliyor."],["Elif Hoca","İşte buna ima diyoruz. İyi öykü anlatmaz, sezdirir. Peki dil hakkında ne dersiniz?"],["Dilnoza","Devrik cümleler dikkatimi çekti: \"Gelmedi o akşam vapur.\" Düz yazsaydı bu kadar hüzünlü olmazdı."],["Kerem","Bir de ikilemeler var: \"ağır aksak\", \"sessiz sedasız\". Adamın yürüyüşünü gözümün önüne getirdi."],["Elif Hoca","Denizin \"kapkara\" olması sizce rastlantı mı?"],["Dilnoza","Sanmıyorum. Başta deniz masmaviydi; adam bileti yırtınca kapkara oluyor. Renk, adamın iç dünyasını yansıtıyor."],["Elif Hoca","Çok iyi. Sonunu nasıl buldunuz?"],["Kerem","Yarım kalmış gibi. Çocuk simidi uzatıyor ve öykü bitiyor. Adam yarın gelecek mi, bilmiyoruz."],["Elif Hoca","Yazar o kararı size bırakmış. Ödeviniz de bu: öyküye kendi sonunuzu yazın, bir paragraf yeter."]]},{"gloss":[["gözlem","kuzatuv"],["sezdirmek","sezdirmoq"],["düz","oddiy, toʻgʻri"],["gözünün önüne getirmek","koʻz oldiga keltirmoq"],["rastlantı","tasodif"],["yırtmak","yirtmoq"],["yarım kalmak","chala qolmoq"],["uzatmak","uzatmoq"]]}]}],"reading":{"text":"İskelenin en ucundaki bankta oturuyordu yaşlı adam. Elinde iki bilet vardı; birini cebine koydu, ötekini avucunda tuttu. Deniz masmaviydi o saatte, martılar simitçinin tezgâhı üstünde dönüp duruyordu. Yanındaki boş yere ceketini serdi, sanki biri gelip oturacakmış gibi. Kırk yıl boyunca her pazar bu vapura binmişlerdi. Karşı kıyıdaki çay bahçesinde aynı masaya oturur, aynı şeyleri konuşurlardı; daha doğrusu o konuşur, adam dinlerdi. Şimdi anlıyordu ki dinlememişti hiç, yalnızca susmuştu. Akşam indi yavaş yavaş. İskele memuru sessiz sedasız yaklaştı: \"Amca, son vapur bozulmuş, bu akşam sefer yok.\" Adam başını salladı, kalkmadı. Gelmedi o akşam vapur. Rüzgâr serinledi, deniz kapkara oldu. Avucundaki bileti uzun uzun seyretti, sonra ikiye yırtıp suya bıraktı. Kâğıt parçaları bir süre dalgaların üstünde kaldı, bembeyaz. Ağır aksak doğruldu, ceketini omzuna aldı. Tam o sırada simitçinin küçük oğlu koşarak geldi; elinde son kalan simidi tutuyordu. \"Dede,\" dedi, \"babam bunu sana yolladı. Bir de dedi ki, yarın sabah ilk vapur yedide.\" Adam çocuğun yüzüne baktı. İçinde, çoktandır sustuğunu sandığı bir şey kıpırdadı.","gloss":[["iskele","pristan"],["uç","chekka"],["avuç","kaft"],["martı","chagʻalay"],["tezgâh","peshtaxta"],["kıyı","sohil"],["sefer","reys"],["seyretmek","tikilib qaramoq"],["doğrulmak","qaddini rostlamoq"],["yollamak","yubormoq"],["çoktandır","anchadan beri"],["kıpırdamak","qimirlamoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Yaşlı adamın elinde kaç bilet vardı?","Adam ceketini yanındaki boş yere nasıl serdi?","Kırk yıl boyunca pazar günleri ne yapmışlardı?","İskele memuru ne haber verdi?","Adam avucundaki bileti ne yaptı?","Çocuk adama ne getirdi ve ne söyledi?"],"title":"Son vapur","ans":{"1":"İki bilet vardı.","2":"Sanki biri gelip oturacakmış gibi serdi.","3":"Vapura binip karşı kıyıdaki çay bahçesine gitmişlerdi.","4":"Son vapurun bozulduğunu, o akşam sefer olmadığını söyledi.","5":"İkiye yırtıp suya bıraktı.","6":"Bir simit getirdi ve yarın sabah ilk vapurun yedide olduğunu söyledi."}},"exercises":[{"n":1,"title":"Devrik gapni odatiy tartibga keltiring.","items":[["a","Gelmedi o akşam vapur. →"],["b","Unutamadım annemin sesini. →"],["c","Oturuyordu yaşlı adam iskelede. →"]],"ans":{"a":"O akşam vapur gelmedi.","b":"Annemin sesini unutamadım.","c":"Yaşlı adam iskelede oturuyordu."}},{"n":2,"title":"Kuchaytirma shaklini yozing.","items":[["a","mavi →"],["b","kara →"],["c","beyaz →"],["d","temiz →"],["e","yeşil →"],["f","yalnız →"]],"ans":{"a":"masmavi","b":"kapkara","c":"bembeyaz","d":"tertemiz","e":"yemyeşil","f":"yapayalnız"}},{"n":3,"title":"Mos ikilemeni qoʻying: yavaş yavaş · ağır aksak · sessiz sedasız · ufak tefek.","items":[["a","Hava ___ kararıyordu."],["b","Yaşlı adam ___ yürüyordu."],["c","Misafirler ___ evden ayrıldı."],["d","Çantasında ___ eşyalar vardı."]],"ans":{"a":"yavaş yavaş","b":"ağır aksak","c":"sessiz sedasız","d":"ufak tefek"}},{"n":4,"title":"Sanʼat turini aniqlang: oʻxshatish (O), jonlantirish (J) yoki majoz (M).","items":[["a","Zaman su gibi akıp gitti."],["b","Rüzgâr pencereye fısıldıyordu."],["c","Yüreğinde bir taş vardı."],["d","Çocuk kuş gibi hafifti."]],"ans":{"a":"O","b":"J","c":"M","d":"O"}},{"n":5,"title":"Turkchaga tarjima qiling.","items":[["a","Dengiz koʻm-koʻk edi."],["b","U jimgina chiqib ketdi."],["c","Oʻsha kecha kema kelmadi. (devrik)"],["d","Vaqt suvdek oqib ketdi."]],"ans":{"a":"Deniz masmaviydi.","b":"Sessiz sedasız çıkıp gitti.","c":"Gelmedi o gece vapur.","d":"Zaman su gibi akıp gitti."}},{"n":6,"title":"Yozish. Ijodiy yozish: «Son vapur» hikoyasini davom ettiring — ertasi kuni ertalab nima boʻldi? 200–250 soʻz. Kamida ikkita devrik gap, ikkita ikileme va bitta oʻxshatish ishlating.","items":[],"ans":{}}]},{"id":"c1-8","level":"C1","n":8,"title":"Sınava Hazırlık","sub":"C1 imtihon koʻnikmalari: matnni qisqartirish · grafikni sharhlash · dalilli insho · ogʻzaki bayon","goals":["matnning qisqacha bayonini (özet) yozish","grafik va jadvalni sharhlash tili","dalilli insho tuzilishi: tezis — asos — qarshi fikr — xulosa","ogʻzaki bayonda vaqt yutish va fikrni tartiblash"],"vocab":[{"title":"Lugʻat","words":[["özet","qisqacha bayon"],["ana fikir","asosiy gʻoya"],["yardımcı fikir","yordamchi gʻoya"],["oran","nisbat, ulush"],["artış","oʻsish"],["düşüş","pasayish"],["zirve","choʻqqi"],["sabit","oʻzgarmas"],["tez","tezis"],["gerekçe","asos"],["karşı görüş","qarshi fikr"],["çürütmek","dalil bilan rad etmoq"],["kuraklık","qurgʻoqchilik"],["su kıtlığı","suv tanqisligi"],["tasarruf","tejash"],["sürdürülebilir","barqaror"],["tüketim","isteʼmol"],["yeraltı suyu","yer osti suvi"]]}],"sections":[{"kind":"grammar","title":"Grammatika","blocks":[{"sub":"1. Matnni qisqartirish (özet çıkarma)"},{"p":"Uch qadam: 1) har xatboshining asosiy gapini toping; 2) misol, raqam va takrorlarni olib tashlang; 3) oʻz soʻzlaringiz bilan matn hajmining uchdan biriga keltiring. Oʻz fikringizni qoʻshmang."},{"table":{"h":["Qolip","Maʼnosi"],"r":[["Metinde … ele alınmaktadır.","Matnda … koʻrib chiqilgan."],["Yazara göre …","Muallifga koʻra …"],["Yazar, … olduğunu savunmaktadır.","Muallif … deb hisoblaydi."],["Sonuç olarak yazar … gerektiğini vurgulamaktadır.","Xulosada muallif … zarurligini taʼkidlaydi."]]}},{"sub":"2. Grafik va jadvalni sharhlash"},{"table":{"h":["Turkcha","Oʻzbekcha"],"r":[["Grafik, 2000–2025 yılları arasındaki su tüketimini göstermektedir.","Grafik 2000–2025-yillardagi suv isteʼmolini koʻrsatadi."],["Tüketim yüzde 40 oranında artmıştır.","Isteʼmol 40 foizga oshgan."],["2015'te zirveye ulaşmış, ardından düşüşe geçmiştir.","2015-yilda choʻqqiga chiqib, keyin pasaya boshlagan."],["Oran yaklaşık olarak sabit kalmıştır.","Ulush taxminan oʻzgarmay qolgan."],["En belirgin fark tarım sektöründe görülmektedir.","Eng sezilarli farq qishloq xoʻjaligida kuzatiladi."]]}},{"sub":"3. Dalilli insho tuzilishi"},{"table":{"h":["Qism","Vazifasi","Qolip"],"r":[["Giriş","mavzu + tezis","Bu yazıda … savunulacaktır."],["Gelişme","dalil + misol","İlk olarak … / Bunun yanı sıra …"],["Karşı görüş","eʼtiroz va uni rad etish","… öne sürülebilir; ancak …"],["Sonuç","tezisni qayta aytish","Bütün bunlar göz önüne alındığında …"]]}},{"sub":"4. Ogʻzaki bayon"},{"p":"Bir daqiqa tayyorgarlikda uchta kalit soʻz yozing: fikr — sabab — misol. Vaqt yutish uchun: «Bu konuya iki açıdan bakılabilir», «Şöyle bir örnek vereyim». Bilmagan soʻzni tasvirlab ayting: «… için kullanılan bir şey»."},{"note":"C1 imtihonlarida til xatosidan koʻra koʻproq ball yoʻqotiladigan joy — savolga toʻliq javob bermaslik. Avval topshiriqni tagiga chizib oʻqing: nechta narsa soʻralyapti?"}]},{"kind":"dialog","title":"Dialog: Sözlü sınav provası","blocks":[{"dlg":[["Elif Hoca","Jasur, sözlü sınav provasına hazır mısın? Bugünkü konu şöyle — \"Su kıtlığı bireysel bir sorun mu, toplumsal bir sorun mu?\" Bir dakika düşünme süren var."],["Jasur","Hazırım hocam. Bu konuya iki açıdan bakılabilir. İlk olarak bireysel boyutu ele almak istiyorum."],["Elif Hoca","Buyur, seni dinliyorum."],["Jasur","Hepimiz günlük hayatta su israf ediyoruz. Şöyle bir örnek vereyim: dişlerini fırçalarken musluğu açık bırakan biri yılda tonlarca suyu boşa harcar."],["Elif Hoca","Peki bireysel tasarruf sorunu çözmeye yeter mi?"],["Jasur","Tek başına yetmez, zira tatlı suyun yaklaşık yüzde yetmişi tarımda kullanılıyor. Dolayısıyla asıl çözüm sulama yöntemlerinin değiştirilmesinde yatıyor."],["Elif Hoca","Yani toplumsal bir sorun olduğunu mu savunuyorsun?"],["Jasur","Evet, ancak iki boyut birbirinden ayrılamaz. Bireyler bilinçlenmedikçe doğru politikalar da desteklenmez."],["Elif Hoca","Bazıları teknolojinin, örneğin deniz suyunun arıtılmasının, sorunu çözeceğini söylüyor. Buna ne dersin?"],["Jasur","Bu görüş öne sürülebilir; ancak arıtma hem pahalı hem de çok enerji gerektiren bir yöntem. O yüzden tasarrufun yerini tutamaz."],["Elif Hoca","Güzel. Şimdi tek cümleyle sonuca bağla."],["Jasur","Bütün bunlar göz önüne alındığında, su kıtlığı ancak bireysel sorumlulukla toplumsal planlamanın birleştirilmesi hâlinde aşılabilir."],["Elif Hoca","Çok iyi bir yapı kurdun: tez, gerekçe, karşı görüş, sonuç. Yalnız örneklerini biraz çeşitlendir ve daha yavaş konuş."]]},{"gloss":[["prova","sinov mashqi"],["boyut","jihat"],["ele almak","koʻrib chiqmoq"],["israf etmek","isrof qilmoq"],["sulama","sugʻorish"],["bilinçlenmek","ongli boʻlmoq"],["arıtmak","tozalamoq"],["yerini tutmak","oʻrnini bosmoq"],["çeşitlendirmek","xilma-xil qilmoq"]]}]}],"reading":{"text":"Bir zamanlar dünyanın dördüncü büyük gölü olan Aral, yirminci yüzyılın en büyük çevre felaketlerinden birinin simgesi hâline gelmiştir. 1960'lı yıllarda gölü besleyen Amuderya ve Siriderya nehirlerinin suları, pamuk tarımını genişletmek amacıyla geniş çaplı sulama kanallarına yönlendirildi. Kısa vadede hedefe ulaşıldı: pamuk üretimi katlanarak arttı. Ne var ki göle ulaşan su miktarı her yıl azaldı ve Aral'ın yüzeyi birkaç on yıl içinde onda birine kadar küçüldü. Sonuçlar yalnızca çevreyle sınırlı kalmadı. Balıkçılık bütünüyle sona erdi; bir zamanlar kıyıda bulunan liman kentleri sudan onlarca kilometre uzakta kaldı. Kuruyan göl tabanından kalkan tuzlu tozlar çevredeki tarım arazilerine ve yerleşimlere taşındı, bölgede solunum yolu hastalıkları yaygınlaştı. İklim de değişti: yazlar daha sıcak, kışlar daha sert geçmeye başladı. Bugün gölün kuzey kesiminde yapılan bir baraj sayesinde su seviyesi kısmen yükselmiş, balıkçılık sınırlı ölçüde geri dönmüştür. Güneyde ise kuruyan tabana tuza dayanıklı bitkiler dikilmek suretiyle toz fırtınalarının azaltılmasına çalışılmaktadır. Aral'ın öyküsü, doğal kaynakların kısa vadeli kazanç uğruna tüketilmesinin bedelinin kuşaklar boyunca ödendiğini göstermektedir. Aynı zamanda, kararlı adımlar atıldığı takdirde zararın en azından bir bölümünün giderilebileceğine dair bir umut da sunmaktadır.","gloss":[["felaket","falokat"],["simge","timsol"],["beslemek","suv bilan taʼminlamoq"],["yönlendirmek","yoʻnaltirmoq"],["kısa vade","qisqa muddat"],["katlanarak","bir necha barobar"],["yüzey","sath"],["liman","port"],["taban","tub"],["toz","chang"],["solunum yolu","nafas yoʻli"],["baraj","toʻgʻon"],["dayanıklı","chidamli"],["uğruna","yoʻlida"],["kuşak","avlod"],["gidermek","bartaraf etmoq"]],"qtitle":"Savollar. Turkcha javob bering.","qs":["Aral bir zamanlar dünyanın kaçıncı büyük gölüydü?","Nehirlerin suları neden kanallara yönlendirildi?","Gölün yüzeyi ne kadar küçüldü?","Kuruyan göl tabanı bölgede hangi sağlık sorununa yol açtı?","Kuzey kesiminde su seviyesi nasıl yükseldi?","Aral'ın öyküsü bize ne gösteriyor?"],"title":"Aral'dan alınacak ders","ans":{"1":"Dördüncü büyük gölüydü.","2":"Pamuk tarımını genişletmek amacıyla yönlendirildi.","3":"Onda birine kadar küçüldü.","4":"Solunum yolu hastalıkları yaygınlaştı.","5":"Yapılan bir baraj sayesinde yükseldi.","6":"Doğal kaynakların kısa vadeli kazanç uğruna tüketilmesinin bedelinin kuşaklar boyunca ödendiğini gösteriyor."}},"exercises":[{"n":1,"title":"«Aral'dan alınacak ders» matni: qaysi gap xulosaga (özet) kiradi (K), qaysi biri kirmaydi (Y)?","items":[["a","Aral'ın küçülmesinin başlıca nedeni nehir sularının sulamaya yönlendirilmesidir."],["b","Pamuk çok güzel bir bitkidir."],["c","Kuruma hem çevreyi hem insan sağlığını olumsuz etkilemiştir."],["d","Bence herkes Aral'ı ziyaret etmeli."]],"ans":{"a":"K","b":"Y","c":"K","d":"Y"}},{"n":2,"title":"Grafik tilida turkcha yozing.","items":[["a","40 foizga oshdi."],["b","Choʻqqiga chiqdi."],["c","Oʻzgarmay qoldi."],["d","Yarmiga kamaydi."]],"ans":{"a":"Yüzde 40 oranında arttı.","b":"Zirveye ulaştı.","c":"Sabit kaldı.","d":"Yarı yarıya azaldı."}},{"n":3,"title":"Insho qismini aniqlang: Giriş (G), Gelişme (L), Karşı görüş (K) yoki Sonuç (S).","items":[["a","Bu yazıda su tasarrufunun zorunlu olduğu savunulacaktır."],["b","Teknolojinin sorunu çözeceği öne sürülebilir; ancak bu yöntem çok pahalıdır."],["c","Bütün bunlar göz önüne alındığında acil önlem alınmalıdır."],["d","İlk olarak, tatlı suyun büyük bölümü tarımda kullanılmaktadır."]],"ans":{"a":"G","b":"K","c":"S","d":"L"}},{"n":4,"title":"Mos qolipni qoʻying: ele alınmaktadır · savunmaktadır · göz önüne alındığında · bunun yanı sıra.","items":[["a","Metinde su kıtlığı sorunu ___ ."],["b","Yazar, tasarrufun tek başına yetmediğini ___ ."],["c","Bütün veriler ___ durum ciddidir."],["d","Tarımda su israf edilmektedir; ___ şehirlerde de kayıplar büyüktür."]],"ans":{"a":"ele alınmaktadır","b":"savunmaktadır","c":"göz önüne alındığında","d":"bunun yanı sıra"}},{"n":5,"title":"Ogʻzaki bayon. Mavzulardan birini tanlang, bir daqiqa tayyorlanib, ikki daqiqa ovoz chiqarib gapiring: «Su kıtlığına karşı ne yapılmalı?», «Büyük projeler doğaya zarar vermeden yapılabilir mi?», «Tüketim alışkanlıklarımız değişmeli mi?». Tuzilish: tezis — asos — qarshi fikr — xulosa.","items":[],"ans":{}},{"n":6,"title":"Yozish. «Doğal kaynaklar ekonomik büyüme için feda edilebilir mi?» mavzusida 250–300 soʻzlik dalilli insho yozing: tezis, ikki asos, qarshi fikr va uni rad etish, xulosa.","items":[],"ans":{}}]}]};
